int main(){
  vector<int> g[4], acc[4];
  int N, W, n[4];
  int w1 = -1;
  long long w_all[4], v_all[4];
  cin >> N >> W;
  for (int i=0;i<N;i++) {
    int w, v;
    cin >> w >> v;
    if (w1 < 0) {
      w1 = w;
    }
    g[w-w1].push_back(v);
  }
  for (int i=0;i<4;i++) {
    sort(g[i].rbegin(), g[i].rend());
    n[i] = g[i].size();
    acc[i].push_back(0);
    for (int j=0;j<n[i];j++) {
      acc[i].push_back(acc[i][j] + g[i][j]);
    }
  }
  long long result = 0;


  for (int i=0;i<=n[3];i++) {
    w_all[3] = i*(w1+3);
    if (w_all[3] > W)
      break;
    v_all[3] = acc[3][i];
    for (int j=0;j<=n[2];j++) {
      w_all[2] = w_all[3] + j*(w1+2);
      if (w_all[2] > W)
	break;
      v_all[2] = v_all[3] + acc[2][j];
      for (int k=0;k<=n[1];k++) {
	w_all[1] = w_all[2] + k*(w1+1);
	if (w_all[1] > W)
	  break;
	v_all[1] = v_all[2] + acc[1][k];
	for (int l=0;l<=n[0];l++) {
	  w_all[0] = w_all[1] + l*(w1);
	  if (w_all[0] > W)
	    break;
	  v_all[0] = v_all[1] + acc[0][l];
	  if (v_all[0] > result) {
	    result = v_all[0];
	  }
	}
      }
    }
  }
  cout << result << endl;
}

