ll n, w, ans = 0;
ll dps(int a, int b, int c, int d, ll W) {
	// trace(a, b, c, d, W, ans)
	if (W > w)return -1e9 + 7;
	if (!dp[a][b][c][d]) {
		ll tans = 0;
		// trace("inside", a, b, c, d, W, ans)
		if (a < aa[0].S && W + aa[0].F <= w) {
			tans = max(tans, dps(a + 1, b, c, d, W + aa[0].F) + ww[0][a]);
		}
		if (b < aa[1].S && W + aa[1].F <= w) {
			tans = max(tans, dps(a, b + 1, c, d, W + aa[1].F) + ww[1][b]);
		}
		if (c < aa[2].S && W + aa[0].F <= w) {
			tans = max(tans, dps(a, b, c + 1, d, W + aa[2].F) + ww[2][c]);
		}
		if (d < aa[3].S && W + aa[0].F <= w) {
			tans = max(tans, dps(a, b, c, d + 1, W + aa[3].F) + ww[3][d]);
		}
		dp[a][b][c][d] = tans;
		ans = max(ans, tans);
		// trace(tans, ans)
	}
	return dp[a][b][c][d];
}
