signed main() {
    int N, W;
    cin >> N >> W;

    vi w(N), v(N);
    rep(i, N) cin >> w[i] >> v[i];

    //バッグがある重さのときの、価値の最大値を更新していくマップ
    map<int, int> dp;
    dp[0] = 0;

    int res = 0;

    //この問題ではw[0]からw[0]+3までの重さの物しか存在しないため、
    //重さの総和が同じになる組み合わせが多く存在するはずである。
    //したがって、全ての物について入れるか、入れないかの２通りを試しても、
    //重さの総和の状態数はさほど大きくならない。
