    rep(i, N) {
        auto tmp = dp;

        int cnt = 0;
        for(auto p: tmp) {
            auto x = p.first + w[i];
            auto y = p.second + v[i];
            if(x <= W) res = max(res, dp[x]=max(dp[x], y));
            cnt++;
        }
        cout << cnt << endl;
    }

    cout << res << endl;

    return 0;
}

