#define rep(i,n) for(int i=0;i<(int)(n);i++)
#define reps(i,s,n) for(int i=(int)(s);i<(int)(n);i++)

int N;
ll W;
ll w[100];
ll v[100];
ll dp[100 + 1][100 + 1];

ll DP(int i, int j) {	//i番目以降重さj以下
	if (dp[i][j] != -1) {
		return dp[i][j];
	}
	ll res;
	if (i == N) {
		res = 0;
	}
	else if (j < w[i]) {
		res = DP(i + 1, j);
	}
	else {
		res = max(DP(i + 1, j), DP(i + 1, j - w[i]) + v[i]);
	}
	return dp[i][j] = res;
}

int main() {
	cin.sync_with_stdio(false);
	cin >> N >> W;
	rep(i, N) {
		cin >> w[i] >> v[i];
		w[i] = w[i] - (w[0] - 1);
	}
	W = W - (w[0] - 1);
	memset(dp, -1, sizeof(dp));

	cout << DP(0, W) << endl;
	return 0;
}

