int N, W;
int w[100];
int v[100];
int dp[101][101];

int rec(int i, int j) {
  if (dp[i][j] >= 0) {
    return dp[i][j];
  }
  int val;
  if (i == N) {
    val = 0;
  } else if (j < w[i]) {
    val = rec(i+1, j);
  } else {
    val = std::max(rec(i+1, j), rec(i+1, j-w[i])+v[i]);
  }
  dp[i][j] = val;
  return val;
}

int main() {
  std::cin >> N >> W;
  memset(dp, -1, sizeof(dp));

  for (int i = 0; i < N; i++) {
    std::cin >> w[i] >> v[i];
  }

  std::cout << rec(0, W) << std::endl;

  return 0;
}

