    long long i, j, k;
    cin >> w[0] >> v[0];
    long long base = w[0];
    w[0] -= base;
    for(i = 1; i < n; i++){
        cin >> w[i] >> v[i];
        w[i] -= base;
    }

    vector<vector<vector<long long> > > dp(110, vector<vector<long long> >(330, vector<long long>(110)));
    for(i = 0; i < 110; i++){
        for(j = 0; j < 330; j++){
