                dp[i][j][k] = 0;
            }
        }
    }
    //cout << "AAA" << endl;
    for(i = 0; i < n; i++){
        for(j = 0; j < 330; j++){
            for(k = 0; k < n; k++){
                dp[i+1][j][k] = max(dp[i+1][j][k], dp[i][j][k]);
                if(j+w[i] < 330){
                    dp[i+1][j+w[i]][k+1] = max(dp[i+1][j+w[i]][k+1], dp[i][j][k] + v[i]);
