int main() {
    int N, W;
    cin >> N >> W;
    vector<int> Ws;
    vector<int> Vs;
    vector<array<int, 110>> dp(N+10);

    for(int i = 0; i < N; ++i) {
        int w, v;
        cin >> w >> v;
        Ws.push_back(w);
        Vs.push_back(v);
    }

    for(int w = 0; w <= W; ++w) {
        for(int i = 0; i < N; ++i) {
            int value = Vs[i];
            int weight = Ws[i];
            if(w >= weight) {
                dp[w][i+1] = max(dp[w][i], dp[w-weight][i] + value);
            }
            else dp[w][i+1] = dp[w][i];
        }
    }

    cout << dp[W][N] << endl;

    return 0;
}

