std::vector< P > ps;

void solve() {
    int n = N / 2;
    for (int i=0; i<(1<<n); ++i) {
        ll sw = 0, sv = 0;
        for (int j=0; j<n; ++j) {
            if (i >> j & 1) {
                sw += w[j];
                sv += v[j];
            }
        }
        ps.push_back( P(sw, sv) );
    }

    std::sort(ps.begin(), ps.end());
    int m = 1;
    for (int i=1; i<(1<<n); ++i) {
        if (ps[m-1].second < ps[i].second) {
            ps[m++] = ps[i];
        }
    }

    ll res = 0;
    for (int i=0; i<(1<<(N-n)); ++i) {
        ll sw = 0, sv = 0;
        for (int j=0; j<(N-n); ++j) {
            if (i >> j & 1) {
                sw += w[n + j];
                sv += v[n + j];
            }
        }
        if (sw <= W) {
            ll tv = ( std::lower_bound(ps.begin(), ps.end(), P(W-sw, LLONG_MAX)) -1 )->second;
            res = std::max(res, sv + tv);
        }
    }
    std::cout << res << std::endl;
}

