int N,W; vi w,v, u;
int dp[110][110][310];

int sub(int n){
    ll rest = W - w[0]*n;
    if (rest < 0) return 0;


    mset(dp, 0);
    rep(i,N){
        rep(j,n+1){
            rep(k,3*n+1){
                amax(dp[i+1][j][k], dp[i][j][k]);
                amax(dp[i+1][j+1][k + u[i]], dp[i][j][k] + v[i]);
            }
        }
    }
    return dp[N][n][min((int)rest, 300)];
}

