int n, maxW, w[101], v[101];

int sortW[4][101];
int sum3[101] = {};
int how[4] = {};

int memo[101][101][101][4];

int saiki(int use0, int use1, int use2, int nowIndex){
	if(use0 > how[0] || use1 > how[1] || use2 > how[2]) return -INF;
	if(use0 * w[0] + use1 * (w[0] + 1) + use2 * (w[0] + 2) > maxW) return -INF;

	if(memo[use0][use1][use2][nowIndex] != -1) return memo[use0][use1][use2][nowIndex];

	if(nowIndex == 3){
		int lastUse = (maxW -(use0 * w[0] + use1 * (w[0] + 1) + use2 * (w[0] + 2))) / (w[0] * 3);
		if(lastUse == 0) return 0;
		return sum3[lastUse - 1];
	}

	ll a = 0, b = 0, c = 0, d = 0, e = 0;

	if(use0 < how[0] && nowIndex == 0) a = saiki(use0 + 1, use1, use2, nowIndex) + -sortW[0][use0];
	if(use1 < how[1] && nowIndex == 1) b = saiki(use0, use1 + 1, use2, nowIndex) + -sortW[1][use1];
	if(use2 < how[2] && nowIndex == 2) c = saiki(use0, use1, use2 + 1, nowIndex) + -sortW[2][use2];
	e = saiki(use0, use1, use2, nowIndex + 1);

	return memo[use0][use1][use2][nowIndex] = max(a, max(b, max(c, max(d, e))));
}

int main() {
	for(int i = 0;i < 101;i++){
		for(int j = 0;j < 101;j++){
			for(int k = 0;k < 101;k++){
				for(int l = 0;l < 4;l++){
					memo[i][j][k][l] = -1;
				}
			}
		}
	}

	cin >> n >> maxW;
	for(int i = 0;i < n;i++){
		cin >> w[i] >> v[i];
	}
	for(int i = 0;i < n;i++){
		int now = w[i] - w[0];
		sortW[now][how[now]] = -v[i];
		how[now]++;
	}
	for(int i = 0;i < 4;i++){
		sort(sortW[i], sortW[i] + how[i]);
	}
	sum3[0] = sortW[3][0];
	for(int i = 1;i < 101;i++){
		sum3[i] = sum3[i-1] + sortW[3][i];
	}

	// cout << sortW[0][0] << "," << sortW[0][1];

	cout << saiki(0, 0, 0, 0) << endl;

	return 0;
}

