  }
  sort(a.begin(), a.end(), comp);

  ll w0 = a[0].first;
  for (int i = 0; i < n; i++) {
    b[a[i].first - w0].push_back(a[i].second);
  }

  ll ans = 0;
  for (ll i = 0; i < b[0].size(); i++) {
    for (ll j = 0; j < b[1].size(); j++) {
      for (ll k = 0; k < b[2].size(); k++) {
        ll sumw = i * w0 + j * (w0 + 1) + k * (w0 + 2);
        if (sumw > W) continue;
        int c[4] = {i, j, k, (W - sumw) / (w0 + 3)};
        ans = max(ans, calc(c));
      }
    }
  }
  cout << ans << endl;

  return 0;
}

