void knapsack(ll i, ll wi){
    i++;
    wi++;
    if(wi < w[i]){
        dp[i][wi] = dp[i-1][wi];
    }else{
        dp[i][wi] = max(dp[i-1][wi],dp[i-1][wi-w[i]]+v[i]);
    }
}



