    vector<int> ws(n), vs(n);
    for(int i=0; i<n; ++i){
        cin >> ws[i] >> vs[i];
    }
    long long w_base=ws[0]-1;
    for(int i=0; i<n; ++i){
        ws[i]-=w_base;
    }
    vector<vector<int>> dp(n+1, vector<int>(400));
    vector<vector<int>> cnt(n+1, vector<int>(400));
    for(int i=0; i<n; ++i){
        for(int wi=0; wi<400; ++wi){
            dp[i+1][wi]=dp[i][wi];
            cnt[i+1][wi]=cnt[i][wi];
            if(ws[i]<=wi){
                int nv=dp[i][wi-ws[i]]+vs[i];
                int nc=cnt[i][wi-ws[i]]+1;
                if(nv>dp[i+1][wi] && nc*w_base+wi<=w){
                    dp[i+1][wi]=nv;
                    cnt[i+1][wi]=nc;
                }
            }
        }
    }
    int ans=0;
    for(int wi=0; wi<400; ++wi){
        if(wi+cnt[n][wi]*w_base<=w) ans=max(ans, dp[n][wi]);
    }
    cout << ans << endl;
    return 0;
}

