                        else continue;
                    } else {
                        if (prev(s)->second < nv) s = a.emplace(nw, nv).first;
                        else continue;
                    }
                } else {
                    s = a.emplace(nw, nv).first;
                }
                s++;
                while (s != a.end() && s->second <= nv) a.erase(s++);
            }
        }
        LL ans = 0;
        for (auto& i : a) ans = max(ans, i.second);
