	}
	aa[0] = {wmin, m[wmin]};
	if (m[wmin + 1])aa[1] = {wmin + 1, m[wmin + 1]};
	else aa[1] = {0, 0};
	if (m[wmin + 2])aa[2] = {wmin + 2, m[wmin + 2]};
