map<int, map<int, int> > dp;

long long knapsack(int n, int W) {
	if (n == 0 || W == 0)
		return 0;
	if (dp.find(n) != dp.end() && dp[n].find(W) != dp[n].end())
		return dp[n][W];
	if (wt[n - 1] > W)
		dp[n][W] = knapsack(n - 1, W);
	else dp[n][W] = max(knapsack(n - 1, W - wt[n - 1]) + val[n - 1], knapsack(n - 1, W));
	return dp[n][W];
}

