                    if(tmp_w > W) continue;
                    long long tmp_v = a[i] + b[j] + c[k] + d[l];

                    ans = max(ans, tmp_v);
                    //cout << i << " " << j << " " << k << " " << l << " " << tmp_w << " " << tmp_v << endl;
                }
            }
        }
    }

    cout << ans << endl;    


    return 0;
}

