int func(int,int,int,int,int,int);
int N, W, V = 0, w[100], v[100]/*, memo[1000][1000]*/;
int ma = 1, mb, mc, md;
int main(void) {
	int max=0,n;
	cin >> N>>W;
	cin >> w[0] >> v[0];

	for (int i = 1; i < N; i++) {
		cin >> w[i] >> v[i];
		if (w[i] == w[0])
			ma += 1;
		if (w[i] == w[0]+1)
			mb += 1;
		if (w[i] == w[0]+2)
			mc += 1;
		if (w[i] == w[0]+3)
			md += 1;
	}

	for (int a = N; a >= 0; a--) {
		for (int b = N-a; b >= 0; b--) {
			for (int c = N-a-b; c >= 0; c--) {
				int d = N - a - b - c;
				V = func(0,W,a,b,c,d);
				if (max < V) {
					max = V;
				}
			}
		}
	}

	cout << max << endl;

}

int func(int i, int j, int a, int b, int c, int d) {
	int res;

	if (a > ma || b > mb || c > mc || d > md)
		return 0;

	if (i == N||(a==0&&b==0&&c==0&&d==0))
		res = 0;

	else if (j < w[i])
		res = func(i+1,j,a,b,c,d);

	else {
		if ((w[i] == w[0])&& a != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a-1, b, c, d) + v[i]);
		}
		else if ((w[i] == w[0] + 1)&& b != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b-1, c, d) + v[i]);
		}
		else if ((w[i] == w[0] + 2)&& c != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b, c-1, d) + v[i]);
		}
		else if ((w[1] == w[0] + 3)&& d != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b, c, d-1) + v[i]);
		}
		else {
			res = func(i + 1, j, a, b, c, d);
		}
	}
	//return memo[i][j]=res;
	return res;
}

