vector<ll> zero, one, two, three;
ll mini;
//-------------------関数----------------------//

ll DP(ll num, ll onenum, ll weight) {
	if (num*mini + weight > W) { return -INF; }
	if (num == n+1) { return 0; }
	if (dp[num][onenum][weight]) { return dp[num][onenum][weight]; }
	ll cnt = 0; 
	for (ll izryt = 0; izryt < 4; izryt++)
	{
	//	cout << izryt << endl;
		if (izryt == 0) {
			if (zero.size()) {
				ll hoge = zero.back(); zero.pop_back();
				ll bwam = DP(num + 1, onenum + 1, weight) + hoge; cnt = max(cnt, bwam); 
				zero.push_back(hoge);
			}
		}
		if (izryt == 1) {
			if (one.size()) {
				ll hoge = one.back(); one.pop_back();
				ll bwam = DP(num + 1, onenum, weight + 1) + hoge; cnt = max(cnt, bwam); 
				one.push_back(hoge);
			}
		}
		if (izryt == 2) {
			if (two.size()) {
				ll hoge = two.back(); two.pop_back();
				ll bwam = DP(num + 1, onenum, weight + 2) + hoge;  cnt = max(cnt, bwam); 
				two.push_back(hoge);
			}
		}
		if (izryt == 3) {
			if (three.size()) {
				ll hoge = three.back(); three.pop_back();
				ll bwam = DP(num + 1, onenum, weight + 3) + hoge; cnt = max(cnt, bwam); 
				three.push_back(hoge);
			}
		}
	}

		return dp[num][onenum][weight] = cnt;
}

