	REP(i, n) {
		ll izryt = p[i].first - mini;
		if (izryt == 0) { zero.push_back(p[i].second); }
		if (izryt == 1) { one.push_back(p[i].second); }
		if (izryt == 2) { two.push_back(p[i].second); }
		if (izryt == 3) { three.push_back(p[i].second); }
	}
	cout << DP(0, 0, 0) << endl;
	return 0;
}

