long long weight[MAX_N];
long long value[MAX_N];
map< int, map<long long, long long> > dp;

long long knapsack(int up_bound, long long weight_limit) {
        if (dp.find(up_bound)!=dp.end() && dp[up_bound].find(weight_limit)!=dp[up_bound].end()) {
                return dp[up_bound][weight_limit];
        }
        if (up_bound==0 || weight_limit==0) {
                dp[up_bound][weight_limit] = 0;
        } else if (weight_limit-weight[up_bound]<0) {
                dp[up_bound][weight_limit] = knapsack(up_bound-1, weight_limit);
        } else {
                dp[up_bound][weight_limit] = max(knapsack(up_bound-1, weight_limit),
                knapsack(up_bound-1, weight_limit-weight[up_bound])+
                value[up_bound]);
        }
        return dp[up_bound][weight_limit];
}

