vector<vector<int> > b(4, vector<int>(1, 0));

bool comp(const P& a, const P& b) {
  if (a.first == b.first) return a.second > b.second;
  return a.first < b.first;
}

ll calc(int c[4]) {
  ll res = 0;
  for (int i = 0; i < 4; i++) {
    if (c[i] >= b[i].size()) c[i] = b[i].size() - 1;
    for (int j = 1; j <= c[i]; j++) {
      res += b[i][j];
    }
  }
  return res;
}

int main(void) {
  int n, W;
  cin >> n >> W;

  vector<P> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i].first >> a[i].second;
  }
  sort(a.begin(), a.end(), comp);

  int w0 = a[0].first;
  for (int i = 0; i < n; i++) {
    b[a[i].first - w0].push_back(a[i].second);
  }

  ll ans = 0;
  for (int i = 0; i < b[0].size(); i++) {
    for (int j = 0; j < b[1].size(); j++) {
      for (int k = 0; k < b[2].size(); k++) {
        ll sumw = i * w0 + j * (w0 + 1) + k * (w0 + 2);
        if (sumw > W) continue;
        int c[4] = {i, j, k, (W - sumw) / (w0 + 3)};
        ans = max(ans, calc(c));
      }
    }
  }
  cout << ans << endl;

  return 0;
}

