/* A Naive recursive implementation of 0-1 Knapsack problem */
#include<stdio.h>
#include <bits/stdc++.h>

using namespace std;
map<pair<long long,long long>,long long> mymap;
// A utility function that returns maximum of two integers
int max(long long  a, long long b) { return (a > b)? a : b; }

// Returns the maximum value that can be put in a knapsack of capacity W
int knapSack(long long W, long long wt[], long long  val[], long long n)
{
// Base Case
if (n == 0 || W == 0)
	return 0;

// If weight of the nth item is more than Knapsack capacity W, then
// this item cannot be included in the optimal solution
if (wt[n-1] > W)
	return knapSack(W, wt, val, n-1);

// Return the maximum of two cases: 
// (1) nth item included 
// (2) not included

else{
    if(mymap.find(pair<long,long>(W,n-1))==mymap.end())
    {
        mymap[pair<long,long>(W,n-1)]=max( val[n-1] + knapSack(W-wt[n-1], wt, val, n-1),
					knapSack(W, wt, val, n-1)
				);
    }
    return  mymap[pair<long,long>(W,n-1)];
} 
}

