int main() {
    ios::sync_with_stdio(false);
    int N, W;
    vector<int> ws(100, 0);
    vector<int> vs(100, 0);

    cin >> N >> W;
    for (int i = 0; i < N; ++i) cin >> ws[i] >> vs[i];

    cout << solve(N, W, ws, vs) << endl;
    return 0;
