int solve(int N, int W, vector<int> &ws, vector<int> &vs)
{
    auto min_w = ws[0];
    vector<vector<int>> vv(4, vector<int>(0));
    for (int i = 0; i < N; ++i) vv[ws[i] - min_w].push_back(vs[i]);
    for (int i = 0; i < 4; ++i) sort(vv[i].begin(), vv[i].end());
    vector<vector<int>> cumvs(4, vector<int>(1, 0));
    int i = 0;
    for (auto vec: vv){
        for (auto v: vec) cumvs[i].push_back(cumvs[i].back() + v);
        ++i;
    }

    int record = 0;
    int cum_w0 = 0;
    for (auto cum_v0: cumvs[0]){
        if (cum_w0 > W) break;
        int cum_w1 = cum_w0;
        cum_w0 += min_w;
        for (auto cum_v1: cumvs[1]){
            if (cum_w1 > W) break;
            int cum_w2 = cum_w1;
            cum_w1 += min_w + 1;
            for (auto cum_v2: cumvs[2]){
                if (cum_w2 > W) break;
                int cum_w3 = cum_w2;
                cum_w2 += min_w + 2;
                for (auto cum_v3: cumvs[3]){
                    if (cum_w3 > W) break;
                    cum_w3 += min_w + 2;
                    record = max(cum_v0 + cum_v1 + cum_v2 + cum_v3, record);
                }
            }
        }
    }
    return record;
}

