vector<long long> V[4] = {{0}, {0}, {0}, {0}};

int main(){
    scanf("%lld%lld%lld%lld", &N, &W, &w, &v);
    w0 = w;
    V[0].push_back(v);
    for(int i = 1; i < N; ++i){
        scanf("%lld%lld", &w, &v);
        V[w - w0].push_back(v);
    }
    for(auto& k : V){
        sort(k.begin() + 1, k.end());
        reverse(k.begin() + 1, k.end());
        partial_sum(k.begin() + 1, k.end(), k.begin() + 1);
    }
    for(int i = V[0].size(); --i >= 0;){
        t = i * w0;
        b = i ? V[0][i] : 0;
        if(t > W)continue;
        for(int j = V[1].size(); --j >= 0;){
            t += j * (w0 + 1);
            b += j ? V[1][j] : 0;
            if(t > W){
                t -= j * (w0 + 1);
                b -= j ? V[1][j] : 0;
                continue;
            }
            for(int k = V[2].size(); --k >= 0;){
                t += k * (w0 + 2);
                b += k ? V[2][k] : 0;
                if(t > W){
                    t -= k * (w0 + 2);
                    b -= k ? V[2][k] : 0;
                    continue;
                }
                b += (W - t) / (w0 + 3) >= 0 ? V[3][min<long long>(V[3].size() - 1, (W - t) / (w0 + 3))] : 0;
                a = max(a, b);
                b -= (W - t) / (w0 + 3) >= 0 ? V[3][min<long long>(V[3].size() - 1, (W - t) / (w0 + 3))] : 0;
                t -= k * (w0 + 2);
                b -= k ? V[2][k] : 0;
            }
            t -= j * (w0 + 1);
            b -= j ? V[1][j] : 0;
        }
    }
    cout << a << endl;
    return 0;
}

