LL v[200];
std::map<std::pair<LL, LL>, LL> dp;

LL rec(LL i, LL j) {
  if (dp.find(std::make_pair(i,j)) != dp.end()) {
    return dp[std::make_pair(i,j)];
  }
  LL val;
  if (i == N) {
    val = 0;
  } else if (j < w[i]) {
    val = rec(i+1, j);
  } else {
    val = std::max(rec(i+1, j), rec(i+1, j-w[i])+v[i]);
  }
  dp[std::make_pair(i,j)] = val;
  return val;
}

