int main() {
    ll N, W, std_num, sub_count, max_count = 0;
    vector<ll> a, b, c, d;
    cin >> N >> W;
    for (int i = 0; i < N; i++) {
        cin >> w[i] >> v[i];
    }
    std_num = w[0];
    for (int i = 0; i < N; i++) {
        if (w[i] == std_num) a.push_back(v[i]);
        else if (w[i] == std_num + 1) b.push_back(v[i]);
        else if (w[i] == std_num + 2) c.push_back(v[i]);
        else d.push_back(v[i]);
    }
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    sort(c.begin(), c.end());
    sort(d.begin(), d.end());

    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());
    reverse(c.begin(), c.end());
    reverse(d.begin(), d.end());

    for (int i = 0; i <= a.size(); i++) {
        for (int j = 0; j <= b.size(); j++) {
            for (int k = 0; k <= c.size(); k++) {
                for (int l = 0; l <= d.size(); l++) {
                    if (std_num * i + (std_num + 1) * j + (std_num + 2) * k + (std_num + 3) * l > W) continue;
                    sub_count = 0;
                    for (int m = 0; m < i; m++) sub_count += a[m];
                    for (int m = 0; m < j; m++) sub_count += b[m];
                    for (int m = 0; m < k; m++) sub_count += c[m];
                    for (int m = 0; m < l; m++) sub_count += d[m];
                    if (sub_count > max_count) {
                        max_count = sub_count;
                    }
                }
            }
        }
    }
    cout << max_count << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

int knapsack(int n, int w, int wt[], int c[])
{
  	int k[n+1][w+1];
  	memset(k, 0, sizeof(k));
	for(int i = 1; i < n+1; i++)
    {
    	for(int j = 1; j < w+1; j++)
        {
        	if(wt[i-1] <= j)
              	k[i][j] = max(c[i-1] + k[i-1][j-wt[i-1]], k[i-1][j]);
          	else
              	k[i][j] = k[i-1][j];
        }
    }
    return k[n][w];
}

