int kagi(int pos, int sisa){
	if (pos == N) return 0;
	if (lho[pos].count(sisa))
		return lho[pos][sisa];
	int best = 0;
	if (sisa >= w[pos])
		best = v[pos] + kagi(pos + 1, sisa - w[pos]);
	best = max(best, kagi(pos + 1, sisa));
	lho[pos][sisa] = best;
	return best;
}

