#include <bits/stdc++.h>

using namespace std;

const int MAX = 1000;

long long n, limit;
long long val[MAX], wt[MAX];

long long knapsack() {
	long long dp[MAX][limit + 1];
	memset(dp, 0, sizeof dp);
	for (int i = 0; i <= n; i++) {
		for (int j = 0; j <= limit; j++) {
			if (i == 0 || j == 0)
				dp[i][j] = 0;
			else if (wt[i - 1] <= j)
				dp[i][j] = max(dp[i - 1][j - wt[i - 1]] + val[i - 1], dp[i - 1][j]);
			else dp[i][j] = dp[i - 1][j];
		}
	}
	return dp[n][limit];
}

int main () {
	scanf("%lld %lld", &n, &limit);
	for (int i = 0; i < n; i++)
		scanf("%lld %lld", &wt[i], &val[i]);
	limit = limit - wt[0];
	for (int i = 1; i < n; i++)
		wt[i] = (wt[i] - wt[0]) + 1;
	wt[0] = 1;
	if (limit < wt[0])
		printf("0\n");
	else printf("%lld\n", knapsack());
	return 0;
}

