int dfs(int pos,int cnt,int lt){
	if(cnt<0){
		if(debug)cout<<"dfs "<<pos<<" "<<cnt<<" "<<lt<<"=-inf"<<endl;
		return -1e9;
	}
	if(cnt==0){
		return 0;
	}
	if(pos==0){
		if(debug)cout<<"dfs "<<pos<<" "<<cnt<<" "<<lt<<"="<<v[pos]<<endl;
		return v[pos];
	}

	if(dp[pos][cnt][lt]!=-1){
		return dp[pos][cnt][lt];
	}

	int ans1,ans2;
	if(lt-d[pos]<0){
		ans1=dfs(pos-1,cnt-2,lt-d[pos]+w[0])+v[pos];
	}else{
		ans1=dfs(pos-1,cnt-1,lt-d[pos])+v[pos];
	}

	ans2=dfs(pos-1,cnt,lt);

	if(debug)cout<<"dfs "<<pos<<" "<<cnt<<" "<<lt<<"="<<max(ans1,ans2)<<endl;
	return dp[pos][cnt][lt]=max(ans1,ans2);
}

