long long cmb(int x, int y){
    if (y == 0) return 1;
    long long res = 1;
    for (int i = 1; i <= y; i++){
        res *= x - i + 1;
        res /= i;
    }
    return res;
}

int main(){
    int n, a, b;
    cin >> n >> a >> b;
    vector<long long> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    sort(v.begin(), v.end(), greater<long long>());
    bool flag = true;
    long long ans = v[0];
    for (int i = 1; i < a; i++){
        if (v[i] != v[i - 1]) flag = false;
        ans += v[i];
    }
    if (flag){
        int cnt = a;
        for (int i = a; i < b; i++){
            if (v[i] == v[a - 1]) cnt++;
            else break;
        }
        cout << setprecision(30) << (double)1.0 * ans / a << endl;
        long long q = pow(2, cnt);
        for (int i = 0; i < a; i++){
            q -= cmb(cnt, i);
        }
        cout << setprecision(30) << q << endl;
        exit(0);
    }
    else if (a == b || v[a] != v[a - 1]) {
        cout << setprecision(30) << (double)1.0 * ans / a << endl;
        cout << setprecision(30) << 1 << endl;
        exit(0);
    }
    else {
        int left = a - 1;
        int right = a;
        while (left > 0){
            if (v[left - 1] == v[a]) left--;
            else break;
        }
        while (right < n - 1){
            if (v[right + 1] == v[a]) right++;
            else break;
        }
        cout << setprecision(30) << (double)1.0 * ans / a << endl;
        cout << setprecision(30) << cmb(right - left + 1, a - left) << endl;
    }
}

