    long long ans = 0;
    ans += (long long)(u % cnt[0]) * k;       u /= cnt[0];
    ans += (long long)(u % cnt[1]) * (k + 1); u /= cnt[1];
    ans += (long long)(u % cnt[2]) * (k + 2); u /= cnt[2];
    ans += (long long)u * (k + 3);
