#define MAX 100000

void solve_dp(int N, int W, int w[], int v[], int dp[][MAX]) {
  for (int j = 0; j <= W; j++) {
    dp[N][j] = 0;
  }
  for (int i = N - 1; i >= 0; i--) {
    for (int j = 0; j <= W; j++) {
      if (j < w[i])
        dp[i][j] = dp[i + 1][j];
      else
        dp[i][j] = max(dp[i + 1][j], dp[i + 1][j - w[i]] + v[i]);
    }
  }
  cout << dp[0][W] << endl;
}


