#define MAX_N 110
#define MAX_W 32000

long long dp[MAX_N][MAX_W];

struct Item {
    long long weight;
    long long value;
    bool operator<(const Item& r) const {
        return value != r.value ? value < r.value : weight > r.weight;
    }
};

int main() {
    long long N, W;
    cin >> N >> W;

    vector<Item> vs(N);
    for (int i=0; i<N; i++) {
        cin >> vs[i].weight >> vs[i].value;
    }
    // 小さいときは普通にdp
    if (vs.at(0).weight <= 310) {
        for (int i=0; i<N; i++) {
            for (int j=0; j<MAX_W; j++) {
                dp[i+1][j] = dp[i][j]; // i個目の要素を使わないとき
                if (j - vs.at(i).weight >= 0) { // i個目の要素を使うとき
                    dp[i+1][j] = max(dp[i+1][j], dp[i][j-vs.at(i).weight] + vs.at(i).value);
                }
            }
        }
        long long ans = 0;
        for (int j=0; j<=W; j++) {
            ans = max(ans, dp[N][j]);
        }
        cout << ans << endl;
    } else {
        sort(vs.rbegin(), vs.rend());
        long long v = 0;
        long long w = 0;
        for (const auto item: vs) {
            if (w + item.weight <= W) {
                v += item.value;
                w += item.weight;
            }
        }
        cout << v << endl;
    }

    return 0;
}

