const int MAX = 1000;

long long n, limit;
long long val[MAX], wt[MAX];

long long knapsack() {
	long long dp[MAX][limit + 1];
	memset(dp, 0, sizeof dp);
	for (int i = 0; i <= n; i++) {
		for (int j = 0; j <= limit; j++) {
			if (i == 0 || j == 0)
				dp[i][j] = 0;
			else if (wt[i - 1] <= j)
				dp[i][j] = max(dp[i - 1][j - wt[i - 1]] + val[i - 1], dp[i - 1][j]);
			else dp[i][j] = dp[i - 1][j];
		}
	}
	return dp[n][limit];
}

int main () {
	scanf("%lld %lld", &n, &limit);
	for (int i = 0; i < n; i++)
		scanf("%lld %lld", &wt[i], &val[i]);
	if (limit > 100000) {
		limit /= 1000;
		for (int i = 0; i < n; i++)
			wt[i] /= 1000;
	}
	printf("%lld\n", knapsack());
	return 0;
}

