ll dp[128][128][305];
// https://atcoder.jp/contests/abc060/submissions/3639903
int main() {
    int N;
    ll W;
    cin >> N >> W;
    vector<ll> weight(N);
    vector<ll> value(N);
    REP(i, N) { cin >> weight[i] >> value[i]; }
    // weight value
    ll ans = 0;
    ll fin = W / weight[0];
    ll finw = W % weight[0];
    ll fw = weight[0];
    for(int i = 0; i < N; i++) {
        weight[i] -= fw;
    }
    dp[0][1][0] = value[0];
    for(int i = 1; i < N; i++) {
        for(int j = 1; j <= i + 1; j++) {
            for(int k = 0; k <= 300; k++) {
                if(i == 0) {
                    continue;
                }
                dp[i][j][k] = dp[i - 1][j][k];
                if(k - weight[i] >= 0) {
                    dp[i][j][k] =
                        max(dp[i][j][k],
                            dp[i - 1][j - 1][k - weight[i]] + value[i]);
                }
            }
        }
    }

    for(int i = 0; i <= N; i++) {
        for(int j = 0; j <= 305; j++) {
            if(fw * i + j > W) {
                continue;
            }
            ans = max(ans, dp[N - 1][i][j]);
        }
    }
    cout << ans << endl;
    return 0;
}

