using ll = long long;

int N, W;
int wmin;
vector<int> V[4];


void solve()
{
    ll vmax = 0;

    ll v0, v1, v2, v3;
    ll w0, w1, w2, w3;
    for(size_t i0 = 0; i0 <= V[0].size(); ++i0) {
        v0 = accumulate(begin(V[0]), begin(V[0])+i0, 0);
        w0 = i0 * wmin;
        for(size_t i1 = 0; i1 <= V[1].size(); ++i1) {
            v1 = accumulate(begin(V[1]), begin(V[1])+i1, 0);
            w1 = i1 * (wmin+1);
            for(size_t i2 = 0; i2 <= V[2].size(); ++i2) {
                v2 = accumulate(begin(V[2]), begin(V[2])+i2, 0);
                w2 = i2 * (wmin+2);
                for(size_t i3 = 0; i3 <= V[3].size(); ++i3) {
#ifdef DEBUG
                    cout << i0 << " " << i1 << " " << i2 << " " << i3 << "\n";
#endif

                    v3 = accumulate(begin(V[3]), begin(V[3])+i3, 0);
                    w3 = i3 * (wmin+3);

                    if(w0 + w1 + w2 + w3 <= W) {
                        vmax = max(vmax, v0 + v1 + v2 + v3);
                    }
                }
            }
        }
    }

    cout << vmax << "\n";
}

