    REP(i, N) {
        int w, v;
        cin >> w >> v;
        if(i == 0) {
            wmin = w;
            V[0].push_back(v);
        }
        else {
            V[w-wmin].push_back(v);
        }
    }
    FOR(i, 0, 4) {
        sort(begin(V[i]), end(V[i]), greater<int>());
    }

    solve();

    return 0;
}

