int rec(int i, int j, int weights[], int values[], int N) {
    int res = 0;
    if (i == N)
    {
        res = 0;
    } else if (j < weights[i])
    {
        res = rec(i+1, j, weights, values, N);
    } else {
        res = max(
            rec(i+1, j, weights, values, N),
            rec(i+1, j-weights[i], weights, values, N) + values[i] );
    }

    return res;
}


