ll getq(multiset<ll, greater<ll>>& q, ll t) {
  ll ret = 0;
  ll cnt = 0;
  for (auto itr = q.begin(); cnt < t; itr++) {
    ret += *itr;
    cnt++;
  }
  return ret;
}

int main() {
  ll n, w;

  cin >> n >> w;

  vll ws(n);
  vll vs(n);

  multiset<ll, greater<ll>> q[4];

  ll tw, tv;
  cin >> tw >> tv;
  ll w0 = tw;
  q[0].insert(tv);
  for (ll i = 1; i < n; i++) {
    cin >> tw >> tv;
    bool chk = false;
    for (ll j = 0; j < 4; j++) {
      if (tw == w0 + j) {
        q[j].insert(tv);
        chk = true;
        break;
      }
    }  // j
    assert(chk);
  }  // i

  ll ans = 0;
  for (ll i = 0; i <= n; i++) {
    if (i > (ll)q[0].size()) continue;
    for (ll j = 0; j <= n; j++) {
      if (j > (ll)q[1].size()) continue;
      for (ll k = 0; k <= n; k++) {
        if (k > (ll)q[2].size()) continue;
        for (ll l = 0; l <= n; l++) {
          if (l > (ll)q[3].size()) continue;
          ll wt = w0 * i + (w0 + 1) * j + (w0 + 2) * k + (w0 + 3) * l;
          if (wt <= w) {
            ll tmp = 0;
            tmp += getq(q[0], i);
            tmp += getq(q[1], j);
            tmp += getq(q[2], k);
            tmp += getq(q[3], l);
            chmax(ans, tmp);
          }
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

