int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int n,w,wi,vi,first_w;

    while(cin>>n>>w){
        // vector<int> vec;
        vector<int> a;
        vector<int> b;
        vector<int> c;
        vector<int> d;

        int c_a=0,c_b=0,c_c=0,c_d=0;

        for(int i=0;i<n;i++){
            cin>>wi>>vi;
            if(i==0) first_w = wi;
            if(wi==first_w){
                a.pb(vi);
                c_a++;
            }
            if(wi==first_w + 1){
                b.pb(vi);
                c_b++;
            }
            if(wi==first_w + 2){
                c.pb(vi);
                c_c++;
            }
            if(wi==first_w + 3){
                d.pb(vi);
                c_d++;
            }
        }

        sort(a.rbegin(),a.rend());
        sort(b.rbegin(),b.rend());
        sort(c.rbegin(),c.rend());
        sort(d.rbegin(),d.rend());

        a.insert(a.begin(), 0);
        b.insert(b.begin(), 0);
        c.insert(c.begin(), 0);
        d.insert(d.begin(), 0);

        for(int i=1;i<a.size();i++){
            a[i] += a[i-1];
        }
        for(int i=1;i<b.size();i++){
            b[i] += b[i-1];            
        }
        for(int i=1;i<c.size();i++){
            c[i] += c[i-1];
        }
        for(int i=1;i<d.size();i++){
            d[i] += d[i-1];
        }

        int ans = -1;
        for(int i=0;i<=c_a;i++){
            for(int j=0;j<=c_b;j++){
                for(int k=0;k<=c_c;k++){
                    for(int l=0;l<=c_d;l++){
                        int x = (first_w*i)+((first_w+1)*j)+((first_w+2)*k)+((first_w+3)*l);
                        if(x>w)continue;
                        ans = max(ans, a[i]+b[j]+c[k]+d[l]);
                    }
                }
            }
        }

        cout<<ans<<endl;
    }
    return 0;
}

