int number_of_item, max_weight;
int w[100], v[100];

int memo[100+1][100+1];

int dp(int num, int weight) {
  if(memo[num][weight] != -1) {
    return memo[num][weight];
  }

  if(num == number_of_item){
   return 0;
  } else if (weight < w[num]) {
    return dp(num+1, weight);
  } else {
    return max(dp(num+1, weight),
               dp(num+1, weight -w[num]) + v[num]);
  }
}

