long long nap(long long i, long long j, vector <long long>w, vector <long long>v,  vector <vector <long long> >&dp) {
    if (dp[i][j] != -1) return dp[i][j];
    long long ans = 0;
    if (i == N) ans = 0;
    else if (j < w[i]) {
        ans = nap(i + 1, j, w, v, dp);
    } else {
        ans = max(nap(i + 1, j, w, v, dp), (nap(i + 1, j - w[i], w, v, dp) + v[i]));
    }
    dp[i][j] = ans;
    return ans;
}

