				if(s[3]>0)
				for(ll l = 0; l<=min(w/(a[0][0]+3),(ll)v[3].size()-1); l++)
				{
					ll y4 = v[3][l];
					ll w5 = l*(s[3]);
					if(w2+w3+w4+w5<=w)
						ans = max(ans,y+y2+y3+y4);
				}
			}
		}
	}
