        int s = N/2;
        vector<P> dp(1 << s);
        for(int i=0; i<(1 << s); ++i) {
            ll sw = 0, sv = 0;
            for(int j=0; j<s; ++j) {
                if(i >> j & 1) {
                    sw += w[j];
                    sv += v[j];
                }
            }
            dp[i] = make_pair(sw, sv);
        }
        sort(dp.begin(), dp.end());
        int m = 1;
        for(int i=1; i<1<<s; ++i) {
            if(dp[m-1].second < dp[i].second) {
                dp[m++] = dp[i];
            }
        }
        ll res = 0;
        for(int i=0; i<1<<(N - s); ++i) {
            ll sw = 0, sv = 0;
            for(int j=0; j<N-s; ++j) {
                if(i >> j & 1) {
                    sw += w[j+s];
                    sv += v[j+s];
                }
            }
            if(sw <= W) {
                ll tv = (lower_bound(dp.begin(), dp.begin()+m, make_pair(W-sw, INF)) - 1)->second;
                res = max(res, sv+tv);
            }
        }
        cout << res << endl;
    } else if(*max_element(v.begin(), v.end()) <= 1000) {
        ll V = accumulate(v.begin(), v.end(), 0LL);
        vector<ll> dp(V+1, INF);
        dp[0] = 0;
        for(int i=0; i<N; ++i) {
            for(int j=V-v[i]; j>=0; --j) {
                dp[j+v[i]] = min(dp[j+v[i]], dp[j] + w[i]);
            }
        }
        for(int i=V; i>=0; --i) {
            if(dp[i] <= W) {
                cout << i << endl;
                return 0;
            }
        }
    } else {
        vector<ll> dp(W+1, -1);
        dp[0] = 0;
        for(int i=0; i<N; ++i) {
            for(int j=W-w[i]; j>=0; --j) {
                if(dp[j] == -1) {
                    continue;
                }
                dp[j+w[i]] = max(dp[j+w[i]], dp[j] + v[i]);
            }
        }
        cout << *max_element(dp.begin(), dp.end()) << endl;
    }
}

