int knapsack(int n, int weight)
{
	int pat1, pat2;

	if (n >= N) return 0;

	pat1 = knapsack(n + 1, weight);
	if (weight + w[n] <= W) {
		pat2 = v[n] + knapsack(n + 1, weight + w[n]);
	}
	else pat2 = 0;

	return max(pat1, pat2);
}

