      // i 番目の品物を選ぶ場合
      if (sum_w - w[i] >= 0) {
          dp[i+1][sum_w] = max(dp[i+1][sum_w], dp[i][sum_w - w[i]] + v[i]);
      }

      // i 番目の品物を選ばない場合
      dp[i+1][sum_w] = max(dp[i+1][sum_w], dp[i][sum_w]);
    }
  }

  cout << dp[N][W] << endl;

}

