#define REP(i, n) FOR(i, 0, n)

int N, W;
int VS[101];
int WS[101];


int knapsack(int n, int w)
{
    // 品物を入れないなら価値0
    if(n == 0) return 0;

    // 容量0なら価値0
    if(w == 0) return 0;

    // n番目の品物を入れるかどうか
    // まず、w < WS[n] ならそもそも入れられない
    //   入れない場合、knapsack(n-1, w) が最大価値
    //   入れる場合、VS[n] + knapsack(n-1, w-WS[n]) が最大価値
    if(w < WS[n]) {
        return knapsack(n-1, w);
    }
    else {
        return max(knapsack(n-1, w), VS[n] + knapsack(n-1, w-WS[n]));
    }
}

void solve()
{
    int result = knapsack(N, W);
    cout << result << "\n";
}

int main()
{
    cin >> N >> W;
    REP(i, N) {
        cin >> WS[i+1] >> VS[i+1];
    }

    solve();

    return 0;
}

