                    if (dp[i - 1].find(k + w[i - 1]) != dp[i - 1].end())
                    {
                        dp[i][k + w[i - 1]] = max(dp[i - 1][k + w[i - 1]], dp[i - 1][k] + v[i - 1]);
                    }
                    else
                    {
                        dp[i][k + w[i - 1]] = dp[i - 1][k] + v[i - 1];
                    }

                    dp[i][k] = max(dp[i - 1][k], dp[i][k]);
                }
            }
        }
    }
    ll ans = 0;
    REPV(it, dp[N])
    {
        if (it->first <= W)
        {
            ans = max(ans, it->second);
        }
    }

    cout << ans << endl;
}

