int knapsack(int numberOfItem, int maxWeight, int weightOfItems[],
             int valueOfItems[]) {
  map<pair<int, int>, int> mm;

  function<int(int, int)> _knapsack = [&](int i, int j) -> int {
    auto p = mp(i, j);
    if (mm.count(p)) {
      return mm[p];
    }
    int r;
    if (i == numberOfItem) {
      r = 0;
    } else if (j < weightOfItems[i]) {
      r = _knapsack(i + 1, j);
    } else {
      r = max(_knapsack(i + 1, j),
              _knapsack(i + 1, j - weightOfItems[i]) + valueOfItems[i]);
    }
    mm[p] = r;
    return r;
  };

  return _knapsack(0, maxWeight);
}

