int N;
long w[MAX_N], v[MAX_N];
// メモ化テーブル
typedef pair<int,long> P;
map<P,long> dp;

// i番目以降の品物から重さの総和が
// j以下となるように選ぶ
// 戻り値: その選び方をしたときの価値の総和
// j: 残りの容量 (重さ)
long rec(int i, long j)
{
  // メモを利用
  if (dp.count(P(i,j))) return dp[P(i,j)];

  long res;
  if (i == N) res = 0;
  // 商品 i は入らない
  // 他の商品が入るか試す
  else if (j < w[i]) res = rec(i+1, j);
  // 商品 i を入れる場合・入れない場合を両方とも試して、
  // 大きい方をとる
  else res = max(rec(i+1, j),
                 rec(i+1, j - w[i]) + v[i]);
  dp[P(i,j)] = res;
  return res;
}

int main()
{
  long W;
  cin >> N >> W;
  REP(i,0,N) cin >> w[i] >> v[i];

  long res = rec(0, W);
  cout << res << endl;

  return 0;
}

