vector<int> weight, value;

int max_v(int next, int remain) {
	if (next == weight.size() || remain <= 0) {
		return 0;
	} else if (remain < weight[next]) {
		return max_v(next+1, remain);
	} else {
		int yes = max_v(next+1, remain - weight[next]) + value[next];
		int no = max_v(next+1, remain);
		return (yes > no ? yes : no);
	}
}

