LL val(LL i, LL w){
	auto p = make_pair(i, w);
	if(M.count(p) != 0){
		return M[p];
	}
	LL ret;
	if(i == 0){
		if(VW[0] <= w){
			ret = VV[0];
		}
		else{
			ret = 0;
		}
		M[make_pair(i, w)] = ret;
		return ret;
	}
	if(VW[i] > w){
		ret = val(i-1, w);
	}
	else{
		ret = max(val(i-1, w-VW[i]) + VV[i], val(i-1, w));
	}
	M[make_pair(i, w)] = ret;
	return ret;
}

