        // cout << ((w-1)/cycle+1)*W[1]+(w-1)%cycle << endl;
        if(((w-1)/cycle+1)*W[1]+(w-1)%cycle<=maxW) {
            if((N-1)%2==0) {
                ans = max(ans, dp[1][w]);
            } else {
                ans = max(ans, dp[0][w]);
            }
        }
    }

    cout << ans << endl;

