int rec(int i, int k, int j) {
        if (k <= 0 || j <= 0) return 0;
        if (dp[i][k][j] >= 0) {
                return dp[i][k][j];
        }
        int res;
        if (i == n) {
                res = 0;
        } else if (j < w[i]) {
                res = rec(i + 1, k, j);
        } else {
                res = max(rec(i + 1, k, j), rec(i + 1, k - 1, j - w[i]) + v[i]);
        }
        return dp[i][k][j] = res;
}

