void solve(){

    fill(dp[0],dp[0]+ARRAY_MAX*ARRAY_MAX+1,INF);
    dp[0][0] = 0;
    for(int i = 0;i < n;i++){
        for(int j = 0;j <= ARRAY_MAX*ARRAY_MAX;j++){
