const int mxN = 100;
int n, W;
int w[mxN], v[mxN];


void solve() {
    map<int, vt<int>> mp;

    read(n, W);


    FOR(n) {
        read(w[i], v[i]);
        mp[w[i]].pb(v[i]);
    }

    EACH(x, mp) {
        sort(all(x.second), greater<int>());
    }

    if (mp.size() == 1) {
        int cnt = W / w[0];

        int val = 0;
        FOR(i, min(cnt, n)) {
            val += v[i];
        }
        print(val);
        return;
    }

    if (mp.size() == 2) {
        int ans = 0;

        auto it = mp.begin();
        int x = it->first;
        it++;
        int y = it->first;


        FOR(mp[x].size() + 1) {
            FOR(j, mp[y].size() + 1) {

                int wt = i * x + j * y;

                if (wt > W) continue;
                int val = 0;

                FOR(z, 0, i) {
                    val += mp[x][z];
                }

                FOR(z, 0, j) {
                    val += mp[y][z];
                }

                umax(ans, val);


            }
        }

        print(ans);
        return;
    }

    int ans = 0;

    FOR(mp[w[0]].size() + 1) {
        FOR(j, mp[w[1]].size() + 1) {
            FOR(k, mp[w[2]].size() + 1) {
                int wt = i * w[0] + j * w[1] + k * w[2];

                if (wt > W) continue;
                int val = 0;

                FOR(z, 0, i) {
                    val += mp[w[0]][z];
                }

                FOR(z, 0, j) {
                    val += mp[w[1]][z];
                }

                FOR(z, 0, k) {
                    val += mp[w[2]][z];
                }

                umax(ans, val);

            }
        }
    }

    print(ans);

}

int32_t main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    int tt = 1;
    //read(tt);
    FOR(tt) {

        solve();

    }

}

