ll DP(ll num, ll onenum, ll weight) {
	if (num*mini + weight > W) { return -INF; }
	if (num == n) { return 0; }
	if (dp[num][onenum][weight]>=0) { return dp[num][onenum][weight]; }
	ll cnt = 0; 
