int rec(int i, int j) {
    int res = 0;
    if (i == w.size()) {
        res = 0;
    }
    else if (j < w[i]) {
        res = rec(i+1, j);
    }
    else {
        res = rec(i+1, j);
        int sum = 0;
        for (int k=0; k<v[i].size(); ++k) {
            sum += v[i][k];
            if (j >= w[i]*(k+1)) {
                res = max(res, rec(i+1, j-w[i]*(k+1))+sum);
            }
        }
    }
    return res;
}

