		for (int j = 0; j <= v[1].size(); j++) {
			for (int k = 0; k <= v[2].size(); k++) {
				for (int l = 0; l <= v[3].size(); l++) {
					LL num = 0;
					LL cost = 0;
					if (i != 0) {
						num += v[0][i - 1];
						cost += i*minw;
					}
					if (j != 0) {
						num += v[1][j - 1];
						cost += j*(minw + 1);
					}
					if (k != 0) {
						num += v[2][k - 1];
						cost += k*(minw + 2);
					}
					if (l != 0) {
						num += v[3][l - 1];
						cost += l*(minw + 3);
					}
					if (cost <= w) {
						ans = max(ans, num);
					}
				}
			}
		}
	}
	cout << ans << endl;
	system("pause");
}

