const int MAX_N = 1000;
const int MAX_W = 1000000000; 
int n, W;
int w[MAX_N], v[MAX_N];
int dp2[MAX_N + 1][MAX_W + 1];
void solve_dp2() {
  for (int j = 0; j <= W; j++) dp2[n][j] = 0;
  for (int i = n - 1; i >= 0; i--) {
    for (int j = 0; j <= W; j++) {
      if (j < w[i])
        dp2[i][j] = dp2[i + 1][j];
      else
        dp2[i][j] = max(dp2[i + 1][j], dp2[i + 1][j - w[i]] + v[i]);
    }
  }
  cout << dp2[0][W] << endl;
}
int main() {
  cin >> n >> W;
  for (int i = 0; i < n; i++) {
    cin >> w[i] >> v[i];
  }
  solve_dp2();
  return 0;
}

