int main(void) {
    int N,W;cin>>N>>W;
    // N個選んだ中で合計W以下の重さの荷物の価値の総和の最大値
    int dp[N+1][W+1];

    // 重さと価値
    int w[N+1],v[N+1];
    w[0] = 0;
    v[0] = 0;
    for (int i = 0; i <= W; i++) dp[0][i] = 0;
    for (int i = 0; i <= N; i++) dp[i][0] = 0;
    for (int i = 1; i <= N; i++) {
        cin>>w[i];cin>>v[i];
    }
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= W; j++) {
            if (j >= w[i]) {
                dp[i][j] = max(dp[i-1][j-w[i]] + v[i], dp[i-1][j]);
            } else dp[i][j] = dp[i-1][j];
        }
    }
    cout << dp[N][W] << endl;
    return 0;
}

