map<pair<ll,ll>,ll> mp;
ll solve(ll pos,ll wr) {
  if(wr < 0) return -INF;
  if(pos == N) {
     if(wr >= 0) return 0;
  }
  if(mp.find(make_pair(pos,wr)) != mp.end()) return mp[make_pair(pos,wr)];
  ll res = 0;
  res = v[pos] + solve(pos+1,wr-w[pos]);
  res = max(res,solve(pos+1,wr));
  mp[make_pair(pos,wr)] = res;
  return res;
}
