void compute(int &maxValue, vector<int> &path) {
	for (int w = 0; w <= weight; w++) {
		C[0][w] = 0;
		G[0][w] = DIAGONAL;
	}

	for (int i = 1; i <= n; i++) C[i][0] = 0;

	for (int i = 1; i <= n; i++) {
		for (int w = 1; w <= weight; w++) {
			if (items[i].weight <= w) {
				if (items[i].value + C[i - 1][w - items[i].weight] > C[i - 1][w]) {
					C[i][w] = items[i].value + C[i - 1][w - items[i].weight];
					G[i][w] = DIAGONAL;
				} else {
					C[i][w] = C[i - 1][w];
					G[i][w] = LEFT;
				}
			} else {
				C[i][w] = C[i - 1][w];
				G[i][w] = LEFT;
			}
		}
	}

	maxValue = C[n][weight];

