#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#define NMAX 100
#define WMAX 1000000
#define DIAGONAL 1
#define TOP 0

using namespace std;

struct Item {
    char value, weight;
};

char N, W;
Item items[NMAX + 1];
vector<vector<char>> C(NMAX + 1, vector<char>(WMAX + 1, 0)), G(NMAX + 1, vector<char>(WMAX + 1, 0));

void compute(char &maxValue, vector<char> &selection) {
    for (char w = 0; w <= W; w++)
    {
        C[0][w] = 0;
        G[0][w] = DIAGONAL;
    }

    for (char i = 1; i <= N; i++) C[i][0] = 0;

    for (char i = 1; i <= N; i++)
    {
        for (char w = 0; w <= W; w++)
        {
            C[i][w] = C[i - 1][w];
            G[i][w] = TOP;
            if (items[i].weight > w) continue;
            if (items[i].value + C[i - 1][w - items[i].weight] > C[i - 1][w])
            {
                C[i][w] = items[i].value + C[i - 1][w - items[i].weight];
                G[i][w] = DIAGONAL;
            }
        }
    }

    maxValue = C[N][W];
    selection.clear();
    for (char i = N, w = W; i >= 1; i--)
    {
        if (G[i][w] == DIAGONAL)
        {
            selection.push_back(i);
            w -= items[i].weight;
        }
    }

    reverse(selection.begin(), selection.end());
}

void input() {
    cin >> N >> W;
    for (char i = 1; i <= N; i++)
    {
        cin >>   items[i].weight>>items[i].value;
    }
}

int main() {
    char maxValue;
    vector<char> selection;
    input();
    compute(maxValue, selection);

    cout << maxValue << endl;
    return 0;
}

