void knapsack_01(int n,int W,vector<pair<int,int>>v)
{
    int m[n+1][W+1];
    for(int i=0;i<=n;i++)
    {
        for(int j=0;j<=W;j++)
        {
            if(i==0||j==0)
                m[i][j]=0;
            else if(v[i].first>j)
                m[i][j]=m[i-1][j];
            else
                m[i][j]=max(m[i-1][j],v[i].second+m[i-1][j-v[i].first]);
        }
    }
    cout<<m[n][W]<<endl;
}

