// i番目まで見たときの、j個使って重さの総和がk以下のときの価値の最大値が入る。
// 実際の重さの総和は、(j * sub + k)   ←これとWを比較してdpテーブルを埋める。
ll dp[105][105][310];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, W;
    cin >> n >> W;
    vector<int> w(n), v(n);
    int sub;
    for(int i = 0; i < n; ++i){
        cin >> w[i] >> v[i];
        if(i == 0){
            if(W < w[0]){
                cout << 0 << endl;
                return 0;
            }
            sub = w[0];
        }
        w[i] -= sub;
    }

    int limit = 0;
    // dpテーブルを埋める
    for(int i = 0; i < n; ++i){
        limit += w[i];

        for(int j = 0; j < i + 1; ++j){     // (i+1)番目を見ているときの取れる個数の最大値は(i+1)個
            for(int k = 0; k <= n * 3; ++k){
                // (i+1)番目を使わない場合
                dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k]);

                // (i+1)番目を使う場合
                if(k + w[i] <= limit && (j + 1) * sub + k + w[i] <= W){
                    dp[i + 1][j + 1][k + w[i]] = max(dp[i + 1][j + 1][k + w[i]], dp[i][j][k] + v[i]);
                }
            }
        }
    }

    ll res = 0;
    for(int i = 1; i <= n; ++i){
        for(int j = 0; j <= i; ++j){
            for(int k = 0; k <= n * 3; ++k){
                if(j * sub + k <= W){
                    res = max(res, dp[i][j][k]);
                }
            }
        }
    }
    cout << res << endl;
}

