ll dp[101][1000000001];

ll solve(ll i, ll j)
{
    if (dp[i][j] >= 0)
        return dp[i][j];
    ll res;
    if (i == n)
        res = 0;
    else if (j < w[i])
    {
        res = solve(i + 1, j);
    }
    else
    {
        res = max(solve(i + 1, j), solve(i + 1, j - w[i]) + v[i]);
    }
    return dp[i][j] = res;
}

