	unordered_map<int,int> weightvalue;
	for (int i = 0; i < N; ++i) {
		cin >> weights[i] >> values[i];
		weightvalue[values[i]] = weights[i];
	}

	sort(values, values + N);
	long long int value_result = 0, weight_final = 0, max_value = 0;

	for (int i = 1; i <= N; ++i) {
		for (int j = N-i; j >= 0; --j) {
			if (weight_final + weightvalue[values[j]] <= W) {
				value_result += values[j];
				weight_final += weightvalue[values[j]];
			}
		}

		if (value_result > max_value) {
			max_value = value_result;
		}
		value_result = 0;
		weight_final = 0;
	}

	cout << max_value;
	return 0;
}

