map<pair<long long, long long>, long long> memo;

long long rec(long long W, long long weight[], long long value[], long long n){

	if (n < 0) {
		return 0;
	}

	pair<long long, long long> p = make_pair(W, n);

	if (memo.find(p) != memo.end()){
		return memo[p];
	}
	long long ret = 0;
	if (W < weight[n]){
		ret = rec(W, weight, value, n-1);
	} else {
		ret = max(
			value[n] + rec(W - weight[n], weight, value, n-1),
			rec(W, weight, value, n-1)
			);
	}

	memo[p] = ret;
	return ret;
}

