      for(int k=0; k<N+1; k++){
        dp[i][j][k] = INF;
      }
    }
  }

  for(int i=0; i<N; i++){
    int64_t x = vec[i][0] - W_START;
    int64_t y = vec[i][1];
    if(i == 0){
      dp[i][x][1] = y;
    }
    else{
      dp[i][x][1] = max(dp[i][x][1], y);
      for(int j=0; j<W_MAX; j++){
        for(int k=0; k<N+1; k++){
          if(dp[i-1][j][k] != INF){
            dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k]);
            dp[i][j+x][k+1] = max(dp[i][j+x][k+1], dp[i-1][j][k] + y);
          }
        }
      }
    }
  }

  int64_t ans = 0;
  for(int i=0; i<=W_MAX; i++){
    for(int j=0; j<N+1; j++){
      if(i + j*W_START <= W){
        ans = max(ans,dp[N-1][i][j]);
      }
    }
  }
  cout << ans << endl; 
}

