using namespace std;

int Search(int W, int a, vector<vector<int>> &d, const vector<int> &l, vector<int> &k) {
	int i, ans = 0, w = 0;
	for (i = 0; i < 4; i++) {
		ans += d[i][k[i]];
		w += (a + i) * k[i];
	}
	if (W < w)
		return 0;
	for (i = 0; i < 4; i++) {
		if (l[i] > k[i]) {
			k[i]++;
			ans = max(ans, Search(W, a, d, l, k));
			k[i]--;
		}
	}
	return ans;
}

