int n, W;

int w[MAX_N], v[MAX_N];

int rec(int i, int j) {
	int res;
	if (i == n) {
		res = 0;
	}
	else if (j < w[i]) {

		res = rec(i + 1, j);
	}
	else {

		res = max(
			rec(i + 1, j),
			rec(i + 1, j - w[i]) + v[i]
		);
	}
	return res;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> n >> W;

	for (int i = 0; i < n; i++)
		cin >> w[i] >> v[i];

	cout << rec(0, W) << endl;

	return 0;
}

