using namespace std;
const int MAX_N = 100;
int N,W;
int w[MAX_N],v[MAX_N];
int dp[MAX_N+1][MAX_N+1];

int rec(int i,int j){
	if (dp[i][j] >= 0){
		// すでに訪れた計算結果なら、それを返せばよい
		return dp[i][j];
	}

	int res;
	if (i == N){
		res = 0;
	}else if(j < w[i]){
		res = rec(i+1,j);
	}else{
		//入れる場合と入れない場合を試す
		res = max(rec(i+1,j), rec(i+1,j-w[i])+ v[i]);
	}
	dp[i][j] = res;
	return res;
}

void solve(){
	memset(dp,-1,sizeof(dp));
	cout << rec(0,W) << endl;
}

int main(){
	cin >> N >> W;
	REP(i,N){
		cin >> w[i] >> v[i];
	}
	solve();
}

