const int N = 101;
int n, W, arr[N], v[N];
map < long long , int > dp[N];

int call(int i, long long w)
{
    if(i == n)
        return 0;
    if(dp[i].find(w) != dp[i].end())
        return dp[i][w];
    int ret = call(i + 1, w);
    if(w + arr[i] <= W)
        ret = max(ret, v[i] + call(i + 1, w + arr[i]));
    return dp[i][w] = ret;
}

int main()
{
    cin>>n>>W;
    for(int i=0;i<n;i++)
    {
        cin>>arr[i];
        cin>>v[i];
        dp[i].clear();
    }
    printf("%d\n", call(0, 0));
    return 0;
}

