	int ret = 0;
	LL sum = a * minwt + b * (minwt + 1) + c * (minwt + 2) + d * (minwt + 3);
	if(sum > W)
	{
		ret = max(ret, MPV(a - 1, b, c, d));
		ret = max(ret, MPV(a, b - 1, c, d));
		ret = max(ret, MPV(a, b, c - 1, d));
		ret = max(ret, MPV(a, b, c, d - 1));
	}
	else
	{
		if(a > 0) ret += A[a - 1];
		if(b > 0) ret += B[b - 1];
