using namespace std;

const int MAX_N = 100;
const long MAX_W = (long)1e9;

int N;
long w[MAX_N], v[MAX_N];

// i番目以降の品物から重さの総和が
// j以下となるように選ぶ
// 戻り値: その選び方をしたときの価値の総和
// j: 残りの容量 (重さ)
long rec(int i, long j)
{

  long res;
  if (i == N) res = 0;
  // 商品 i は入らない
  // 他の商品が入るか試す
  else if (j < w[i]) res = rec(i+1, j);
  // 商品 i を入れる場合・入れない場合を両方とも試して、
  // 大きい方をとる
  else res = max(rec(i+1, j),
                 rec(i+1, j - w[i]) + v[i]);
  return res;
}

