void dfs(int x, int ww, int v)
{
    if (v > ans) ans = v;
	if (x > totw) return;

	int i, t=min(w_id[x + 1] - 1, w_id[x] + ww / w[x] - 1);
	for (i = t; i >= w_id[x]; i--)
	   v += a[i].second;
	ww -= (t - w_id[x] + 1) * w[x];
	for (i = t; i >= w_id[x]; i--)
	   {
	       dfs(x + 1, ww, v);
	       v -= a[i].second;
	       ww += w[x];
	   }
	dfs(x + 1, ww, v);
}

