	for (i = n >> 1; i >= 1; i--) swap(a[i], a[n - i + 1]);
	a[n + 1].first = -1;
	i = 1;
	while (i <= n)
	{
	    w_id[++totw] = i;
	    w[totw] = a[i].first;
	    j = i;
	    while (a[j + 1].first == a[i].first) j++;
	    i = j + 1;
    }
    w_id[totw + 1] = n + 1;
	dfs(1, m, 0);
	printf("%d\n", ans);
	return 0;
}

