            rep(j, w.size()) {
                if (w[j] == wi) {
                    v[j].push_back(vi);
                    f=false;
                }
            }
            if (f) {
                w.push_back(wi);
                v[w.size()-1].push_back(vi);
            }
        }
    }
    rep(i, w.size()) {
        sort(v[i].begin(), v[i].end(), greater<ll>());
