	cin >> wm >> wv[0][0];
	ws[0] ++;
	for (int i = 1;i < n;i ++) {
		cin >> wc;
		cin >> wv[wc-wm][ws[wc-wm]];
		ws[wc-wm] ++;
	}
	for (int i = 0;i < PATURN;i ++) {
		sort(wv[i], wv[i]+ws[i]);
		s[i][0] = 0;
		for (int j = 0;j < ws[i];j ++) {
			s[i][j+1] = s[i][j] + wv[i][j];
		}
	}
	int ret = 0;
	for (int i = 0;i <= ws[0];i ++) {
		if (wm*i<=w) ret = max(ret, knapsack(w, wm*i, wm, ws, wv, s, 1, s[0][i]));
	}
	cout << ret;
}

