using namespace std;
int solve(int w, vector<int> wt, vector<int> val)
{
	long long dp[w + 1];
	memset(dp,0,sizeof(dp));
	for(int i =0;i<val.size();i++)
	{
		for(int j = w; j >= wt[i]; j--)
			dp[j] = max(dp[j], val[i] + dp[j - wt[i]]);
	}
	return dp[w];
}
int main()
{
	int n, w;
	cin>>n>>w;
	vector<int> wt, val;
	for(int i =0;i<n;i++)
	{
		int a, b;
		cin>>a>>b;
		wt.push_back(a);
		val.push_back(b);
	}
	cout<<solve(w,wt,val);
}

