using namespace std;

typedef long long ll;

const int INF = 1e9;
const ll LLINF = 1e18;
const ll MOD = (ll)1e9 + 7;

int main()
{
  int N; scanf("%d", &N);
  ll W; scanf("%lld", &W);

  vector<vector<ll>> items(4, vector<ll>());
  for (int i = 0; i < 4; ++i) { items[i].push_back(0); }
  ll w0, w;
  ll v;
  scanf("%lld %lld", &w0, &v);
  items[0].push_back(v);
  for (int i = 1; i < N; ++i) {
    scanf("%lld %lld", &w, &v);
    items[w - w0].push_back(v);
  }
  for (int i = 0; i < 4; ++i) {
    sort(items[i].begin() + 1, items[i].end(), greater<ll>());
    for (int j = 1; j < (int)items[i].size(); ++j) {
      items[i][j] += items[i][j - 1];
    }
  }

  ll ans = 0;
  for (int i = 0; i < (int)items[0].size(); ++i) {
    ll a = i * w0;
    for (int j = 0; j < (int)items[1].size(); ++j) {
      ll b = j * (w0 + 1);
      if (a + b > W) { break; }
      for (int k = 0; k < (int)items[2].size(); ++k) {
        ll c = k * (w0 + 2);
        if (a + b + c > W) { break; }
        for (int l = 0; l < (int)items[3].size(); ++l) {
          ll d = l * (w0 + 3);
          if (a + b + c + d > W) { break; }
          ll val = items[0][i] + items[1][j] + items[2][k] + items[3][l];
          ans = max(ans, val);
        }
      }
    }
  }
  printf("%lld\n", ans);
  return 0;
}

