int func(int i, int j, int a, int b, int c, int d) {
	int res;
	/*if (memo[i][j] != 0)
		return memo[i][j];*/
	if (i == N)
		res = 0;
	else if (j < w[i])
		res = func(i+1,j,a,b,c,d);
	else {
		if ((w[i] == w[0])&& a != 0) {
			a -= 1;
			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b, c, d) + v[i]);
		}
		else if ((w[i] == w[0] + 1)&& b != 0) {
			b -= 1;
			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b, c, d) + v[i]);
