	ll N = 0, W = 0,k = 0;
	ll w[100] = { 0 }, v[100] = { 0 };
	ll m[100][500] = { 0 };
	ll n[100][500] = { 0 };

	scanf("%lld%lld", &N, &W);
	for (long long i = 0; i < N; i++)
		scanf("%lld%lld", &w[i], &v[i]);
	k = w[0];
	for (int i = N - 1; i >= 0; i--)
		w[i] -= w[0] - 1;

	for (ll i = 0; i < N; i++) {
		m[i + 1][w[i]] = v[i];
		n[i + 1][w[i]] = 1;
		for (ll j = 1; j <= 500; j++) {
			if (m[i][j] != 0) {
				if (m[i + 1][j] < m[i][j] && W >= j + n[i][j] * (k - 1)) {
					m[i + 1][j] = m[i][j];
					n[i + 1][j] = n[i][j];
				}
				if (W >= j + n[i][j] * (k - 1)) {
					m[i + 1][j + w[i]] = m[i][j] + v[i];
					n[i + 1][j + w[i]] = n[i][j] + 1;
				}

			}
		}
	}

	ll max = 0;
	for (int i = 0; i <= 500; i++)
		if (max < m[N][i] && W >= i + n[N][i] * (k - 1))
			max = m[N][i];

	printf("%d\n", max);
	return 0;
}

