typedef long long ll;
// i番目まで見たときの、j個使って重さの総和がk以下のときの価値の最大値が入る。
// 実際の重さの総和は、(j * sub + k)   これとWを比較してdpテーブルを埋める。
ll dp[105][105][600];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, W;
    cin >> n >> W;
    vector<int> w(n), v(n);
    int sub;
    for(int i = 0; i < n; ++i){
        cin >> w[i] >> v[i];
        if(i == 0){
            if(W < w[0]){
                cout << 0 << endl;
                return 0;
            }
            sub = w[0];
        }
        w[i] -= sub;
    }

    // dpテーブルを埋める三重ループ O(n^3)
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < i + 1; ++j){
            for(int k = 0; k <= n * 5; ++k){
                if(j * sub > W)     continue;

                // (i+1)番目を使わない場合
                dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k]);

                // (i+1)番目を使う場合
                if(k >= w[i] && (j + 1) * sub + k <= W){
                    dp[i + 1][j + 1][k] = max(dp[i + 1][j + 1][k], dp[i][j][k - w[i]] + v[i]);
                }
            }
        }
    }

    ll res = 0;
    for(int i = 0; i <= n; ++i){
        for(int j = 0; j <= n * 3; ++j){
            if(i * sub + j <= W){
                res = max(res, dp[n][i][j]);
            }
        }
    }
    cout << res << endl;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#define NMAX 100
#define WMAX 1000000
#define DIAGONAL 1
#define TOP 0

using namespace std;

struct Item {
    unsigned int value, weight;
};

unsigned int N, W;
Item items[NMAX + 1];
vector<vector<unsigned int>> C(NMAX + 1, vector<unsigned int>(WMAX + 1, 0)), G(NMAX + 1, vector<unsigned int>(WMAX + 1, 0));

void compute(unsigned int &maxValue, vector<unsigned int> &selection) {
    for (unsigned int w = 0; w <= W; w++)
    {
        C[0][w] = 0;
        G[0][w] = DIAGONAL;
    }

    for (unsigned int i = 1; i <= N; i++) C[i][0] = 0;

    for (unsigned int i = 1; i <= N; i++)
    {
        for (unsigned int w = 0; w <= W; w++)
        {
            C[i][w] = C[i - 1][w];
            G[i][w] = TOP;
            if (items[i].weight > w) continue;
            if (items[i].value + C[i - 1][w - items[i].weight] > C[i - 1][w])
            {
                C[i][w] = items[i].value + C[i - 1][w - items[i].weight];
                G[i][w] = DIAGONAL;
            }
        }
    }

    maxValue = C[N][W];
    selection.clear();
    for (unsigned int i = N, w = W; i >= 1; i--)
    {
        if (G[i][w] == DIAGONAL)
        {
            selection.push_back(i);
            w -= items[i].weight;
        }
    }

    reverse(selection.begin(), selection.end());
}

void input() {
    cin >> N >> W;
    for (unsigned int i = 1; i <= N; i++)
    {
        cin >>   items[i].weight>>items[i].value;
    }
}

int main() {
    unsigned int maxValue;
    vector<unsigned int> selection;
    input();
    compute(maxValue, selection);

    cout << maxValue << endl;
    return 0;
}

