ll weight[sz],cost[sz],dp[sz][sz*sz*sz],cap,n;

ll fun(ll pos, ll w)
{
    if(pos==(n+1))
        return 0;

    if(dp[pos][w]!=-1)
        return dp[pos][w];

    ll profit1;

    if(w+weight[pos]<=cap)
        profit1=cost[pos]+fun(pos+1, w+weight[pos]);

    else
        profit1=0;

    ll profit2=fun(pos+1, w);

    ll r=max(profit1, profit2);

    return dp[pos][w]=r;
}

