using namespace std;

int main()
{
    int64_t N, W;
    std::cin >> N >> W;

    struct Material {
        int64_t w;
        int64_t v;
    };

    std::vector<Material> M;
    for (decltype(N) i = 0; i < N; ++i) {
        Material t;
        std::cin >> t.w >> t.v;
        M.push_back(t);
    }

    std::vector<std::unordered_map<int64_t, int64_t>> memo(N+1);

    auto f = [N, W, &M, &memo](auto F, int64_t n, int64_t w) -> int64_t {
        if (memo[n].count(w) == 1) {
            return memo[n][w];
        }

        if (n == N) {
            memo[n][w] = 0;
        }
        else if (w + M[n].w > W) {
            memo[n][w] = F(F, n+1, w);
        }
        else {
            memo[n][w] = std::max(F(F, n+1, w), F(F, n+1, w+M[n].w) + M[n].v);
        }
        return memo[n][w];
    };

    auto v = f(f, 0, 0);

    std::cout << v << std::endl;

    return 0;
}

