ll N;
ll W;
ll w[100];
ll v[100];
ll dp[100 + 1][100 + 1];

ll DP(ll i, ll j) {	//i番目以降重さj以下
	if (dp[i][j] != -1) {
		return dp[i][j];
	}
	ll res;
	if (i == N) {
		res = 0;
	}
	else if (j < w[i]) {
		res = DP(i + 1, j);
	}
	else {
		res = max(DP(i + 1, j), DP(i + 1, j - w[i]) + v[i]);
	}
	return dp[i][j] = res;
}

int main() {
	cin.sync_with_stdio(false);
	cin >> N >> W;

	rep(i, N) {
		cin >> w[i] >> v[i];
		if (W >= w[0]) {
			w[i] = w[i] - (w[0] - 1);
			if (i == 0) {
				W = W - (w[0] - 1);
			}
		}
		else {
			w[i] = w[i]-W+1;
			W = 1;
		}
	}

	memset(dp, -1, sizeof(dp));

	cout << DP(0, W) << endl;
