int dfs(int now, int weight) {
	if (now == 100) return 0;
	if (dp[now].count(weight)) return dp[now][weight];
	int res = dfs(now + 1, weight);
	if (weight + items[now].first <= w) {
		res = max(res, dfs(now + 1, weight + items[now].first) + items[now].second);
	}
	return dp[now][weight] = res;
}

