using namespace std;

vector<long long> ww;
vector<vector<long long>> wc;
long long best;

void solve(long long step, long long w, long long v) {
	if (step == ww.size()) {
		best = max(best, v);
	}
	else {
		long long i;
		solve(step + 1, w, v);
		for (i = 0; (i < wc[step].size()) && ((i + 1) * ww[step] <= w); i++) {
			solve(step + 1, w - (i + 1) * ww[step], v + wc[step][i]);
		}
	}
}

int main()
