		if (ct.find(w) == ct.end()) ct[w] = { v };
		else ct[w].push_back(v);
	}

	for (auto p : ct) {
		ww.push_back(p.first);
		wc.push_back(p.second);
		x = wc.size() - 1;
		sort(wc[x].rbegin(), wc[x].rend());
		for (i = 1; i <= wc[x].size() - 1; i++) wc[x][i] += wc[x][i - 1];
	}

	best = 0;
	solve(0, www, 0);

	cout << best << "\n";

	return 0;
}

