ll W, W2;
const int maxn = 101;
const int maxw = 400;
const int maxv = 1e7 + 100;
ll w[maxn];
int v[maxn];
int n;
int dp[maxn][maxw][maxn];

int dfs(int i, int j, int k) {
  //インデックスi番目以降の品物から
  //重さj以内で
  //残りk個選べる
  //場合の価値の最大値 == ret
  //printf("i,j,k = %3d %3d %3d\n", i, j, k);
  if (dp[i][j][k] != -1) {
    return dp[i][j][k];
  }
  int ret = 0;
  if (k == 0) {
    ret = 0;
  } else if (i == n) {
    ret = 0;
  } else if (j < w[i]) {  //少なくとも1個選べるが、i番目の品物は入らない
    ret = dfs(i + 1, j, k);
  } else {  //i番目の品物が入れられる
    ret = max(dfs(i + 1, j - w[i], k - 1) + v[i], dfs(i + 1, j, k));
  }
  dp[i][j][k] = ret;
  return dp[i][j][k];
}

void solve() {
  cin >> n >> W;
  cin >> w[0] >> v[0];
  ll wm = 0;
  for (int i = 1; i < n; ++i) {
    cin >> w[i] >> v[i];
    wm = max(w[i], wm);
    w[i] -= w[0];
  }
  ll w0 = w[0];
  w[0] = 0;
  //使う個数がt個のとき, 重さ制限はW - t*w0
  //重さW'以内になるようにt個までの品物を選択して得られる最大の価値を求めよ
  //個数制限つきナップサック問題をW/w0回解く（最大でn回）
  //O(N*NW')
  //W'は3*n以内
  //O(N*N*3*N) = O(N^3)
  ll ans = 0, ret;
  for (ll t = 1; t <= n; ++t) {
    W2 = min(W - t * w0, (wm - w0) * t);
    if (W2 < 0)
      continue;
    for (int i = 0; i < maxn; ++i) {
      for (int j = 0; j < maxw; ++j) {
        for (int k = 0; k < maxn; ++k) {
          dp[i][j][k] = -1;
        }
      }
    }
    //debug(W2);
    ret = dfs(0, W2, t);
    ans = max(ans, ret);
    //cout << "t=" << t << ":" << ret << endl;
  }
  cout << ans << endl;
}

int main() {
  solve();
  return 0;
}

