void solve() {
  long long  n, k;
  cin >> n >> k;
  vector<long long int> w(n+1), v(n+1);
  for (int i = 1; i <= n; i++) {
    cin >> w[i] >> v[i];
  }
  vector< vector<long long int>> dp(n + 1, vector<long long int>(k + 1));
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= k; j++) {
      dp[i][j] = dp[i - 1] [j];

      if(j - w[i] >= 0) {
        dp[i][j] = max(dp[i][j], v[i] + dp[i-1][j - w[i]]);
      }
    }
  }
  cout << dp[n][k];
}


int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  solve();
  return 0;
}

