		sort(v[i].rbegin(), v[i].rend());

	ll maxim = 0;
	for(int a = 0; a <= v[0].size(); ++a) {
		ll suma = 0;
		int aw = a * w1;
		if(aw <= W) {
			for(int i = 0; i < a; ++i)
				suma += v[0][i];
			/* cerr << "suma " << suma << '\n'; */
			for(int b = 0; b <= v[1].size(); ++b) {
				ll sumb = 0;
				int bw = b * (w1 + 1);
				if(aw + bw <= W) {
					for(int i = 0; i < b; ++i)
						sumb += v[1][i];
					/* cerr << "sumb " << sumb << '\n'; */
					for(int c = 0; c <= v[2].size(); ++c) {
						ll sumc = 0;
						int cw = c * (w1 + 2);
						if(aw + bw + cw <= W) {
							for(int i = 0; i < c; ++i)
								sumc += v[2][i];
							int le = (W - aw - bw - cw)/(w1+3);
							le = min(le, int(v[3].size()-1));
							for(int i = 0; i <= le ; ++i){
								sumc += v[3][i];
							}
							/* cerr << "sumc " << sumc << '\n'; */
							maxim = max(maxim, suma+sumb+sumc);
						}
					}
				}
			}
		}
	}
	cout << maxim << '\n';
}

