ll dp(int k, int cnt, int extra) {
    if (k == n) {
        return 0;
    }
    if (ready[k][cnt][extra]) return cache[k][cnt][extra];
    ready[k][cnt][extra] = true;

    ll &rv = cache[k][cnt][extra];
    rv = 0;
    if (ok(cnt + 1, extra + a[k] - fw)) {
        rv = b[k] + dp(k + 1, cnt + 1, extra + a[k] - fw);
    }
    rv = max(rv, dp(k + 1, cnt, extra));
    return rv;
}

