LL N, W, w[100], v[100];
bool done[100][100];
LL memo[100][100];

int dp(LL i, LL u) {
	if (done[i][u]) return memo[i][u];
	int res1, res2, res;
	if (i == N)
		return 0;
	else if (w[i] > u)
		res = dp(i + 1, u);
	else {
		res1 = dp(i + 1, u);
		res2 = dp(i + 1, u - w[i]) + v[i];
		res = max(res1, res2);
	}
	done[i][u] == true;
	memo[i][u] == res;
	return res;
}

