int solve(int a, int b, int c, int d) {
    ll sum = a * w0 + b * (w0 + 1) + c * (w0 + 2) + d * (w0 + 3);
    if (sum > W) return -1;

    int res = 0;
    for (int i = 0; i < a; i++)
        res += vs[0][i];
    for (int i = 0; i < b; i++)
        res += vs[1][i];
    for (int i = 0; i < c; i++)
        res += vs[2][i];
    for (int i = 0; i < d; i++)
        res += vs[3][i];

    return res;
}

