bool sort_cost( P a, P b )
{
	if( a.second * b.first > b.second * a.first ) {
		return true;
	}
	return false;
}

double ubound( int i, long long ww )
{
	double res = 0;
	for( int j = i; ww > 0 && j < N; i++ ) {
		long long www = vec[j].first;
		long long vv = vec[j].second;
		if( www >= ww ) {
			res += vv * ww / www;
			break;
		}
		res += vv;
		ww -= www;
	}
	return res;
}

long long ans;
void dfs( int i, long long ww, long long sum )
{
	if( sum > ans ) {
		ans = sum;
	}
	if( i >= N ) {
		return;
	}
	double ub = ubound( i, ww );
	if( sum + ub < ans ) {
		return;
	}
	long long www = vec[i].first;
	long long vv = vec[i].second;
	long long res = 0;
	if( www <= ww ) {
		dfs( i + 1, ww - www, sum + vv );
	}
	dfs( i + 1, ww, sum );
}

