			for(int h=0;h<=3*j;h++)
			{
				dp[i+1][j][h]=max(dp[i+1][j][h],dp[i][j][h]);
				dp[i+1][j+1][h+a[i]-a[0]]=max(dp[i+1][j+1][h+a[i]-a[0]],dp[i][j][h]+b[i]);
			}
		}
	}
	int ans=0;
	for(int i=0;i<=n;i++)
	{
		for(int j=0;j<=3*i;j++)
		{
			long long curW=(long long)a[0]*i+j;
			if(curW<=W)
				ans=max(ans,dp[n][i][j]);
		}
	}
	printf("%d\n",ans);
	return 0;
}

