int dp(int i,int sum,int cnt);
int n,p,t;
int w[109],v[109];
int memo[109][1009][109];

int main(){
  memset(memo,-1,sizeof(memo));
  cin>>n>>p;
  for(int i=0;i<n;i++){
    cin>>w[i]>>v[i];
    if(i==0){
      t=w[i];
      w[i]=0;
    }
    else w[i]-=t;
  }
  cout<<dp(0,0,0)<<endl;
  return(0);
}

int dp(int i,int sum,int cnt){
  if(memo[i][sum][cnt]!=-1)return memo[i][sum][cnt];
  if(i==n)return 0;
  int rec=dp(i+1,sum,cnt);
  if(sum+w[i]+t*(cnt+1)<=p){
    rec=max(rec,dp(i+1,sum+w[i],cnt+1)+v[i]);
  }
  return memo[i][sum][cnt]=rec;
}

