vector<pair<int,int> > items;
int knapsack(int w)
{
    vector<int> dp(w+4,0);
    for(int i=0 ; i<items.size() ; ++i)
    {
        for(int j=w ; j>=items[i].first ; --j)
        {
            dp[j]=max(dp[j],dp[j-items[i].first]+items[i].second);
        }
    }
    return dp[w];
}

