namespace Program
{
    using namespace std;
    class Solver
    {
    private:
        // 荷物の個数 整数
        int N;

        // ナップサックの許容重量 整数
        int W;

        // 価値 v[i]
        array<long long int, 100> v;

        // 重さ w[i]
        array<long long int, 100> w;

    public:
        Solver()
        {
            cin.tie(0);
            ios::sync_with_stdio(false);

            cin >> N >> W;

            // 重量オーバー除外後 荷物の個数 整数
            int overN = 0;

            int tmpw, tmpv;

            cin >> tmpw >> tmpv;

            for (int i = 1; i <= N; i++)
            {
                if (W < tmpw) overN++;
                else
                {
                    w[i - overN - 1] = tmpw;
                    v[i - overN - 1] = tmpv;
                }

                if (i == N) break;
                cin >> tmpw >> tmpv;
            }
            N = N - overN;
        }

        void Solve()
        {
            // それぞれ荷物の重量が1000以内のときに使用するナップサック
            cout << knapsackW(w, v, N, W) << endl;
        }

        // それぞれ荷物の重量が1000以内のときに使用するナップサック
        long long int knapsackW(
            const array<long long int, 100> &w,   /* 重さ */
            const array<long long int, 100> &v,   /* 価値 */
            const long long int &numOfItems,      /* 荷物の個数 */
            const long long int &wUpperBound      /* 総重量の上限 */
            )
        {
            // 動的計画法
            array<array<long long int, 10000>, 100> dp;

            long long int j;

            for (long i = 0; i < N; i++) dp[i].fill(0);

            long long int mn = min(10000LL, wUpperBound); 

            /* 価値の総和の最大値 動的計画法 */
            for (long i = 0; i < numOfItems; i++)
            {
                for (j = 0; j <= mn; j++)
                {
                    if (w[i] <= j && dp[i][j] < dp[i][j - w[i]] + v[i])
                    {
                        dp[i + 1][j] = dp[i][j - w[i]] + v[i];
                    }
                    else {
                        dp[i + 1][j] = dp[i][j];
                    }
                }
            }

            // 最大価値
            return N == 0 ? 0 : dp[numOfItems][wUpperBound];
        }
    };
}

int main()
{
    // メモリリーク検出
    //    _CrtSetDbgFlag(_CRTDBG_ALLOC_MEM_DF
