int N;

map<pair<int, int>, ll> mem;

ll MaxValue(int W, int i, const vpi& w)
{
    if (i == N) return 0;
    auto it = mem.find(make_pair(W, i));
    if (it != mem.end()) return it->second;
    ll result = max(W >= w[i].first ? MaxValue(W-w[i].first, i+1, w) + w[i].second : 0ll, MaxValue(W, i+1, w));
    mem[make_pair(W, i)] = result;
    return result;
}

