#define LL long long
using namespace std;
LL n,sum[110][6],W,w[6],cnt=1,c1=0,c2=0,c3=0,c4=0;
LL res=0,ans=0;
struct Node{
    int w,v;
}a[110];

bool cmp(Node x,Node y){
    if(x.w<y.w) return true;
    if(x.w==y.w && x.v>y.v) return true;
    return false;
}

LL getsum(int i,int j,int k,int l){
    return (sum[i][1]+sum[j][2]+sum[k][3]+sum[l][4]);
}

int main(){
    scanf("%lld%lld",&n,&W);
    for(int i=1;i<=n;i++){
        scanf("%d%d",&a[i].w,&a[i].v);
    }
    sort(a+1,a+1+n,cmp);
    w[cnt]=a[1].w;
    for(int i=1;i<=n;i++){
        if(a[i].w!=w[cnt])
            w[++cnt]=a[i].w;
    }
    for(int i=1;i<=n;i++)
    {
        if(a[i].w==w[1]){
            sum[++c1][1]=sum[c1-1][1]+a[i].v;
        }
        else if(a[i].w==w[2]){
            sum[++c2][2]=sum[c2-1][2]+a[i].v;
        }
        else if(a[i].w==w[3]){
            sum[++c3][3]=sum[c3-1][3]+a[i].v;
        }
        else
            sum[++c4][4]=sum[c4-1][4]+a[i].v;
    }
    for(int i=c1+1;i<=n;i++)
    {
        sum[i][1]=sum[i-1][1];
    }
    for(int i=c2+1;i<=n;i++)
    {
        sum[i][2]=sum[i-1][2];
    }
    for(int i=c3+1;i<=n;i++)
    {
        sum[i][3]=sum[i-1][3];
    }
    for(int i=c4+1;i<=n;i++)
    {
        sum[i][4]=sum[i-1][4];
    }
    LL k,m;
    LL tem=(W/w[1])+1;
    m=n < tem ? n : tem;
    for(int i=0;i<=m;i++){
        for(int j=0;i+j<=m;j++)
            for(int k=0;i+j+k<=m;k++)
            {
                res=i*w[1]+j*w[2]+k*w[3];
                if(res>W) continue;
                else if(res <= W)
                {
                    int l=0;
                    if(w[4]!=0) l=(W-res)/w[4];
                    ans=max(ans,getsum(i,j,k,l));
                }
            }
    }
    printf("%lld",ans);
    return 0;
}

