long long int SIZE, N, cost[505], weight[505], dp[505][505], w=0 ;

int call(int i , int w)
{
      if( i == N+1)
            return 0;

      if( dp[i][w] != -1)
            return dp[i][w];

      int profit1=0, profit2=0;

      if(w + weight[i] <= SIZE )
      {
            profit1 = cost[i] + call(i+1 , w+weight[i]);
      }
      profit2 = call(i+1 , w);

       dp[i][w]=max(profit1 , profit2);
       return dp[i][w];
}

