LL dp[101][101];

LL rec(LL i, LL j) {
  if (dp[i][j] >= 0) {
    return dp[i][j];
  }
  LL val;
  if (i == N) {
    val = 0;
  } else if (j < w[i]) {
    val = rec(i+1, j);
  } else {
    val = std::max(rec(i+1, j), rec(i+1, j-w[i])+v[i]);
  }
  dp[i][j] = val;
  return val;
}

