int N;

int dfs(int item_idx, int rest_w) {
    if (memo[item_idx][rest_w] != -1) return memo[item_idx][rest_w];
    int res;
    if (item_idx == N) {
        res = 0;
    }
    else if (rest_w < w[item_idx]) {
        res = dfs(item_idx + 1, rest_w);
    }
    else {
        res = max(dfs(item_idx + 1, rest_w), dfs(item_idx + 1, rest_w - w[item_idx]) + v[item_idx]);
    }
    return memo[item_idx][rest_w] = res;
}

