const ll MOD = 1000000007;

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

void solve(long long N, long long W, std::vector<long long> w, std::vector<long long> v)
{
    ll dp[N + 10][W + 10];

    memset(dp, 0, sizeof(dp));

    for (int i = 1; i <= N; i++)
    {
        ll weight = w[i - 1];
        ll value = v[i - 1];

        for (ll j = 0; j <= W; j++)
        {
            if (0 <= j - weight)
            {
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - weight] + value);
            }
            dp[i][j] = max(dp[i - 1][j], dp[i][j]);
        }
    }

    cout << dp[N][W] << endl;
}

int main()
{
    long long N;
    scanf("%lld", &N);
    long long W;
    scanf("%lld", &W);
    std::vector<long long> w(N);
    std::vector<long long> v(N);
    for (int i = 0; i < N; i++)
    {
        scanf("%lld", &w[i]);
        scanf("%lld", &v[i]);
    }
    solve(N, W, std::move(w), std::move(v));
    return 0;
}

