int calc(int u) {
    int ans = 0;
    ans += (u % base[1]) * k; u -= u % base[1];
    ans += (u % base[2]) / base[1] * (k + 1); u -= u % base[2];
    ans += (u % base[3]) / base[2] * (k + 2); u -= u % base[3];
    ans += u * (k + 3);
    return ans;
}
int main() {

    scanf("%d%d", &n, &m);

    cnt[0] = cnt[1] = cnt[2] = cnt[3] = 1;
    for(int i = 0; i < n; i++) {
        scanf("%d%d", &w[i], &v[i]);
        if(i == 0) k = w[i];
        ++cnt[ w[i] -= k ];
    }

    base[0] = 1;
    for(int i = 1; i < 4; i++) 
        base[i] = cnt[i-1], cnt[i] *= cnt[i-1];

    int cur = 1;
    for(int i = 0; i < n; i++) {
        for(int j = 1000000+10-1; j >= base[w[i]]; j--) 
            dp[cur][j] = max(dp[cur^1][j], dp[cur^1][j-base[w[i]]] + v[i]);
        for(int j = base[w[i]]-1; j >= 0; j--)
            dp[cur][j] = dp[cur^1][j];

        cur ^= 1;
    }
    int ans = 0;
    for(int j = 0; j < 1000000 + 10; j++) 
        if(calc(j) <= m) ans = max(ans, dp[cur^1][j]);

    printf("%d\n", ans);

    return 0;
}

