#include <bits/stdc++.h>
using namespace std;

int Knapsack01(int W, int wt[],int v[] ,int n)
{
   int Ks[n+1][W+1];

   for(int i=0; i<=n; ++i)
      for(int w=0; w<=W ; ++w)
      {
         /*When either the capacity is 0
         or no item is to be taken */
         if(i==0 || w==0)
            Ks[i][w]=0;
         /*Case 1 listed above*/
         else if(wt[i-1]<=w)
            Ks[i][w]=max(Ks[i-1][w],Ks[i-1][w-wt[i-1]] + v[i-1]);
         /*Case 2 listd above*/
         else
            Ks[i][w]=Ks[i-1][w];
      }
   return Ks[n][W];
}

int main()
{
    int  W,n;
    scanf("%d%d",&n,&W);
    int val[n],wt[W];
    for(int i=0; i<n ;++i)
    	scanf("%d%d",&wt[i],&val[i]);
    cout<<Knapsack01(W, wt, val, n)<<endl;
    return 0;
}

