using namespace std;
const int MAX_N = 100; 
const int MAX_W = 1000000000; 
int n, W;
int w[MAX_N], v[MAX_N];
int dp[MAX_N + 1][MAX_W + 1];
int rec_dp(int i, int j) {
  if (dp[i][j] != -1) {
    return dp[i][j];
  }
  int res;
  if (i == n) {
    res = 0;
  } else if (j < w[i]) {
    res = rec_dp(i + 1, j);
  } else {
    res = max(
        rec_dp(i + 1, j),
        rec_dp(i + 1, j - w[i]) + v[i]
    );
  }
  return dp[i][j] = res;
}
int main () {
  cin >> n >> W;
  for(int i=0; i<n ; i++) cin >> w[i] >> v[i];
  memset(dp, -1, sizeof(dp));
  cout << rec_dp(0, W) << endl;
  return 0;
}

