	int inf = 1 << 30;
	int w0 = inf;
	vector<pair<int,int>> wvs;
	for (int i = 0; i < n; ++i) {
		int wi, vi;
		cin >> wi >> vi;
		if (w0 == inf) w0 = wi;
		wi -= w0;
		wvs.push_back(make_pair(wi,vi));
	}

	vector<vector<int>> dp1(300+1, vector<int>(101, -1));
	vector<vector<int>> dp2(300 + 1, vector<int>(101, -1));
	vector<pair<int, int>> not_inf;
	dp1[0][0] = 0;
	dp2[0][0] = 0;
	not_inf.push_back(make_pair(0, 0));
	int max_value = 0;
	for (auto item : wvs) {
		int weight = item.first;
		int value = item.second;
		vector<pair<int, int>> next_inc;
		for (auto pos : not_inf) {
			int weight_sum  = pos.first;
			int count_sum = pos.second;
			int value_sum = dp1[weight_sum][count_sum];
			int comp_val = dp1[weight_sum + weight][count_sum + 1];
			if (comp_val < value_sum + value) {
				if (weight_sum + (count_sum + 1)*w0 +weight <= w) {
					if (dp1[weight_sum + weight][count_sum + 1] == -1) {
						next_inc.push_back(make_pair(weight_sum + weight, count_sum + 1));
					}
					dp2[weight_sum + weight][count_sum + 1] = value_sum + value;
					if (max_value < value_sum + value) max_value = value_sum + value;
				}
			}
		}
		for (auto pos : next_inc) {
			not_inf.push_back(pos);
		}
		for (int i = 0; i < 301; ++i) {
			dp1[i] = dp2[i];
		}
	}
	cout << max_value << endl;
}

