int func(int i,int j) {
	int res;
	if (memo[i][j] != 0)
		return memo[i][j];
	if (i == N)
		res = 0;
	else if (j < w[i])
		res = func(i+1,j);
	else {
		res=max(func(i + 1, j), func(i + 1, j - w[i])+v[i]);
	}
	return memo[i][j]=res;
}

