void solve()
{
	int n, W;
	cin >> n >> W;
	ll w[n], v[n];
	ll mn = 1e9;
	rep(i, n){
		cin >> w[i] >> v[i];
		mn = min(mn, w[i]);
	}
	ll sum = 0;
	rep(i, n){
		g[w[i] - mn].pb(v[i]);
	}
	for(int i = 0; i < 4; ++i) sort(all(g[i]));
	while(W >= 0){
		int id = -1;
		for(int i = 0; i < 4; ++i){
			if(g[i].size() == 0) continue;
			if(W - i - mn >= 0 && (id == -1 || g[id].back() < g[i].back())) id = i;
		}
		if(id == -1) break;
		t[id].pb(g[id].back());
		sum += g[id].back();
		W -= (mn + id);
		g[id].pop_back();
	}
	for(int i = 3; i >= 0; --i){
		for(int j = i - 1; j >= 0; --j){
			sort(all(g[i]));
			sort(all(g[j]));
			sort(all(t[i]));
			sort(all(t[j]));
		}

		for(int j = i - 1; j >= 0; --j){
			ll xsum = 0;
			ll ysum = 0;
			ll id = sz(t[i]), jd = sz(g[j]);
			for(int k = 0; k < sz(t[i]); ++k){
				xsum += t[i][k];
				if((mn + j) * (k + 1) + mn + j <= (mn + i) * (k + 1)){
					id = k + 1;
					break;
				}
			}
			reverse(all(g[j]));
			for(int k = 0; k < sz(g[j]); ++k){
				ysum += g[j][k];
				if((mn + j) * (k + 1) + mn + j <= (mn + i) * (k + 1)){
					jd = k + 1;
					break;
				}
			}
			if(ysum > xsum && (id * (mn + i)) >= (jd) * (mn + j)){
				ll xd = id;
				ll yd = jd;
				reverse(all(t[i]));
				reverse(all(g[j]));
				while(xd--){
					g[i].pb(t[i].back());
					sum -= t[i].back();
					t[i].pop_back();
				}
				while(yd--){
					sum += g[j].back();
					t[j].pb(g[j].back());
					g[j].pop_back();
				}
				W += id * (mn + i) - (jd) * mn + j;
				for(int k = 0; k < 4; ++k) sort(all(g[k]));
				for(int k = i - 1; k >= 0; --k){
					ll id = -1;
					for(int z = 0; z < 4; ++z){
						if(g[z].size() == 0) continue;
						if(W - mn - z >= 0 && (id == -1 || g[id].back() < g[z].back())) id = z;
					}
					if(id == -1) break;
					t[id].pb(g[id].back());
					W -= (mn + id);
					g[id].pop_back();
				}
			}
		}
	}
	cout << sum << '\n';

}





