  for ( int i=1; i<=N; i++ ) {
    cin >> wList[i] >> vList[i];
  }

  int wBase = wList[1];

  int W_ = 0;
  for ( int i=1; i<=N; i++ ) {
    W_ += (wList[i] - wBase);
    wList[i] -= wBase;
  }

  int dp[N+2][N+2][W_+2];
  for ( int n=0; n<N+2; n++ ) {
    for ( int k=0; k<N+2; k++ ) {
      for ( int w=0; w<W_+2; w++ ) {
        dp[n][k][w] = 0;
      }
    }
  }

  for ( int n=0; n<N+1; n++ ) {
    for ( int k=0; k<N+1; k++ ) {
      for ( int w=0; w<W_+1; w++ ) {

        if ( w-wList[n] >= 0 ) {
          dp[n+1][k+1][w] = max( dp[n][k][w-wList[n]] + vList[n], dp[n][k+1][w] );
        } else {
          dp[n+1][k+1][w] = dp[n][k+1][w];
        }

      }
    }
  }

  int max_v = 0;
  for ( int k=1; k<=N; k++ ) {
    int amari = W - k*wBase;
    if ( amari >= 0 ) {
      max_v = max( max_v, dp[N][k][min(amari, W_)] );
    }
  }
