typedef long long ll;
const ll INF = 1e12;

typedef std::pair< ll, ll > P;

const ll MAX_N = 100;
const ll MAX_W = 1e9;
const ll MAX_DIFF = 3;

// 最大価値 = i個目まで選択, j個選択, 重さk(差分のみで計算)
ll dp[MAX_N+1][MAX_N+1][MAX_DIFF * MAX_N + 1];

int main(int argc, char* argv[])
{
  ll N, W;
  std::cin >> N >> W;
  std::vector< P > vp(N+1, std::make_pair(0, 0));

  std::cin >> vp[0].first >> vp[0].second;
  ll base_w = vp[0].first;
  vp[0].first = 0;
  for (ll i = 1; i < N; i++) {
    std::cin >> vp[i].first >> vp[i].second;
    vp[i].first -= base_w;
  }

  // Initialize
  for (ll j = 0; j <= MAX_N; j++) {
    for (ll w = 1; w <= MAX_DIFF * MAX_N; w++) {
      dp[0][j][w] = -INF;
    }
  }
  for (ll i = 1; i <= N; i++) {
    for (ll j = 1; j <= i; j++) {
      ll max_w = 3 * j;
      for (ll k = 0; k <= max_w; k++) {
	if (W - base_w * j - k >= 0 && k - vp[i-1].first >= 0) {
	  dp[i][j][k] = std::max(dp[i-1][j-1][k-vp[i-1].first] + vp[i-1].second, dp[i-1][j][k]);
	} else {
	  dp[i][j][k] = dp[i-1][j][k];
	}
      }
    }
  }

  ll ans = 0;
  for (ll j = 0; j <= N; j++) {
    for (ll k = 0; k <= MAX_DIFF * MAX_N; k++) {
      if (W - base_w * j - k >= 0) {
	ans = std::max(ans, dp[N][j][k]);
      }
    }
  }

  std::cout << ans << std::endl;

  return 0;
}

