#define MOD 1000000007

using namespace std;

struct Object
{
	int w;
	int v;
	bool operator < (const Object& x) const {
		if(w == x.w){
			return v > x.v;
		}
		return w < x.w;
	}
};

class SimpleKnapsack
{
private:
	int n;
	int max_w;
	vector<Object> objs;
	unordered_map<int, vector<int> > w_imos;
	int min_w;

public:
	SimpleKnapsack(){
		cin >> n >> max_w;
		for (int i = 0; i < n; ++i)
		{
			Object tmp;
			cin >> tmp.w >> tmp.v;
			objs.push_back(tmp);

		}
		min_w = objs[0].w;
		sort(objs.begin(), objs.end());
	}
	void exec(){
		for (int i = 0; i < n; ++i)
		{
			w_imos[objs[i].w].push_back(objs[i].v);
 		}

 		for (auto itr = w_imos.begin(); itr != w_imos.end(); ++itr)
 		{
 			vector<int> arr = itr->second;
 			for (int i = 1; i < arr.size(); ++i)
 			{
 				 arr[i] += arr[i-1]; 
 			}
 			for (int i = arr.size(); i <= n; ++i)
 			{
 				 arr.push_back(0); 
 			}
 			arr.insert(arr.begin(), 0);
 			itr->second = arr;
 		}

 		int ans = 0;

 		for (int i = 0; i < n+1; ++i)
 		{
 			for (int j = 0; j < n+1; ++j)
 			{
 				for (int k = 0; k < n+1; ++k)
 				{
 					for (int l = 0; l < n+1; ++l)
 					{
 						if(min_w * i + (min_w + 1) * j + (min_w + 2) * k + (min_w + 3) * l  <= max_w){
 							int val_i = w_imos.find(min_w) == w_imos.end() ? 0 : w_imos[min_w][i]; 
 							int val_j = w_imos.find(min_w + 1) == w_imos.end() ? 0 : w_imos[min_w + 1][j];
 							int val_w = w_imos.find(min_w + 2) == w_imos.end() ? 0 : w_imos[min_w + 2][k];
 							int val_l = w_imos.find(min_w + 3) == w_imos.end() ? 0 : w_imos[min_w + 3][l];
 							ans = max(ans, val_i + val_j + val_w + val_l);
 						}
 					}
 				}
 			}
 		}
 		cout << ans << endl;
	}
};

int main(){
	SimpleKnapsack sk = SimpleKnapsack();
	sk.exec();
}

