                } else if (j >= w[i + 1]) {
                    dp[i + 1][j][k + 1] = dp[i][j - w[i + 1]][k] + v[i + 1];
                } else if (i >= k + 1) {
                    dp[i + 1][j][k + 1] = dp[i][j][k + 1];
                }
            }
        }
    }

    ll ans = 0;
    for (int j = 0; j <= sw; j++) {
        for (int k = 1; k <= N; k++) {
            if (k * bw + j <= W) {
                ans = max(ans, dp[N][j][k]);
            }
        }
    }

    cout << ans << "\n";

    return 0;
}

