void format(deque<ll> &v) {
    size_t n = v.size();
    if (n == 0) {
        v.emplace_back(0);
    }
}

void accum(deque<ll> &v) {
    size_t n = v.size();
    for (auto &&i: boost::irange(1U, (unsigned int) v.size())) {
        v.at(i) = v.at(i) + v.at(i - 1);
    }
}


