        wvs.at(w-w0).emplace_back(v);
    }
    for (auto &&i: boost::irange(0U, 4U)){
        format(wvs.at(i));
        sort(wvs.at(i).begin(), wvs.at(i).end(), greater<>());
        accum(wvs.at(i));
        wvs.at(i).emplace_front(0);
    }

