	vector<vector<int>> dp(100, vector<int>(1000000));
	//初期値
	for (int w = 0; w <= W; w++) {
		dp[0][w] = 0;
	}

	for (int i = 0; i < N; i++) {
		for (int w = 0; w <= W; w++) {
			if (w >= weight[i]) {
				dp[i+1][w] = max(dp[i][w], value[i]+dp[i][w-weight[i]]);
			}
			else{
				dp[i+1][w] = dp[i][w];
			}
		}
	}
	//output
	cout << dp[N][W] << endl;
}

