long long rec(int i, int j,int n,vector<long long>v,vector<long long>w) {
  long long res;
  if (i == n) {
    res = 0;
  } else if (j < w[i]) {
    res = rec(i + 1, j,n,v,w);
  } else {
    res = max(
        rec(i + 1, j,n,v,w),
        rec(i + 1, j - w[i],n,v,w) + v[i]
    );
  }
  return res;
}
