    }

    set<ll> weight_candidates;
    for (ll s = weights[0], e = s + 3, i = 0; i <= 100; i++, s = s + weights.front(), e += weights.front() + 3) {
        for (ll k = s; k <= e; k++) {
            if (k > w) continue;
            weight_candidates.insert(k);
        }
    }


    Knapsack k(n, values, weights, weight_candidates);
    cout << k.calculate() << endl;


}

