void solve()
{
	int n, W;
	cin >> n >> W;
	ll w[n], v[n];
	ll mn = 1e9;
	rep(i, n){
		cin >> w[i] >> v[i];
		mn = min(mn, w[i]);
	}
	ll sum = 0;
	rep(i, n){
		g[w[i] - mn].pb(v[i]);
	}
	for(int i = 0; i < 4; ++i) sort(all(g[i]));
	while(W >= 0){
		int id = -1;
		for(int i = 0; i < 4; ++i){
			if(g[i].size() == 0) continue;
			if(W - i - mn >= 0 && (id == -1 || g[id].back() < g[i].back())) id = i;
		}
		if(id == -1) break;
		t[id].pb(g[id].back());
		sum += g[id].back();
		W -= (mn + id);
		g[id].pop_back();
	}
	for(ll i = 3; i >= 0; --i){

		for(int j = i - 1; j >= 0; --j){
			ll l = 0, r = 0;
			ll f = 0, x = 0, s = 0, y = 0;
			sort(all(g[i]));
			sort(all(t[i]));
			sort(all(t[j]));
			sort(all(g[j]));
			while(l < sz(t[i])){
				f += mn + i;
				x += t[i][l];
				while(r < sz(g[j]) && s + mn + j <= f){
					s += mn + j;
					y += g[j][sz(g[j]) - 1 - r];
					r++;
				}
				l++;
				if(y > x) break;
			}
			if(x < y) continue;
			else if(x == y && f <= s) continue;
			else j++;
			reverse(all(t[i]));
			for(int k = 0; k < l; ++k){
				g[i].pb(t[i].back());
				sum -= t[i].back();
				W -= mn + i;
				t[i].pop_back();
			}
			for(int k = 0; k < r; ++k){
				t[j].pb(g[j].back());
				sum += g[j].back();
				W += mn + j;
				t[j].pop_back();
			}
			for(int k = 0; k < 4; ++k){
				sort(all(g[k]));
				sort(all(t[k]));
			}
			while(W >= 0){
				int id = -1;
				for(int k = 0; k < 4; ++k){
					if(g[k].size() == 0) continue;
					if(W - k - mn >= 0 && (id == -1 || g[id].back() < g[k].back())) id = k;
				}
				if(id == -1) break;
				t[id].pb(g[id].back());
				sum += g[id].back();
				W -= (mn + id);
				g[id].pop_back();
			}
		}

	}
	cout << sum << '\n';

}





