                int d = min((ll)N - (a+b+c), (ll)(W - (w[0] * a + (w[0]+1) * b + (w[0]+2) * c)/(w[0] + 3)));
                ll tmp = sum[0][a] + sum[1][b] + sum[2][c] + sum[3][d];
                //cout << a << b << c << d  << endl;
                ans = max(ans, tmp);
            }
        }
    }
    cout << ans << endl;
}

