	for(int i=0; i<N; i++)
	{
		wv[w[i]-w[0]].push_back(v[i]);
	}
	for(int i=0; i<4; i++)
	{
		sort(wv[i].begin(), wv[i].end(), greater<long long>());

		for(int j=1; j<wv[i].size(); j++)
			wv[i][j] += wv[i][j-1];
	}

	long long ret = 0;
	for(int n=1; n<=N; n++)
	{
		for(int i=min(n, (int)wv[0].size()); i>=0; i--)
		{
			if(i*w[0] > W)
				continue;

			for(int j=min(n-i, (int)wv[1].size()); j>=0; j--)
			{
				if((i+j)*w[0]+j > W)
					continue;

				for(int k=min(n-i-j, (int)wv[2].size()); k>=0; k--)
				{
					if((i+j+k)*w[0]+j+k > W)
						continue;

					for(int l=min(n-i-j-k, (int)wv[3].size()); l>=0; l--)
					{
						long long weight = (i+j+k+l)*w[0] + j + 2*k + 3*l;
						if(weight > W)
							continue;

						long long value = 0;
						if(i != 0)
							value += wv[0][i-1];
						if(j != 0)
							value += wv[1][j-1];
						if(k != 0)
							value += wv[2][k-1];
						if(l != 0)
							value += wv[3][l-1];

						ret = max(ret, value);
					}
				}
			}
		}
	}

	cout << ret << endl;

	return 0;
}

