ll O_1knapsack(ll n,ll val)
{
    int i,w;
    for(i=0; i<=n; i++)

        for(w=0; w<=val; w++)
        {
            if (i==0 || w==0)
                dp[i][w] = 0;
            else if(weight[i-1]<=w)
            {
                if(cost[i-1]+dp[i-1][w-weight[i-1]]>=dp[i-1][w])
                {
                    dp[i][w]=cost[i-1]+dp[i-1][w-weight[i-1]];

                }
                else
                {
                    dp[i][w]=dp[i-1][w];
                }
            }
            else
                dp[i][w]=dp[i-1][w];

        }
    return dp[n][val];
}
