  for(int i=0; i<N; i++){
    for(int j=0; j<2; j++){
      cin >> vec[i][j];
    }
  }

  const int64_t W_MAX = 4*N;
  const int64_t W_START = vec[0][0];
  const int64_t INF = 0;

  int64_t dp[N][W_MAX];
  for(int i=0; i<N; i++){
    for(int j=0; j<W_MAX; j++){
      dp[i][j] = INF;
    }
  }

  for(int i=0; i<N; i++){
    int64_t x = vec[i][0];
    int64_t y = vec[i][1];
    if(i == 0){
      dp[0][0] = y;
    }
    else{
      dp[i][x - W_START] = max(dp[i][x - W_START], y);
      for(int j=0; j<W_MAX; j++){
        if(dp[i-1][j] != INF){
          dp[i][j] = max(dp[i][j], dp[i-1][j]);
          dp[i][j+x] = max(dp[i][j+x], dp[i-1][j] + y);
        }
      }
    }
  }

