class item
{
public:
	int w, v;
	bool operator < (item& rhs){
		if(rhs.v == v)
			return rhs.w > w;
		return rhs.v < v;
	}
};

int N, W;
int knapsack()
{
	vector<item> items(N);

	 int minwt = INT_MAX;
	 REP(i, 0, N){
	 	cin >> items[i].w >> items[i].v;
		 minwt = min(minwt, items[i].w);
	 }
	 VI A, B, C, D;
	 REP(i, 0, N)
	 {
		 int wt = items[i].w, val = items[i].v;
		 if(wt - minwt == 0)
		 	A.push_back(val);
		 else if(wt - minwt == 1)
		 	B.push_back(val);
		 else if(wt - minwt == 2)
		 	C.push_back(val);
		else
			D.push_back(val);
	 }	

	 sort(ALL(A), greater<int>());
	 sort(ALL(B), greater<int>());
	 sort(ALL(C), greater<int>());
	 sort(ALL(D), greater<int>());

	 partial_sum(ALL(A), A.begin());
	 partial_sum(ALL(B), B.begin());
	 partial_sum(ALL(C), C.begin());
	 partial_sum(ALL(D), D.begin());

	 int ans = 0;
	 for(int i = 0; i <= sz(A); ++i)
	 	for(int j = 0; j <= sz(B); ++j)
		 	for(int k = 0; k <= sz(C); ++k)
				{
					LL sumwt = i * minwt + j * (minwt + 1) + k * (minwt + 2);
					if(sumwt > W)
						continue;
					int h = (W - sumwt) / (minwt + 3);
					if(D.empty()) h = 0;

					int sum = 0;
					if(i > 0) sum += A[i - 1];
					if(j > 0) sum += B[j - 1];
					if(k > 0) sum += C[k - 1];
					if(h > 0) sum += D[h - 1];

					ans = max(ans, sum);
				}
	return ans;
}

