void solve(){
    ll n,s;
    cin >> n >> s; 
    for(int i = 1; i <= n; ++i)
        cin >> w[i] >> c[i];
    int mn = *min_element(w + 1, w + n + 1); 
    vector <pair <ll,ll > > v1, v2, v3,v4;
    for(int i = 1; i <= n; ++i) {
        if(w[i] == mn) {
            v1.pb({w[i],c[i]});
        }
        else if(w[i] == mn + 1) {
            v2.pb({w[i],c[i]});
        }
        else if(w[i] == mn+ 2){
            v3.pb({w[i],c[i]});
        }
        else {
            v4.pb({w[i], c[i]});
        }
    }
    sort(all(v1));
    sort(all(v2));
    sort(all(v3));
    sort(all(v3));
    for(int i = 0; i < v1.size(); ++i) {
        if(i)
            sum1[i] = sum1[i - 1] + v1[i].Y;
        else 
            sum1[i] = v1[i].Y;
    }
    for(int i = 0; i < v2.size(); ++i) {
        if(i)
            sum2[i] = sum2[i - 1] + v2[i].Y;
        else 
            sum2[i] = v2[i].Y;
