    for(int i = 0; i < v3.size(); ++i) {
        if(i)
            sum3[i] = sum3[i - 1] + v3[i].Y;
        else 
            sum3[i] = v3[i].Y;
    }

    for(int i = 0; i < v4.size(); ++i) {
        if(i)
            sum4[i] = sum4[i - 1] + v4[i].Y;
        else 
            sum4[i] = v4[i].Y;
    }


    ll mx = 0;
    for(int i = 0; i <= v1.size(); ++i) {
        for(int j = 0; j <= v2.size(); ++j) {
            for(int k = 0; k <= v3.size(); ++k) {
                if(i * mn + j * (mn + 1) + k * (mn + 2) > s)
                    continue;
                ll tot = 0;
                if(i)
                    tot += sum1[i - 1];
                if(j)
                    tot += sum2[j - 1];
                if(k)
                    tot += sum3[k - 1]; 
                int m = s - (i * mn + j * (mn + 1) + k * (mn + 2));
                if(m)
                    tot += sum4[m - 1];
                mx = max(mx, tot);
            }
        }
    }
    cout << mx;
}
