int n,W,Ans;
int w[110],v[110],len[5];
int a[5][110],pre[5][110];

inline bool cmp(int a,int b){
  return a>b;
}

inline int calc(int a,int b,int c){
  return min((W-a*w[1]-b*(w[1]+1)-c*(w[1]+2))/(w[1]+3),len[3]);
}

int main(){
  scanf("%d%d",&n,&W);
  for(int i=1;i<=n;i++) scanf("%d%d",&w[i],&v[i]);
  for(int i=1;i<=n;i++) a[w[i]-w[1]][++len[w[i]-w[1]]]=v[i];
  for(int i=0;i<4;i++) sort(a[i]+1,a[i]+1+len[i],cmp);
  for(int i=0;i<4;i++)
    for(int j=1;j<=len[i];j++) pre[i][j]=pre[i][j-1]+a[i][j];
  for(int A=0;A<=len[0];A++)
    for(int B=0;B<=len[1];B++)
      for(int C=0;C<=len[2];C++)
	if(1ll*A*w[1]+1ll*B*(w[1]+1)+1ll*C*(w[1]+2)<=W)
	  Ans=max(Ans,pre[0][A]+pre[1][B]+pre[2][C]+pre[3][calc(A,B,C)]);
  printf("%d\n",Ans);
  return 0;
}

