using namespace std;

void dfs(const long n, const long W, const long value, const long weight, long &opt, const long index, const vector<long> &rsumw, const vector<long> &rminw, const vector<pair<long, long>> &v) {
  if (index == n) {
    opt = max(opt, value);
    return;
  }
  if (rsumw.at(index) <= W - weight) {
    long tvalue = value;
    for (long i = index; i < n; i++) {
      tvalue += v.at(i).first;
    }
    opt = max(opt, tvalue);
    return;
  }
  if (rminw.at(index) > W - weight) return;
  if (weight + v.at(index).second <= W) {
    opt = max(opt, value + v.at(index).first);
    long tweight = weight + v.at(index).second, tvalue = value + v.at(index).first;
    for (long i = index + 1; i < n; i++) {
      if (tweight + v.at(i).second <= W) {
        tweight += v.at(i).second, tvalue += v.at(i).first;
      } else {
        tvalue += v.at(i).first * (W - tweight) / v.at(i).second;
      break;
      }
    }
    if (opt < tvalue) {
      dfs(n, W, value + v.at(index).first, weight + v.at(index).second, opt, index + 1, rsumw, rminw, v);
    }
  }
  long tweight = weight, tvalue = value;
  for (long i = index + 1; i < n; i++) {
    if (tweight + v.at(i).second <= W) {
      tweight += v.at(i).second, tvalue += v.at(i).first;
    } else {
      tvalue += v.at(i).first * (W - tweight) / v.at(i).second;
    break;
    }
  }
  if (opt < tvalue) {
    dfs(n, W, value, weight, opt, index + 1, rsumw, rminw, v);
  }
}

long solve(const long n, const long W, vector<pair<long, long>> &v) {
  sort(v.begin(), v.end(), [&](pair<long, long> &a, pair<long, long> &b) {
    return (__int128)a.first * b.second > (__int128) a.second * b.first;
  });
  vector<long> rsumw(n + 1, 0);
  vector<long> rminw(n + 1, LONG_MAX);
  for (long i = n - 1; i >= 0; --i) {
    rsumw.at(i) = rsumw.at(i + 1) + v.at(i).second, rminw.at(i) = min(rminw.at(i + 1), v.at(i).second);
  }
  long opt = 0;
  dfs(n, W, 0, 0, opt, 0, rsumw, rminw, v);
  return opt;
}

