int func(int i, int j, int a, int b, int c, int d) {
	int res;

	if (i == N||(a==0&&b==0&&c==0&&d==0))
		res = 0;
	else if (j < w[i])
		res = func(i+1,j,a,b,c,d);
	else {
		if ((w[i] == w[0])&& a != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a-1, b, c, d) + v[i]);
		}
		else if ((w[i] == w[0] + 1)&& b != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b-1, c, d) + v[i]);
		}
		else if ((w[i] == w[0] + 2)&& c != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b, c-1, d) + v[i]);
		}
		else if ((w[1] == w[0] + 3)&& d != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b, c, d-1) + v[i]);
		}
		else {
			res = func(i + 1, j, a, b, c, d);
		}
	}
	//return memo[i][j]=res;
	return res;
}

