int main()
{
    long long int  N, W;
    if (scanf("%lld%lld", &N, &W) < 2) return 0;

    // 重さ 4通り グループ分け
    vector<long long int> a, b, c, d;

    long long int w, v;

    if (scanf("%lld%lld", &w, &v) < 2) return 0;
    long long int w0 = w;

    for (int i = 1; i <= N; i++)
    {
        if (w == w0) a.push_back(v);

        else if (w == w0 + 1) b.push_back(v);

        else if (w == w0 + 2) c.push_back(v);

        else d.push_back(v);

        if (i != N) if (scanf("%lld%lld", &w, &v) < 2) return 0;
    }

    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    sort(c.begin(), c.end());
    sort(d.begin(), d.end());

    // 価値 降順
    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());
    reverse(c.begin(), c.end());
    reverse(d.begin(), d.end());

    // 価値 降順 累積和
    for (int i = 1; i < (signed)a.size(); i++) a[i] += a[i - 1];
    for (int i = 1; i < (signed)b.size(); i++) b[i] += b[i - 1];
    for (int i = 1; i < (signed)c.size(); i++) c[i] += c[i - 1];
    for (int i = 1; i < (signed)d.size(); i++) d[i] += d[i - 1];

    long long int ans = 0LL;
    for (int i = 0; i <= (signed)a.size(); i++)
    {
        for (int j = 0; j <= (signed)b.size(); j++)
        {
            for (int k = 0; k <= (signed)c.size(); k++)
            {
                // グループ A B C 重さ 合計
                long long int
                    wag = i * w0 + j * (w0 + 1) + k * (w0 + 2);

                // 制限超過
                if (wag > W) continue;

                // グループ D 数
                // グループ A B C 重さ 合計 から 算出
                long long int l = (W - wag) / (w0 + 3);

                if ((int)d.size() < l) l = d.size();

                long long int s = 0LL;

                if (i != 0LL) s += a[i - 1];

                if (j != 0LL) s += b[j - 1];

                if (k != 0LL) s += c[k - 1];

                if (l != 0LL) s += d[l - 1];

                if (s > ans) ans = s;
            }
        }
    }

    printf("%lld\n", ans);
    return 0;
}

