template <typename T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return 1; } return 0; }
template <typename T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }
const long long INF = 1LL << 60;
const int INT_INF = 1 << 30;
#define MOD 1000000007LL
#define endl "\n"

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll N, W;
  cin >> N >> W;
  vll w(N), v(N);
  vll w0(0), w1(0), w2(0), w3(0);
  for(int i = 0; i < N; i++){
    cin >> w.at(i) >> v.at(i);
    if(i == 0) w0.push_back(v.at(i));
    else if(w.at(i) == w.at(0)) w0.push_back(v.at(i));
    else if(w.at(i) == w.at(0) + 1) w1.push_back(v.at(i));
    else if(w.at(i) == w.at(0) + 2) w2.push_back(v.at(i));
    else if(w.at(i) == w.at(0) + 3) w3.push_back(v.at(i));
  }
  sort(ALL(w0), greater<ll>());
  sort(ALL(w1), greater<ll>());
  sort(ALL(w2), greater<ll>());
  sort(ALL(w3), greater<ll>());
  ll n0 = w0.size(), n1 = w1.size(), n2 = w2.size(), n3 = w3.size();
  vll sum0(n0+1, 0), sum1(n1+1, 0), sum2(n2+1, 0), sum3(n3+1, 0);
  for(int i = 0; i < n0; i++) sum0.at(i+1) = sum0.at(i) + w0.at(i);
  for(int i = 0; i < n1; i++) sum1.at(i+1) = sum1.at(i) + w1.at(i);
  for(int i = 0; i < n2; i++) sum2.at(i+1) = sum2.at(i) + w2.at(i);
  for(int i = 0; i < n3; i++) sum3.at(i+1) = sum3.at(i) + w3.at(i);

  ll ww = w.at(0);
  ll ans = 0LL;
  for(int i = 0; i <= n0; i++){
    if(ww * i > W) break;
    for(int j = 0; j <= n1; j++){
      if(ww * i + (ww+1) * j > W) break;
      for(int k = 0; k <= n2; k++){
        if(ww * i + (ww+1) * j + (ww+2) * k > W) break;
        ll d = W - (ww * i + (ww+1) * j + (ww+2) * k);
        ll l = min(n3, d/(ww+3));
        ll wt = sum0.at(i) + sum1.at(j) + sum2.at(k) + sum3.at(l);
        chmax(ans, wt);
      }
    }
  }
  cout << ans << endl;
}

