// DP Definition
using Data = struct {
  ll N;
  ll W;
  vecl w;
  vecl v;
};
using Key = tuple<ll, ll>;
using Value = ll;
using Cache = u_map<Key, Value>;
struct DP {
  Data data;
  Cache cache;
  DP(Data const &data) : data(data), cache((ll)1e6) {}
  Value compute(Key const &key) {
    auto const &[i, w] = key;
    if (i < 0)
      return 0;
    if (w < 0)
      return 0;
    if (auto found = cache.find(key); found != cache.end())
      return found->second;
    ll ans = this->compute(Key{i - 1, w});
    if (w - data.w[i] >= 0)
      ans = max(ans, data.v[i] + this->compute(Key{i - 1, w - data.w[i]}));
    return cache[key] = ans;
  }
};
