const int MAX_V = 1000000000;

int N, W;
int w1, ans;
int vs[4];
vector<int> V[4];

void input_data(void) {
	int wn, val;

	cin >> N >> W;
	for (int i = 0; i < 4; ++i) {
		V[i].clear();
		V[i].push_back(MAX_V);
	}
	cin >> w1 >> val;
	V[0].push_back(val);
	for (int i = 1; i < N; ++i) {
		cin >> wn >> val;
		V[wn - w1].push_back(val);
	}
	for (int i = 0; i < 4; ++i)
		sort(V[i].begin(), V[i].end(), greater<int>());
}

void calcu(void) {
	for (int i = 0; i < 4; ++i) {
		vs[i] = V[i].size() - 1;
		V[i][0] = 0;
		if (vs[i] == 0)
			continue;
		vs[i] = min(vs[i], W / (w1 + i));
		for (int j = 1; j <= vs[i]; ++j)
			V[i][j] += V[i][j - 1];
	}
}

void solve(void) {
	int w_sum, v_sum;
	for (int a = vs[0]; a >= 0; --a) {
		for (int b = vs[1]; b >= 0; --b) {
			w_sum = w1 * a + (w1 + 1) * b;
			if (w_sum > W)
				continue;
			for (int c = vs[2]; c >= 0; --c) {
				w_sum = w1 * a + (w1 + 1) * b + (w1 + 2) * c;
				if (w_sum > W)
					continue;
				for (int d = vs[3]; d >= 0; --d) {
					w_sum = w1 * a + (w1 + 1) * b + (w1 + 2) * c + (w1 + 3) * d;
					if (w_sum > W)
						continue;
					v_sum = V[0][a] + V[1][b] + V[2][c] + V[3][d];
					if (v_sum > ans) {
						ans = v_sum;
						break;
					}
				}
			}
		}
	}
}

int main(void) {
	input_data();
	calcu();
	ans = 0;
	solve();
	cout << ans << '\n';
	return 0;
}

