int main(){
	scanf("%d%d",&nn,&W);
	for(int i=1;i<=nn;i++){
		scanf("%d%d",w+i,v+i);
		vec[w[i]-w[1]].push_back(v[i]);
	}
	n[0]=vec[0].size();
	n[1]=vec[1].size();
	n[2]=vec[2].size();
	n[3]=vec[3].size();
 	for(int i=0;i<4;i++){
 		sort(vec[i].begin(),vec[i].end());
 		reverse(vec[i].begin(),vec[i].end());
	}
	for(int i=0;i<4;i++){
		sum[i][0]=0;
		for(int j=1;j<=n[i];j++){
			sum[i][j]=sum[i][j-1]+vec[i][j-1];
//			printf("%d ",sum[i][j]);
		}
//		puts("");
	}
	for(int i=0;i<=n[0];i++){
		for(int j=0;j<=n[1];j++){
			for(int k=0;k<=n[2];k++){
				long long v0=sum[0][i],w0=i*w[1];
				long long v1=sum[1][j],w1=j*(w[1]+1);
				long long v2=sum[2][k],w2=k*(w[1]+2);
				if(w0+w1+w2>W) continue;
//				printf("%d %I64d\n%d %I64d\n%d %I64d\n\n",v0,w0,v1,w1,v2,w2);
				int l=max((W-w0-w1-w2)/(w[1]+3),(long long)n[3]);
				ans=max(ans,v0+v1+v2+sum[3][l]);
			}
		}
	}
	printf("%d\n",ans);
	return 0;
}

