typedef long long int ll;

ll n, W;
vector<ll> v, w;
void solve()
{
    ll dp[101][1000000001];
    for (ll i = n - 1; i >= 0; i--)
    {
        for (ll j = 0; j <= W; j++)
        {
            if (j < w[i])
            {
                dp[i][j] = dp[i + 1][j];
            }
            else
            {
                dp[i][j] = max(dp[i + 1][j], dp[i + 1][j - w[i]] + v[i]);
            }
        }       
    }
    cout << dp[0][W] << endl;
}

