    for(int i=0; i<N; i++){
        int w, v;
        cin >> w >> v;
        if(i==0) w0 = w;
        a[w].push_back(v);
    }

    for(auto it=a.begin(); it!=a.end(); it++){
        vector<int> b = it->second;
        sort(b.begin(), b.end(), greater<int>());
        it->second = b;
    }

    ll ans = 0;
    for(int i=0; i<=N; i++){
        for(int j=0; j<=N; j++){
            for(int k=0; k<=N; k++){
                int l = N - i - j - k;
                if(l < 0) continue;

                ll wsum = 0;
                ll vsum = 0;
                for(int t=0; t<i; t++){
                    if(a[w0].size() <= t) break;
