                    vsum = vsum + a[w0][t];
                }
                for(int t=0; t<j; t++){
                    if(a[w0+1].size() <= t) break;
                    wsum = wsum + w0+1;
                    vsum = vsum + a[w0+1][t];
                }
                for(int t=0; t<k; t++){
                    if(a[w0+2].size() <= t) break;
                    wsum = wsum + w0+2;
                    vsum = vsum + a[w0+2][t];
                }
                for(int t=0; t<l; t++){
                    if(a[w0+3].size() <= t) break;
                    wsum = wsum + w0+3;
                    vsum = vsum + a[w0+3][t];
                }

                if(wsum > W) continue;
