using namespace std;

int main()
{
  uint32_t N, W;

  cin >> N >> W;

  vector<uint32_t> v_w(N,0), v_v(N,0);

  for (uint32_t n=0; n<N; ++n)
    cin >> v_w[n] >> v_v[n];

  uint32_t dp[N+1][W+1];

  for (uint32_t n=0; n<N+1; ++n)
    dp[n][0] = 0;

  for (uint32_t w=0; w<W+1; ++w)
    dp[0][w] = 0;

  for (uint32_t n=1; n<=N; ++n) {
    for (uint32_t w=1; w<=W; ++w) {
      if (w >= v_w[n-1])
	dp[n][w] = max(dp[n-1][w-v_w[n-1]]+v_v[n-1], dp[n-1][w]);
      else
	dp[n][w] = dp[n-1][w];
    }
  }

  cout << dp[N][W] << endl;

  return 0;
}

