constexpr ll mypow(ll base, ll exponent){
    ll ret{1};
    for (unsigned int j = 0; j < exponent; ++j) {
        ret *= base;
    }
    return ret;
}

constexpr ll w_limit = 6 * mypow(10LL, 5LL);

int main() {
    ll N, W;
    cin >> N >> W;
    vector<pair<ll, ll>> vws;
    for (auto&& i: boost::irange(0LL, N)){
        ll w, v;
        cin >> w >>v;
        vws.emplace_back(make_pair(v, w));
    }
    ll w_0 = vws.at(0).second;
    if (w_0 <= w_limit){
        vector<ll> values((w_0+3)*(N+1)+100, numeric_limits<ll>::min());
        values.at(0) = 0;
        for (auto &&p: vws){ // 10 ** 2
            ll w, v;
