struct Item
{
    ll value, weight;


};

// Comparison function to sort Item according to val/weight ratio


double fractionalKnapsack(ll W, struct Item arr[], ll n)
{
    ll i, j;
    for0(i, n-1)
    {
        for(j=i; j<n-i-1; j++)
        {
            double x, y;
            x = arr[j].value/(double)arr[j].weight;
            y = arr[j+1].value/(double)arr[j+1].weight;
            if((ll)x <= (ll)y)
            {
                swap(arr[j].weight, arr[j+1].weight);
                swap(arr[j].value, arr[j+1].value);
            }
        }
    }

    ll curWeight = 0;
    double finalvalue = (ll)0;
    for (ll i = 0; i < n; i++)
    {
        if (curWeight + arr[i].weight <= W)
        {
            curWeight += arr[i].weight;
            finalvalue += floor(arr[i].value);
        }

        else
        {
            int remain = W - curWeight;
            finalvalue += (ll)floor((arr[i].value * ((double) remain / floor(arr[i].weight))))/1;
            break;
        }
        finalvalue = floor(finalvalue);
       // pnf((finalvalue));
    }

    return floor(finalvalue);
}

