int main()
{
	while(scanf("%d %d", &n, &V) != EOF)
	{
		sum = 0;
		memset(dp, 0, sizeof(dp));
		for(int i = 1; i <= n; i++)
		{
			scanf("%d %d", &w[i], &v[i]);
			a[i] = w[i] - w[1];
			sum = sum + a[i];
		}
		for(int i = 1; i <= n; i++)
		{
			for(int j = 1; j <= i; j++)
			{
				for(int k = 0; k < a[i]; k++)
					dp[i][j][k] = dp[i - 1][j][k];
			}
			for(int j = 1; j <= i; j++)
			{
				for(int k = a[i]; k <= sum; k++)
					dp[i][j][k] = max(dp[i - 1][j][k], dp[i - 1][j - 1][k - a[i]] + v[i]);
			}
		}
		int ans = 0;
		for(int i = 1; i <= n; i++)
			for(int j = 1; j <= i; j++) {
				if(w[1] * j > V) break;
				for(int k = 0; k <= min(sum, V - w[1] * j); k++) ans = max(ans, dp[i][j][k]);
			}
		printf("%d\n", ans);
	}
}

