using ll = long long int;
const int MAX_N = (int)(100 + 5);

ll n, w, weight[MAX_N], value[MAX_N];

map<ll, vector<ll>> cnt;
vector<vector<ll>> combs(0);
ll ans = 0;

void produce(auto itr, vector<ll> part) {
  if (itr != cnt.end()) {
    auto itrp = next(itr, 1);
    for (int i = 0; i <= itr->second.size(); ++i) {
      vector<ll> tmppart = part;
      tmppart.push_back(i);
      produce(itrp, tmppart);
    }
  }
  else {
    combs.push_back(part);
  }
}

int main(void) {
  // Here your code !
  scanf("%lld %lld", &n, &w);
  for (int i = 0; i < n; ++i) {scanf("%lld %lld", &weight[i], &value[i]);}
  for (int i = 0; i < n; ++i) {cnt[weight[i]].push_back(value[i]);}

  for (auto itr = cnt.begin(); itr != cnt.end(); ++itr) {
    sort(itr->second.begin(), itr->second.end(), greater<ll>());
  }

  auto itr = cnt.begin();
  vector<ll> tmp(0);
  produce(itr, tmp);

  for (int k = 0; k < combs.size(); ++k) {
    vector<ll> x = combs[k];
    ll candans = 0;
    ll candweight = 0;
    for (int j = 0; j < x.size(); ++j) {
      auto titr = next(itr, j);
      vector<ll> tmpvalue = titr->second;
      candweight += titr->first * x[j];
      for (int i = 0; i < x[j]; ++i) {
        candans += tmpvalue[i];
      }
    }

    if (candweight <= w) {
      ans = max(ans, candans);

    }
  }

  printf("%lld\n", ans);

  return 0;
}

