struct item_t {
  int weight, value;
  bool operator<(const item_t& other) const {
    return value > other.value;
  }
};

int main() {
  int N, W;
  cin >> N >> W;
  vector<item_t> items[4];
  vector<int> w(N), v(N);
  int w0;
  for (int i = 0; i < N; i++) {
    int w, v;
    cin >> w >> v;
    if (i == 0) w0 = w;
    items[w - w0].push_back((item_t){w, v});
  }

  for (int i = 0; i < 4; i++) {
    sort(items[i].begin(), items[i].end());
  }

  int w_sum[4] = {}, v_sum[4] = {};
  int v_max = 0;
  for (int n0 = 0; n0 <= items[0].size(); n0++) {
    // printf("n0 = %d\n", n0);
    if (n0 > 0) {
      w_sum[0] += items[0][n0-1].weight;
      v_sum[0] += items[0][n0-1].value;
      w_sum[1] = 0;
      v_sum[1] = 0;
    }
    if (w_sum[0] > W) break;
    for (int n1 = 0; n1 <= items[1].size(); n1++) {
      // printf("n1 = %d\n", n1);
      if (n1 > 0) {
        w_sum[1] += items[1][n1-1].weight;
        v_sum[1] += items[1][n1-1].value;
        w_sum[2] = 0;
        v_sum[2] = 0;
      }
      if (w_sum[0] + w_sum[1] > W) break;
      for (int n2 = 0; n2 <= items[2].size(); n2++) {
        // printf("n2 = %d\n", n2);
        if (n2 > 0) {
          w_sum[2] += items[2][n2-1].weight;
          v_sum[2] += items[2][n2-1].value;
          w_sum[3] = 0;
          v_sum[3] = 0;
        }
        if (w_sum[0] + w_sum[1] + w_sum[2] > W) break;
        for (int n3 = 0; n3 <= items[3].size(); n3++) {
          // printf("n3 = %d\n", n3);
          if (n3 > 0) {
            w_sum[3] += items[3][n3-1].weight;
            v_sum[3] += items[3][n3-1].value;
          }
          if (w_sum[0] + w_sum[1] + w_sum[2] + w_sum[3] > W) break;
          if (v_sum[0] + v_sum[1] + v_sum[2] + v_sum[3] > v_max) {
            v_max = v_sum[0] + v_sum[1] + v_sum[2] + v_sum[3];
          }
        }
      }
    }
  }

  cout << v_max << endl;

  return 0;
}

