ll weight[sz],cost[sz];
ll n,cap;

map<pair<ll, ll>, ll>dp;

ll fun(ll pos, ll w)
{
    if(pos==(n+1))
        return 0;

    if(dp[make_pair(pos, w)])
        return dp[make_pair(pos, w)];

    ll profit1;

    if(w+weight[pos]<=cap)
        profit1=cost[pos]+fun(pos+1, w+weight[pos]);

    else
        profit1=0;

    ll profit2=fun(pos+1, w);

    ll r=max(profit1, profit2);

    return dp[make_pair(pos, w)]=r;
}

