    sum += w[i];
    sums += v[i];
  }
  if (sum <= W) {
    cout << sums << endl;
    return 0;  
  }
  if (w[0] > W) {
    cout << 0 << endl;
    return 0;  
  }
  ll max = W / w[0];
  if (w[0] <= 300) {
    ll dp[N + 1][W + 1];
    for (ll i = 0; i <= N; i++) {
      for (ll j = 0; j <= W; j++) {
        dp[i][j] = 0;  
      }  
    }  
    for (ll i = 1; i <= N; i++) {
      for (ll j = 0; j <= W; j++) {
        dp[i][j] = dp[i - 1][j];
        if (j >= w[i - 1]) {
          dp[i][j] = maxs(dp[i - 1][j], dp[i - 1][j - w[i - 1]] + v[i - 1]);  
        }    
      }  
    }
    cout << dp[N][W] << endl;
  }
  else {
    // 0, w[0], w[0] + 1, ... w[0] + 300, w[0] * 2, ... 
    ll nokori = W - max * w[0];
    if (nokori > 300) {
      nokori = 300;  
    }    
    ll dp[N][max + 1][301];
    for (ll i = 0; i < N; i++) {
      for (ll j = 0; j <= max; j++) {
        for (ll l = 0; l <= 300; l++) {
          dp[i][j][l] = 0;  
        }  
      }  
    }
    for (ll i = 0; i < N; i++) {
      for (ll j = 1; j <= max; j++) {
        for (ll l = 0; l <= 300; l++) {
          // weight = j * w[0] + l;
          if (j * w[0] + l > w[i]) {
            if (i == 0) {
              dp[i][j][l] = v[i];  
            }  
            else {
              dp[i][j][l] = dp[i - 1][j][l];
              ll no = w[i] - w[0];
              if (no <= l) {
                dp[i][j][l] = maxs(
                  dp[i - 1][j][l], dp[i - 1][j - 1][l - no] + v[i]
                );
              }
              else {
                if (j - 2 >= 0) {
                  ll sub = 0;
                  for (ll p = 0; p <= 300; p++) {
                    if (dp[i - 1][j - 2][p] > sub) {
                      sub = dp[i - 1][j - 2][p];  
                    }    
                  }
                  dp[i][j][l] = maxs(dp[i - 1][j][l], 
                    sub + v[i]);
                }
              }
            }
          } 
        }  
      }  
    }
    ll ANS  = -1;
    for (ll j = 0; j <= max; j++) {
      for (ll l = 0; l <= 300; l++) {
        if (j == max) {
          if (l <= nokori && ANS <= dp[N - 1][j][l]) {
            ANS = dp[N - 1][j][l];  
          }  
        }    
        else {
          if (ANS <= dp[N - 1][j][l]) {
            ANS = dp[N - 1][j][l];  
          }  
        }
      }  
    }
    cout << ANS << endl;
  }

}

