void solveSingleCase(int caseNo)
{
    int N, W;
    cin >> N >> W;
    VEC(int) items[4];
    FOR(i, 0, N) {
        cin >> w[i] >> v[i];
        items[w[i] - w[0]].PB(v[i]);
    }

    VEC(int) acc[4];
    FOR(i, 0, 4) {
        sort(ALL(items[i]), greater<int>());
        acc[i].PB(0);
        FOR(j, 0, SZ(items[i])) {
            acc[i].PB(acc[i].back() + items[i][j]);
        }
    }

    int ret = 0;
    FOR(a, 0, SZ(acc[0]))
        FOR(b, 0, SZ(acc[1]))
            FOR(c, 0, SZ(acc[2])) {
                lint weight = a * 1LL * w[0] + b * 1LL * (w[0] + 1);
                weight += c * 1LL * (w[0] + 2);
                if (weight <= W) {
                    lint rem = W - weight;
                    int take = (int)(rem / (w[0] + 3));
                    take = min(take, SZ(acc[3]) - 1);
                    ret = max(ret, acc[0][a] + acc[1][b] + acc[2][c] + 
                                acc[3][take]);
                }
            }

    cout << ret << endl;
};

