    rep(i, n - 1) {
        int c; cin >> c >> b;
        for (auto e : se) {
            if (e > c) { //小さいやつが自分より大きい価値を持ってたら更新
                mp[e] = max(mp[e], b);
                ans = max(ans, mp[e]);
            }
            if (e + c <= w) {
                mp[e + c] = max(mp[e + c], mp[e] + b);
                ans = max(ans, mp[e + c]);
                se2.insert(e + c);
            }
        }
        for (auto e : se2) {
            se.insert(e);
        }
        mp[c] = max(mp[c], b);
        ans = max(ans, mp[c]);
        se.insert(c);
    }
    cout << ans << endl;
}

