template<class T>
class KnapsackProblem {
private:
	size_t n; // アイテムの個数
	size_t W; // ナップサックに入れられる最大重量
	std::vector<T> v; // v[i] := アイテムiの価値
	std::vector<T> w; // w[i] := アイテムiの重さ
public:
	struct Result {
		double value;
		std::vector<int> selection;
		bool isInteger;
	};
	KnapsackProblem(size_t n, T W, std::vector<T> v, std::vector<T> w) : n(n), W(W), v(v), w(w) {}
	Result calcSubProblem(std::vector<int> x) const {
		double res = 0; // 価値合計
		bool isInteger = true;

		long long restW = W;
		struct Item { T v, w; size_t i; }; // (価値v, 重さw, アイテム番号i)
		std::vector<Item> item;
		for (size_t itemIdx = 0; itemIdx < n; ++itemIdx) {
			if (x[itemIdx] == -1) { // x[itemIdx]がまだ決められていないとき
				item.emplace_back(Item{v[itemIdx], w[itemIdx], itemIdx});
			}
			else { // x[itemIdx]の値が決まっているとき
				restW -= w[itemIdx] * x[itemIdx];
				res += v[itemIdx] * x[itemIdx];

				if (restW < 0) { // 与えられたxでは実行可能解が存在しないとき
					return Result{-1.0, x, false};
				}
			}
		}

		// v/wの効率で降順ソート(greedy)
		std::sort(std::begin(item), std::end(item), [&](Item& lhs, Item& rhs) {
			return lhs.v * rhs.w > rhs.v * lhs.w;
			});

		// 未確定の変数をまだ使っていないとする
		for (size_t itemIdx = 0; itemIdx < n; ++itemIdx) {
			if (x[itemIdx] == -1) x[itemIdx] = 0;
		}

		for (auto&& it : item) { // 次に効率が最もよいアイテムitについて
			if (restW == 0) break;
			if (restW - it.w >= 0) { // itを完全に入れられるとき
				res += it.v;
				restW -= it.w;
				x[it.i] = 1;
			}
			else { // itを完全には入れられないとき
				res += (double)it.v * restW / it.w;
				x[it.i] = -1; // it.i番目のアイテムを実数値にした
				isInteger = false;
				break;
			}
		}
		return Result{res, x, isInteger};
	}

	size_t getN() const { return n; }
};

class BranchAndBound {
private:
	class Node {
	private:
		const long long value;
		const std::vector<int> valueSelection;
		const std::vector<int> fixedSelection; // -1 -> not selected
	public:
		static BranchAndBound* BB;
		Node() : value(-1), valueSelection(), fixedSelection() {}
		Node(long long value, std::vector<int> valueSelection, std::vector<int> fixedSelection) :
			value(value), valueSelection(valueSelection), fixedSelection(fixedSelection) {}
		Node& operator=(const Node& rhs) { return (Node&)rhs; }
		static Node makeNode(std::vector<int> selection) {
			auto&& result = BB->problem.calcSubProblem(selection);
			return makeNode(result, selection);
		}
		static Node makeNode(KnapsackProblem<long long>::Result result, std::vector<int> selection) {
			return Node(result.value, result.selection, selection);
		}
		long long getValue() const { return value; }
		std::vector<int> getValueSelection() const { return valueSelection; }
		std::vector<int> getFixedSelection() const { return fixedSelection; }
	};

	KnapsackProblem<long long> problem;
	KnapsackProblem<long long>::Result best;
	size_t nodeNum;
	std::stack<Node> notSerchNodes;

public:
	BranchAndBound(KnapsackProblem<long long> problem) : problem(problem), best({-1}), nodeNum(0) {
		Node::BB = this;
	}

	KnapsackProblem<long long>::Result solve() {
		// step 0. (初期化)
		std::vector<int> emptySet(problem.getN(), -1);

		KnapsackProblem<long long>::Result result(problem.calcSubProblem(emptySet));
		if (result.isInteger) { // 連続問題を解いてそれが整数制約を満たしていれば
			return result;
		}
		else {
			notSerchNodes.push(Node::makeNode(result, emptySet));
		}

		// step 1. (分枝ノードの選択)
		while (!notSerchNodes.empty()) {
			Node selectedNode = notSerchNodes.top();
			notSerchNodes.pop();
			if (selectedNode.getValue() < best.value) { // step 4.の(ノード検査)をここに入れ込む
				continue;
			}

			// step 2. (分枝変数の選択)
			int boundIdx = -1;
			std::vector<int> selection = selectedNode.getValueSelection();
			for (size_t variableIdx = 0; variableIdx < selection.size(); ++variableIdx) {
				if (selection[variableIdx] == -1) {
					boundIdx = variableIdx;
					break;
				}
			}

			std::vector<std::vector<int>> subSelection(2, selectedNode.getFixedSelection());

			subSelection[0][boundIdx] = 0;
			subSelection[1][boundIdx] = 1;

			// step 3. (分枝計算)
			std::vector<KnapsackProblem<long long>::Result> subResult(2);
			for (size_t childIdx = 0; childIdx < 2; ++childIdx) {
				subResult[childIdx] = problem.calcSubProblem(subSelection[childIdx]);
			}

			// step 4. (ノード検査)
			for (size_t childIdx = 0; childIdx < 2; ++childIdx) {
				auto&& res = subResult[childIdx];
				if (res.value == -1) { // 子ノードが解けなかったとき
					continue;
				}
				if (res.value >= best.value) { // 子ノードが暫定解よりよい場合
					if (res.isInteger) { // 整数制約を満たしている場合
						best = res; // 暫定解を更新
					}
					else {
						notSerchNodes.push(Node::makeNode(res, subSelection[childIdx]));
					}
				}
			}
		}
		return best;
	}
};
BranchAndBound* BranchAndBound::Node::BB;

