//添え字p,残り容量qから最大の利益となる利益vを返す
int np(vector<pii> &item, int p, int q){
    static vector<vector<int>> dp;
    for(auto a : dp){
        if(a[0]==p && a[1]==q){
            return a[2];
        }
    }
    int v;
    if(p==n){
        v=0;
    }else if(q<item[p].first){
        v=np(item,p+1,q);
    }else{
        v=max(np(item,p+1,q), np(item,p+1,q-item[p].first)+item[p].second);
    }
    dp.push_back(vector<int>{p,q,v});
    return v;
}

