int main(void) {
    lint n, bag_w;
    cin >> n >> bag_w;

    lint std_w;
    vector<vector<lint>> item(4);
    repeat(i, n) {
        lint w, v;
        cin >> w >> v;
        if (i == 0) {
            item[0].emplace_back(v);
            std_w = w;
        }
        else {
            lint dif = w - std_w;
            item[dif].emplace_back(v);
        }
    }

    repeat(i, 4) {
        sort(item[i].begin(), item[i].end(), greater<lint>());
    }

    vector<vector<lint>> item_value(4);
    repeat(i, 4) item_value[i].emplace_back(0);

    repeat(i, 4) {
        lint partial_sum = 0;
        repeat(j, (int)item[i].size()) {
            partial_sum += item[i][j];
            item_value[i].emplace_back(partial_sum);
        }
    }

    auto calc_val = [&item_value](int a, int b, int c, int d) -> lint {
        lint ret = 0;
        ret += item_value[0][a];
        ret += item_value[1][b];
        ret += item_value[2][c];
        ret += item_value[3][d];
        return ret;
    };

    lint ans = 0;
    repeat_from_to(a, 0, n) {
        repeat_from_to(b, 0, n) {
            repeat_from_to(c, 0, n) {
                repeat_from_to(d, 0, n) {
                    if (a > (int)item[0].size() || b > (int)item[1].size() || c > (int)item[2].size() || d > (int)item[3].size()) continue;
                    lint tot_w = a * std_w + b * (std_w+1) + c * (std_w+2) + d * (std_w+3);
                    if (tot_w > bag_w) continue;
                    ans = max(ans, calc_val(a, b, c, d));
                    //dump(a); dump(b); dump(c); dump(d); dump(tot_w); dump(ans); cout << endl;
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

