ll rec(int  i, int  j, int count){
    if (dp[i][j][count] > 0) return dp[i][j][count];
    if (i == n) return 0;
    ll ret = 0;
    int wd = w[i] - w[0];
    if (j + wd + w[0] * (count + 1) <= W){
        ret = v[i] + rec(i + 1, j + wd, count + 1);
    }
    ret = max(ret, rec(i + 1, j, count));

    return dp[i][j][count] = ret;
}

