	for (int i = 1; i <= n; i++) C[i][0] = 0;

	for (int i = 1; i <= n; i++) {
		for (int w = 1; w <= weight; w++) {
			if (items[i].weight <= w) {
				if (items[i].value + C[i - 1][w - items[i].weight] > C[i - 1][w]) {
					C[i][w] = items[i].value + C[i - 1][w - items[i].weight];
					G[i][w] = DIAGONAL;
				} else {
					C[i][w] = C[i - 1][w];
					G[i][w] = LEFT;
				}
			} else {
				C[i][w] = C[i - 1][w];
				G[i][w] = LEFT;
			}
		}
	}

	maxValue = C[n][weight];

	path.clear();
	int w = weight;

	for (int i = n; i >= 1; i--) {
		if (G[i][w] == DIAGONAL) {
			path.push_back(i);
			w -= items[i].weight;
		}
	}

	reverse(path.begin(), path.end());
}

void input() {
	cin >> n >> weight;
	for (int i = 1; i <= n; i++) {
		cin >> items[i].weight >> items[i].value;
	}
}

int main() {
	int maxValue;
	vector<int> path;
	input();
	compute(maxValue, path);

	cout << maxValue << endl;
}

