/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, W, wM;
ll vsum[4][104];
vector<vl> vs;
vl w, v;

void solve(){
    wM = 1;
    rep(i, n){
        w.pb(0); v.pb(0);
        in2(w[i], v[i]);
        wM = max(wM, w[i]);
    }

    rep(i, 4) vs.pb({});

    rep(i, n){
        if (wM - w[i] == 0) vs[3].pb(v[i]);
        else if (wM - w[i] == 1) vs[2].pb(v[i]);
        else if (wM - w[i] == 2) vs[1].pb(v[i]);
        else if (wM - w[i] == 3) vs[0].pb(v[i]);
    }

    rep(i, 4) sort(rall(vs[i]));
    rep(i, 4) vsum[i][0] = 0;
    rep(i, 4) rep(j, vs[i].size()) vsum[i][j + 1] = vsum[i][j] + vs[i][j];

    ll ww[4], vv[4];
    rep(i1, vs[0].size() + 1){
        ww[0] = i1 * (wM - 3); if (ww[0] > W) break;
        vv[0] = vsum[0][i1];
        rep(i2, vs[1].size() + 1){
            ww[1] = i2 * (wM - 2); if (ww[0] + ww[1] > W) break;
            vv[1] = vsum[1][i2];
            rep(i3, vs[2].size() + 1){
                ww[2] = i3 * (wM - 1); if (ww[0] + ww[1] + ww[2] > W) break;
                vv[2] = vsum[2][i3];
                rep(i4, vs[3].size() + 1){
                    ww[3] = i4 * wM; if (ww[0] + ww[1] + ww[2] + ww[3] > W) break;
                    vv[3] = vsum[3][i4];
                    answer = max(vv[0] + vv[1] + vv[2] + vv[3], answer);
                }
            }
        }
    }
    prl(answer);
}

int main(void){
    in2(n, W);
    solve();

    return 0;
}

