int N, W;
vector<int> w(100), v(100);
map<pii, int> mp;

long long f(int i, int j) {
    if (mp[pii(i, j)]) return mp[pii(i, j)];

    int res;
    if (i == N) res = 0;
    else if (j < w[i]) res = f(i + 1, j);
    else res = max(f(i + 1, j), f(i + 1, j - w[i]) + v[i]);
    return mp[pii(i, j)] = res;
}

