long max_knapsack(long i, long j) {
    long v;
    if (note[i][j] != -1) {
        return note[i][j];
    }
    if (i == 0 || j == 0) {
        v = 0;
    } else if (j < wa[i - 1]) {
        v = max_knapsack(i - 1, j);
    } else {
        v = std::max(
            max_knapsack(i - 1, j),
            max_knapsack(i - 1, j - wa[i - 1]) + va[i - 1]
            );
    }
    note[i][j] = v;
    return v;
}

