ll rec(int i, int avail, int N, vector<ll>& W, vector<ll>& V,
       map<pair<int, ll>, ll>& memo)
{
  if (i >= N) { return 0; }
  if (memo.count(make_pair(i, avail)) != 0) {
    return memo[make_pair(i, avail)];
  }
  ll ret = 0;
