struct OBJ {
	LL w;
	LL v;
	double v_w;
	OBJ(LL _w,LL _v){
		w=_w;
		v=_v;
		if (w!=0){
			v_w=(double)v/(double)w;
		}else{
			v_w=0.0;
		}
	}
	bool operator>=(const OBJ &obj){
		return v_w>=obj.v_w;
	}
	bool operator<(const OBJ &obj){ 
		return v_w < obj.v_w; 
	}
};
bool desc(const OBJ &obj1,const OBJ &obj2){
	if (obj1.v>obj2.v){
		return true;
	}else if (obj1.v>obj2.v){
		return obj1.w<obj2.w;
	}else{
		return false;
	}
};
