ll dfs(ll now_limit, vector<vector<ll>> &wv, int n, ll rest, ll cnt) {
	if(n == 4) {
		return cnt;
	}
	ll ans = 0;
	for(int i=0;i<=min(now_limit, (ll)wv[n].size()-1);i++) {
		ll next_limit = (rest - i * (n + sw)) / (n + 1 + sw);
		ans = max(ans, dfs(next_limit, wv, n + 1, rest - i * (n + sw), cnt + wv[n][i]));
	}
	return ans;
}

