        chmax(dp.at(i).at(j + w), dp.at(i - 1).at(j) + v);
    }
  }

  int ans = 0;
  for (int i = 0; i <= min(W - w0, 3 * N + 9); i++)
  {
    chmax(ans, dp.at(N - 1).at(i));
  }

  cout << ans << endl;
}

