  if(stor[{curr, weight}]) return mp[{curr, weight}];
  if(p[curr].f <= weight)
  {
    aa = findans(curr+1, weight - p[curr].f) + p[curr].s;
  }
  bb = findans(curr+1, weight);
  stor[{curr, weight}] = 1;
  return mp[{curr, weight}] = max(aa, bb);
}

