void solve(long long N, long long W, std::vector<long long> w,
           std::vector<long long> v) {
    vector<vector<ll>> dp(N, vector<ll>(W+1, 0));
    for (int i = 0; i < N; i++) {
	for (int j = 0; j <= W ; j++) {
	    ll prev = 0;
	    ll prev2 = 0;
	    if (i-1 >= 0) prev = dp[i-1][j];
	    if (i-1 >= 0 and j-w[i] >= 0) prev2 = dp[i-1][j-w[i]];
	    dp[i][j] = max(prev, prev2 + ((j >= w[i]) ? v[i] : 0));
        }
    }
    cout << dp.back().back() << endl;
}

