int W;

int Search(int a, int w, vector<vector<int>> &d, const vector<int> &l, vector<int> &k) {
	if (W < w)
		return 0;
	int i, ans = 0;
	for (i = 0; i < 4; i++)
		ans += d[i][k[i]];
	for (i = 0; i < 4; i++) {
		if (l[i] > k[i]) {
			k[i]++;
			ans = max(ans, Search(a, w + a + i, d, l, k));
			k[i]--;
		}
	}
	return ans;
}

