int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, W;
    cin >> N >> W;    
    vector<pair<int, int>> wv(N);
    rep(i, N) cin >> wv[i].first >> wv[i].second;
    int wmin = wv[0].first;
    vector<vector<vector<ll>>> dp(N);
    ll ans = 0;

    rep(i, N) {
        wv[i].first -= wmin;
    }

    rep(i, N) {
        dp[i].resize(N + 1);

        rep(ii, N + 1) {
            dp[i][ii].resize(N * 3, 0);
        }
    }

    rep(i, N) {
        if (i == 0) {
            dp[i][1][wv[i].first] = wv[i].second;
        }
        else {
            reps(ii, 1, N + 1) {
                if (ii == 1) {
                    rep(iii, N * 3) {
                        if (iii == wv[i].first) {
                            dp[i][ii][iii] = max(dp[i - 1][ii][iii], (ll)wv[i].second);
                        }
                        else {
                            dp[i][ii][iii] = dp[i - 1][ii][iii];
                        }
                    }
                }
                else {
                    rep(iii, N * 3) {
                        if (iii < wv[i].first) {
                            dp[i][ii][iii] = dp[i - 1][ii][iii];
                            continue;
                        }

                        if (dp[i - 1][ii - 1][iii - wv[i].first] == 0) {
                            continue;
                        }

                        dp[i][ii][iii] = max(dp[i - 1][ii][iii], dp[i - 1][ii - 1][iii - wv[i].first] + wv[i].second);
                    }
                }
            }
        }
    }

    rep(i, N + 1) {
        rep(ii, N * 3) {
            if ((i * wmin + ii) > W) {
                continue;
            }

            ans = max(ans, dp[N - 1][i][ii]);
        }
    }

    cout << ans << endl;
    return 0;
}

