	VI w(n), v(n);
	REP(i, n) { cin >> w[i] >> v[i]; }

	VI values[4];
	REP(i, n) { values[w[i] - w[0]].push_back(v[i]); }
	REP(i, 4) { sort(ALL(values[i]), greater()); }

	VI values_sum[4];
	REP(i, 4) {
		int size = values[i].size();
		values_sum[i].resize(size + 1);
		values_sum[i][0] = 0;
		REP(j, size) { values_sum[i][j + 1] = values_sum[i][j] + values[i][j]; }
	}

	int result = 0;
	for(int i = 0; i < values_sum[0].size() && i * w[0] <= w_max; i++) {
		for(int j = 0;
			j < values_sum[1].size() && i * w[0] + j * (w[0] + 1) <= w_max;
