				ll bwam = DP(num + 1, onenum , weight) + hoge; cnt = max(cnt, bwam); 
				zero.push_back(hoge);
			}
		}
		if (izryt == 1) {
			if (one.size()) {
				ll hoge = one.back(); one.pop_back();
				ll bwam = DP(num + 1, onenum+1, weight + 1) + hoge; cnt = max(cnt, bwam); 
				one.push_back(hoge);
			}
		}
		if (izryt == 2) {
			if (two.size()) {
				ll hoge = two.back(); two.pop_back();
				ll bwam = DP(num + 1, onenum, weight + 2) + hoge;  cnt = max(cnt, bwam); 
