		for(int i = 0;i <= 3;i++)
			sort(v[i] + 1,v[i] + sw[i] + 1,cmp);
		for(int i = 0;i <= sw[0];i++)
		{
			sum0 += v[0][i];
			for(int j = 0;j <= sw[1];j++)
			{
				sum1 += v[1][j];
				for(int k = 0;k <= sw[2];k++)
				{
					sum2 += v[2][k];
					int lw = w - i * stdw - j * (stdw + 1) - k * (stdw + 2);
					if(lw < 0)continue;
					int c =	lw / (stdw + 3);
					if(c <= sw[3])
					{
						for(int t = 1;t <= c;t++)
							sum3 += v[3][t];
					}
					if(sum3 + sum2 + sum1 + sum0 > ans)ans = sum3 + sum2 + sum1 + sum0;
					sum3 = 0;
				}
				sum2 = 0;
			}
			sum1 = 0;
		}
		printf("%d\n", ans);
	}

}

