using ll = long long;

//vector
template <class T>
using vec = std::vector<T>;

struct Item
{
    int value;
    int weight;
};

class DpKnapsack
{
private:
    static constexpr ll nil = -1;

    vec<Item> items;
    vec<vec<ll>> dp;
    ll W;

public:
    DpKnapsack(vec<Item> items, ll W)
        : items {items}
        , dp {vec<vec<ll>>(items.size(), vec<ll>(W + 1, nil))}
        , W {W}
    {}

    ll ans(int w)
    {
        return solve(items.size() - 1, w);
    }

private:

    // i番目の品物までで制約jのときの最大値
    ll solve(int i, int j)
    {
        if (i < 0 || j <= 0)
            return 0;
        if (dp[i][j] != nil)
            return dp[i][j];

        dp[i][j] = solve(i - 1, j);
        if (j >= items[i].weight)
            dp[i][j] = std::max(dp[i][j], solve(i - 1, j - items[i].weight) + items[i].value);

        return dp[i][j];
    }

};

void solve()
{
    using namespace std;

    // Wが小さいときのナップサック
    int N, W;
    cin >> N >> W;
    vec<Item> items(N);
    for (auto & x : items)
        cin >> x.weight >> x.value;

    DpKnapsack dp {items, W};

    cout << dp.ans(W) << endl;
}

int main()
{
    solve();
    return 0;
}

