  for (int i = 0; i < I; i++) result += -vv[0][i];
  for (int j = 0; j < J; j++) result += -vv[1][j];
  for (int k = 0; k < K; k++) result += -vv[2][k];
  for (int l = 0; l < L; l++) result += -vv[3][l];
  return result;
}

