        for(int j=0; j<=N; j++){
            for(int k=0; k<=N; k++){
                int l = N - i - j - k;
                if(l < 0) continue;

                ll wsum = 0;
                ll vsum = 0;
                for(int t=0; t<i; t++){
                    if(a[w0].size() <= t) break;
                    wsum = wsum + w0;
                    vsum = vsum + a[w0][t];
                }
                for(int t=0; t<j; t++){
                    if(a[w0+1].size() <= t) break;
                    wsum = wsum + w0+1;
                    vsum = vsum + a[w0+1][t];
                }
                for(int t=0; t<k; t++){
                    if(a[w0+2].size() <= t) break;
                    wsum = wsum + w0+2;
                    vsum = vsum + a[w0+2][t];
                }
                for(int t=0; t<l; t++){
                    if(a[w0+3].size() <= t) break;
                    wsum = wsum + w0+3;
                    vsum = vsum + a[w0+3][t];
                }

                if(wsum > W) continue;
                ans = max(ans, vsum);
            }
        }
    }

    cout << ans << endl;

    return 0;
}

