using namespace std;

struct para
{
    long long int w, v;
};

// 重さ 昇順
bool wasc(para a, para b)
{
    if (a.w < b.w)
        return true;

    return false;
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    long long int  N, W;
    cin >> N >> W;

    vector<para> p(N);

    for (int i = 0; i < N; i++) cin >> p[i].w >> p[i].v;

    // 重さ 昇順
    sort(p.begin(), p.end(), wasc);

    // 重さ 4通り グループ分け
    vector<long long int> a, b, c, d;

    for (int i = 0; i < N; i++)
    {
        if (p[i].w == p[0].w) a.push_back(p[i].v);

        if (p[i].w == p[0].w + 1) b.push_back(p[i].v);

        if (p[i].w == p[0].w + 2) c.push_back(p[i].v);

        if (p[i].w == p[0].w + 3) d.push_back(p[i].v);
    }

    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    sort(c.begin(), c.end());
    sort(d.begin(), d.end());

    // 価値 降順
    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());
    reverse(c.begin(), c.end());
    reverse(d.begin(), d.end());

    // 価値 降順 累積和
    for (int i = 1; i < (signed)a.size(); i++) a[i] += a[i - 1];
    for (int i = 1; i < (signed)b.size(); i++) b[i] += b[i - 1];
    for (int i = 1; i < (signed)c.size(); i++) c[i] += c[i - 1];
    for (int i = 1; i < (signed)d.size(); i++) d[i] += d[i - 1];

    long long int ans = 0;
    for (int i = 0; i <= (signed)a.size(); i++)
    {
        for (int j = 0; j <= (signed)b.size(); j++)
        {
            for (int k = 0; k <= (signed)c.size(); k++)
            {
                // グループ A B C 重さ 合計
                long long int
                    wag = i * p[0].w + j * (p[0].w + 1) + k * (p[0].w + 2);

                // 制限超過
                if (wag > W) continue;

                // グループ D 数
                // グループ A B C 重さ 合計 から 算出
                long long int l = (W - wag) / (p[0].w + 3);

                if ((int)d.size() < l) l = d.size();

                long long int s = 0LL;

                if (i != 0LL) s += a[i - 1];

                if (j != 0LL) s += b[j - 1];

                if (k != 0LL) s += c[k - 1];

                if (l != 0LL) s += d[l - 1];

                if (s > ans) ans = s;
            }
        }
    }
    cout << ans;
    return 0;
}

