using namespace std;



ll knapsack_dp(ll wt[],ll price[], ll n, ll w)
{
	vector<vector<ll>>dp(n+1,vector<ll>(w+1,0));
	for(ll i = 1; i <= n; i++)
	{
		for(ll j = 1; j <= w; j++)
		{
			if(i == 0 || j == 0) dp[i][j] = 0;
			else if(wt[i-1] <= j)
			{
				dp[i][j] = max(dp[i-1][j],price[i-1] + dp[i-1][j-wt[i-1]]);
			}
			else
			{
				dp[i][j] = dp[i-1][j];
			}
		}
	}
	return dp[n][w];
}
