std::map<std::pair<int, int>, int> note;

int max_knapsack(int i, int j) {
    int v;
    std::pair<int, int> p = std::make_pair(i, j);
    if (note.find(p) != note.end()) {
        return note[p];
    }
    if (i == 0 || j == 0) {
        v = 0;
    } else if (j < wa[i - 1]) {
        v = max_knapsack(i - 1, j);
    } else {
        v = std::max(
            max_knapsack(i - 1, j),
            max_knapsack(i - 1, j - wa[i - 1]) + va[i - 1]
            );
    }
    note[p] = v;
    return v;
}

