class nap {
public:
    ll w;
    ll v;
};
int N, MaxCnt, cnt;
ll W, ans = 0;

void Sort(nap x[]);
int Search(nap x[], ll vv, ll ww, int n);

int main() {
    cin >> N >> W;

    nap x[N];

    for (int i = 0; i < N; i++) {
        cin >> x[i].w >> x[i].v;
    }
    MaxCnt = W / x[0].w;
    Sort(x);
    // for (int i = 0; i < N; i++) {
    //     cout << x[i].w << " " << x[i].v << endl;
    // }
    Search(x, 0, 0, -1);
    cout << ans << endl;

    return 0;
}

void Sort(nap x[]) {
    for (int i = 0; i < N; i++) {
        for (int j = N - 1; j > i; j--) {
            if (x[j].v > x[j - 1].v) {
                nap tmp;
                tmp = x[j];
                x[j] = x[j - 1];
                x[j - 1] = tmp;
            }
        }
    }
}

int Search(nap x[], ll vv, ll ww, int n) {
    if(n >= MaxCnt or ww >= W or n >= N) {
        ans = max(ans, vv);
        //cout << "OK: " << ans << endl;
        return 0;
    }
    n++;
    if (ww + x[n].w <= W) {
        Search(x, vv + x[n].v, ww + x[n].w, n);
    }
    Search(x, vv, ww, n);
    return 0;
}

