{
	if (a > SZ(wv[0]) || b > SZ(wv[1]) || c > SZ(wv[2]) || d > SZ(wv[3]))
		return -LLMAX;

	if (a * w + b * (w + 1) + c * (w + 2) + d * (w + 3) > lim)
		return -LLMAX;

	ll ret = 0;
	if (a)
		ret += accumulate(wv[0].begin(), wv[0].begin() + a, 0);
	if (b)
		ret += accumulate(wv[1].begin(), wv[1].begin() + b, 0);
