		ret += accumulate(wv[2].begin(), wv[2].begin() + c, 0);
	if (d)
		ret += accumulate(wv[3].begin(), wv[3].begin() + d, 0);

	chmax(ret, dfs(a + 1, b, c, d));
	chmax(ret, dfs(a, b + 1, c, d));
	chmax(ret, dfs(a, b, c + 1, d));
	chmax(ret, dfs(a, b, c, d + 1));

	return ret;
}

