  REP(i,0,N) cin >> w[i] >> v[i];
  // dp テーブル初期化 (-1 で)
  REP(i,0,N) {
    REP(j,0,W+1) dp[i][j] = -1;
  }

  long res = rec(0, W);
  cout << res << endl;

  return 0;
}

