// ABC060D Simple Knapsack

ll solve(int N, int W, vector<ll> &ws, vector<ll> &vs);

int main() {
    ios::sync_with_stdio(false);
    int N, W;
    vector<ll> ws(100, 0);
    vector<ll> vs(100, 0);

    cin >> N >> W;
    for (int i = 0; i < N; ++i) cin >> ws[i] >> vs[i];

    cout << solve(N, W, ws, vs) << endl;
