static int64_t W;
static vector<vector<int32_t>> value(4);
static int64_t weights[4];
static vector<vector<vector<vector<int32_t>>>> memo;

static int32_t dfs(int32_t rest0, int32_t rest1, int32_t rest2, int32_t rest3)
{
	if (memo[rest0][rest1][rest2][rest3] > numeric_limits<int32_t>::min())
		return memo[rest0][rest1][rest2][rest3];

	int32_t res = 0;
	if (rest0 > 0)
		res = max(res, dfs(rest0 - 1, rest1, rest2, rest3) + value[0][rest0 - 1]);
	if (rest1 > 0)
		res = max(res, dfs(rest0, rest1 - 1, rest2, rest3) + value[1][rest1 - 1]);
	if (rest2 > 0)
		res = max(res, dfs(rest0, rest1, rest2 - 1, rest3) + value[2][rest2 - 1]);
	if (rest3 > 0)
		res = max(res, dfs(rest0, rest1, rest2, rest3 - 1) + value[3][rest3 - 1]);

	memo[rest0][rest1][rest2][rest3] = res;
	return res;
}

int main()
{
	int32_t N;
	scanf("%d%" PRId64, &N, &W);

	int64_t first_w;
	int32_t first_v;
	scanf("%" PRId64 "%d", &first_w, &first_v);
	value[0].push_back(first_v);
	for (int32_t i = 1; i < N; i++) {
		int64_t w;
		int32_t v;
		scanf("%" PRId64 "%d", &w, &v);
		w -= first_w;
		value[w].push_back(v);
	}
	for (int32_t i = 0; i < 4; i++) {
		sort(value[i].begin(), value[i].end());
		weights[i] = first_w + i;
	}

	memo.resize(value[0].size() + 1);
	for (int64_t i = 0; i <= (int64_t)value[0].size(); i++) {
		memo[i].resize(value[1].size() + 1);
		for (int64_t j = 0; j <= (int64_t)value[1].size(); j++) {
			memo[i][j].resize(value[2].size() + 1);
			for (int64_t k = 0; k <= (int64_t)(int64_t)value[2].size(); k++) {
				memo[i][j][k].resize(value[3].size() + 1);
				for (int64_t l = 0; l <= (int64_t)value[3].size(); l++) {
					memo[i][j][k][l] = numeric_limits<int32_t>::min();
					if (((int64_t)value[0].size() - i) * weights[0] + ((int64_t)value[1].size() - j) * weights[1] +
					    ((int64_t)value[2].size() - k) * weights[2] + ((int64_t)value[3].size() - l) * weights[3] > W) {
						memo[i][j][k][l] = numeric_limits<int32_t>::min() + 1;
					}
				}
			}
		}
	}

	printf("%d\n", dfs(value[0].size(), value[1].size(), value[2].size(), value[3].size()));

	return 0;
}

