	long long int v0s[101],v1s[101],v2s[101],v3s[101];
	scanf("%d %lld", &N, &W);
	for(int i=0; i<N; i++){
		scanf("%lld %lld", &w, &v);
		if(i==0){
			w1=w;
			v0.insert(v);
			n0++;
