			n0++;
		}else if(w==w1+1){
			v1.insert(v);
			n1++;
		}else if(w==w1+2){
			v2.insert(v);
			n2++;
		}else{
			v3.insert(v);
			n3++;
		}
	}
	v0s[0]=0, v1s[0]=0, v2s[0]=0, v3s[0]=0;
	if(n0!=0){
	auto itr=v0.end();
	int k=0;
	while(itr!=v0.begin()){
		itr--;
		k++;
		v=*itr;
		v0s[k]=v0s[k-1]+v;
	}
	}
	if(n1!=0){
	auto itr=v1.end();
	int k=0;
	while(itr!=v1.begin()){
		itr--;
