    for(int i = 1; i <= N; ++i){
        for(int j = 1; j <= i; ++j){
            for(int k = 0; k <= i * 3; ++k){
                if(dp[i][j][k] == -1)   continue;
                if((ll)base * j + k <= W)   chmax(ans, dp[i][j][k]);
            }
        }
    }
