long long knapsack(int n, int w,vector<pair<int ,int>> a){
    long long dp[n][w+1];
    for (int i=0; i<n; i++){
        for (int j=0; j<w+1; j++){
            dp[i][j]=0;
        }
    }
    dp[0][a[0].second]=a[0].first;
    for (int i=1; i<n; i++){
        int v_i=a[i].first, w_i=a[i].second;
        for (int j=1; j<w+1; j++){
            if (j<w_i){
                dp[i][j]=dp[i-1][j];
            }
            else {
                dp[i][j]=max(dp[i-1][j],dp[i-1][j-w_i]+v_i);
            }
        }
    }
    long long ans=0;
    for (int i=1;i<w+1; i++){
        ans=max(ans,dp[n-1][i]);
    }
    return ans;
}

