const int MAX_N = 101;
const int MAX_W = 5000; // Wの最大値
int n, W;
int v[MAX_N];
int w[MAX_N];

// i番目以降の品物から重さの和がj以下なるように選んだときの、
// 取りうる価値の総和の最大値を返す関数
int rec(int i, int j) {
	int res;
	if (i == n) {
		// 品物がもう残っていないときは、価値の和の最大値は0で確定
		res = 0;
	} else if (j < w[i]) {
		// 残りの容量が足りず品物iを入れられないので、入れないパターンだけ処理
		// i+1 以降の品物で判定したときの最大値をそのままこの場合の最大値にする
		res = rec(i + 1, j);
	} else {
		// 品物iを入れるか入れないか選べるので、両方試して価値の和が大きい方を選ぶ
		res = max(
			rec(i + 1, j),
			rec(i + 1, j - w[i]) + v[i]
		);
	}
	return res;
}


// メモ化テーブル
// dp[i][j]はi番目以降の品物から重さの和がj以下なるように選んだときの価値の和の最大値を表す。
// -1なら値が未決定であることを表す
int dp[MAX_N + 1][MAX_W + 1];
// i番目以降の品物から重さの和がj以下なるように選んだときの、
// 取りうる価値の総和の最大値を返す関数。メモ配列で計算結果を再利用する
int rec_dp(int i, int j) {
	if (dp[i][j] != -1) {
		// すでに調べたことがあるならその結果を再利用
		return dp[i][j];
	}
	int res;
	if (i == n) {
		// 品物がもう残っていないときは、価値の和の最大値は0で確定
		res = 0;
	} else if (j < w[i]) {
		// 残りの容量が足りず品物iを入れられないので、入れないパターンだけ処理
		res = rec_dp(i + 1, j);
	} else {
		// 品物iを入れるか入れないか選べるので、両方試して価値の和が大きい方を選ぶ
		res = max(
			rec_dp(i + 1, j),
			rec_dp(i + 1, j - w[i]) + v[i]
		);
	}
	// 結果をテーブルに記憶する
	return dp[i][j] = res;
}

// メモ化再帰を用いた解法
void solve_dp() {
	for (int i = 0; i < n + 1; i++)
		for (int j = 0; j < MAX_W + 1; j++)
			dp[i][j] = -1;

	// 0番目以降で容量W以下の場合の結果を表示する
	cout << rec_dp(0, W) << endl;
}



int main() {
	cin >> n >> W;
	for (int i = 0; i < n; i++) {
		cin >> w[i] >> v[i];
	}
	solve_dp(); // メモ化再帰によるDP
	return 0;
}

