			if (i == 0) {
				W = W - (w[0] - 1);
			}
			else {
				w[i] = w[i]-W+1;
				W = 1;
			}
		}
	}

	memset(dp, -1, sizeof(dp));

	cout << DP(N,0, W) << endl;
	return 0;
}

