void solve(){
  // main algorithm
  dp[0][0][0] = 0;
  for (ll i = 0; i < N; ++i)
  {
    for (ll j = 0; j <= i * 3; ++j)
    {
      for (ll k = 0; k <= i; ++k)
      {
        if (dp[i][j][k] != -1)
        {
          dp[i+1][j][k] = max(dp[i+1][j][k], dp[i][j][k]);
          ll jj = j + A[i] - A[0];
          dp[i+1][jj][k+1] = max(dp[i+1][jj][k+1], dp[i][j][k] + (ll)B[i]);
        }
      }
    }
  }
  for (ll i = 0; i <= N; ++i)
  {
    for (ll j = 0; j + A[0] * i <= M; ++j)
    {
      ans = max(ans, dp[N][j][i]);
