  else
    return gcd(n,m%n);
}

//table[w][i]:重さw以下でi番目まで入れたときの最大の価値
int main(){
  int N,W;
  cin>>N>>W;
  vector<int> weights(N),values(N);
  for(int i=0;i<N;++i){
    cin>>weights[i]>>values[i];
  }

  int g = weights[0];
  for(int i=1;i<N;++i){
    g = gcd(g,weights[i]);
  }
  g = gcd(g,W);
  for(auto &w:weights) w /= g;
  W /= g;

  vector<vector<int>> table(W+1,vector<int>(N+1));

  for(int w=1;w<=W;++w){
    for(int i=1;i<=N;++i){
      if(w<weights[i-1]){
        table[w][i] = table[w][i-1];
      }else{
        table[w][i] = max(table[w-weights[i-1]][i-1]+values[i-1],table[w][i-1]);
      }
    }
  }
  cout<<table[W][N]<<endl;

  return 0;
}

