    cin >> w0 >> v0;
    v[0].push_back(v0);
    for(ll i = 1; i < N; i++){
        ll wi, vi;
        cin >> wi >> vi;
        v[wi - w0].push_back(vi);
    }
    for(ll i = 0; i < 4; i++){
        sort(v[i].begin(), v[i].end(), greater<ll>());
    }
    vector<ll>sum[4];
    for(ll i = 0; i < 4; i++){
        sum[i].push_back(0);
        for(ll j = 0; j < v[i].size(); j++){
            sum[i].push_back(sum[i][j] + v[i][j]);
        }
    }
    map<ll, ll>A;
    for(ll i = 0; i < sum[0].size(); i++){
        for(ll j = 0; j < sum[1].size(); j++){
            ll w = i * (w0) + j * (w0 + 1);
            A[w] = max(A[w], sum[0][i] + sum[1][j]);
        }
    }
    A[-2] = 0;
    A[-1] = 0;
    A[1e16] = 0;
    ll ans = 0;
    for(ll i = 0; i < sum[2].size(); i++){
        for(ll j = 0; j < sum[3].size(); j++){
            ll w = i * (w0 + 2) + j * (w0 + 3);
            ll sm = sum[2][i] + sum[3][j];
            if(W < w)continue;
            if(W == w)ans = max(ans, sm);
            else{
                ll red = W - w;
                map<ll, ll>::iterator it = A.lower_bound(red);
                if((*it).first > red)it--;
                ans = max(ans, sm + (*it).second);
            }
        }
    }
    cout << ans << endl;

    return 0;
}

