int knapsack(int w,vector<pair<int,int> > items)
{
    vector<vector<int> > dp(items.size()+4,vector<int>(w+4,0));
    for(int i=1 ; i<=items.size() ; ++i)
    {
        for(int j=1 ; j<=w ; ++j)
        {
            if(items[i-1].first<=j)
            dp[i][j]=max(dp[i-1][j],dp[i-1][j-items[i-1].first]+items[i-1].second);
            else
            dp[i][j]=dp[i-1][j];
        }
    }
    return dp[items.size()][w];
}

