int main() {
  ll N, W;
  Read(N, W);

  vector<ll> v[4];
  ll w1, u;
  Read(w1, u);
  v[0].push_back(u);

  for (int i = 0; i < N - 1; i++) {
    ll t;
    Read(t, u);
    t = t - w1;
    v[t].push_back(u);
  }

  for (int i = 0; i < 4; i++) {
    sort(v[i].begin(), v[i].end(), greater<int>());
  }
  vector<ll> s[4];
  for (int i = 0; i < 4; i++) {
    s[i].resize(Size(v[i]) + 1);
    for (int j = 0; j <= Size(v[i]); j++) {
      if (j == 0) {
        s[i][0] = 0;
      } else {
        s[i][j] = s[i][j - 1] + v[i][j - 1];
      }
    }
  }

  ll v_max = 0;
  for (int i = 0; i <= N; i++) {
    if (i >= Size(s[0])) {
      break;
    }
    for (int j = 0; j <= N - i; j++) {
      if (j >= Size(s[1])) {
        break;
      }
      for (int k = 0; k <= N - i - j; k++) {
        if (k >= Size(s[2])) {
          break;
        }
        for (int l = 0; l <= N - i - j - k; l++) {
          if (l >= Size(s[3])) {
            break;
          }
          ll w_ = w1 * i + (w1 + 1) * j + (w1 + 2) * k + (w1 + 3) * l;
          if (w_ > W) {
            break;
          }
          ll t = s[0][i] + s[1][j] + s[2][k] + s[3][l];
          v_max = max(v_max, t);
        }
      }
    }
  }

  Print(v_max);

  return 0;
}
