			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b, c-1, d) + v[i]);
		}
		else if ((w[1] == w[0] + 3)&& d != 0) {

			res = max(func(i + 1, j, a, b, c, d), func(i + 1, j - w[i], a, b, c, d-1) + v[i]);
		}
		else {
			res = func(i + 1, j, a, b, c, d);
		}
	}
	//return memo[i][j]=res;
	return res;
}

