    //printf("bucket sz = %d %d %d %d\n", bucketsz[0], bucketsz[1], bucketsz[2], bucketsz[3]);
    for (int k = 0; k < 4; k ++) {
        sort(bucket[k], bucket[k] + bucketsz[k], std::greater<int>());
    }
    int bestvalue = 0;
    for (int i0 = 0; i0 <= bucketsz[0]; i0 ++)
    for (int i1 = 0; i1 <= bucketsz[1]; i1 ++)
    for (int i2 = 0; i2 <= bucketsz[2]; i2 ++)
    for (int i3 = 0; i3 <= bucketsz[3]; i3 ++) {
        int weight = 0, value = 0;
