int rec(vector<int> w, vector<int> v, int i, int j, int cnt){
  if(dp[i][j] >= 0){
    return dp[i][j];
  }
  int res;
  if(i == N){
    res = 0;
  }else if(j < w[i] + a){
    res = rec(w, v, i + 1, j, cnt);
  }else{
    res = max(rec(w, v, i + 1, j, cnt), rec(w, v, i + 1, j - (w[i] + a), cnt + 1) + v[i]);
  }
  return dp[i][j] = res;
}

