ll dfs(int n, ll wt) {
    if (n >= N) return 0;

    if (dp[wt] > 0) return dp[wt];

    ll ret = 0;
    if (wt+w[n] <= W) {
        ll yes = dfs(n + 1, wt + w[n]) + v[n];
        ll no = dfs(n + 1, wt);
        ret = max(yes, no);
    } else {
        ret = dfs(n + 1, wt);
    }

    dp[wt] = ret;
    return ret;
}

