// i番目以降の品物から重さの総和がj以下となるように選ぶ
int rec(int i, int j, int n, int *w, int *v, int **dp) {
    int res;
    if (i == n) {
        res = 0;
        return res;
    } else if (j < w[i]) {
        if (dp[i][j] >= 0) {
            return dp[i][j];
        }
        // 指定の重さjよりも荷物が重い場合，荷物はいれられないので次の荷物に進む
        res = rec(i + 1, j, n, w, v, dp);
    } else {
        if (dp[i][j] >= 0) {
            return dp[i][j];
        }
        // 荷物をいれることができる場合，荷物をいれた場合といれない場合の二通りで試す
        int rec1 = rec(i + 1, j, n, w, v, dp);
        int rec2 = rec(i + 1, j - w[i], n, w, v, dp) + v[i];
        if (rec1 < rec2) {
            res = rec2;
        } else {
            res = rec1;
        }
    }
    dp[i][j] = res;
    return dp[i][j];
}

void solve(int W, int n, int *w, int *v) {
    int **dp = new int *[n + 1];
    for (int i = 0; i < n; ++i) {
        dp[i] = new int[W + 1];
        for (int j = 0; j < W + 1; ++j) {
            dp[i][j] = -1;
        }
    }
    int ans = rec(0, W, n, w, v, dp);
    cout << ans << endl;
    for (int i = 0; i < n; ++i) {
        delete[] dp[i];
    }
    delete[] dp;
}

int main() {
    long long int N, W;
    cin >> N >> W;
    int w[N], v[N];
    for (int i = 0; i < N; ++i) {
        cin >> w[i] >> v[i];
    }
    solve(W, N, w, v);
    return 0;
}

