        for (int l = 0; l < v[3].size(); l++) {
          r -= w1+3;
          if (r < 0 || l == v[3].size()-1) {
            ans = max(ans, -rv);
            break;
          }
          rv += v[3][l];
        }
        q -= w1+2;
        if (q < 0 || k == v[2].size()-1) {
          ans = max(ans, -qv);
          break;
        }
        qv += v[2][j];
      }
      p -= w1+1;
      if (p < 0 || j == v[1].size()-1) {
        ans = max(ans, -pv);
        break;
      }
      pv += v[1][j];
    }
    t -= w1;
    if (t < 0 || i == v[0].size()-1) {
      ans = max(ans, -tv);
      break;
    }
    tv += v[0][i];
  }

  cout << ans << endl;
  return 0;
}

