int t[101][101][101][101];
void SimpleKnapsack() {

	int n;
	ll W;
	cin >> n >> W;
	ll wf = -1;
	int ar[4] = {0,0,0,0};
	int res = 0;
	for (size_t i = 0; i < n; i++)
	{
		ll w;
		int v;
		cin >> w >> v;
		if (wf == -1) {
			wf = w;
		}
		int mi = w - wf;
		for (short j = 0; j <= ar[0]; j++)
		{
			int tj = j * wf;
			if (tj > W) break;
			for (short k = 0; k <= ar[1]; k++)
			{
				int tk = tj + k * (wf + 1);
				if (tk > W) break;
				for (short g = 0; g <= ar[2]; g++)
				{
					int tg = tk + g * (wf + 2);
					if (tg > W) break;
					for (short u = 0; u <= ar[3]; u++)
					{
						int tu = tg + u * (wf + 3);
						if (tu + (wf + mi) > W) break;
						int aa = max(t[j + (mi == 0)][k + (mi == 1)][g + (mi == 2)][u + (mi == 3)]
								, t[j][k][g][u] + v);
						t[j + (mi == 0)][k + (mi == 1)][g + (mi == 2)][u + (mi == 3)] = aa;
						res = max(aa, res);
					}
				}
			}
		}
		ar[mi]++;
	}
	cout << res << endl;

}
int main() {

	SimpleKnapsack();
	return 0;
}

