      if(j!=-1){
        wsum1+=(w1+1)*(j+1);
        vsum1+=b[1][j];
      }
      if(wsum1>W)break;
      for(int k=-1;k<(int)a[2].size();k++){
        ll wsum2 = wsum1;
        ll vsum2 = vsum1;
        if(k!=-1){
          wsum2+=(w1+2)*(k+1);
          vsum2+=b[2][k];
        }
        if(wsum2>W)break;
        for(int h=-1;h<(int)a[3].size();h++){
          ll wsum3 = wsum2;
          ll vsum3 = vsum2;
          if(h!=-1){
            wsum3+=(w1+3)*(h+1);
            vsum3+=b[3][h];
          }
