class item
{
public:
	int w, v;
	bool operator < (item& rhs){
		if(rhs.v == v)
			return rhs.w > w;
		return rhs.v < v;
	}
};

int N, W;
VI A, B, C, D;
LL minwt;
const int MAXN = 101;
vector<vector<VVI>> cache;
int MPV(int a, int b, int c, int d)
{
	if(a < 0 || b < 0 || c < 0 || d < 0)
		return 0;

	int& dp = cache[a][b][c][d];
	if(dp != -1)
		return dp;

	int ret = 0;
	LL sum = a * minwt + b * (minwt + 1) + c * (minwt + 2) + d * (minwt + 3);
	if(sum > W)
	{
		ret = max(ret, MPV(a - 1, b, c, d));
		ret = max(ret, MPV(a, b - 1, c, d));
		ret = max(ret, MPV(a, b, c - 1, d));
		ret = max(ret, MPV(a, b, c, d - 1));
	}
	else
	{
		if(a > 0) ret += A[a - 1];
		if(b > 0) ret += B[b - 1];
		if(c > 0) ret += C[c - 1];
		if(d > 0) ret += D[d - 1];
	}
	return dp = ret;
}

int knapsack()
{
	vector<item> items(N);

	 minwt = LLONG_MAX;
	 REP(i, 0, N){
	 	cin >> items[i].w >> items[i].v;
		minwt = min(minwt, (LL)items[i].w);
	 }
	 REP(i, 0, N)
	 {
		 int wt = items[i].w, val = items[i].v;
		 if(wt - minwt == 0)
		 	A.push_back(val);
		 else if(wt - minwt == 1)
		 	B.push_back(val);
		 else if(wt - minwt == 2)
		 	C.push_back(val);
		else
			D.push_back(val);
	 }	

	 sort(ALL(A), greater<int>());
	 sort(ALL(B), greater<int>());
	 sort(ALL(C), greater<int>());
	 sort(ALL(D), greater<int>());

	 partial_sum(ALL(A), A.begin());
	 partial_sum(ALL(B), B.begin());
	 partial_sum(ALL(C), C.begin());
	 partial_sum(ALL(D), D.begin());

	 int a = sz(A), b = sz(B), c = sz(C), d = sz(D);
	 cache.assign(a + 1, vector<VVI>(b + 1, VVI(c + 1, VI(d + 1, -1))));

	 return MPV(a, b, c, d);
}

