  valueMap.insert(make_pair(0, q0));
  priority_queue<int> q1;
  valueMap.insert(make_pair(1, q1));
  priority_queue<int> q2;
  valueMap.insert(make_pair(2, q2));
  priority_queue<int> q3;
  valueMap.insert(make_pair(3, q3));

  rep(i, N) {
