map<pll,ll>K;

ll knapSack(ll W, ll wt[], ll val[],ll n){
   if(K[make_pair(n,W)]) return K[make_pair(n,W)];
   if (n == 0 || W == 0)
       return K[make_pair(n,W)]=0;

   if (wt[n-1] > W)
       return K[make_pair(n-1,W)]=knapSack(W, wt, val, n-1);

   else return K[make_pair(n,W)]=max( val[n-1] + knapSack(W-wt[n-1], wt, val, n-1),
                    knapSack(W, wt, val, n-1)
                  );
}

