using namespace std;
const int maxn = 100 + 10;

int n, m, k;
int dp[2][10000010];

int w[maxn], v[maxn];
int cnt[10], base[10], t[10];

int calc(int u) {
    int ans = 0;
    ans += (u % cnt[0]) * k;       u /= cnt[0];
    ans += (u % cnt[1]) * (k + 1); u /= cnt[1];
    ans += (u % cnt[2]) * (k + 2); u /= cnt[2];
    ans += u * (k + 3);
    return ans;
}
int main() {

    scanf("%d%d", &n, &m);

    cnt[0] = cnt[1] = cnt[2] = cnt[3] = 1;
    for(int i = 0; i < n; i++) {
        scanf("%d%d", &w[i], &v[i]);
        if(i == 0) k = w[i];
        ++cnt[ w[i] -= k ];
    }

    for(int i = 0; i < 4; i++) t[i] = cnt[i];

    base[0] = 1;
    for(int i = 1; i < 4; i++) 
        base[i] = t[i-1], t[i] *= t[i-1];

    int cur = 1;
    memset(dp, -1, sizeof dp);

    dp[0][0] = 0;
    for(int i = 0; i < n; i++) {
        for(int j = 10000000+10-1; j >= base[w[i]]; j--) {
            dp[cur][j] = dp[cur^1][j]; 
            if(dp[cur^1][j-base[w[i]]] >= 0)
                dp[cur][j] = max(dp[cur][j], dp[cur^1][j-base[w[i]]] + v[i]);
        }

        for(int j = base[w[i]]-1; j >= 0; j--)
            dp[cur][j] = dp[cur^1][j];

        cur ^= 1;
    }
    int ans = 0, lim = 0;
    for(int i = 0; i < n; i++) lim += base[w[i]];

    if(lim >= 10000000) for(;;);

    for(int j = 0; j <= lim; j++) {
        if(calc(j) <= m) {
            if(dp[cur^1][j] > ans) {
                ans = dp[cur^1][j];
            }
        }
    }
    printf("%d\n", ans);

    return 0;
}

