    int N, W;
    cin >> N >> W;    
    vector<pair<int, int>> wv(N);
    rep(i, N) cin >> wv[i].first >> wv[i].second;
    int wmin = wv[0].first;
    vector<vector<vector<int>>> dp(N);
    int ans = 0;

    rep(i, N) {
        wv[i].first -= wmin;
    }

    rep(i, N) {
        dp[i].resize(N + 1);

        rep(ii, N + 1) {
            dp[i][ii].resize(N * 3, 0);
        }
    }

    rep(i, N) {
        if (i == 0) {
            dp[i][1][wv[i].first] = wv[i].second;
            continue;
        }

        reps(ii, 1, N + 1) {
            if (ii == 1) {
                rep(iii, N * 3) {
                    if (iii == wv[i].first) {
                        dp[i][ii][iii] = max(dp[i - 1][ii][iii], wv[i].second);
