const int maxn = 110;
int N,W, w[maxn],v[maxn];
map< pair<int,LL>, LL > dp;

LL dfs(const int i, const LL j)
{
    if (i == N)
        return 0;
    pair<int,LL> k = make_pair(i,j);
    if (!in_(k,dp)) {
        if (j + w[i] <= W)
            dp[k] = max(dp[k], v[i]+dfs(i+1,j+w[i]));
        dp[k] = max(dp[k], dfs(i+1,j));
    }
    return dp[k];
}

