ll rec(ll W, ll i){
        ll res;
        if(i==N){
                res=0;
        }
        else if(W<w[i]){
                res=rec(W, i+1);
        }
        else{
                res=max(rec(W, i+1), rec(W-w[i], i+1)+v[i]);
        }
        return res;
}

