using namespace std;

int main() {
	int N, W;
	vector<int> v, w;

	cin >> N >> W;

	int x, y, weight_std;
	REP(i, N) {
		cin >> x >> y;
		v.push_back(y);
		if (i == 0) {
			weight_std = x - 1;
			w.push_back(1);
		}
		else {
			w.push_back(x - weight_std);
		}
	}


	if (W < w[0]) {
		cout << 0 << endl;
		return 0;
	}

	int dp[100][50001] = { 0 }, num[100][50001] = { 0 };

	REP(i, N) {
		REP(j, W + 1) {
			if (i != 0) {
				if (j - w[i] >= 0) {
					dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - w[i]] + v[i]);
					if (dp[i - 1][j] == dp[i - 1][j - w[i]] + v[i]) {
						num[i][j] = min(num[i - 1][j], num[i - 1][j - w[i]] + 1);
					}
					else if (dp[i - 1][j] < dp[i - 1][j - w[i]] + v[i]) {
						num[i][j] = num[i - 1][j - w[i]] + 1;
					}
					else {
						num[i][j] = num[i - 1][j];
					}
				}
				else {
					dp[i][j] = dp[i - 1][j];
					num[i][j] = num[i - 1][j];
				}
			}
			else {
				if (j - w[i] >= 0) {
					dp[i][j] = v[i];
					num[i][j] = 1;
				}
			}
		}
	}

	int ans = 0;
	REP(i, min(W + 1, 50001)) {
		if (W - i - num[N - 1][i] * weight_std >= 0) {
			ans = max(ans, dp[N - 1][i]);
		}
	}
	//cout << dp[N - 1][4] << " " << dp[N - 1][W] << " " << num[N - 1][W] << endl;
	cout << ans << endl;

	return 0;
}

