int knapsack(int n, int w, int wt[], int c[])
{
  	int k[n+1][w+1];
  	memset(k, 0, sizeof(k));
	for(int i = 1; i < n+1; i++)
    {
    	for(int j = 1; j < w+1; j++)
        {
        	if(wt[i-1] <= j)
              	k[i][j] = max(c[i-1] + k[i-1][j-wt[i-1]], k[i-1][j]);
          	else
              	k[i][j] = k[i-1][j];
        }
    }
    return k[n][w];
}

