  for(int i=0; i<N; i++){
    cin >> data.at(i).second >> data.at(i).first;
  }

  auto comp= [](item a, item b){
    return a.first* b.second > b.first* a.second;
  };
  sort(data.begin(), data.end(), comp);

  bitset<Nmax> choice;

  cout << solve(0, 0, 0, &choice, data, W) << endl;
}

