// given n items( val , weight )
// you have a bag with max limit K
// find the max values you can take and put in the bag
// ( Knapsack Problem )

const int N = 1000 , W = 10009;
long long n , val[N] , w[N] ;
long long mem[N][W] , k ;

long long dp(long long i,long long sum){

if( i==n )return 0; // no more items to take

if( mem[i][sum]!=-1 )return mem[i][sum];

long long ans = dp(i+1,sum); // skip this item
if( sum+w[i] <=k )// try to take this item
    ans=max( ans , val[i]+dp(i+1,sum+w[i]) );

return mem[i][sum]=ans;
}

