int main() {
    int n, W;
    cin >> n >> W;
    vl w(n), v(n);
    ll totW = 0;
    ll totV = 0;
    vector<deque<ll>> pq(4);
    for (int i = 0; i < n; ++i) {
        cin >> w[i] >> v[i];
        totW += w[i];
        totV += v[i];
        pq[w[i] - w[0]].emplace_back(v[i]);
    }
    for (int i = 0; i < 4; ++i) {
        sort(pq[i].begin(), pq[i].end(), greater<ll>());
    }
    for (int i = 0; i < 4; ++i) {
        pq[i].push_front(0); // centinel
    }
    vvl vv(4);
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < pq[i].size(); ++j) {
            if (j == 0) {
                vv[i].push_back(pq[i][0]);
            } else {
                vv[i].push_back(pq[i][j] + vv[i][j - 1]);
            }
        }
