using namespace std;
#define MAX 100
#define PATURN 4
int knapsack(int W, int w, int wm, int *ws, int wv[][MAX], int s[][MAX+1], int c, int v) {
	int ret = v;
	if (c >= PATURN) return 0;
	for (int i = 0;i <= ws[c];i ++) {
		if (w+(wm+c)*i>W) break;
		ret = max(ret, knapsack(W, w+(wm+c)*i, wm, ws, wv, s, c+1, v+s[c][i]));
	}
	return ret;
}
int main() {
	int n, w, wm, ws[PATURN], wv[PATURN][MAX], wc, s[PATURN][MAX+1];
	for (int i = 0;i < PATURN;i ++) {
		ws[i] = 0;
	}
	cin >> n >> w;
	cin >> wm >> wv[0][0];
	ws[0] ++;
	for (int i = 1;i < n;i ++) {
		cin >> wc;
		cin >> wv[wc-wm][ws[wc-wm]];
		ws[wc-wm] ++;
	}
	for (int i = 0;i < PATURN;i ++) {
		sort(wv[i], wv[i]+ws[i]);
		s[i][0] = 0;
		for (int j = 0;j < ws[i];j ++) {
			s[i][j+1] = s[i][j] + wv[i][j];
		}
	}
	int ret = 0;
	for (int i = 0;i <= ws[0];i ++) {
		if (wm*i>w) break;
		ret = max(ret, knapsack(w, wm*i, wm, ws, wv, s, 1, s[0][i]));
	}
	cout << ret;
}

