        for( int j = 0; j <= v[1].size(); ++j ) {
            if( j != 0 ) {
                ++w2;
                v2 += v[1][j - 1];

            }
            LL w3 = 0, v3 = 0;
            for( int k = 0; k <= v[2].size(); ++k ) {
                if( k != 0 ) {
                    ++w3;
                    v3 += v[2][k - 1];

                }
                LL w4 = 0, v4 = 0;
                for( int l = 0; l <= v[3].size(); ++l ) {
                    if( l != 0 ) {
                        ++w4;
                        v4 += v[3][l - 1];

                    }
                    if( w1 * w + w2 * (w + 1) + w3 * (w * 2) + w4 * (w * 3) <= W ) {
                        res = max(res, v1 + v2 + v3 + v4);

                    }
                }
            }
        }
    }
    cout << res << endl;
    return 0;
}

