void solve(int w0) {
	rep(i, 0, 4)
		w[i] = w0+i;
	rep(i, 0, 4) {
		sort(vc[i].begin(), vc[i].end(), greater<int>());
		const int sz = vc[i].size();
		c[i] = sz;
		vs[i].push_back(0LL);
		rep(j, 0, sz) {
			LL x = vs[i][j] + vc[i][j];
			vs[i].push_back(x);
		}
	}

	LL ans = 0, tmp;

	for (int x=0; x<=c[0]; ++x) {
		if (x*w[0] > W) break;
		for (int y=0; y<=c[1]; ++y) {
			if (x*w[0]+y*w[1] > W) break;
			for (int z=0; z<=c[2]; ++z) {
				if (x*w[0]+y*w[1]+z*w[2] > W) break;

