long memo[100+1][100+1];

long dp(long num, long weight) {
  if(memo[num][weight] != -1) {
    return memo[num][weight];
  }

  long ret = 0;
  if(num == number_of_item){
   ret = 0;
  } else if (weight < w[num]) {
    ret = dp(num+1, weight);
  } else {
    ret = max(dp(num+1, weight),
               dp(num+1, weight -w[num]) + v[num]);
  }
  memo[num][weight] = ret;
  return ret;
}

