void dfs(long long w,long long v,int i,int j,int k,int m)
{
	if(w<=vv)
	{
		if(v>maxm)
		maxm=v;
		if(i<=len0)
		dfs(w+a[i].w,v+a[i].v,i+1,j,k,m);
		if(j<=len1)
		dfs(w+b[j].w,v+b[j].v,i,j+1,k,m);
		if(k<=len2)
		dfs(w+c[k].w,v+c[k].v,i,j,k+1,m);
		if(m<=len3)
		dfs(w+d[m].w,v+d[m].v,i,j,k,m+1);
	}
}
int main()
{
    int n,i,j,k,h,m;
