			{
				len1++;
				b[k].w=w;
				b[k].v=v;
				k++;
			}
			else if(w==s+2)
			{
				len2++;
				c[h].w=w;
				c[h].v=v;
				h++;
			}
			else
			{
				len3++;
				d[m].w=w;
				d[m].v=v;
				m++;
			}
		}
		sort(a+1,a+n+1,cmp);
		sort(b+1,b+n+1,cmp);
		sort(c+1,c+n+1,cmp);
		sort(d+1,d+n+1,cmp);
		dfs(0,0,0,0,0,0);
		printf("%d\n",maxm);
	}
    return 0;
}

