  for ( int i=0; i<N; i++ ) {
    wList[i] -= wBase;
  }

  int dp[N+1][N+1][W_+1];
  for ( int n=0; n<N+1; n++ ) {
    for ( int k=0; k<N+1; k++ ) {
      for ( int w=0; w<W_+1; w++ ) {
        dp[n][k][w] = 0;
      }
    }
