long memo[S][S][MW];

int input(){
	std::cin >> N >> W;
	for( int i = 0; i < S; i++ ){
		for( int j = 0; j < S; j++ ){
			for( int k = 0; k < MW; k++ ){
				memo[i][j][k] = -1;
			}
		}
	}
	for( int i = 0; i < N; i++ ){
		std::cin >> w[i] >> v[i];
	}
	for( int i = 0; i < N; i++ ){
		w2[i] = w[i] - w[0];
	}
	return 0;
}

long search(int i, int c, long u){
	//printf("%d,%d,%ld\n", i, c, u);
	if( i == N ){ return 0; }
	if( memo[i][c][u] >= 0 ){ return memo[i][c][u]; }
	//std::cout << c*(w[0]+3)-u << std::endl;
	long v1 = v[i] + search(i+1, c+1, u-w2[i]);
	if( (c+1)*w[0] + (3*N - u + w2[i]) > W ){ v1 = -INF; }
	long v2 = search(i+1, c, u);
	//printf("%d,%d,%ld, %ld,%ld\n", i, c, u, v1, v2);
	memo[i][c][u] = (v1>v2?v1:v2);
}

int run(){
	long re = search(0, 0, 3*N);
	std::cout << re << std::endl;
	return 0;
}

