  for(int i = 0; i*(w0+cnt) <= W && i <= wv[cnt].size(); i++) {
    if(i > 0) sum += wv[cnt][i-1];
    chmax(ret, sum + dfs(W-i*(w0+cnt), cnt+1));
  }

  return ret;
}

