      if (wt + w <= m)
        dp[t][wt + w] = max(dp[t][wt + w], va + v);
    }
  }
  int ans = 0;
  // 最後に更新したtを用いてdp[t]を取り出す
  for (auto x : dp[t])
    ans = max(ans, x.second);
  cout << ans << endl;
  return 0;
}

