  REP(i,0,N) cin >> w[i] >> v[i];
  // dp テーブル初期化 (-1 で)
  REP(i,0,N+1) {
    for (long j = 0; j < W + 1; ++j) {
      dp[i][j] = -1;
    }
  }

  long res = rec(0, W);
  cout << res << endl;

  return 0;
}

