using namespace std;
const int MAX_N = 100;
int n, W;
int w[MAX_N], v[MAX_N];
// i番目以降の品物から重さの和がj以下なるように選んだときの、
// 取りうる価値の総和の最大値を返す関数
int rec(int i, int j) {
  int res;
  if (i == n) {
    // 品物がもう残っていないときは、価値の和の最大値は0で確定
    res = 0;
  } else if (j < w[i]) {
    // 残りの容量が足りず品物iを入れられないので、入れないパターンだけ処理
    // i+1 以降の品物のみを使ったときの最大値をそのままこの場合の最大値にする
    res = rec(i + 1, j);
  } else {
    // 品物iを入れるか入れないか選べるので、両方試して価値の和が大きい方を選ぶ
    res = max(
        rec(i + 1, j),
        rec(i + 1, j - w[i]) + v[i]
    );
  }
  return res;
}
int main () {
  cin >> n >> W;
  for(int i=0; i<n ; i++) cin >> w[i] >> v[i];
  // 0番目以降で容量W以下の場合の結果を表示する
  cout << rec(0, W) << endl;
}

