knap(int n,int tw)
{
    int i,j;
     for(i=0; i<n; i++)
    {
        for(j=0; j<=tw; j++)
        {
            if(j==0) dp[i][j]=0;
            else if(j<w[i])dp[i][j]=dp[i-1][j];
            else dp[i][j]=max(v[i]+dp[i-1][j-w[i]],dp[i-1][j]);
        }
    }
    return dp[n-1][tw];
}
