#include <iostream>
#include <vector>

const int MAX_N = 100;

int n, w;
int wa[MAX_N];
int va[MAX_N];
long note[MAX_N + 1][1000000000];

long max_knapsack(long i, long j) {
    long v;
    if (note[i][j] != -1) {
        return note[i][j];
    }
    if (i == 0 || j == 0) {
        v = 0;
    } else if (j < wa[i - 1]) {
        v = max_knapsack(i - 1, j);
    } else {
        v = std::max(
            max_knapsack(i - 1, j),
            max_knapsack(i - 1, j - wa[i - 1]) + va[i - 1]
            );
    }
    note[i][j] = v;
    return v;
}

int main() {
    std::cin >> n >> w;
    for (int i = 0; i < n; i++) {
        std::cin >> wa[i] >> va[i];
    }
    for (int i = 0; i < n + 1; i++) {
        for (int j = 0; j < w + 1; j++) {
            note[i][j] = -1;
        }
    }
    std::cout << max_knapsack(n, w) << std::endl;
}

