int func(int i, int j){
  pair<int, int> tmp = make_pair(i, j);
  if(dp.find(tmp)==dp.end()){
    if(i==0 || j==0){
      return dp[tmp]=0;
    }
    else if(j<w[i]){
      return dp[tmp]=func(i-1, j);
    }
    else{
      return dp[tmp]=max(func(i-1, j), func(i-1, j-w[i-1])+v[i-1]);
    }
  }
  else{
    return dp[tmp];
  }
}

