using namespace std;

ll knapSack(ll W, ll wt[], ll val[], int n)
{
   ll i, w;
   ll K[n+1][W+1];

   // Build table K[][] in bottom up manner
   for (i = 0; i <= n; i++)
   {
       for (w = 0; w <= W; w++)
       {
           if (i==0 || w==0)
               K[i][w] = 0;
           else if (wt[i-1] <= w)
                 K[i][w] = max(val[i-1] + K[i-1][w-wt[i-1]],  K[i-1][w]);
           else
                 K[i][w] = K[i-1][w];
       }
   }

   return K[n][W];
}

int main()
{
    int n; ll w;
    cin >> n >> w;

    ll wt[n];
    ll val[n];

    for(int i = 0; i<n; i++)
    {
        cin >> wt[i] >> val[i];
    }

    cout << knapSack(w, wt, val, n) << endl;
}

