// i番目まで見たときの、j個使って重さの総和がk以下のときの価値の最大値が入る。
// 実際の重さの総和は、(j * w[0] + k)   これとWを比較してdpテーブルを埋める。
ll dp[101][101][301];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, W;
    cin >> n >> W;
    vector<int> w(n), v(n);
    int sub;
    for(int i = 0; i < n; ++i){
        cin >> w[i] >> v[i];
        if(i == 0){
            if(W < w[0]){
                cout << 0 << endl;
                return 0;
            }
            sub = w[0];
        }
        w[i] -= sub;
    }

    // dpテーブルを埋める三重ループ O(n^3)
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < i + 1; ++j){
            for(int k = 0; k <= n * 3; ++k){
                // (i+1)番目を使わない場合
                dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k]);

                // (i+1)番目を使う場合
                if(k >= w[i] && (j + 1) * sub + k <= W){
                    dp[i + 1][j + 1][k] = max(dp[i + 1][j + 1][k], dp[i][j][k - w[i]] + v[i]);
                }
            }
        }
    }

    ll res = 0;
    for(int i = 0; i <= n; ++i){
        for(int j = 0; j <= n * 3; ++j){
            if(i * sub + j <= W){
                res = max(res, dp[n][i][j]);
            }
        }
    }
    cout << res << endl;
}

