int main() {
  int n, W;
  scanf("%d%d", &n, &W);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d", &w[i], &v[i]);
  }
  int ret = 0;
  for (int k = 1; k <= n && (int64)w[0] * k <= W; ++k) {
    int rem = W - w[0] * k;
    memset(dp, 255, sizeof(dp));
    dp[0][0] = 0;
    for (int i = 0; i < n; ++i) {
      int cur = w[i] - w[0];
      for (int j = k; j >= 1; --j) {
        for (int u = min(rem, 3 * k); u >= cur; --u) {
