          dp[j][u] = max(dp[j][u], dp[j - 1][u - cur] + v[i]);
        }
      }
    }
    for (int u = 0; u <= rem; ++u) {
      if (dp[k][u] < 0) continue;
      ret = max(ret, dp[k][u]);
    }
  }
  printf("%d\n", ret);
  return 0;
