int n, w, base;

bool visited[100][100][100][100] = {};

llong solve(priority_queue<int> que[4], llong sum, llong weight, int num[4]){
  llong res = 0;
  bool pushed = false;
  REP(i,4){
    num[i]++;
    if(!que[i].empty() && weight + base + i <= w && !visited[num[0]][num[1]][num[2]][num[3]]){
      visited[num[0]][num[1]][num[2]][num[3]] = true;
      pushed = true;
      int tmp = que[i].top();
      que[i].pop();
      res = max(solve(que, sum + tmp, weight + base + i, num), res);
      que[i].push(tmp);
    }
    num[i]--;
  }

  if(!pushed){
    return sum;
  }

  return res;
}

int main(){

  scanf("%d %d", &n ,&w);

  priority_queue<int> que[4];
  REP(i,n){
    int t1, t2;
    scanf("%d %d", &t1, &t2);
    if(i == 0){
      base = t1;
    }
    que[t1 - base].push(t2);
  }

  int num[4] = {};
  printf("%lld\n", solve(que, 0, 0, num));

  return 0;
}

