int main(void) {
  int n;
  ll limit;
  scanf("%d%lld", &n, &limit);
  REP(i, n) {
    scanf("%lld%lld", &cs[i], &vs[i]);
    ks[cs[i]-cs[0]].push_back(vs[i]);
  }
  REP(i, 4) {
    sort(ks[i].begin(), ks[i].end());
    reverse(ks[i].begin(), ks[i].end());
    REP(j, ks[i].size()) {
      ss[i][j+1] = ss[i][j] + ks[i][j];
    }
  }
  ll res = 0;
  REP(i0, ks[0].size()+1) REP(i1, ks[1].size()+1) REP(i2, ks[2].size()+1) {
    ll w = cs[0]*i0 + (cs[0]+1)*i1 + (cs[0]+2)*i2;
    if(w > limit) {
      continue;
    }
    int i3 = min((ll)ks[3].size(), (limit - w) / (cs[0]+3));
    // cerr << i0 << " " << i1 << " " << i2 << " " << i3 << " " << w << endl;
    res = max(res, ss[0][i0] + ss[1][i1] + ss[2][i2] + ss[3][i3]);
