    for (int i = 0; i < N; i++) cin >> w[i] >> v[i];

    vector<vector<int>> vv(4);
    for (int i = 0; i < N; i++) {
        vv[w[i] - w[0]].push_back(v[i]);
    }

    for (int i = 0; i < 4; i++) {
        sort(vv[i].begin(), vv[i].end());
        vv[i].push_back(0);
        reverse(vv[i].begin(), vv[i].end());
        for (int j = 1; j < vv[i].size(); j++) {
            vv[i][j] += vv[i][j - 1];
        }
    }

    int ans = 0;
    for (int i = 0; i <= vv[0].size(); i++) {
        for (int j = 0; j < vv[1].size(); j++) {
            for (int k = 0; k < vv[2].size(); k++) {
                for (int l = 0; l < vv[3].size(); l++) {
                    long long wei = 1LL * w[0] * i + 1LL * (w[0] + 1) * j + 1LL * (w[0] + 2) * k + 1LL * (w[0] + 3) * l;
                    int val = vv[0][i] + vv[1][j] + vv[2][k] + vv[3][l];
                    if (wei <= 1LL * W) ans = max(ans, val);
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

