	ll max = 0;
	stack<pii> s;
	set<int> bag;
	s.push(pii(0, 1));
	s.push(pii(0, 0));
	while (!s.empty()) {
		pii c = s.top();
		if (c.second == 2) {
			s.pop();
			s.pop();
			bag.erase(c.first);
			continue;
		}
		if (c.second == 1) {
			bag.insert(c.first);
		}

