struct pair_hash {
	template<typename T1, typename T2>
	std::size_t operator()(const std::pair<T1, T2> &p) const {
		const auto h1 = std::hash<T1>{}(p.first);
		const auto h2 = std::hash<T2>{}(p.second);
		return h1 ^ h2;
	}
};

std::unordered_map<std::pair<int, int>, int, pair_hash> map;

int solve(int, std::vector<std::pair<int, int>>);

int SOLVE(int W, std::vector<std::pair<int, int>> item) {
	if(map.find(std::make_pair(W, item.size())) != map.end()) {
		return map.at(std::make_pair(W, item.size()));
	} else {
		int a = solve(W, item);
		map[std::make_pair(W, item.size())] = a;
		return a;
	}
}

// 
int solve(int W, std::vector<std::pair<int, int>> item) {
	if(W == 0 || item.empty()) {
		return 0;
	} else {
		auto item2 = item;
		item2.erase(item2.begin());
		const int w = item.front().first;
		const int v = item.front().second;
		// 強度が足りる
		if(w <= W) {
			return std::max(SOLVE(W, item2), SOLVE(W - w, item2) + v);
		} else {
			return SOLVE(W, item2);
		}
	}
}

int main() {
	int N, W;
	std::cin >> N >> W;

	std::vector<std::pair<int, int>> item(N);
	for(int i = 0; i < N; i++) {
		int w, v;
		std::cin >> w >> v;
		item[i] = std::make_pair(w, v);
	}

	std::cout << solve(W, item) << std::endl;

	return 0;
}

