template <typename X, typename Y, typename Z, typename... Zs> auto vectors(X x, Y y, Z z, Zs... zs) { auto cont = vectors(y, z, zs...); return vector<decltype(cont)>(x, cont); }
constexpr ll inf = ll(1e18)+9;
int main() {
    int n, total_w; scanf("%d%d", &n, &total_w);
    vector<int> w(n), v(n); repeat (i,n) scanf("%d%d", &w[i], &v[i]);
    int base = w[0];
    vector<int> delta(n);
    repeat (i,n) {
        delta[i] = w[i] - base;
        assert (0 <= delta[i] and delta[i] <= 3);
    }
    ll result = 0;
    for (int cnt = total_w / (base + 3); ; ++ cnt) {
        int total = total_w - cnt*base;
        if (total <= 0) break;
        auto dp = vectors<ll>(2, cnt+1, total + 1, - inf);
        auto & cur = dp[0];
        auto & prv = dp[1];
        cur[0][0] = 0;
        repeat (i,n) {
            prv = cur;
            repeat_reverse (j,cnt) {
                repeat_reverse (k,total+1) if (k+delta[i] <= total) {
                    setmax(cur[j+1][k+delta[i]], cur[j][k] + v[i]);
                }
            }
        }
        repeat (j,cnt+1) {
            repeat (k,total+1) {
                setmax(result, cur[j][k]);
            }
