	return left.vs < right.vs;
}

void f(size_t num, int vadd, int wadd, int passed)
{
	if (maxv > vadd + allv - vl[passed])
	{
		return;
	}

	if (passed + 1 == asize)
	{
		maxv = max(maxv, vadd);
		return;
	}

	if (wadd + arr[num].w <= w)
	{
		f(num + 1, vadd + arr[num].v, wadd + arr[num].w, passed + 1);
	}
	f(num + 1, vadd, wadd, passed + 1);
}

