long long int dfs(int remain_weight,int index)
{
	if(remain_weight < w[index])
	{
		if(memo[remain_weight][index] != -1)
		{
			return memo[remain_weight][index];
		}
		else
		{
			memo[remain_weight][index] = dfs(remain_weight,index+1);
			return memo[remain_weight][index];
		}
	}
	else if(index == n)
	{
		return 0;
	}
	else
	{
		return max(dfs(remain_weight-w[index],index+1)+v[index],dfs(remain_weight,index+1));
	}
}


