int rec(int i,int j){
  if (dp[i][j] >= 0) {
    return dp[i][j];
  }

  int res;
  if (i == N) {
    res = 0;
  } else if (j < w[i]) {
    res = rec(i+1,j);
  } else {
    res = max(rec(i+1,j), rec(i+1,j-w[i])+v[i]);
  }

  return dp[i][j] = res;
}

