// binary search
ll BSearch(ll _begin, ll _end, bool (*f)(int)){
  ll mid;
  while(_end - _begin > 1LL) {
  mid = (_begin + _end) / 2LL;
  if(f(mid)) {
    debug("BSearch: f(%d) == true\n", mid);
    _end = mid;
  }
  else
  {
    debug("BSearch: f(%d) == false\n", mid);
    _begin = mid;
  }
  }
  return _end;
}


ll N,M,K,A[NMAX],B[NMAX],C,D,E;
ll dp[NMAX][3 * NMAX][NMAX];

string S;
vec v;

ll ans = 0;

void solve(){
  // main algorithm
  dp[0][0][0] = 0;
  for (ll i = 0; i < N; ++i)
  {
    for (ll j = 0; j <= i * 3; ++j)
    {
      for (ll k = 0; k <= i; ++k)
      {
        if (dp[i][j][k] != -1)
        {
          dp[i+1][j][k] = max(dp[i+1][j][k], dp[i][j][k]);
          ll jj = j + A[i] - A[0];
          dp[i+1][jj][k+1] = max(dp[i+1][jj][k+1], dp[i][j][k] + (ll)B[i]);
        }
      }
    }
  }
  for (ll i = 0; i <= N; ++i)
  {
    for (ll j = 0; j + A[0] * i <= M; ++j)
    {
      ans = max(ans, dp[N][j][i]);
    }
  }
}
