	LL tem=(W/w[1])+1;
	m=min(n,tem);
	for(int i=0;i<=m;i++){
		for(int j=0;i+j<=m;j++)
			for(int k=0;i+j+k<=m;k++){
				res=i*w[1]+j*w[2]+k*w[3];
				if(res>W) continue;
				else if(res<=W){
					int l=0;
					if(w[4]!=0) l=(W-res)/w[4];
					ans=max(ans,getsum(i,j,k,l));
				}
			}
	}
	cout<<ans;
	return 0;
}

