  	cin.tie(0);

	int N, W;
	cin >> N >> W;

	vector< pair<int, int> > obj(N);
	vector<ll> a, b, c, d;

	for (int i = 0; i < N; i++)
		cin >> obj[i].first >> obj[i].second;

	sort(obj.begin(), obj.end());
	int w1 = obj[0].first;
	for (int i = 0; i < N; i++) {
		if (obj[i].first == w1) 
			a.push_back(obj[i].second);
		else if (obj[i].first == w1 + 1)
			b.push_back(obj[i].second);
		else if (obj[i].first == w1 + 2)
			c.push_back(obj[i].second);
		else
			d.push_back(obj[i].second);
	}

	sort(a.rbegin(), a.rend());
	sort(b.rbegin(), b.rend());
	sort(c.rbegin(), c.rend());
	sort(d.rbegin(), d.rend());

	for (int i = 1; i < (int) a.size(); i++)
		a[i] += a[i-1];
	for (int i = 1; i < (int) b.size(); i++)
		b[i] += b[i-1];
	for (int i = 1; i < (int) c.size(); i++)
		c[i] += c[i-1];
	for (int i = 1; i < (int) d.size(); i++)
		d[i] += d[i-1];

	ll ans = 0;
	for (int i = 0; i <= (int) a.size(); i++) {
		for (int j = 0; j <= (int) b.size(); j++) {
			for (int k = 0; k <= (int) c.size(); k++) {
				ll cur_weight = w1*i + (w1+1)*j + (w1+2)*k;
				if (cur_weight > W) 
					continue;
				ll l = (W - cur_weight) / (w1+3);
				if ((int) d.size() < l)
					l = (int) d.size();	
				ll cur_value = 0;
				if (i != 0)
					cur_value += a[i - 1];
				if (j != 0)
					cur_value += b[j - 1];
				if (k != 0)
					cur_value += c[k - 1];
				if (l != 0)
					cur_value += d[l - 1];
				ans = max(ans, cur_value);
			}
		}
	}

	cout << ans << endl;




	return 0;
}

