		sort(ALL(wv[i]), greater<ll>());

	memo.resize(4, vll(100));
	REP(i, 4)
	{
		if (!wv[i].empty())
		{
			memo[i][0] = wv[i][0];
			REP1O(j, SZ(wv[i]))
				memo[i][j] = memo[i][j - 1] + wv[i][j];
		}
	}

}


ll dfs(int a, int b, int c, int d)
{
	if (a > SZ(wv[0]) || b > SZ(wv[1]) || c > SZ(wv[2]) || d > SZ(wv[3]))
		return -LLMAX;

	if (a * w + b * (w + 1) + c * (w + 2) + d * (w + 3) > lim)
		return -LLMAX;

	ll ret = 0;
	if (a)
		ret += memo[0][a - 1];
	if (b)
		ret += memo[1][b - 1];
	if (c)
		ret += memo[2][c - 1];
	if (d)
		ret += memo[3][d - 1];

	chmax(ret, dfs(a + 1, b, c, d));
	chmax(ret, dfs(a, b + 1, c, d));
	chmax(ret, dfs(a, b, c + 1, d));
	chmax(ret, dfs(a, b, c, d + 1));

	return ret;
}

int main()
{
	init();

	ll ans = dfs(0, 0, 0, 0);

	cout << ans << endl;
}

