vector<pii> wv;
map<string, pair<ll, ll>> cache;

pair<ll, ll> calc(set<int> bag) {
	string key = "";
	string left = "";
	string right = "";
	int half = bag.size() / 2;
	int count = 0;
	repv(itr, bag) {
		key += to_string(*(itr)) + ",";
		if (count < half) {
			left += to_string(*(itr)) + ",";
		}
		else {
			right += to_string(*(itr)) + ",";
		}
	}
	if (cache.find(key) != cache.end()) {
		return cache[key];
	}
	if (cache.find(left) != cache.end() && cache.find(right) != cache.end()) {
		cache[key] = pair<ll, ll>(cache[left].first + cache[right].first, cache[left].second + cache[right].second);
		return cache[key];
	}
	ll w = 0;
	ll v = 0;
	repv(itr, bag) {
		w += wv[*itr].first;
		v += wv[*itr].second;
	}
	cache[key] = pair<ll, ll>(w, v);
#ifdef DEBUG
	printf("%s = (%lld %lld)\n", key.c_str(), w, v);
#endif
	return cache[key];
}

int main(int argc, char** argv) {
	sint2(N, W);
	wv = vector<pii>(N);
	rep(i, N) {
		sint2(w, v);
		wv[i] = pii(w, v);
	}
	sort(all(wv));
	reverse(all(wv));

	ll max = 0;
	stack<pii> s;
	set<int> bag;
	s.push(pii(0, 1));
	s.push(pii(0, 0));
	while (!s.empty()) {
		pii c = s.top();
		if (c.second == 2) {
			s.pop();
			s.pop();
			bag.erase(c.first);
			continue;
		}
		if (c.second == 1) {
			bag.insert(c.first);
		}

		pair<ll, ll> r = calc(bag);
		if (r.first <= W) {
			if (c.first == N - 1) {
				if (max < r.second) {
					max = r.second;
				}
			}
			else {
				s.push(pii(c.first + 1, 2));
				s.push(pii(c.first + 1, 1));
				s.push(pii(c.first + 1, 0));
			}
		}
		if (c == s.top()) {
			s.pop();
			bag.erase(c.first);
		}
	}
	pll(max);
	return 0;
}

