    vl w(N+1,0); vl v(N+1,0);
    FOR(i,1,N+1) cin >> w[i] >> v[i];

    ll WMIN = LINF;
    FOR(i,1,N+1) WMIN = min(WMIN, w[i]);    

    vi r(N+1,0);
    FOR(i,1,N + 1) r[i] = w[i] - WMIN;

    vi rs(N+1, 0);
    FOR(i,1,N + 1) rs[i] = rs[i - 1] + r[i];

    const ll RMAX = 300;
    vvl dp(N+MGN, vl(RMAX+MGN, 0));
