            for (int k = rs[i]; k >= 0; k--) {
                assert(k + r[i] < dp[0].size());
                dp[j+1][k+r[i]] = max(dp[j+1][k+r[i]], dp[j][k]+v[i]);
            }
        }
    }

    ll ans = 0;
