int64_t rec(int i, int j, const int n, const vector<int64_t> &wi, const vector<int64_t> &vi) {
  int64_t res;
  if (i == n) {
    res = 0;
  } else if (j < wi[i]) {
    res = rec(i + 1, j, n, wi, vi);
  } else {
    res = max(
      rec(i + 1, j, n, wi, vi),
      rec(i + 1, j - wi[i], n, wi, vi) + vi[i]
    );
  }
  return res;
}

