int solve()
{
	int b = 0;
	int maxi = 1 << n / 2;
	while (b<maxi)
	{
		int t = b;
		int i = 0;
		long long int wsum = 0;
		long long int vsum = 0;
		while (t>0)
		{
			if (t % 2) {
				wsum += w[i + 1];
				vsum += v[i + 1];
			}
			t >>= 1;
			i++;
		}
		da.push_back(make_pair(wsum, vsum));
		b++;
	}
	b = 0;
	maxi = 1 << (n - n / 2);
	while (b<maxi)
	{
		int t = b;
		int i = 0;
		long long int wsum = 0;
		long long int vsum = 0;
		while (t>0)
		{
			if (t % 2) {
				wsum += w[i + 1 + n / 2];
				vsum += v[i + 1 + n / 2];
			}
			t >>= 1;
			i++;
		}
		db.push_back(make_pair(wsum, vsum));
		b++;
	}
	sort(da.begin(), da.end());
	sort(db.begin(), db.end());
	long long int tmpmax = -1;
	REP(i, da.size())
	{
		if (tmpmax<da[i].second)
		{
			dc.push_back(make_pair(da[i].first, da[i].second));
			tmpmax = da[i].second;
		}
	}
	tmpmax = -1;
	REP(i, db.size())
	{
		if (tmpmax<db[i].second)
		{
			dd.push_back(make_pair(db[i].first, db[i].second));
			tmpmax = db[i].second;
		}
	}
	REP(i, dc.size())
	{
		long long int target = W - dc[i].first;
		int lb = 0, ub = dd.size(), mid;
		if (target < 0) break;
		while (ub - lb>1)
		{
			mid = (lb + ub) / 2;
			if (dd[mid].first>target)
			{
				ub = mid;
			}
			else lb = mid;
		}
		ans = max(ans, dc[i].second + dd[lb].second);
	}
	cout << ans << endl;
	return 0;
}

