template<typename T, size_t N>
constexpr size_t NELEMS(T (&)[N]) { return N; }

#define FOR(i, start, end) for(int i = (start); i < (end); ++i)
#define REP(i, n) FOR(i, 0, n)

int N, W;
int wmin;
vector<int> V[5];


// 種類iまでの品物を容量jに詰めたときの最大価値
int knapsack(int i, int j)
{
    // 品物を入れないなら価値0
    if(i == 0) return 0;

    // 容量0なら価値0
    if(j == 0) return 0;

    // 種類iの品物を入れるパターンを試す
    // 1つも入れない場合、knapsack(i-1, j) が最大価値
    // 入れる場合は価値の高いものから入れる。その場合
    // (入れる価値の総和) + knapsack(i-1, j-(入れる重さの総和)) が最大価値
    // なお、j < (入れる重さの総和) の場合は弾くこと
    //
    // N <= 100 だから、これでかなり再帰の深さは抑えられるはず…
    int totalmax = knapsack(i-1, j);
    int vadd = 0;
    int wadd = 0;
    for(size_t k = 0; k < V[i].size(); ++k) {
        vadd += V[i][k];
        wadd += wmin + (i-1);
        if(j < wadd) break;
        totalmax = max(totalmax, vadd + knapsack(i-1, j-wadd));
    }

    return totalmax;
}

void solve()
{
    int result = knapsack(4, W);
    cout << result << "\n";
}

int main()
{
    cin >> N >> W;
    REP(i, N) {
        int w, v;
        cin >> w >> v;
        if(i == 0) {
            wmin = w;
            V[1].push_back(v);
        }
        else {
            V[1+w-wmin].push_back(v);
        }
    }
    FOR(i, 1, 5) {
        sort(begin(V[i]), end(V[i]), greater<int>());
    }

    solve();

    return 0;
}

