using namespace std;

map<pair<int, int>, int> dp;
vector<int> weight, value;

int solve(int next, int remain) {
	auto p = make_pair(next, remain);
	if (dp.find(p) != dp.end()) {
		return dp[p];
	} else if (next == weight.size()) {
		return 0;
	} else if (remain < weight[next]) {
		int ans = solve(next + 1, remain);
		dp[p] = ans;
		return ans;
	} else {
		int ans = max(solve(next + 1, remain - weight[next]) + value[next],
					  solve(next + 1, remain));
		dp[p] = ans;
		return ans;
	}
}

