      if (w_sum[0] + w_sum[1] > W) break;
      for (int n2 = 0; n2 <= items[2].size(); n2++) {
        // printf("n2 = %d\n", n2);
        if (n2 > 0) {
          w_sum[2] += items[2][n2-1].weight;
          v_sum[2] += items[2][n2-1].value;
        }
        w_sum[3] = 0;
        v_sum[3] = 0;
        if (w_sum[0] + w_sum[1] + w_sum[2] > W) break;
        for (int n3 = 0; n3 <= items[3].size(); n3++) {
          // printf("n3 = %d\n", n3);
          if (n3 > 0) {
            w_sum[3] += items[3][n3-1].weight;
            v_sum[3] += items[3][n3-1].value;
          }
          if (w_sum[0] + w_sum[1] + w_sum[2] + w_sum[3] > W) break;
          if (v_sum[0] + v_sum[1] + v_sum[2] + v_sum[3] > v_max) {
            v_max = v_sum[0] + v_sum[1] + v_sum[2] + v_sum[3];
          }
        }
      }
    }
  }

  cout << v_max << endl;

  return 0;
}

