	ll N,W;
	ll w[101]={},v[101]={};
	ll w_1;
	cin >> N >> W;

	for(int i=1;i<=N;i++){
		cin >> w[i] >> v[i];
		if(i==1){ //w[i] 0<=...<=3
			w_1=w[1]-1;
			w[1]=1;
		}else{
			w[i]=w[i]-w_1;
		}
	}

	for(int i=0;i<101;i++){
		for(int j=0;j<11;j++){
			dp[i][j]=0;
		}
	}

	bool check[5]={};
	check[0]=true;

	for(int i=0;i<N;i++){
		for(int j=0;j<11;j++){
			if(check[j]){
				dp[i+1][j]=max(dp[i+1][j],dp[i][j]);

				if(j+w[i+1]<=W-(w_1+1)&&j+w[i+1]<11){
					dp[i+1][j+w[i+1]]=max(dp[i+1][j+w[i+1]],dp[i][j]+v[i+1]);
					check[j+w[i+1]]=true;
				}
			}
		}
	}

	ll answer=0;

	for(int i=0;i<W-(w_1);i++){
		answer = max(answer,dp[N][i]);
	}

	cout << answer << endl;

	return 0;
}

