int N,W; vi w,v, u;
int dp[110][110][310];

int sub(int n){
    ll rest = W - (ll)w[0]*n;
    if (rest < 0) return 0;


    mset(dp, 0);
    rep(i,N){
        rep(j,n+1){
            rep(k,3*n+1){
                amax(dp[i+1][j][k], dp[i][j][k]);
                amax(dp[i+1][j+1][k + u[i]], dp[i][j][k] + v[i]);
            }
        }
    }
    int best=0;
    for(int i=min((int)rest, 3*n); i>=0; --i) amax(best, dp[N][n][i]);
    return best;
}

int main() {
    scanf("%d%d", &N, &W);
    w.resize(N);
    v.resize(N);
    rep(i,N){
        scanf("%d%d", &w[i], &v[i]);
    }
    u.resize(N);
    rep(i,N) {
        u[i]=w[i]-w[0];
        assert(IN(u[i], 0, 3));
    }

    int best=0;
    for(int n=1; n<=N; ++n){
        amax(best, sub(n));
    }
    printf("%d\n", best);
    return 0;
}

