using namespace std;

typedef pair<int, int> P;
int N, W;
int v, w;
vector<vector<P> > luggage(4);

int knapsack(int n1, int n2, int n3, int n4) {
  int w_sum, v_sum;
  w_sum = v_sum = 0;
  for (int i=0; i<n1; i++) {
    w_sum += luggage[0][i].first;
    v_sum += -luggage[0][i].second;
  }
  for (int i=0; i<n2; i++) {
    w_sum += luggage[1][i].first;
    v_sum += -luggage[1][i].second;
  }
  for (int i=0; i<n3; i++) {
    w_sum += luggage[2][i].first;
    v_sum += -luggage[2][i].second;
  }
  for (int i=0; i<n4; i++) {
    w_sum += luggage[3][i].first;
    v_sum += -luggage[3][i].second;
  }
  if (w_sum <= W) return v_sum;
  else return 0;
}

int main() {
  cin >> N >> W;
  cin >> w >> v;
  luggage[0].push_back(P(w, -v));
  int base = w;
  for (int i=1; i<N; i++) {
    cin >> w >> v;
    luggage[w-base].push_back(P(w, -v));
  }
  for (int i=0; i<4; i++) sort(luggage[i].begin(), luggage[i].end());
  int maxi = 0;
  // 重さは高々4種類なので、全探索して価値の総和を計算する
  for (int i=0; i<=luggage[0].size(); i++) {
    for (int j=0; j<=luggage[1].size(); j++) {
      for (int k=0; k<=luggage[2].size(); k++) {
        for (int l=0; l<=luggage[3].size(); l++) {
          maxi = max(maxi, knapsack(i, j, k, l));
        }
      }
    }
  }
  cout << maxi << endl;
  return 0;
}

