using namespace std;
#define MAX 100 // 最大の個数
#define PATURN 4 // 重さの種類
// int W:バッグの容量
// int w:今バッグに入れている物の重さ
// int wm:一個目の物の重さ
// int ws[x]:x番目の重さの物の個数
// int s[x][y]:x番目の重さの物の中でy番目に価値が高い物までの価値の総和
// int c:今入れようとしている重さ
// int v:現在までにバッグに入れた物の価値の総和
int knapsack(int W, int w, int wm, int *ws, int s[][MAX+1], int c, int v) {
	int ret = v;
	if (c >= PATURN) return v; // 範囲外ならv返す
	for (int i = 0;i <= ws[c];i ++) { // 重さwm+cをi個かばんに入れてみる
		if (w + (wm + c) * i > W) break; // 入らなかったら諦める
		ret = max(ret, knapsack(W, w + (wm + c) * i, wm, ws, s, c + 1, v + s[c][i])); // 入るようなら、その時更にもっと重い荷物にトライ
	}
	return ret; // 既に0~c-1までの荷物を入れ終わっていて重さwのとき、その後最善手を打った時の価値の最大値
}
int main() {
	int n, w, wm, ws[PATURN], wv[PATURN][MAX], wc, s[PATURN][MAX + 1];
	for (int i = 0;i < PATURN;i ++) {
		ws[i] = 0;
	}
	cin >> n >> w;
	cin >> wm >> wv[0][0];
	ws[0] ++;
	for (int i = 1;i < n;i ++) {
		cin >> wc;
		cin >> wv[wc - wm][ws[wc - wm]]; // 重さごと(=4種類)に別々に価値を記録する
		ws[wc - wm] ++;
	}
	for (int i = 0;i < PATURN;i ++) {
		sort(wv[i], wv[i] + ws[i], greater<int>()); // 各重さで価値の高い順に並べる
		s[i][0] = 0;
//		cout << i + wm << "(" << ws[i] << "):0";
		for (int j = 0;j < ws[i];j ++) {
			s[i][j + 1] = s[i][j] + wv[i][j]; // 累積和。価値の高い順に足している
//			cout << "," << s[i][j + 1];
		}
//		cout << endl;
	}
	cout << knapsack(w, 0, wm, ws, s, 0, 0); // 答えて終了
}

