ll answer = 0;
ll n, w, w0;
vl v0, v1, v2, v3;

void solve(){
    v0.pb(0);
    in2(w0, v0[0]);
    rep(i, n - 1){
        ll u, v; in2(u, v);
        if (u - w0 == 0) v0.pb(v);
        else if (u - w0 == 1) v1.pb(v);
        else if (u - w0 == 2) v2.pb(v);
        else if (u - w0 == 3) v3.pb(v);
    }

    sort(rall(v0));
    sort(rall(v1));
    sort(rall(v2));
    sort(rall(v3));
    vl sv0(v0.size() + 1, 0), sv1(v1.size() + 1, 0), sv2(v2.size() + 1, 0), sv3(v3.size() + 1, 0);
    rep(i, v0.size()) sv0[i + 1] = sv0[i] + v0[i];
    rep(i, v1.size()) sv1[i + 1] = sv1[i] + v1[i];
    rep(i, v2.size()) sv2[i + 1] = sv2[i] + v2[i];
    rep(i, v3.size()) sv3[i + 1] = sv3[i] + v3[i];

    ll ww0, ww1, ww2, ww3;
