using namespace std;

int n, cnt[4];
ll res, w, nw, table[4][110];

bool compare(ll d1, ll d2){ return d1 > d2; }
int main(){
	int i, j, k;
	ll a, s, now, nsum, idx;
	scanf("%d %lld %lld %lld", &n, &w, &a, &s); nw = a;
	table[0][cnt[0]++] = s;
	for(i = 1; i < n; i++){
		scanf("%lld %lld", &a, &s);
		a -= nw;
		table[a][cnt[a]++] = s;
	}
	for(i = 0; i < 4; i++){
		sort(table[i], table[i] + cnt[i], compare);
		for(j = 1; j <= 100; j++) table[i][j] += table[i][j - 1];
	}
	for(i = 0; i <= cnt[0]; i++){
		now = nw * i; nsum = 0;
		if(i) nsum = table[0][i - 1];
		if(now > w) break;
		for(j = 0; j <= cnt[1]; j++){
			if(now + j * (nw + 1) > w) break;
			now += j * (nw + 1);
			if(j) nsum += table[1][j - 1];
			for(k = 0; k <= cnt[2]; k++){
				if(now + k * (nw + 2) > w) break;
				now += k * (nw + 2);
				if(k) nsum += table[2][k - 1];
				idx = min(100ll, (w - now) / (nw + 3));
				if(idx) nsum += table[3][idx - 1];
				res = max(res, nsum);
				now -= k * (nw + 2);
				if(idx) nsum -= table[3][idx - 1];
				if(k) nsum -= table[2][k - 1];
			}
			now -= j * (nw + 1);
			if(j) nsum -= table[1][j - 1];
		}
	}
	printf("%lld", res);
	return 0;
}

