int main() {
	int n, knap;
	cin >> n >> knap;
	vector<int> weight(n), value(n);
	vector<vector<int>> dp(n + 1, vector<int>(knap + 1, -1));
	for (int i = 0; i < weight.size(); i++) {
		cin >> weight[i] >> value[i];
	}
	function<int(int, int)> maxv = [&] (int next, int remain) {
		if (dp[next][remain] != -1) {
			return dp[next][remain];
		} else if (next == weight.size() || remain <= 0) {
			return 0;
		} else if (remain < weight[next]) {
			dp[next][remain] = maxv(next+1, remain);
			return dp[next][remain];
		} else {
			int yes = maxv(next+1, remain - weight[next]) + value[next];
			int no = maxv(next+1, remain);
			dp[next][remain] = (yes > no ? yes : no);
			return dp[next][remain];
		}
	};
	cout << maxv(0, knap) << endl;
}

