class item {
public:
  std::int_fast64_t weight;
  std::int_fast64_t value;
  friend std::istream& operator>>(std::istream& is, item& self) {
    return is >> self.weight >> self.value;
  }
};

int main() {
  std::int_fast64_t n, w;
  std::cin >> n >> w;
  std::vector<item> items(n);
  std::copy_n(std::istream_iterator<item>(std::cin), n, items.begin());

  std::set<std::int_fast64_t> possible_weights;
  for (std::int_fast64_t i = 0; i <= n; ++i) {
    for (std::int_fast64_t j = 0; j <= 3 * i; ++j) {
      possible_weights.insert(i * items[0].weight + j);
    }
  }
  std::unordered_map<std::int_fast64_t, std::int_fast64_t> reverse_map;
  {
    std::int_fast64_t i = 0;
    for (const std::int_fast64_t& weight : possible_weights) {
      reverse_map[weight] = i;
      ++i;
    }
  }
  auto not_greater_than = [&](const std::int_fast64_t x) {
    std::set<std::int_fast64_t>::iterator it = possible_weights.lower_bound(x);
    return *it == x ? x : *(--it);
  };

  std::vector<std::vector<std::int_fast64_t>> dp(n + 1, std::vector<std::int_fast64_t>(possible_weights.size(), -1));
  std::function<std::int_fast64_t(std::int_fast64_t, std::int_fast64_t)> solve;
  solve = [&](const std::int_fast64_t i, const std::int_fast64_t capacity) {
    const std::int_fast64_t j = reverse_map[not_greater_than(capacity)];
    if (dp[i][j] >= 0) {
      return dp[i][j];
    }
    std::int_fast64_t result;
    if (i == n) {
      result = 0;
    } else if (capacity < items[i].weight) {
      result = solve(i + 1, capacity);
    } else {
      result = std::max(solve(i + 1, capacity), solve(i + 1, capacity - items[i].weight) + items[i].value);
    }
    return dp[i][j] = result;
  };

  std::cout << solve(0, w) << std::endl;
  return 0;
}

