ll DP(ll i, ll j) {	//i番目以降重さj以下
	if (dp[i][j] != -1) {
		return dp[i][j];
	}
	ll res;
	if (i == N) {
		res = 0;
	}
	else if (j < w[i]) {
		res = DP(i + 1, j);
	}
	else {
		res = max(DP(i + 1, j), DP(i + 1, j - w[i]) + v[i]);
	}
	return dp[i][j] = res;
}

