typedef long long LL;
using namespace std;
struct OBJ {
	LL w;
	LL v;
	double v_w;
	OBJ(LL _w,LL _v){
		w=_w;
		v=_v;
		if (w!=0){
			v_w=(double)v/(double)w;
		}else{
			v_w=0.0;
		}
	}
};
bool desc(const OBJ &obj1,const OBJ &obj2){
	if (obj1.v>obj2.v){
		return true;
	}else if (obj1.v==obj2.v){
		return obj1.w<obj2.w;
	}else{
		return false;
	}
};
int main(int argc, char* argv[])
{
	int N;
	LL W;
	cin>>N>>W;
	int i;
	vector<OBJ> objs;
	LL W1=0;
	LL V1=0;
	for (i=0;i<N;i++){
		cin>>W1>>V1;
		if (W1<=W){
			objs.push_back(OBJ(W1,V1));
		}
	}
	sort(objs.begin(),objs.end(),desc);

	int j;
	LL maxV=0;
	for (i=0;i<objs.size();i++){
		for (int k=1;k<objs.size()-1;k++){
			W1=objs[i].w;
			V1=objs[i].v;
			for (j=i+k;j<objs.size();j++){ 
				if (W1+objs[j].w<=W){
					W1+=objs[j].w;
					V1+=objs[j].v;
				}
			}
			if (maxV<V1){
				maxV=V1;
			}
		}
	}
	cout<<maxV<<endl;
	objs.clear();
	return 0;
}

