int main(){
    int n,w;
    cin >> n >> w;
    int *weight = new int(n);
    int *value = new int(n);
    int minW = INF;
    for(int i=0;i < n; i++){
        cin >> weight[i] >> value[i];
        minW = min(minW, weight[i]);
    }
    vector<int> w0,w1,w2,w3;
    for(int i=0;i<n;i++){
        switch(weight[i]-minW){
            case 0:
                w0.push_back(value[i]);
                break;
            case 1:
                w1.push_back(value[i]);
                break;
            case 2:
                w2.push_back(value[i]);
                break;
            case 3:
                w3.push_back(value[i]);
                break;
        }
    }
    sort(w0.begin(), w0.end());
    sort(w1.begin(), w1.end());
    sort(w2.begin(), w2.end());
    sort(w3.begin(), w3.end());
    for(int i=0;i<n;i++){
         sum0[i+1] = i < (int)w0.size() ? w0[i] : 0;
         sum1[i+1] = i < (int)w1.size() ? w1[i] : 0;
         sum2[i+1] = i < (int)w2.size() ? w2[i] : 0;
         sum3[i+1] = i < (int)w3.size() ? w3[i] : 0;
         sum0[i+1] += sum0[i];
         sum1[i+1] += sum1[i];
         sum2[i+1] += sum2[i];
         sum3[i+1] += sum3[i];
    }
    int answer = 0;
    for(int i=(int)w0.size();i>=0;i--){
        for(int j=(int)w1.size();j>=0;j--){
            for(int p=(int)w2.size();p>=0;p--){
                for(int q=(int)w3.size();q>=0;q--){
                    if((i+j+p+q) * minW + j + p * 2 + q * 3 > w){
                        continue;
                    }
                    answer = max(answer, sum0[i] + sum1[j] + sum2[p] + sum3[q]);
                }
            }
        }
    }
    cout << answer << endl;
    return 0;
}

