				if(s[3]>0)
				for(int l = 0; l<min(w/(a[0][0]+3)+1,(ll)v[3].size()); l++)
				{
					ll y4 = v[3][l];
					ll w5 = l*(s[3]);
					if(w2+w3+w4+w5<=w)
