ll N, W;
map<pair<ll, ll> , ll> dp; //<i番目まで見たときの重さに対する価値の最大値>
vector<ll> w, v;

ll func(ll, ll);
int main(){
  cin >> N >> W;
  ll wt, vt;
  w.push_back(0); v.push_back(0);
  for(int i=1; i<=N; i++) {
    cin >> wt >> vt;
    w.push_back(wt);
    v.push_back(vt);
  }

  for(int i=0; i<=W; i++){
    dp[make_pair(0, i)] = 0;
  }
  for(int i=0; i<=N; i++){
    dp[make_pair(i, 0)] = 0;
  }

  ll ans=0;
  for(int i=max(w[0]-3, 0); i<=W; i++){
    ans = max(ans, func(N, i));
  }

  cout << ans << endl;

  return 0;
}

ll func(ll i, ll wm){
  pair<ll, ll> tmp = make_pair(i, wm);
  if(dp.find(tmp)==dp.end()){
    if(wm<w[i]){
      return dp[tmp]=func(i-1, wm);
    }
    else{
      return dp[tmp]=max(func(i-1, wm), func(i-1, wm-w[i])+v[i]);
    }
  }
  else{
    return dp[tmp];
  }
}

