                    if(j > 0) sumw += (minw+1) * j, sumv += item[1][j-1];
                    if(k > 0) sumw += (minw+2) * k, sumv += item[2][k-1];
                    if(l > 0) sumw += (minw+3) * l, sumv += item[3][l-1];

                    if(sumw <= W) ans = max(ans, sumv);
                }
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

