long long dpp(long long i, long long j) {
	if (dp[i][j] != 0) {
		return dp[i][j];
	}
	long long res;
	if (i == n) {
		res = 0;
	}
	else if (j < w[i]) {
		res = dpp(i + 1, j);
	}
	else {
		res = max(dpp(i + 1, j),dpp(i + 1, j - w[i]) + v[i]);
	}
	dp[i][j] = res;
	return res;
}

