ll f(ll i, ll wlimit){
    ll ret;

    if (wlimit < 0 || i >= n) return 0;

    auto itr = mp.find(make_pair(i, wlimit));
    if (itr != mp.end()){
        ret = itr -> second;
    } else {
        if (v[i].first <= wlimit) {
            ret = max(f(i + 1, wlimit - v[i].first) + v[i].second, f(i + 1, wlimit));
        } else {
            ret = f(i + 1, wlimit);
        }
    }

    mp[make_pair(i, wlimit)] = ret;
    return ret;
}

