    }else{
        --it;
        x = *it;
        y = it-pm.begin();
    }
    for (ll i = 0; i < n; ++i) {
        for (ll j = 0; j <= y; ++j) {
            ll w = pm[j];
            if(w >= weight[i]){
                if(mp.count(w-weight[i])){
                    dp[i+1][j] = max(dp[i][mp[w-weight[i]]] + value[i], dp[i][j]);
                }else{
                    dp[i+1][j] = max(dp[i+1][j-1], dp[i][j]);
                }
            }
            else dp[i+1][j] = dp[i][j];
        }
    }
    dump(pm);
    dump(mp);
    dump(x);
    dump(y);
    rep(i, n+1) dump(i, dp[i]);
    cout << dp[n][y] << endl;
    return 0;
}

