struct Comb {
    vector<vector<s64> > data;
    Comb(int n) { // O(n^2)
        data = vector<vector<s64> >(n+1,vector<s64>(n+1,1));
        UPTO(i,1,n) {
            FOR(j,i+1) {
                if (!j || j == i) data[i][j] = 1;
                else data[i][j] = data[i-1][j-1] + data[i-1][j];
            }
        }
    }

    s64 ncr(int n, int r) {
        return data[n][r];
    }
};

static inline int ri() {
  int a;
  scanf("%d", &a);
  return a;
}

int int_less(const void *a, const void *b) {
  return (*((const int*)a) - *((const int*)b));
}
int int_greater(const void *a, const void *b) {
  return (*((const int*)b) - *((const int*)a));
}

int main() {
	int n = ri();
	int w = ri();
	int a[n], b[n];
	FOR(i,n) a[i] = ri(), b[i] = ri();
	int base = INF;
	FOR(i,n) base = min(base, a[i]);
	vector<int> c[4] = { {} };
	FOR(i,n) c[a[i]-base].push_back(b[i]);
	FOR(i,4) sort(all(c[i]), greater<int>());

	s64 res = 0;
	FOR(i,c[0].size()+1) {
		FOR(j,c[1].size()+1) {
			FOR(k,c[2].size()+1) {
				if (((s64)i)*base + ((s64)j)*(base+1) + ((s64)k)*(base+2) > w) continue;
				int l = (w-(((s64)i)*base + ((s64)j)*(base+1) + ((s64)k)*(base+2)))/(base+3);
				l = min(l,(int)c[3].size());
				s64 score = 0;
				score += accumulate(c[0].begin(), c[0].begin()+i, 0);
				score += accumulate(c[1].begin(), c[1].begin()+j, 0);
				score += accumulate(c[2].begin(), c[2].begin()+k, 0);
				score += accumulate(c[3].begin(), c[3].begin()+l, 0);
				res = max(res,score);
			}
		}
	}
	cout << res << endl;
    return 0;
}

