using namespace std;

long number_of_item, max_weight;
long w[100], v[100];

long memo[100+1][100+1];

long dp(long num, long weight) {
  if(memo[num][weight] != -1) {
    return memo[num][weight];
  }

  long ret = 0;
  if(num == number_of_item){
   ret = 0;
  } else if (weight < w[num]) {
    ret = dp(num+1, weight);
  } else {
    ret = max(dp(num+1, weight),
               dp(num+1, weight -w[num]) + v[num]);
  }
  return memo[num][weight] = ret;
}

int main(){
  memset(memo, -1, sizeof(memo));

  cin >> number_of_item >> max_weight;
  for(int i = 0; i < number_of_item ; i++) {
    cin >> w[i] >> v[i];
  }

  long ret = dp(0, max_weight);

  cout << ret << endl;
  return 0;
}

