const uint64_t Undefined = static_cast<uint64_t>(-1);

int main()
{
  uint64_t N, W;
  std::cin >> N >> W;

  std::vector<uint64_t> w(N), v(N);
  for (uint64_t n = 0; n < N; ++n) {
    std::cin >> w[n] >> v[n];
  }

  uint64_t base_weight = w[0];
  for (uint64_t n = 0; n < N; ++n) {
    w[n] -= base_weight;
  }

  std::vector< std::array< std::array<uint64_t, 301> , 101> > dp(N + 1);
  for (uint64_t n = 0; n <= N; ++n) {
    for (uint64_t k = 0; k <= 100; ++k) {
      for (uint64_t i = 0; i <= 300; ++i) {
        dp[n][k][i] = Undefined;
      }
    }
  }
  dp[0][0][0] = 0;

  for (uint64_t n = 0; n < N; ++n) {
    for (uint64_t k = 0; k <= 100; ++k) {
      for (uint64_t i = 0; i <= 300; ++i) {
        if (dp[n][k][i] != Undefined) {
          uint64_t current_weight = k * base_weight + i;
          uint64_t new_weight = current_weight + (w[n] + base_weight);
          uint64_t new_value = dp[n][k][i] + v[n];
          if (new_weight <= W) {
            if (dp[n + 1][k + 1][i + w[n]] == Undefined) {
              dp[n + 1][k + 1][i + w[n]] = new_value;
            } else {
              dp[n + 1][k + 1][i + w[n]] = std::max(new_value, dp[n + 1][k + 1][i + w[n]]);
            }
          }

          if (dp[n + 1][k][i] == Undefined) {
            dp[n + 1][k][i] = dp[n][k][i];
          } else {
            dp[n + 1][k][i] = std::max(dp[n][k][i], dp[n + 1][k][i]);
          }
        }
      }
    }
  }

  uint64_t max = 0;
  for (uint64_t k = 0; k <= 100; ++k) {
    for (uint64_t i = 0; i <= 300; ++i) {
      if (dp[N][k][i] != Undefined) {
        max = std::max(dp[N][k][i], max);
      }
    }
  }
  std::cout << max << std::endl;

  return 0;
}

