int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll n, W;
	cin >> n >> W;
	vector<ll> w(n), v(n);
	rep(i, n) cin >> w[i] >> v[i];

	// w1 <= wi <= w1 + 3
	// wは4パターンしか値を持たない

	ll maxW = accumulate(allof(w), 0);
	if (maxW <= W) {
		cout << accumulate(allof(v), 0) << endl;
		return 0;
	}

	// wsumの取りうる値は？
	// w1 * i <= wsum <= (w1 + 3) * i
	int baseWeight = w[0];
	rep(i, n) {
		w[i] -= baseWeight;
	}
	maxW -= baseWeight * n;
	// dp[i][j][k] := i番目までの商品を見て重さがjでありk個選んだ時の価値
	vector<vector<vector<ll>>> dp(n + 1, vector<vector<ll>>(maxW + 1, vector<ll>(n+ 1, -1)));
	rep(i, n + 1) {
		dp[i][0][0] = 0;
	}

	rep(i, n) {
		rep(j, maxW + 1) {
			rep(k, n + 1) {
				if (j - w[i] >= 0 && k < n) {
					dp[i + 1][j][k + 1]  = max(dp[i + 1][j][k + 1], dp[i][j - w[i]][k] + v[i]);
				}
				dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k]);
			}
		}
	}

	ll ans = 0;
	for (int j = maxW; j >= 0; j--) {
		rep(k, n + 1) {
			if (dp[n][j][k] != -1 && j + k * baseWeight <= W) {
				ans = max(ans, dp[n][j][k]);
			}
		}
	}
	cout << ans << endl;
	return 0;
}

