						max=r;
						a1=i;
						a2=j;
						a3=k;
						a4=l;
					}
				}
			}
		}
	}
	long long ans=0;
	if(a1)ans+=V[0][a1-1];
	if(a2)ans+=V[1][a2-1];
	if(a3)ans+=V[2][a3-1];
	if(a4)ans+=V[3][a4-1];
