#include <stdio.h>
#include <inttypes.h>

int N;
int64_t W;
int64_t w[128], v[128];

int memo[128][128][334];

int64_t search(int idx, int count, int delta) {
	int64_t answer, candidate;
	int64_t current;
	if (idx >= N) return 0;
	if (memo[idx][count][delta]) return ~memo[idx][count][delta];

	answer = search(idx + 1, count, delta);
	current = w[0] * count + delta;
	if (current + w[idx] <= W) {
		candidate = search(idx + 1, count + 1, delta + (int)(w[idx] - w[0])) + v[idx];
		if (candidate > answer) answer = candidate;
	}
	return ~(memo[idx][count][delta] = ~answer);
}

int main(void) {
	int i;
	if (scanf("%d%" SCNd64, &N, &W) != 2) return 1;
	for (i = 0; i < N; i++) {
		if (scanf("%" SCNd64 "%" SCNd64, &w[i], &v[i]) != 2) return 1;
		if (w[i] < w[0] || w[0] + 3 < w[i]) {
			puts("invalid input");
			return 2;
		}
	}
	printf("%" PRId64 "\n", search(0, 0, 0));
	return 0;
}

