void max_value(const int N, const long weight, long w[], long v[], long	*ans, long *box, long *rweight, int *a)
{
	int i, b;

	for (i = 0; i + a < N; i++)
	{
		b = a;
		if(rweight + w[i+b] <= weight)
		{
			rweight += w[i+b];
			box += v[i+ b];
			a++;
			max_value(N, weight, w, v, ans, box, rweight, a);
		}
		else {
			rweight = 0;
			if (box > ans)
				ans = box;
