		scanf("%d%d", &w[i], &v[i]);
	}

	for(j = 1; j <= N; j++) C[0][j] = 0;
	for(i = 1; i <= W; i++) C[i][0] = 0;

	for(i = 1; i <= N; i++){
		for(j = 1; j <= W; j++){
			if(j < w[i]) C[i][j] = C[i-1][j];
