#define Min(a,b) ((a)<(b)?(a):(b))

int cmp(const void *ax, const void *ay){
	unsigned long x = *(unsigned long *)ax;
	unsigned long y = *(unsigned long *)ay;

	if(x > y) return -1;
	if(x < y) return 1;
	if(x = y) return 0;
}

unsigned long sub2(unsigned long **V, unsigned int *n, unsigned long W, unsigned long base, unsigned int ofs){
	unsigned int i,  N;	
	unsigned long sum = 0, tmp, w;
	w = base+ofs;
	N = Min(n[ofs], (unsigned int)(W/w+1));

	if(ofs == 0) return V[0][N-1];

	for(i = 0; i < N; i++){
		tmp = V[ofs][i] + sub2(V, n, W-w*i, base, ofs-1); 
		if(sum < tmp) sum = tmp;
	}

	return sum;
}

unsigned long sub1(unsigned int N, unsigned long W, unsigned long *w, unsigned long *v){
	unsigned int i, n[4], diff;
	unsigned long *V[4], Vmax;

	for(diff = 0; diff < 4; diff++){
		V[diff] = (unsigned long *)malloc(sizeof(unsigned long) * (N+1));
		if(V[diff] == NULL) exit(1);
		V[diff][0] = 0;
		n[diff] = 1;
	}

	for(i = 0; i < N; i++){
		diff = (unsigned int)(w[i] - w[0]);
		V[diff][n[diff]] = v[i];
		n[diff]++;
	}
	for(diff = 0; diff < 4; diff++){
		qsort(&V[diff][1], n[diff]-1, sizeof(unsigned long), cmp);
		for(i = 1; i < n[diff]; i++) V[diff][i] += V[diff][i-1];
	}

	Vmax = sub2(V, n, W, w[0], 3);
	for(diff = 0; diff < 4; diff++) free(V[diff]);
	return Vmax;
}

