struct ar {
    struct slot {
        int w, v;
    } slot[40001];
} ar[2];
int add(struct ar *old, int w, int v, int wmax, struct ar *new)
{
    struct slot *oldp = old->slot;
    struct slot *addp = old->slot;
    struct slot *newp = new->slot;
    int current_maxv = -1;
    for (;;) {
        if (oldp->w >= 0) {
            if (addp->w >= 0) {
                int addpw = addp->w + w;
                int addpv = addp->v + v;
                if (oldp->w < addpw)
                    goto putoldp;
                else if (oldp->w > addpw)
                    goto putaddp;
                else {
                    if (oldp->v < addpv) {
                        oldp++;
                        goto putaddp;
                    } else {
                        addp++;
                        goto putoldp;
                    }
                }
            } else
                goto putoldp;
        } else {
            if (addp->w >= 0)
                goto putaddp;
            else
                break;
        }
    putoldp:
        if (current_maxv < oldp->v) {
            *newp++ = *oldp;
            current_maxv = oldp->v;
        }
        oldp++;
        continue;
    putaddp:
        {
            int addpw = addp->w + w;
            int addpv = addp->v + v;
            if (wmax < addpw)
                break;
            if (current_maxv < addpv) {
                newp->v = addpv;
                newp->w = addpw;
                current_maxv = addpv;
                newp++;
            }
            addp++;
            continue;
        }
    }
    newp->w = -1;
    newp->v = -1;
    return current_maxv;
}

int main2(int w[], int v[], int n, int wmax) {
    struct ar *old = &ar[0];
    struct ar *new = &ar[1];
    old->slot[0].w = 0;
    old->slot[0].v = 0;
    old->slot[1].w = -1;

    int vmax = -1;
    int i;
    for (i = 0; i < n; ++i) {
        int wi, vi;
//        scanf("%d%d", &wi, &vi);
        wi = w[i];
        vi = v[i];
        vmax = add(old, wi, vi, wmax, new);
        struct ar *tmp = new;
        new = old;
        old = tmp;
    }
    printf("%d\n", vmax);
    return vmax;
}
