int main(void){

    int N;

    long long W;

    scanf("%d%lld", &N, &W);

    long long dp[N+1][N+1][301];

    long long w[N], v[N];

    for(int i = 0; i < N; i++){
        scanf("%lld%lld", &w[i], &v[i]);
    }

    for(int i = 0; i <= N; i++){
        for(int j = 0; j <= N; j++){
            for(int k = 0; k <= 300; k++){
                dp[i][j][k] = 0;
            }
        }
    }

    long long b = w[0];

    for(int i = 1; i <= N; i++){
        long long t = w[i-1]-b;
        for(int j = 1; j <= N; j++){
            for(int k = 0; k <= 300; k++){
                dp[i][j][k] = dp[i-1][j][k];
                if(t <= k && dp[i][j][k] < dp[i-1][j-1][k-t] + v[i-1]){
                    dp[i][j][k] = dp[i-1][j-1][k-t] + v[i-1];
                }
            }
        }
    }

    long long ans = 0;

    for(int i = 1; i <= N; i++){
        for(int j = 0; j <= 300; j++){
            if(b * i + j <= W && ans < dp[N][i][j]){
                ans = dp[N][i][j];
            }
        }
    }

    printf("%lld\n", ans);

    return 0;
}

