void merge(float a[][2], int N, int left, int right){
    if(right==left){
        return;
    }

    float b[N][2];
    merge(a, N, left, left+(right-left)/2);
    merge(a, N, left+(right-left)/2+1, right);

    int left_c=left, right_c=(right-left)/2+1;

    for(int i=left; i<=right; i++){
        if((left_c<left+(right-left)/2) && (right_c<right)){
            if(a[left_c][0]<a[right_c][0]){
                b[i][0] = a[right_c][0];
                b[i][1] = a[right_c][1];
                right_c++;
            }
            else{
                b[i][0] = a[left_c][0];
                b[i][1] = a[left_c][1];
                left_c++;
            }
        }
