            b[i][0] = a[right_c][0];
            b[i][1] = a[right_c][1];
            right_c++;
        }
    }

    for(int i=left; i<=right; i++){
        a[i][0] = b[i][0];
        a[i][1] = b[i][1];
    }

    return;
}

