int valueMax(int number,int total, int strength, int* weight, int* value)
{
    int totalValue,sumvalue1,sumvalue2;
    if(number == total){
        totalValue=0;
    }
    else if(strength < weight[number]){
        totalValue = valueMax(number+1,total,strength,weight,value);
    }
    else{
        sumvalue1 = valueMax(number+1,total,strength,weight,value);
        sumvalue2 = valueMax(number+1,total,strength-weight[number],weight,value)+value[number];
        totalValue = sumvalue1 > sumvalue2 ? sumvalue1:sumvalue2;
    }
    return totalValue;
}

