int check_input(int N, int W, int* w, int* v)
{
  if((1 <= N && N <= 100) && (1 <= W && W <= 1000000000)){
    int i,flag;
    flag = 1;
    for(i = 0; i < N; i++){
      if((1 <= w[i] && w[i] <= 1000000000) && (1 <= v[i] && v[i] <= 10000000)){
        if(i != 0){
          if(w[i] < w[0] || (w[0]+3) < w[i]){
            flag = -1;
            puts("Error:wの不等式の条件を満たしていません");
            break;
          }
        }
      }
      else{
        flag = -1;
        puts("Error:w,vの値は範囲外です");
        break;
      }
    }
    return flag;
  }
  else{
    puts("Error:N,Wの値は範囲外です");
    return -1;
  }
}

int simple_knapsack(int N, int W, int* w, int* v)
{
  int i,j,value;
  int dp[N+1][W+1];
  /*dp[i+1][j]はi番目までの品物から重さj以下となるように選んだ時の価値の総和の最大値*/
  for(i = 0; i <= W;i++){
    dp[0][i] = 0;
  }
  for(i = 0; i < N;i++){
    for(j = 0;j <= W;j++){
      if(w[i] <= j && dp[i][j] < dp[i][j-w[i]]+v[i]){
        dp[i+1][j] = dp[i][j-w[i]] + v[i];
      }else{
        /*i番目の品物が入らない場合*/
        dp[i+1][j] = dp[i][j];
      }
    }
  }
  return dp[N][W];
}


