#define ll long long

ll N,W,obj[102][2];
ll maxv = 0;

void pick(int i,int tw,int tv,int rtv){

	if(i == N) return;

	if(tw + obj[i][0] <= W){
		if(tv + obj[i][1] > maxv) maxv = tv + obj[i][1];
		pick(i+1, tw + obj[i][0], tv + obj[i][1], rtv);
	}

	if(rtv - obj[i][1] > maxv){
		pick(i+1, tw, tv, rtv - obj[i][1]);
	}
}

