	// 最小品物重さ
	siIWMin = sz1Itm[0].miWeight;

	// ソート
	qsort(sz1Itm, siICnt, sizeof(Itm), fSortFnc);

	// 最小品物重さを減算
	for (i = 0; i < siICnt; i++) {
		sz1Itm[i].miWeight -= siIWMin;
	}

	// 最大合計価値の更新
	fUpSVMax(0, 0, 0, 0);

