void sort(long long arr[], int len) {
    //insertion sort
    for (int i = 1; i < len; i++) {
        // 0 to i - 1 is sorted
        for (int j = i; j > 0; j--) {
            //try to find the place of j so that 0 to i is sorted. 
            if (arr[j] > arr[j - 1]) {
                //move j one step forward
                long long t = arr[j];
                arr[j] = arr[j - 1];
                arr[j - 1] = t;
            }
            else
                break; //ordered. 
        }
    }
}

