void merge(float a[], int N1, int b[], int N2, int left, int right){
    if(right==left){
        return;
    }

    float a2[N1];
    int b2[N2];

    merge(a, N1, b, N2, left, left+(right-left)/2);

    merge(a, N1, b, N2, left+(right-left)/2+1, right);

    int left_c=left, right_c=left+(right-left)/2+1;


    for(int i=left; i<=right; i++){
        if( (left_c <= (left+(right-left)/2)) && (right_c <= right) ){
            if(a[left_c]<a[right_c]){
                a2[i] = a[right_c];
                b2[i] = b[right_c];
                right_c++;
            }
            else{
                a2[i] = a[left_c];
                b2[i] = b[left_c];
                left_c++;
            }
        }
        else if(left_c <= left+(right-left)/2){
            a2[i] = a[left_c];
            b2[i] = b[left_c];
            left_c++;
        }
        else{
            a2[i] = a[right_c];
            b2[i] = b[right_c];
            right_c++;
        }
    }

    for(int i=left; i<=right; i++){
        a[i] = a2[i];
        b[i] = b2[i];
    }

    return;
}

