typedef struct Itm {
	int miWeight;															// 重さ
	int miVal;																// 価値
} Itm;

// 内部変数
static Itm sz1Itm[D_ITM_MAX];												// 品物
static int siICnt;															// 品物数
static int siSWMax;															// 最大合計重さ
static int siIWMin;															// 最小品物重さ
static int siSVMax;															// 最大合計価値
static int si3Memo[D_ITM_MAX + 5][D_ITM_MAX + 5][D_DF_W * D_ITM_MAX];		// メモ変数[品物][個数][合計重さ] = 価値

// 内部変数 - テスト用
