        return 1;
    }
    if ( ((thing_t*)a)->w - ((thing_t*)b)->w <0 ) {
        return -1;
    }
    if ( ((thing_t*)a)->w - ((thing_t*)b)->w ==0 ) {
        if ( ((thing_t*)a)->v - ((thing_t*)b)->v >=0 ) {
            return -1;
        }
        if ( ((thing_t*)a)->v - ((thing_t*)b)->v <0 ) {
            return 1;
        }
    }
    return 0;
}

