int main(void){
    int N, W;
    scanf("%d %d", &N, &W);
    int w[N], v[N];
    float cp[N][2];
    for(int i=0; i<N; i++){
        scanf("%d %d", &w[i], &v[i]);
        cp[i][0] = v[i]/w[i];
        cp[i][1] = i;
    }
    //FR

    merge(cp, N, 0, N-1);

    int Wb = 0, ans = 0;

    for(int i=0; i<N; i++){
        int num = cp[i][1];
        if(Wb+w[num]){
            Wb += w[num];
            ans += v[num];
        } 
    }

    printf("%d\n", ans);
    return 0;
}

void merge(float a[][2], int N, int left, int right){
    if(right-left<0){
        printf("Deepest\n");
        return;
    }

    float b[N][2];

    merge(a, N, left, left+(right-left)/2);
    merge(a, N, left+(right-left)/2+1, right);

    int left_c=left, right_c=(right-left)/2+1;

    for(int i=left; i<=right; i++){
        if((left_c<left+(right-left)/2) && (right_c<right)){
            if(a[left_c][0]<a[right_c][0]){
                b[i][0] = a[right_c][0];
                b[i][1] = a[right_c][1];
                right_c++;
            }
            else{
                b[i][0] = a[left_c][0];
                b[i][1] = a[left_c][1];
                left_c++;
            }
        }
        else if(left_c<left+(right-left)/2){
            b[i][0] = a[left_c][0];
            b[i][1] = a[left_c][1];
            left_c++;
        }
        else{
            b[i][0] = a[right_c][0];
            b[i][1] = a[right_c][1];
            right_c++;
        }
    }

    for(int i=left; i<=right; i++){
        a[i][0] = b[i][0];
        a[i][1] = b[i][1];
    }
    return;
}

