typedef struct{
    int num;
    double w;
    double v;
}IT;

IT *it;


int sol[MAX_N];

double best_val=0;

double d[MAX_N];

double relax(int k,double limit){
    double cnt1=0.0,cnt2=limit;//cnt1はk番目以降の重量制限内での価値の和
    int m=k;
    //重量制限内で価値を足していく
    while(cnt2-it[m].w>=0&&m<N){
        cnt1+=it[m].v;
        cnt2-=it[m].w;
        m++;
    }

    //ぎりぎり選べない物品の価値に、重量制限とその物品の重さとの比率を乗算する
    if(m<N)cnt1+=it[m].v*cnt2/it[m].w;

    return cnt1;
}

int p=0;

double ks(int k,double limit,int *ret,double fixed_val){
    if(k==N){
        p++;
        if(limit>=0) return 0;
        return -100000;
    }

    if(limit<0) return -100000;

    if(relax(k,limit)+fixed_val<best_val)return -100000;

    if(fixed_val>best_val) best_val=fixed_val;

    int taken[N],not_taken[N];

    double taken_v=ks(k+1,limit-it[k].w,taken,fixed_val+it[k].v)+it[k].v;
    double not_taken_v=ks(k+1,limit,not_taken,fixed_val);

    if(taken_v>not_taken_v){
        ret[k]=1;
        for(int i=k+1;i<N;i++) ret[i]=taken[i];
        return taken_v;
    }

    ret[k]=0;
    for(int i=k+1;i<N;i++) ret[i]=not_taken[i];
    return not_taken_v;
}

int cmp(const void *p1, const void *p2){
    IT *s1 = (IT *)p1;
    IT *s2 = (IT *)p2;

    double a=(s1->v)/(s1->w);
    double b=(s2->v)/(s2->w);

    if(b-a>0)return 1;
    if(a-b>0)return -1;
    return 0;
}

