typedef struct {
	int w;
	int n;
	int v[100];
} list_t;

static int cmp(const void *a, const void *b);
static long long calc(int i, int j, int k, int l, list_t list[4]);

int main(int argc, char *argv[])
{
	int i, j, k, l, N, W, n = 0;
	list_t list[4] = {{0}};
	long long max = 0, v;
	scanf("%d %d", &N, &W);
	for ( i = 0; i < N; i++ ){
		int w, v;
		scanf("%d %d", &w, &v);
		for ( j = 0; j < n; j++ ){
			if ( list[j].w == w ){
				list[j].v[list[j].n] = v;
				list[j].w = w;
				list[j].n++;
				break;
			}
		}
		if ( j == n ){
			list[n].v[0] = v;
			list[n].w = w;
			list[n].n++;
			n++;
		}
	}

	for ( i = 0; i < n; i++ ){
		qsort(list[i].v, list[i].n, sizeof(int), cmp);
	}

	for ( i = 0; i <= N; i++ ){
		if ( i > list[0].n ){
			break;
		}
		for ( j = 0; i+j <= N; j++ ){
			if ( j > list[1].n ){
				break;
			}
			for ( k = 0; i+j+k <= N; k++ ){
				if ( k > list[2].n ){
					break;
				}
				for ( l = 0; i+j+k+l <= N; l++ ){
					if ( l > list[3].n ){
						break;
					}
					if ( i*list[0].w + j*list[1].w + k*list[2].w + l*list[3].w > W ){
						continue;
					}
					v = calc(i, j, k, l, list);
					if ( v > max ){
						max = v;
					}
				}
			}
		}
	}
	printf("%lld\n", max);

	return 0;
}

static long long calc(int i, int j, int k, int l, list_t list[4])
{
	long long v = 0;
	int x;
	for ( x = 0; x < i; x++ ){
		v += list[0].v[x];
	}
	for ( x = 0; x < j; x++ ){
		v += list[1].v[x];
	}
	for ( x = 0; x < k; x++ ){
		v += list[2].v[x];
	}
	for ( x = 0; x < l; x++ ){
		v += list[3].v[x];
	}
	return v;
}

