	for ( i = 0; i < N; i++ ){
		long long w, v;
		scanf("%lld %lld", &w, &v);
		for ( j = 0; j < n; j++ ){
			if ( list[j].w == w ){
				list[j].v[list[j].n] = v;
				list[j].w = w;
				list[j].n++;
				break;
			}
		}
		if ( j == n ){
			list[n].v[0] = v;
			list[n].w = w;
			list[n].n++;
			n++;
		}
	}

	for ( i = 0; i < n; i++ ){
		qsort(list[i].v, list[i].n, sizeof(long long), cmp);
	}

	for ( i = 0; i <= N; i++ ){
