			if ( j > list[1].n ){
				break;
			}
			for ( k = 0; i+j+k <= N; k++ ){
				if ( k > list[2].n ){
					break;
				}
				for ( l = 0; i+j+k+l <= N; l++ ){
					if ( l > list[3].n ){
						break;
					}
					w = i*list[0].w + j*list[1].w + k*list[2].w + l*list[3].w;
