	for ( x = 0; x < j; x++ ){
		v += list[1].v[x];
	}
	for ( x = 0; x < k; x++ ){
		v += list[2].v[x];
	}
	for ( x = 0; x < l; x++ ){
		v += list[3].v[x];
	}
	return v;
}

