void max_value(const int N, const long weight, long w[], long v[], double*ans, double *box, double *rweight, int *a)
{
	int i, b;
	long bweight;
	bweight = 0;

	for (i = 0; i + a < N; i++)
	{
		b = a;
		if(rweight + w[i+b] <= weight)
		{
			bweight = w[i + b];
			rweight += w[i+b];
			box += v[i+ b];
			a++;
			max_value(N, weight, w, v, ans, box, rweight, a);
		}
		else {
			if (box > ans)
				ans = box;
		}
		a = 0;
		rweight -= bweight;
	}
}

