// ソート関数 - コスパ降順
int
fSortFnc(
	const void *pzpVal1			// <I> 値１
	, const void *pzpVal2		// <I> 値２
)
{
	Itm *lzpVal1 = (Itm *)pzpVal1;
	Itm *lzpVal2 = (Itm *)pzpVal2;

	// コスパ
	double ldV1 = (double)lzpVal1->miVal / (double)lzpVal1->miWeight;
	double ldV2 = (double)lzpVal2->miVal / (double)lzpVal2->miWeight;

	// コスパ降順
	if (ldV1 > ldV2) {
		return(-1);
	}
	else if (ldV1 < ldV2) {
		return(1);
	}

	return 0;
}

// 最大合計価値の更新
int
fUpSVMax(
	int piINo					// <I> 対象品物 0～
	, int piICnt				// <I> 品物数
	, int piWSum				// <I> 合計重さ
	, int piVSum				// <I> 合計価値
)
{
	// 合計重さチェック
	if (piWSum > siSWMax - siIWMin * piICnt) {
		return 0;
	}

	// メモ変数チェック
	if (si2Memo[piINo][piWSum] > 0) {
		if (si2Memo[piINo][piWSum] >= piVSum) {
			return 0;
		}
	}
	si2Memo[piINo][piWSum] = piVSum;

	// 最大合計価値の更新
	if (siSVMax < piVSum) {
		siSVMax = piVSum;
	}

	// 終了チェック
	if (piINo >= siICnt) {
		return 0;
	}

	// 品物の選択有無
	fUpSVMax(piINo + 1, piICnt + 1, piWSum + sz1Itm[piINo].miWeight, piVSum + sz1Itm[piINo].miVal);		// 選択あり
	fUpSVMax(piINo + 1, piICnt, piWSum, piVSum);														// 選択なし

	return 0;
}

