val MAX_WEIGHT: Int = 400
data class Item(val w: Int, val v: Long)
fun main(args: Array<String>) {
	val (n, w) = readListOfInt()
	val items = Array(n) { Item(0, 0) }
	for(i in 0 until n) {
		val (cw, v) = readListOfInt()
		items[i] = Item(cw, v.toLong())
	}
	val minWeight = items.minBy { it.w }?.w?: 0
	for(i in 0 until n) {
		val oldItem = items[i]
		items[i] = Item(oldItem.w - minWeight + 1, oldItem.v)
	}
	// dp[いくつ目まで選んだか][重さの和(400)] = 価値
	// w1を1として 4まで用意する
	val dp = Array(n+1) { Array(MAX_WEIGHT + 1) { 0L } }
	for(i in 1 .. n) {
		val item = items[i-1]
		for(j in 0 .. MAX_WEIGHT) {
			dp[i][j] = Math.max(dp[i][j], dp[i-1][j])
			if(j + item.w <= MAX_WEIGHT) {
				dp[i][j + item.w] = Math.max(dp[i][j + item.w], dp[i-1][j] + item.v)
			}
		}
	}
	val maxValue = dp[n][Math.max(0, w-minWeight)]
