class Program {
    fun solve() {
        val sc = FastScanner()

        val N = sc.nextInt()
        val W = sc.nextLong()
        val wv = Array(N) { sc.nextLong() to sc.nextLong() }

        // 重さの差が3以下

        // 使った個数, 重さ-(w[0] * 個数), 価値最大
        val dp = Array(N + 1) { Array(it * 3 + 1) { Long.MIN_VALUE } }
        dp[0][0] = 0

        for (i in 0 until N) {
            for (j in i downTo 0) {
                for (k in 0..j * 3) {
                    if (dp[j][k] == Long.MIN_VALUE) continue
                    val w = (wv[i].first - wv[0].first).toInt()
                    dp[j + 1][k + w] = Math.max(dp[j + 1][k + w], dp[j][k] + wv[i].second)
                }
            }
        }

        var ans = Long.MIN_VALUE

        for (j in 0..N) {
            for (k in 0..j * 3) {
                val w = wv[0].first * j + k
                if (w <= W) {
                    ans = Math.max(ans, dp[j][k])
                }
            }
        }

        println(ans)
    }
}


class FastScanner {
    companion object {
        val input: InputStream = System.`in`
        val buffer = ByteArray(1024) { 0 }
        fun isPrintableChar(c: Int): Boolean = c in 33..126
    }

    var ptr = 0
    var buflen = 0
    private fun hasNextByte(): Boolean {
        if (ptr < buflen) {
            return true
        } else {
            ptr = 0
            buflen = input.read(buffer)
            if (buflen <= 0) {
                return false
            }
        }
        return true
    }

    private fun readByte(): Int = if (hasNextByte()) buffer[ptr++].toInt() else -1

    private fun skipUnprintable() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr].toInt())) ptr++
    }

    fun hasNext(): Boolean {
        skipUnprintable()
        return hasNextByte()
    }

    fun next(): String {
        if (!hasNext()) throw NoSuchElementException()
        val sb = StringBuilder()
        var b = readByte()
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b)
            b = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextLong(): Long {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0L
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextDouble(): Double = next().toDouble()
}

