val pw = PrintWriter(System.out)
val MOD: Long = (1e+9 + 7).toLong()

val MAX_WEIGHT: Int = 500
data class Item(val w: Long, val v: Long)
fun main(args: Array<String>) {
	val (n, w) = readListOfInt()
	val items = Array(n) { Item(0, 0) }
	for(i in 0 until n) {
		val (cw, v) = readListOfInt()
		items[i] = Item(cw.toLong(), v.toLong())
	}
	val minWeight = items[0].w
	for(i in 0 until n) {
		val oldItem = items[i]
		items[i] = Item((oldItem.w - minWeight).toLong() + 1L, oldItem.v)
	}

	// w1を1として 4まで用意する
	// dp[いくつ目まで選んだか][重さの和(500)] = 価値
	val dp = Array(n+1) { Array(MAX_WEIGHT + 1) { 0L } }
	for(i in 1 .. n) {
		val item = items[i-1]
		for(j in 0 .. MAX_WEIGHT) {
			dp[i][j] = Math.max(dp[i][j], dp[i-1][j])
			if(j + item.w.toInt() <= MAX_WEIGHT) {
				dp[i][j + item.w.toInt()] = Math.max(dp[i][j + item.w.toInt()], dp[i-1][j] + item.v)
			}
		}
	}
	val maxValue = dp[n][Math.max(0, (w-minWeight).toInt())]
	println(maxValue)
	pw.flush()
}

