import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        SimpleKnapsack solver = new SimpleKnapsack();
        solver.solve(1, in, out);
        out.close();
    }

    static class SimpleKnapsack {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            long w = in.nextLong();

            long[] weights = new long[n];
            long[] values = new long[n];

            //  選んだ個数 | weightの和
            long[][] dp = new long[n + 1][3 * n + 1];
            for (int i = 0; i < n; i++) {
                weights[i] = Long.parseLong(in.next());
                values[i] = Long.parseLong(in.next());
            }

            int sum = 0;
            for (int i = 0; i < n; i++) {
                int diff = (int) (weights[i] - weights[0]);
                for (int j = i; 0 <= j; j--) {
                    for (int k = sum; 0 <= k; k--) {
                        dp[j + 1][k + diff] = Math.max(dp[j + 1][k + diff], dp[j][k] + values[i]);
                    }
                }
                sum += diff;
            }
            long result = 0;
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= sum; j++) {
                    if (w < i * weights[0] + j) {
                        continue;
                    }
                    result = Math.max(result, dp[i][j]);
                }
            }

            out.println(result);

        }

    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args){
        new Main().run();
    }

    int N;
    int W;
    int[] w;
    int[] v;
    long[][] dp;

    private void run() {
        Scanner scanner = new Scanner(System.in);
        N = scanner.nextInt();
        W = scanner.nextInt();
        w = new int[N];
        v = new int[N];
        dp = new long[N+1][W+1];
        for(int i = 0; i < N; i++) {
            w[i] = scanner.nextInt();
            v[i] = scanner.nextInt();
        }

        System.out.println(f(0, W));
    }

    private long f(int i, int weight) {
        if(dp[i][weight]> 0) {
            return dp[i][weight];
        }

        if(i == N) {
            dp[i][weight] = 0;
        }else if(weight  < w[i]) {
            dp[i][weight] = f(i + 1, weight);
        }else{
            dp[i][weight] = Math.max(f(i + 1, weight), f(i + 1, weight - w[i]) + v[i]);
        }
        return dp[i][weight];
    }
}

