public class Main {

	public static void main(String[] args) throws IOException {
		FastScanner sc = new FastScanner(System.in);

		int N = sc.nextInt();
		int W = sc.nextInt();
		ArrayList<ArrayList<Integer>> list = new ArrayList<ArrayList<Integer>>();
		for(int i = 0; i <= 3; i++) list.add(new ArrayList<Integer>());

		long w1 = sc.nextLong();
		list.get(0).add(sc.nextInt());
		for(int i = 1; i < N; i++){
			int w = sc.nextInt() - (int)w1;
			int v = sc.nextInt();
			list.get(w).add(v);
		}

		for(int i = 0; i <= 3; i++){
			Collections.sort(list.get(i), Collections.reverseOrder());
		}

		long ans = 0;

		for(int i = 0; i <= list.get(0).size(); i++){
			long sumW0 = w1 * i;
			if(sumW0 > W) continue;
			for(int j = 0; j <= list.get(1).size(); j++){
				long sumW1 = sumW0 + (w1 + 1) * j;
				if(sumW1 > W) continue;
				for(int k = 0; k <= list.get(2).size(); k++){
					long sumW2 = sumW1 + (w1 + 2) * k;
					if(sumW2 > W) continue;
					for(int m = 0; m <= list.get(3).size(); m++){
						long sumW3 = sumW2 + (w1 + 3) * m;
						if(sumW3 > W) continue;

						long res = 0;
						for(int ii = 0; ii < i; ii++) res += list.get(0).get(ii);
						for(int ii = 0; ii < j; ii++) res += list.get(1).get(ii);
						for(int ii = 0; ii < k; ii++) res += list.get(2).get(ii);
						for(int ii = 0; ii < m; ii++) res += list.get(3).get(ii);

						ans = Math.max(ans, res);
					}
				}
			}
		}

		System.out.println(ans);

	}//end main

}//end Main

class FastScanner {
    private InputStream in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    public FastScanner(InputStream in) {
		this.in = in;
	}
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
