        long ans = 0;
        for (int j = 0; j < dp[n].length && j + base - diff <= w; j++) {
            if (dp[n][j] > ans)
                ans = dp[n][j];
        }
        System.out.println(ans);
    }

    static class item {
        int weight;
        long value;
