import java.util.ArrayList;
import java.util.Comparator;
import java.util.Scanner;

public class Main2 {

	public static void main(String[] args) {
		new Main2().solve();
	}
	static int N,W;
	static int w0;
	static ArrayList<Integer>[] v=new ArrayList[4];

	static void solve(){
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		W = sc.nextInt();

		for (int i = 0; i < v.length; i++) {
			v[i]=new ArrayList<Integer>(N);
		}
		w0=sc.nextInt();
		v[0].add(sc.nextInt());

		for(int i=1;i<N;i++){
			int w=sc.nextInt();
			v[w-w0].add(sc.nextInt());
		}
		for(int i=0;i<v.length;i++){
			v[i].sort(Comparator.reverseOrder());
		}

		System.out.println(solve2(0,N,0));
	}
	static int solve2(int startIndex,int numLeft,int totalW){

		if(startIndex>=v.length){
			return 0;
		}

		int vi=0;
		int wi=totalW;
		int max_v=0;

		for(int n=0;n<=numLeft && n<=v[startIndex].size();n++){
			if(n>=1){
				vi+=v[startIndex].get(n-1);
				wi+=w0+startIndex;
			}
			if(wi>W)break;

			max_v=Integer.max(max_v, vi+solve2(startIndex+1,numLeft-n,wi));
		}
		return max_v;
	}
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {

    static ArrayList<Integer> stones[];
    static long W;
    static long N;
    static long F;
    public static void main(String[] args)  {
        Scanner scanner = new Scanner(System.in);
        N = scanner.nextInt();
        W = scanner.nextInt();
        stones = new ArrayList[4];
        for (int i = 0;i < 4;++i){
            stones[i] = new ArrayList<>();
        }
        for (int i = 0;i < N;++i){
            int w = scanner.nextInt();
            int v = scanner.nextInt();
            if(i == 0){
                F = w;
            }
            stones[(int)(w - F)].add(v);
        }
        for (int i = 0;i < 4;++i){
            stones[i].sort((a,b) -> b - a);
        }
        System.out.println(search());
    }

    public static long search(){
        long r = 0;
        for (long i1 = -1;i1 < stones[0].size();++i1){
            for (long i2 = -1;i2 < stones[1].size();++i2) {
                for (long i3 = -1; i3 < stones[2].size(); ++i3) {
                    for (long i4 = -1; i4 < stones[3].size(); ++i4) {
                        if((i1 + 1) * F + (i2 + 1) * (F + 1) + (i3 + 1) * (F + 2) + (i4 + 1) * (F + 3) > W)continue;
                        long t = 0;
                        if(i1 >= 0)for (int i = 0; i <= i1; ++i) {
                            t += stones[0].get(i);
                        }
                        if(i2 >= 0)for (int i = 0; i <= i2; ++i) {
                            t += stones[1].get(i);
                        }
                        if(i3 >= 0)for (int i = 0; i <= i3; ++i) {
                            t += stones[2].get(i);
                        }
                        if(i4 >= 0)for (int i = 0; i <= i4; ++i) {
                            t += stones[3].get(i);
                        }
                        if(r < t)r = t;
                    }
                }
            }
        }
        return r;
    }

}

