		listD.sort(Comparator.reverseOrder());

		// 計算
		int result = 0;
		for(int i = 0; i <= listA.size(); i++){
		    int tempWA = 0;
		    int tempVA = 0;
		    int indexA = 0;
		    while(indexA < i){
		        tempWA += w1;
		        if(tempWA > w) break;
		        tempVA += listA.get(indexA);
		        indexA++;
		    }
		    for(int j = 0; j <= listB.size(); j++){
		        int tempWB = tempWA;
		        int tempVB = tempVA;
		        int indexB = 0;
		        while(indexB < j){
		            tempWB += w1 + 1;
		            if(tempWB > w) break;
		            tempVB += listB.get(indexB);
		            indexB++;
		        }
		        for(int k = 0; k <= listC.size(); k++){
		            int tempWC = tempWB;
		            int tempVC = tempVB;
		            int indexC = 0;
		            while(indexC < k){
		                tempWC += w1 + 2;
		                if(tempWC > w) break;
		                tempVC += listC.get(indexC);
		                indexC++;
		            }
		            for(int l = 0; l <= listD.size(); l++){
		                int tempWD = tempWC;
		                int tempVD = tempVC;
		                int indexD = 0;
		                while(indexD < l){
		                    tempWD += w1 + 3;
		                    if(tempWD > w) break;
		                    tempVD += listD.get(indexD);
		                    indexD++;
		                }
		                result = max(result, tempVD);
		            }
		        }
		    }
		}

		// 出力
		System.out.println(result);
	}
}

