    for(int i = 0; i < n; i++){
      w[i] = sc.nextInt();
      v[i] = sc.nextInt();
    }

    int[][][] dp = new int[n + 1][n + 1][3 * n + 1];
    for(int i = 0; i <= n; i++){
      for(int j = 0; j <= n; j++){
        Arrays.fill(dp[i][j], -INF);
      }
    }

    dp[0][0][0] = 0;
    for(int i = 1; i <= n; i++){
      for(int j = 0; j <= n; j++){
        for(int k = 0; k <= 3 * n; k++){
          if(j - 1 >= 0 && j <= i && k - (w[i - 1] - w[0]) >= 0){
            if(DEBUG){
              System.out.println("in");
            }
            dp[i][j][k] = Math.max(
                dp[i - 1][j - 1][k - (w[i - 1] - w[0])] + v[i - 1], dp[i - 1][j][k]);
          }
          else{
            dp[i][j][k] = dp[i - 1][j][k];
          }
