static long knapsack(long dp[][],pair[] a,int n,int w) {
  if(w==0) {
    return 0;
  }
  if(n==0) {
    return 0;
  }
  if(dp[n][w]!=-1) {
    return dp[n][w];
  }
  if(a[n-1].wt<=w) {
    return dp[n][w]=Math.max(a[n-1].val+knapsack(dp,a,n-1,w-a[n-1].wt),knapsack(dp,a,n-1,w) );
  }else {
    return dp[n][w]=knapsack(dp,a,n-1,w);
  }
}
