public class Main {

    static int N;
    static int W;
    static Obj[] O;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        W = sc.nextInt();
        O = new Obj[N];
        for (int i = 0; i < N; i++) {
            O[i] = new Obj(sc.nextInt(), sc.nextInt());
        }
        System.out.println( solve() );
    }

    private static long solve() {
        int w1 = O[0].weight;
        for (Obj obj : O) {
            obj.weight -= w1;
        }

        List<Obj> g0 = new ArrayList<>();
        List<Obj> g1 = new ArrayList<>();
        List<Obj> g2 = new ArrayList<>();
        List<Obj> g3 = new ArrayList<>();
        for (Obj obj : O) {
            if( obj.weight == 0 ) {
                g0.add(obj);
            } else if( obj.weight == 1 ) {
                g1.add(obj);
            } else if( obj.weight == 2 ) {
                g2.add(obj);
            } else if( obj.weight == 3 ) {
                g3.add(obj);
            } else {
                throw new RuntimeException("wtf");
            }
        }

        Comparator<Obj> c = Comparator.comparingInt(o -> o.value);
        c = c.reversed();
        g0.sort(c);
        g1.sort(c);
        g2.sort(c);
        g3.sort(c);

        int[] s0 = sigma(g0);
        int[] s1 = sigma(g1);
        int[] s2 = sigma(g2);
        int[] s3 = sigma(g3);

        int max = 0;
        for (int i0 = 0; i0 < s0.length; i0++) {
            for (int i1 = 0; i1 < s1.length; i1++) {
                for (int i2 = 0; i2 < s2.length; i2++) {
                    for (int i3 = 0; i3 < s3.length; i3++) {
                        long w = (long)(i0*w1) + i1*(w1+1) + i2*(w1+2) + i3*(w1+3);
                        if( w > W ) continue;

                        max = Math.max(s0[i0] + s1[i1] + s2[i2] + s3[i3], max);
                    }
                }
            }
        }
        return max;
    }

    private static int[] sigma(List<Obj> objs) {
        Comparator<Obj> c = Comparator.comparingInt(o -> o.value);
        c = c.reversed();
        objs.sort(c);

        int[] s = new int[objs.size() + 1];
        for (int i = 0; i < objs.size(); i++) {
            s[i+1] = s[i] + objs.get(i).value;
        }
        return s;
    }

    private static void show(long[] array) {
        StringJoiner j = new StringJoiner(" ");
        for (long i : array) {
            j.add("" + i);
        }
        System.err.println( j.toString() );
    }

    private static class Obj {
        private int weight; // 0 to 3
        private final int value;

        public Obj(int weight, int value) {
            this.weight = weight;
            this.value = value;
        }
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

import java.util.*;
public class Main {

	public static void main(String[] args) {		
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt(), W = sc.nextInt();
		int item[][] = new int[N][2];
		for(int i=0;i<N;i++) {
			item[i][0]= sc.nextInt(); //w
			item[i][1]= sc.nextInt(); //v
		}
		sc.close();

		int w0 = item[0][0];

		Integer weight0[]= new Integer[100];
		Integer weight1[]= new Integer[100];
		Integer weight2[]= new Integer[100];
		Integer weight3[]= new Integer[100];
		Arrays.fill(weight0, 0);
		Arrays.fill(weight1, 0);
		Arrays.fill(weight2, 0);
		Arrays.fill(weight3, 0);

		int pointer[] = new int[4];
		for(int i=0;i<N;i++) {
			int weight = item[i][0] - w0;
			int value = item[i][1];

			if(weight==0) {
				weight0[pointer[weight]]=value;
				pointer[weight]++;
			}
			if(weight==1) {
				weight1[pointer[weight]]=value;
				pointer[weight]++;
			}
			if(weight==2) {
				weight2[pointer[weight]]=value;
				pointer[weight]++;
			}
			if(weight==3) {
				weight3[pointer[weight]]=value;
				pointer[weight]++;
			}
		}
		Arrays.sort(weight0, (w1,w2)->w2-w1);
		Arrays.sort(weight1, (w1,w2)->w2-w1);
		Arrays.sort(weight2, (w1,w2)->w2-w1);
		Arrays.sort(weight3, (w1,w2)->w2-w1);

		//累積和を用意しておく
		long cumSum0[] = new long[N+1]; 
		long cumSum1[] = new long[N+1];
		long cumSum2[] = new long[N+1];
		long cumSum3[] = new long[N+1];


		for(int i=0;i<N;i++) {
			cumSum0[i+1] = cumSum0[i]+weight0[i];
			cumSum1[i+1] = cumSum1[i]+weight1[i];
			cumSum2[i+1] = cumSum2[i]+weight2[i];
			cumSum3[i+1] = cumSum3[i]+weight3[i];
		}

		int upper = 0;

		//荷物の数
		int minP = Math.min(W/(w0+3),N);
		int maxP = Math.min(W/w0,N);
		long ans = 0;
		for(int p=minP;p<=maxP;p++) {
			upper = W - w0*p;
			for(int i=0;i<=p;i++) {
				for(int j=0;i+j<=p;j++) {
					for(int k=0;i+j+k<=p;k++){	
							int l  = p -(i+j+k);
							//w1をi個, w1+1:j w1+2:k w1+3:l
							if(j+2*k+3*l > upper)continue;
							long sum = cumSum0[i]+cumSum1[j]+cumSum2[k]+cumSum3[l];
							ans = Math.max(ans, sum);
					}
				}
			}


		}
		System.out.println(ans);
	}
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final int w = scanner.nextInt();

        final Map<Integer, List<Long>> items = new HashMap<>();
        for (int i = 0; i < n; i++) {
            final int wi = scanner.nextInt();
            final long vi = scanner.nextInt();
            items.computeIfAbsent(wi, v -> new ArrayList<>()).add(vi);
        }

        items.values().forEach(list -> list.sort(Comparator.reverseOrder()));

        final List<Integer> keys = new ArrayList<>(items.keySet());
        final long answer = recursive(keys, items, 0, w, 0);
        System.out.println(answer);
    }

    private static long recursive(final List<Integer> keys, final Map<Integer, List<Long>> items, final long value, final int w, final int index) {
        long maxValue = value;
        if (index < keys.size() - 1) {
            maxValue = Math.max(maxValue, recursive(keys, items, value, w, index + 1));
        }

        final int key = keys.get(index);
        final List<Long> values = items.get(key);
        long tmpValue = value;
        for (int i = 0; i < values.size() && key * (i + 1) <= w; i++) {
            tmpValue += values.get(i);
            if (index < keys.size() - 1) {
                maxValue = Math.max(maxValue, recursive(keys, items, tmpValue, w - key * (i + 1), index + 1));
            }
        }
        return Math.max(maxValue, tmpValue);
    }
}

