                        for (int m = 0; m < j; m++) candidate += al.get(1).get(m);
                        for (int m = 0; m < k; m++) candidate += al.get(2).get(m);
                        for (int m = 0; m < l; m++) candidate += al.get(3).get(m);
                        if (ans < candidate) {
                            ans = candidate;
                        }
                    }
                }
            }
