class Main{
    public static void main(String[] args)throws IOException{
        int N,W;
        Scanner scan = new Scanner(System.in);
        N = scan.nextInt();
        W = scan.nextInt();
        int[]  v = new int[N+1];  //価値
        int[]  w = new int[N+1]; //重さ
        long[][] dp = new long[N+1][4];

        v[0] = 0;
        w[0] = 0;

        //値を取得
        for(int i=1;i<=N;i++){
          w[i] = scan.nextInt();
          v[i] = scan.nextInt();
        }
        int w1 = w[1];

        //初期化
        for(int i = 0; i <= N; i++) {
             for(int j = 0; j < 4; j++) {
                  dp[i][j] = 0;
             }
        }

        //ナップサック
        for(int i=1;i<=N;i++){
          for(int j=0;j<=3;j++){
            dp[i][j] = dp[i-1][j];
            if(w[i] > j) continue;
            dp[i][j] = Math.max(v[i]+dp[i-1][j-(w[i]-w1)],dp[i-1][j]);
          }
        }
        System.out.println(dp[N][W]);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;


public class Main{

	public static void main(String[] args) {

		class Good implements Comparable<Good>{
			long value;
			long weight;

			public Good(long val, long w) {
				value = val;
				weight = w;
			}

			public long getValue() {
				return value;
			}

			public long getWeight() {
				return weight;
			}

			public int compareTo(Good other) {
				if (weight > other.weight) {
					return 1;
				} else if (weight == other.weight) {
					if (value > other.value) {
						return 1;
					} else if (value < other.value) {
						return -1;
					}
					return 0;
				}
				return -1;
			}

		}

		Scanner reader = new Scanner(System.in);
		int N = reader.nextInt();
		long W = reader.nextLong();
		long ans = 0;
		ArrayList<Good> list = new ArrayList<Good>();
		for (int i = 0; i < N; i++) {
			long wei = reader.nextLong();
			long val = reader.nextLong();
			Good good = new Good(val, wei);
			list.add(good);
		}
		Collections.sort(list);

		for (int i = N-1; i >= 0; i--) {
			Good item = list.get(i);
			long tmp = 0;
			long remain = W-item.getWeight();
			if (remain >= 0) {
				tmp = item.getValue();
				for (int j = i-1; j >= 0; j--) {
					Good next = list.get(j);
					if (remain >= 0) {
						if (next.getWeight() <= remain) {
							tmp += next.getValue();
							remain -= next.getWeight();
						}
					} else {
						break;
					}
				}
			}
			ans = Math.max(ans, tmp);

		}

		System.out.println(ans);
		reader.close();

	}

}

