    private long f(int i, long weight) {

        if(i == N) {
            return 0;
        }else if(weight  < w[i]) {
            return f(i + 1, weight);
        }else{
            return Math.max(f(i + 1, weight), f(i + 1, weight - w[i]) + v[i]);
        }
    }
