			for(int j = 0; j <= x[1].size(); j++)
				for(int k = 0; k <= x[2].size(); k++)
					for(int l = 0; l <= x[3].size(); l++)
						if((long)(i+j+k+l)*w1+j+k*2+l*3 <= W)
