import java.util.ArrayList;
import java.util.Comparator;
import java.util.Scanner;

public class Main {
    int n;
    long w;
    long[] vs;
    long[] ws;
    ArrayList<ArrayList<Long>> is;

    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    private void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        w = sc.nextLong();
        vs = new long[n];
        ws = new long[n];
        is = new ArrayList<>(4);
        for (int i = 0; i < 4; i++) is.add(new ArrayList<>());
        for (int i = 0; i < n; i++) {
            ws[i] = sc.nextLong();
            vs[i] = sc.nextLong();
            int j = (int) (ws[i] - ws[0]);
            is.get(j).add(vs[i]);
        }

        for (int i = 0; i < 4; i++)
            is.get(i).sort(Comparator.reverseOrder());
    }

    private void solve() {
        long ans = 0;
        long weight, tmp;
        for (int i = 0; i <= is.get(0).size(); i++) {
            for (int j = 0; j  <= is.get(1).size(); j++) {
                for (int k = 0; k <= is.get(2).size(); k++) {
                    for (int l = 0; l <= is.get(3).size(); l++) {
                        weight = ws[0] * i + (ws[0] + 1) * j +
                                (ws[0] + 2) * k + (ws[0] + 3) * l;
                        if (weight > w)
                            continue;
                        tmp = 0;
                        for (int m = 0; m < i; m++) {
                            tmp += is.get(0).get(m);
                        }
                        for (int m = 0; m < j; m++) {
                            tmp += is.get(1).get(m);
                        }
                        for (int m = 0; m < k; m++) {
                            tmp += is.get(2).get(m);
                        }
                        for (int m = 0; m < l; m++) {
                            tmp += is.get(3).get(m);
                        }
                        ans = Long.max(ans, tmp);
                    }
                }
            }
        }
        System.out.println(ans);
    }

}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        SimpleKnapsack solver = new SimpleKnapsack();
        solver.solve(1, in, out);
        out.close();
    }

    static class SimpleKnapsack {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int w = in.nextInt();

            int[] weights = new int[n];
            int[] values = new int[n];

            // i番目 | 選んだ個数 | 残 weight
            long[][][] dp = new long[n + 1][n + 1][3 * n + 1];
            for (int i = 0; i < n; i++) {
                int ww = Integer.parseInt(in.next());
                int vv = Integer.parseInt(in.next());
                weights[i] = ww;
                values[i] = vv;
            }
            int limit = w - (w / weights[0]) * weights[0];

            for (int i = 0; i < n; i++) {
                int diff = weights[i] - weights[0];
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k <= 3 * n; k++) {
                        if (k - diff < 0) {
                            dp[i + 1][j + 1][k] = dp[i][j + 1][k];
                        } else {
                            dp[i + 1][j + 1][k] = Math.max(dp[i][j + 1][k], dp[i][j][k - diff] + values[i]);
                        }
                    }
                }
            }
            long result = 0;
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= 3 * n; j++) {
                    if (i * weights[0] + j <= w) {
                        result = Math.max(result, dp[n][i][j]);
                    }

                }
            }

            out.println(result);

        }

    }
}

