public class Main {
  static long[] w;
  static long[] v;
  static long[][] dp;
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    long W = sc.nextLong();
    w = new long[N];
    v = new long[N];
    for(int i = 0; i < N; i++) {
      w[i] = sc.nextLong();
      v[i] = sc.nextLong();
    }
    dp = new long[N][(int)W + 1];
    for(int i = 0; i < N; i++) {
      for(int j = 0; j < W + 1; j++) {
        dp[i][j] = -1;
      }
    }
    System.out.println(func(N - 1, W));
  }

  public static long func(int i, long j) {
    if(dp[i][(int)j] >= 0) {
      return dp[i][(int)j];
    } else {
      if(i > 0) {
        if(j >= w[i]) {
          if(dp[i - 1][(int)j] < 0) dp[i - 1][(int)j] = func(i - 1, j);
          if(dp[i - 1][(int)(j - w[i])] < 0) dp[i - 1][(int)(j - w[i])] = func(i - 1, j - w[i]);
          return dp[i][(int)j] = Math.max(dp[i - 1][(int)j], dp[i - 1][(int)(j - w[i])] + v[i]);
        } else {
          if(dp[i - 1][(int)j] >= 0) return dp[i - 1][(int)j];
          dp[i - 1][(int)j] = func(i - 1, j);
          return dp[i][(int)j] = dp[i - 1][(int)j];
        }
      } else {
        if(j >= w[i]) return dp[i][(int)j] = v[i];
        return dp[i][(int)j] = 0;
      }      
    }
  }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int W = sc.nextInt();
        int[] w = new int[N];
        int[] v = new int[N];
        for (int i = 0; i < N; ++i) {
            w[i] = sc.nextInt();
            v[i] = sc.nextInt();
        }

        System.out.println(solve(w, v, W));

        sc.close();
    }

    static int solve(int[] w, int[] v, int W) {
        int base = w[0];

        @SuppressWarnings("unchecked")
        List<Integer>[] values = new List[4];
        for (int i = 0; i < values.length; ++i) {
            values[i] = new ArrayList<>();
        }

        for (int i = 0; i < w.length; ++i) {
            values[w[i] - base].add(v[i]);
        }

        for (int i = 0; i < values.length; ++i) {
            Collections.sort(values[i], Collections.reverseOrder());
        }

        return search(values, W, base, 0, 0, 0);
    }

    static int search(List<Integer>[] values, int restWeight, int base, int rowIndex, int colIndex, int totalValue) {
        if (rowIndex == values.length) {
            return totalValue;
        }

        int result = 0;
        if (colIndex != values[rowIndex].size() && restWeight >= base + rowIndex) {
            result = Math.max(result, search(values, restWeight - (base + rowIndex), base, rowIndex, colIndex + 1,
                    totalValue + values[rowIndex].get(colIndex)));
        }

        result = Math.max(result, search(values, restWeight, base, rowIndex + 1, 0, totalValue));

        return result;
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int W = scanner.nextInt();

    int[] w = new int[N];
    int[] v = new int[N];

    for (int i = 0; i < N; i++) {
      w[i] = scanner.nextInt();
      v[i] = scanner.nextInt();
    }

    long[][] vw = new long[4][N + 1];
    for (int i = 0; i < N; i++) {
      vw[w[i] - w[0]][i] = v[i];
    }
    for (int i = 0; i < 4; i++) {
      Arrays.sort(vw[i]);
      reverse(vw[i], 1, N);
      for (int j = 1; j < N + 1; j++) vw[i][j] += vw[i][j - 1];
    }

    long max = 0;
    for (int a = 0; a <= N; a++) {
      for (int b = 0; b <= N - a; b++) {
        for (int c = 0; c <= N - a - b; c++) {
          for (int d = 0; d <= N - a - b - c; d++) {
            long tw = (long) w[0] * a + (w[0] + 1L) * b + (w[0] + 2L) * c + (w[0] + 3L) * d;
            long tv = vw[0][a] + vw[1][b] + vw[2][c] + vw[3][d];
            if (tw > W) continue;
            max = Math.max(max, tv);
          }
        }
      }
    }
    System.out.println(max);
  }

  private static void swap(long[] a, int i, int j) {
    long tmp = a[i];
    a[i] = a[j];
    a[j] = tmp;
  }

  private static void reverse(long[] a, int i, int j) {
    if (i > j) throw new IllegalArgumentException("i must be less than j");
    while (i < j) {
      swap(a, i, j);
      i++;
      j--;
    }
  }
}

