            for (int j = 0; j < dp[0].length; j++) {
                if (j - trg.weight - diff < 0) {
                    dp[i][j] = dp[i-1][j];
                }
                else {
                    dp[i][j] = Math.max(dp[i-1][j],
                                        dp[i-1][j- diff -trg.weight] + trg.value);
                }
            }
        }

