// ABC 27-C
// http://abc027.contest.atcoder.jp/tasks/abc027_c

public class Main {

	static int n;
	static int w;
	static int[] weights;
	static int[] values;
	static HashMap<String, Long> memo;

	public static void main (String[] args) throws java.lang.Exception {
		Scanner in = new Scanner(System.in);

		n = in.nextInt();
		w = in.nextInt();
		weights = new int[n];
		values = new int[n];

		for (int i = 0; i < n; i++) {
			weights[i] = in.nextInt();
			values[i] = in.nextInt();
		}
		memo = new HashMap<String, Long>();

		System.out.println(solve2(0, 0));
	}

	public static long solve2(int index, long weight) {
		String s = index + "," + weight;
		if (w < weight) {
			return Integer.MIN_VALUE;
		} else if (index == n) {
			return 0;
		} else if (memo.containsKey(s)) {
			return memo.get(s);
		}

		long temp = solve2(index + 1, weight);
		if (weight + weights[index] <= w) {
			temp = Math.max(temp, values[index] + solve2(index + 1, weight + weights[index]));
		}

		memo.put(s, temp);
		return temp;
	}

	public static long solve(int index, long weight, long value) {
		String s = index + "," + weight;
		if (w < weight) {
			return Integer.MIN_VALUE;
		} else if (index == n) {
			return value;
		} else if (memo.containsKey(s)) {
			return memo.get(s);
		}

		long temp = Math.max(
				solve(index + 1, weight, value),
				solve(index + 1, weight + weights[index], value + values[index])
		);
		memo.put(s, temp);

		return temp;
	}
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = Integer.parseInt(sc.next());
        long W = Long.parseLong(sc.next());
        Map<Long, List<Long>> map = new TreeMap<>();
        long w = Long.parseLong(sc.next());
        long basew = w;
        for (int i = (int)w; i <= w + 3; i++) {
            List<Long> base = new ArrayList<>();
            map.put((long)i, base);
        }
        long v = Long.parseLong(sc.next());
        map.get(w).add(v);
        for (int i = 1; i < N; i++) {
            w = Integer.parseInt(sc.next());
            v = Long.parseLong(sc.next());
            map.get(w).add(v);
        }
        int[] listsize = new int[map.size()];
        int ii = 0;
        for (Long key : map.keySet()) {
            listsize[ii] = map.get(key).size() + 1;
            ii++;
        }
        for (Map.Entry<Long, List<Long>> list : map.entrySet()) {
            Collections.sort(list.getValue(), Comparator.reverseOrder());
            long sum = 0;
            List<Long> sumList = new ArrayList<>();
            for (long l : list.getValue()) {
                sum += l;
                sumList.add(sum);
            }
            sumList.add(0, 0L);
            map.put(list.getKey(), sumList);
        }
        long ans = 0;
        for (int i = 0; i < listsize[0]; i++) {
            for (int j = 0; j < listsize[1]; j++) {
                for (int k = 0; k < listsize[2]; k++) {
                    for (int l = 0; l < listsize[3]; l++) {
                        long sumw = basew * i + (basew + 1) * j + (basew + 2) * k + (basew + 3) * l;
                        if (sumw <= W) {
                            long sum1 = map.get(basew).get(i);
                            long sum2 = map.get(basew + 1).get(j);
                            long sum3 = map.get(basew + 2).get(k);
                            long sum4 = map.get(basew + 3).get(l);
                            long sumv = sum1 + sum2 + sum3 + sum4;
                            ans = Math.max(ans, sumv);
                        }
                    }
                }
            }
        }
        System.out.println(ans);
    }
}

