			c += one.get(onenum-i);
		}
		for(int i = 0;i < twonum;i++){
			c += two.get(twonum-i);
		}
		for(int i = 0;i < threenum;i++){
			c += three.get(threenum-i);
		}
		for(int i = 0;i < fournum;i++){
			c += four.get(fournum-i);
		}

		return c;

	}









