		int N = sc.ni();
		int W = sc.ni();
		long[][] nums = new long[N][2];
		for (int i = 0; i < N; i++) {
			nums[i] = new long[]{sc.nl(),sc.nl()};
		}

		ArrayList<Long> reachable = new ArrayList<Long>();
		long max = 0;
		reachable.add(0L);
		int index = 0;
		loop:
		while (true) {
			for (int i = 0; i <= 3; i++) {
				long next = reachable.get(index)+nums[0][0]+i;
				if (next > W)
					break loop;
				if (next > max) {
					reachable.add(next);
					max = next;
				}
			}
			index++;
		}
		int size = reachable.size()-1;
		long[][] dp = new long[N+1][size+1];
		for (int i = 1; i <= N; i++) {
			for (int j = 1; j <= size; j++) {
				//don't take item i (base case)
				dp[i][j] = Math.max(dp[i-1][j],dp[i][j-1]);
				//take item i
				long targetW = reachable.get(j)-nums[i-1][0];
				if (targetW >= 0) {
					//find index
					int low = 0;
					int high = j-1;
					while (low < high) {
						int med = (low+high)/2;
						if (reachable.get(med) == targetW) {
							low = med;
							high = med;
							break;
						} else if (reachable.get(med) < targetW) {
							low = med+1;
						} else {
							high = med-1;
						}
					}

					dp[i][j] = Math.max(dp[i][j],dp[i-1][low]+nums[i-1][1]);
				}
			}
		}
		//pw.println(reachable);
