class Task {
	private int[] ws;
	private int[] vs;
	private int n;
	private int w;
	private int totalWeight;
	private int totalValue;

	public void solve(int testNumber, InputReader in, OutputWriter out) {
		n = in.nextInt();
		w = in.nextInt();
		ws = new int[n];
		vs = new int[n];
		for (int i = 0; i < n; i++) {
			ws[i] = in.nextInt();
			vs[i] = in.nextInt();
		}

		for (int i = 0; i < n; i++) {
			for (int j = 1; j < n - i; j++) {
				double x = vs[j - 1] / ws[j - 1];
				double y = vs[j] / ws[j];
				if (x < y) {
					swap(j - 1, j);
				}
			}
		}

		for (int i = 0; i < n; i++) {
			if (ws[i] + totalWeight <= w) {
				totalWeight += ws[i];
				totalValue += vs[i];
			}
		}
		out.print(totalValue);
	}

	private void swap(int a, int b) {
		int tmp = vs[a];
		vs[a] = vs[b];
		vs[b] = tmp;

		tmp = ws[a];
		ws[a] = ws[b];
		ws[b] = tmp;
	}
}

class InputReader {
	private InputStream stream;
	private byte[] buf = new byte[1024];
	private int curChar;
	private int numChars;

	public InputReader(InputStream stream) {
		this.stream = stream;
	}

	public int read() {
		if (numChars == -1) {
			throw new InputMismatchException();
		} else {
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException var2) {
					throw new InputMismatchException();
				}
				if (numChars <= 0) {
					return -1;
				}
			}
			return buf[curChar++];
		}
	}

	public boolean isSpace(int c) {
		return c == 10 || c == 13 || c == -1 || c == 9 || c == 32;
	}

	private boolean isEnd(int c) {
		return c == 10 || c == 13 || c == -1;
	}

	public String next() {
		int c = this.read();
		while (isSpace(c)) {
			c = this.read();
		}
		StringBuilder res = new StringBuilder();
		do {
			res.appendCodePoint(c);
		} while (!isSpace(c = this.read()));
		return res.toString();
	}

	public char nextChar() {
		int c = this.read();
		while (isSpace(c)) {
			c = this.read();
		}
		return (char) c;
	}

	public int nextInt() {
		int c = this.read();
		while (isSpace(c)) {
			c = this.read();
		}
		byte sgn = 1;
		if (c == 45) {
			sgn = -1;
			c = this.read();
		}
		int res = 0;
		while (c >= 48 && c <= 57) {
			res *= 10;
			res += c - 48;
			c = this.read();
			if (isSpace(c)) {
				return res * sgn;
			}
		}
		throw new InputMismatchException();
	}

	public long nextLong() {
		int c = this.read();
		while (isSpace(c)) {
			c = this.read();
		}
		byte sgn = 1;
		if (c == 45) {
			sgn = -1;
			c = this.read();
		}
		long res = 0;
		while (c >= 48 && c <= 57) {
			res *= 10;
			res += c - 48;
			c = this.read();
			if (isSpace(c)) {
				return res * sgn;
			}
		}
		throw new InputMismatchException();
	}

	public String nextLine() {
		int c = read();
		while (isEnd(c)) {
			c = this.read();
		}
		StringBuilder res = new StringBuilder();
		do {
			res.appendCodePoint(c);
		} while (!isEnd(c = this.read()));
		return res.toString();
	}

}

