		long[][][] dp = new long[N+1][N+1][3*N+1]; //{items chosen,number of items chosen in total, weight of knapsack}
		for (int i = 1; i <= N; i++) {
			for (int j = 1; j <= N; j++) {
				for (int w = 0; w <= 3*N; w++) {
					int curW = (int)(nums[i-1][0]-nums[0][0]);
					dp[i][j][w] = dp[i-1][j][w];
					if (w-curW >= 0) {
						dp[i][j][w] = Math.max(dp[i][j][w],dp[i-1][j-1][w-curW]+nums[i-1][1]);
					}
				}
			}
		}

		long ans = 0;
		for (int j = 0; j <= N; j++) {
			for (int w = 0; w <= 3*N; w++) {
				if (nums[0][0]*j+w <= W) {
					ans = Math.max(ans,dp[N][j][w]);
				}
			}
		}
