  private static void solve() {
    n = ni();
    W = nl();
    a = ntable(n, 2);

    long ret = dfs(0, 0);
    System.out.println(ret);
  }

  static Map<Long, Long> memo = new HashMap<>();
  private static long dfs(int i, long w) {
    if (i >= n) return 0;

    long h = w * 10000 + i;
    if (memo.containsKey(h)) {
      return memo.get(h);
    }


    long ret = dfs(i + 1, w);
    if (w + a[i][0] <= W) {
      ret = Math.max(ret, dfs(i + 1, w + a[i][0]) + a[i][1]);
    }
    memo.put(h, ret);
    return ret;
  }

