	public static void main(String[] args) {
		FastScanner fs = new FastScanner(System.in);
		int n = fs.nextInt(), w = fs.nextInt();

		List<Integer> item[] = new ArrayList[4];
		for(int i=0;i<4;i++)item[i] = new ArrayList<>();

		int w1 = 0;

		for(int i=0;i<n;i++) {
			int tw = fs.nextInt(), tv = fs.nextInt();
			if(i==0)w1 = tw;
			item[tw - w1].add(tv);
		}
		for(int i=0;i<4;i++) {
			Collections.sort(item[i],(t1,t2)->t2-t1);			
		}

		long ans = 0;

		for(int i=0;i<=item[0].size();i++) {
			for(int j=0;j<=item[1].size();j++) {
				for(int k=0;k<=item[2].size();k++) {
					for(int l=0;l<=item[3].size();l++) {
						if((long)i * w1 + (long)j * (w1 + 1) + (long)k * (w1 + 2) + (long)l * (w1 + 3) > w) {
							continue;
						}
						long val = 0;
						for(int a = 0;a<i;a++) {
							val += item[0].get(a);
						}
						for(int a = 0;a<j;a++) {
							val += item[1].get(a);
						}
						for(int a = 0;a<k;a++) {
							val += item[2].get(a);
						}
						for(int a = 0;a<l;a++) {
							val += item[3].get(a);
						}
						ans = Math.max(ans, val);
					}
				}
			}
		}
		System.out.println(ans);

	}

	//MOD culculations
	static long plus(long x, long y) {
		long res = (x + y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long sub(long x, long y) {
		long res = (x - y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long mul(long x, long y) {
		long res = (x * y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long div(long x, long y) {
		long res = x * pow(y, mod - 2) % mod;
		return res < 0 ? res + mod : res;
	}

	static long pow(long x, long y) {
		if (y < 0)
			return 0;
		if (y == 0)
			return 1;
		if (y % 2 == 1)
			return (x * pow(x, y - 1)) % mod;
		long root = pow(x, y / 2);
		return root * root % mod;
	}
}

