		v0_sum[0] = 0;
		if(w0_cnt!=0){
			for(int i=1; i<=w0_cnt; i++){
				v0_sum[i] += v0_sum[i-1] + v0[N-i];
			}
		}
		Arrays.sort(v1);
		long[] v1_sum = new long[w1_cnt+1];
		v1_sum[0] = 0;
		if(w2_cnt!=0){
