					if(l>w3_cnt){
						l = w3_cnt;
					}
					sum = v0_sum[i] + v1_sum[j] + v2_sum[k]+ v3_sum[(int)l]; 
					if(sum>max){
						max = sum;
					}
				}
			}
		}

		System.out.print(max);

	}

