				}
			}
		}
		long max = 0;
		for (int i = 0; i <= n; i++) {
			if (W - w1 * i >= 0 && W - w1 * i < 500) {
				max = Math.max(max, dp[n][i][W - (int)w1 * i]);
			}
		}
