		long va[] = new long[N+1];
		long vb[] = new long[N+1];
		long vc[] = new long[N+1];
		long vd[] = new long[N+1];

		va[0]=0;
		vb[0]=0;
		vc[0]=0;
		vd[0]=0;

		for(int i=1; i<=N; i++){
			if(w[i]==w[1]){
				a++;
				va[a]=v[i];
			}
			if(w[i]==w[1]+1){
				b++;
				vb[b]=v[i];
			}
			if(w[i]==w[1]+2){
				c++;
				vc[c]=v[i];
			}
			if(w[i]==w[1]+3){
				d++;
				vd[d]=v[i];
			}
		}

		Arrays.sort(va);
		Arrays.sort(vb);
		Arrays.sort(vc);
		Arrays.sort(vd);


		long sum=0;
		long sumtmp=0;
		for(int i=0; i<=a; i++){
			for(int j=0; j<=b; j++){
				for(int k=0; k<=c; k++){
					for(int m=0; m<=d; m++){
						sum=0;
						for(int n=N; n>N-i; n--){
							sum = sum + va[n];
						}
						for(int n=N; n>N-j; n--){
							sum = sum + vb[n];
						}
						for(int n=N; n>N-k; n--){
							sum = sum + vc[n];
						}
						for(int n=N; n>N-m; n--){
							sum = sum + vd[n];
						}
						if(w[1]*i+(w[1]+1)*j+(w[1]+2)*k+(w[1]+3)*d<=W){
							if(sum>sumtmp){
								sumtmp=sum;
							}
						}
					}
				}
			}
		}
		System.out.println(sumtmp);
	}
