        int W = sc.nextInt();
        int[] w = new int[N];
        int[] _v = new int[N];
        for (int i = 0; i < N; i++) {
            w[i] = sc.nextInt();
            _v[i] = sc.nextInt();
        }
        int ww = w[0];
        for (int i = 0; i < N; i++) {
            w[i] -= ww;
        }
        int[] cnt = new int[4];
        for (int i : w) {
            cnt[i]++;
        }
        int[][] v = new int[4][];
        for (int i = 0; i < 4; i++) {
            v[i] = new int[cnt[i]];
        }
        int[] idx = new int[4];
        for (int i = 0; i < N; i++) {
            v[w[i]][idx[w[i]]++] = _v[i];
        }
        for (int i = 0; i < 4; i++) {
            Arrays.sort(v[i]);
            reverse(v[i]);
        }
        int[][] sum = new int[4][];
        for (int i = 0; i < 4; i++) {
            sum[i] = new int[cnt[i] + 1];
        }
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < cnt[i]; j++) {
                sum[i][j + 1] = sum[i][j] + v[i][j];
            }
        }
        for (int i = 0; i <= v[0].length; i++) {
            if (ww * i > W) {
                break;
            }
            for (int j = 0; j <= v[1].length; j++) {
                if (ww * (i + j) + 1 * j > W) {
                    break;
                }
                for (int k = 0; k <= v[2].length; k++) {
                    if (ww * (i + j + k) + 1 * j + 2 * k > W) {
                        break;
                    }
                    for (int l = 0; l <= v[3].length; l++) {
                        if (ww * (i + j + k + l) + 1 * j + 2 * k + 3 * l > W) {
                            break;
                        }
                        ans = Math.max(ans, sum[0][i] + sum[1][j] + sum[2][k] + sum[3][l]);
                    }
                }
            }
        }
        out.println(ans);
    }

    /**
     * arrの中身を逆に並び替える O(n)
     *
     * @param arr
     */
    public static void reverse(int[] arr) {
        for (int i = 0; i < arr.length / 2; i++) {
            int tmp = arr[i];
            arr[i] = arr[arr.length - i - 1];
            arr[arr.length - i - 1] = tmp;
        }
    }

