		int []v=new int[N+1];
		for(int i=0;i<N;i++){
			w[i]=sc.nextInt();
			v[i]=sc.nextInt();
		}

		//dp[i][j]:i番目までの荷物中から重さの合計がj以下になるような価値の最大値
		int[][]dp=new int[N+1][W+1];

		for(int i=1;i<=W;i++)dp[0][i]=0;

		for(int i=0;i<N;i++){
				for(int j=0;j<=W;j++){
					if(j<w[i])dp[i+1][j]=dp[i][j];
					else dp[i+1][j]=Math.max(dp[i][j], dp[i][j-w[i]]+v[i]);
			}
		}

		System.out.println(dp[N][W]);
	}
}

