import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int W = sc.nextInt();
    int[] r = new int[N];
    int[] v = new int[N];
    int w0 = sc.nextInt();
    v[0] = sc.nextInt();
    for(int i = 1; i < N; i++) {
      int w = sc.nextInt();
      r[i] = w - w0;
      v[i] = sc.nextInt();
    }
    // dp[i][j][k]は物0～iまでからrの和がk以下となるようにj個選んだときの価値の最大値
    int[][][] dp = new int[N][N + 1][3 * N];
    for(int k = 0; k < 3 * N; k++) {
      dp[0][1][k] = v[0]; 
    }
    for(int i = 1; i < N; i++) {
      for(int j = 1; j < N + 1; j++) {
        for(int k = 0; k < 3 * N; k++) {
          if(r[i] <= k) {
            dp[i][j][k] = Math.max(dp[i - 1][j][k], dp[i - 1][j - 1][k - r[i]] + v[i]);
          } else {
            dp[i][j][k] = dp[i - 1][j][k];
          }
        }
      }
    }
    int ans = 0;
    for(int j = 1; j < N + 1; j++) {
      if(W - w0 * j >= 0) {
        int re = Math.min(W - w0 * j, 3 * N - 1);
        ans = Math.max(ans, dp[N - 1][j][re]);
      }
    }
    System.out.println(ans);
  }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

class Main{
	static Map<String,Long> dpa;
	static int N,W;
	static long[][] table=new long[N][2];
	static long[][] dp=new long[N+1][W+1];
	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);
		N=sc.nextInt();
		W=sc.nextInt();
		if(N*W<=1000000) {

			for(int i=0; i<=N; i++) {
				for(int j=0; j<=W; j++) {
					dp[i][j]=0;
				}
			}

			for(int i=0; i<N; i++) {
				table[i][0]=sc.nextLong();
				table[i][1]=sc.nextLong();
			}
			for(int i=0; i<N; i++) {
				for(int j=0; j<=W; j++) {
					if(j-table[i][0]>=0) {
						dp[i+1][j]=Math.max(dp[i][j], dp[i][(int) (j-table[i][0])]+table[i][1]);
					}
					else {
						dp[i+1][j]=dp[i][j];
					}
				}
			}
			System.out.println(dp[N][W]);
		}
		else {
			dpa = new HashMap<>();
			long ans = dfs(0,W);
			System.out.println(ans);
		}
	}
	static long dfs(int n, long w) {
		if (dpa.get(getKey(n,w))!=null) {
			return dpa.get(getKey(n,w));
		}
		long res;
		if (n==N) {
			res=0;
		}else if(w<table[n][1]) {
			res = dfs(n+1, w);
		}else{
			res = Math.max( dfs(n+1, w), dfs(n+1, w-table[n][1])+table[n][0]);
		}
		dpa.put(getKey(n,w), res);
		return res;
	}

	static String getKey(int n, long w){
		return String.format("%d.%d", n,w);
	}

}

