    static int search(int i, int j) {
        if (dp[i][j] != 0) {
            return dp[i][j];
        }
        int res;
        if (i == N) {
            res = 0;
        } else if (j < w[i]) {
            res = search(i + 1, j);
        } else {
            res = Math.max(search(i + 1, j), search(i + 1, j - w[i]) + v[i]);
        }
        return dp[i][j] = res;
    }
}

