/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author MaxHeap
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        int[] w;
        int[] v;
        int[][] memo;
        int n;
        int W;

        int f(int i, int weight) {
            if (i == n) return 0;
            if (memo[i][weight] != -1) return memo[i][weight];
            int ans = 0;
            if (weight + w[i] <= W) {
                ans = Math.max(ans, f(i + 1, weight + w[i]) + v[i]);
            }
            ans = Math.max(ans, f(i + 1, weight));
            return memo[i][weight] = ans;
        }

        public void solve(int testNumber, FastReader in, PrintWriter out) {
            n = in.nextInt();
            W = in.nextInt();
            w = new int[n];
            v = new int[n];
            memo = new int[n + 1][W + 1];

            for (int i = 0; i < n; i++) {
                w[i] = in.nextInt();
                v[i] = in.nextInt();
            }

            for (int[] temp : memo) Arrays.fill(temp, -1);
            out.println(f(0, 0));
        }

    }

    static class FastReader {
        BufferedReader reader;
        StringTokenizer st;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    throw new RuntimeException();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

