		}
		long[][] dp=new long[n+1][W+1];
		for(int i=0;i<=n;i++) {
			Arrays.fill(dp[i], Integer.MIN_VALUE);
		}
		dp[0][0]=0;
		for(int i=1;i<=n;i++) {
			for(int j=0;j<=W;j++) {
				if(j-w[i]>=0)
					dp[i][j]=Math.max(dp[i-1][j], dp[i-1][j-w[i]]+(long)v[i]);
				else
					dp[i][j]=dp[i-1][j];
			}
		}
