		for(int i=1;i<=n;i++) {
			w[i]=scanner.nextInt();
			v[i]=scanner.nextInt();
		}
		Long[][] tmp=new Long[n+1][W+1];
		for(int i=0;i<=n;i++) {
			Arrays.fill(tmp[i], (long)Integer.MIN_VALUE);
		}
		List<List<Long>>dp=new ArrayList<>();
		for(int i=0;i<=n;i++) {
			List<Long>list=new ArrayList<>(Arrays.asList(tmp[i]));
			dp.add(list);
