        public void Solve(ConsoleInput cin)
        {
            int N = cin.ReadInt;
            int W = cin.ReadInt;
            int sumW = 0;
            int sumV = 0;
            int maxV = 0;

            List<Item> list = new List<Item>();

            for(int i = 0; i<N; i++)
            {
                list.Add(new Item(cin.ReadInt,cin.ReadInt));
            }

            IOrderedEnumerable<Item> listSorted = list.OrderByDescending(it => it.Average).ThenBy(it => it.Weight);

            sumW = 0;
            sumV = 0;
            foreach (var item in listSorted)
            {
                if(W < sumW + item.Weight) continue;
                sumW += item.Weight;
                sumV += item.Value;

            }
            maxV = sumV;

            IOrderedEnumerable<Item> listSorted2 = list.OrderByDescending(it => it.Value).ThenBy(it => it.Weight);

            for(int i = 0; i < N-1 ; i++)
            {       
                sumW = 0;
                sumV = 0;
                foreach (var item in listSorted2.Where((s,index) => index >= i))
                {
                    if(W < sumW + item.Weight) continue;
                    sumW += item.Weight;
                    sumV += item.Value;

                }
                if(maxV < sumV) maxV = sumV;
            }

            WriteLine(maxV);
        }
    }

