            int N = io.Int();
            int W = io.Int();
            item[] items = new item[N];
            for (int i = 0; i < N; ++i)
            {
                io.ReadSplit();
                items[i] = new item(io.Int(), io.Int());
            }

            items = items.OrderBy(item => item.w).ToArray();
            int totalW = 0;
            int totalV = 0;
            io.WriteLine(Calc(N, W, items, totalW, totalV, 0).ToString());
        }

        private static int Calc(int N, int W, item[] items, int totalW, int totalV, int i)
        {
            if (i >= N)
            {
                return totalV;
            }
            if (totalW + items[i].w <= W)
            {
                int rv = Math.Max(totalV, Calc(N, W, items, totalW + items[i].w, totalV + items[i].v, i + 1));
                return Math.Max(rv, Calc(N, W, items, totalW, totalV, i + 1));
            }
            else
            {
                return totalV;
            }
        }
    }
