class Program{
	static void Main(){
		long[] s=Array.ConvertAll(Console.ReadLine().Split(),long.Parse);
		long a=0,b=0,ans=0;
		long[,,] dp=new long[s[0]+1,s[0]+1,s[0]*4+1];
		for(long i=1;i<=s[0];i++){
			long[] q=Array.ConvertAll(Console.ReadLine().Split(),long.Parse);
			if(i==1){a=q[0]-1;}
			q[0]-=a;
			b+=q[0];
			for(long j=1;j<=i;j++){
				for(long k=1;k<=b;k++){
					if(k>=q[0]&&j*a+k<=s[1]){dp[i,j,k]=Math.Max(dp[i-1,j-1,k-q[0]]+q[1],Math.Max(dp[i-1,j,k],dp[i,j-1,k]));}
					else{dp[i,j,k]=Math.Max(dp[i-1,j,k],dp[i,j-1,k]);}
				}
			}
		}
		for(long i=1;i<=b;i++){ans=Math.Max(ans,dp[s[0],s[0],i]);}
