            var vs = new long[n];
            for (var i = 0; i < n; i++)
            {
                ws[i] = ReadNextLong();
                vs[i] = ReadNextLong();
            }

            var dp = CreateArray2(n + 1, w + 1, (long)0);
            for (var i = 0; i < n; i++)
            {
