                    {
                        dp[i + 1][j] = Math.Max(dp[i][j - ws[i]] + vs[i], dp[i][j]);
                    }
                    else
                    {
                        dp[i + 1][j] = dp[i][j];
                    }
                }
            }
            Console.WriteLine($"{dp[n][w]}");
        }

