public class Hello
{
    public static void Main()
    {
        var d = new Dictionary<int, List<int>>();
        string[] line = Console.ReadLine().Trim().Split(' ');
        var n = int.Parse(line[0]);
        var W = int.Parse(line[1]);
        var minw = 1000000001;
        for (int i = 0; i < n; i++)
        {
            line = Console.ReadLine().Trim().Split(' ');
            var w = int.Parse(line[0]);
            minw = Math.Min(minw, w);
            var v = int.Parse(line[1]);
            if (d.ContainsKey(w)) d[w].Add(v);
            else
            {
                d[w] = new List<int>();
                d[w].Add(v);
            }
        }
        var amax = new int[4];
        amax[0] = d[minw].Count();
        for (int i = 1; i <= 3; i++)
            if (d.ContainsKey(minw + i)) amax[i] = d[minw + i].Count();
        foreach (var x in d) d[x.Key].Sort();
        var t = 0L; var ret = 0L;
        for (int i = 0; i <= amax[0]; i++)
            for (int j = 0; j <= amax[1]; j++)
                for (int k = 0; k <= amax[2]; k++)
                    for (int L = 0; L <= amax[3]; L++)
                    {
                        if (i * minw + j * (minw+1) + k *(minw + 2) + L * (minw + 3) <= W)
                            t = getW(d, i, minw) + getW(d, j, minw + 1) + getW(d, k, minw + 2) + getW(d, L, minw + 3);
                        ret = Math.Max(t, ret);
                    }
        Console.WriteLine(ret);
    }
    public static long getW(Dictionary<int, List<int>> d, int a, int k)
    {
        if (a == 0) return 0;
        var ret = 0L;
        var dL = d[k].Count();
        for (int i = 0; i < a; i++)
            ret += d[k][dL - 1 - i];
        return ret;
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace D
{
    public class Program
    {
        static void Main(string[] args)
        {
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            Solve();
            Console.Out.Flush();
        }

        public static void Solve()
        {
            var NW = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
            var (N, W) = (NW[0], NW[1]);
            var w = new int[N];
            var v = new int[N];
            for (var i = 0; i < N; i++)
            {
                var wv = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
                w[i] = wv[0];
                v[i] = wv[1];
            }

            var dict = new Dictionary<int, List<long>>();
            var min = w[0];
            for (var i = 0; i < N; i++)
            {
                min = Math.Min(min, w[i]);
                if (dict.ContainsKey(w[i])) dict[w[i]].Add(v[i]);
                else dict[w[i]] = new List<long> { v[i] };
            }

            var w0v = CumulativeItems(dict[min].OrderByDescending(x => x)).ToArray();
            var w1v = dict.ContainsKey(min + 1) ? CumulativeItems(dict[min + 1].OrderByDescending(x => x)).ToArray() : new long[] { 0 };
            var w2v = dict.ContainsKey(min + 2) ? CumulativeItems(dict[min + 2].OrderByDescending(x => x)).ToArray() : new long[] { 0 };
            var w3v = dict.ContainsKey(min + 3) ? CumulativeItems(dict[min + 3].OrderByDescending(x => x)).ToArray() : new long[] { 0 };

            var answer = 0L;
            for (var i = 0; i < w0v.Length; i++)
            {
                for (var j = 0; j < w1v.Length; j++)
                {
                    for (var k = 0; k < w2v.Length; k++)
                    {
                        for (var l = 0; l < w3v.Length; l++)
                        {
                            var weight = i * min + j * (min + 1) + k * (min + 2) + l * (min + 3);
                            if (weight > W) continue;
                            var sum = w0v[i] + w1v[j] + w2v[k] + w3v[l];
                            answer = Math.Max(answer, sum);
                        }
                    }
                }
            }

            Console.WriteLine(answer);
        }

        public static IEnumerable<long> CumulativeItems(IEnumerable<long> items)
        {
            var arr = items.ToArray();
            var ret = new long[arr.Length + 1];
            for (var i = 0; i < arr.Length; i++) ret[i + 1] = arr[i] + ret[i];
            return ret;
        }
    }
}

