      var dp = new long[N,W+1];

      for(long i = wei[0];i <= W;i++){
        dp[0,i] = val[0];
      }

      for(int i = 1;i < N ;i++){
        for(int j = 0;j <= W ;j++){
          if(j >= wei[i]){
            dp[i,j] = Math.Max(dp[i-1,j-wei[i]]+val[i],dp[i-1,j]);
          }else{
            dp[i,j] = dp[i-1,j];
          }
        }
      }
      Console.WriteLine(dp[N-1,W]);



    }


}

