namespace ABC060SimpleKnapsack
{
    class Program
    {
        static void Main(string[] args)
        {
            int N, W;
            string[] vals = Console.ReadLine().Split(' ');
            N = int.Parse(vals[0]);
            W = int.Parse(vals[1]);

            int[] w = new int[N + 1];
            int[] v = new int[N + 1];

            for(int i=1; i <= N; i++)
            {
                vals = Console.ReadLine().Split(' ');
                w[i] = int.Parse(vals[0]);
                v[i] = int.Parse(vals[1]);
            }


            W = W / (w[1] + 3) * 3 + 1;

            for(int i=1; i <= N; i++)
            {
                w[i] -= w[1];
            }


            int[,] dp = new int[N + 1, W + 1];
            //int[,] dp = new int[N + 1, 3 * N + 1];


            for (int i = 1; i <= N; i++)
            {
                for(int j = 1; j <= W; j++)
                {
                    dp[i,j] = dp[i-1,j];
                    if(w[i] > j)
                    {
                        continue;
                    }
                    if(dp[i-1, j-w[i]] + v[i] > dp[i-1, j])
                    {
                        dp[i, j] = dp[i - 1, j - w[i]] + v[i];
                    }
                }
            }

            Console.WriteLine(dp[N, W]);
        }
    }
}

