class D
{
	static void Main()
	{
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var h = read();
		var d = new int[h[0]].Select(_ => read()).GroupBy(a => a[0]).ToDictionary(g => g.Key, g => g.Select(a => a[1]).OrderByDescending(x => x).ToArray());
		int w = h[1], w0 = d.Keys.First();
		var v = Enumerable.Range(0, 4).Select(i => d.ContainsKey(w0 + i) ? d[w0 + i] : new int[0]).ToArray();

		var M = 0;
		for (int i0 = 0, s0 = 0, v0 = 0; s0 <= w; s0 += w0, v0 += v[0][i0++])
		{
			for (int i1 = 0, s1 = s0, v1 = v0; s1 <= w; s1 += w0 + 1, v1 += v[1][i1++])
			{
				for (int i2 = 0, s2 = s1, v2 = v1; s2 <= w; s2 += w0 + 2, v2 += v[2][i2++])
				{
					M = Math.Max(M, v2 + v[3].Take((w - s2) / (w0 + 3)).Sum());

					if (i2 == v[2].Length) break;
				}
				if (i1 == v[1].Length) break;
			}
			if (i0 == v[0].Length) break;
