                    lWone += lstItem[j].lW;                                 // 入った荷物の重さ加算
                    lVone += lstItem[j].lV;                                 // 入った荷物の価値加算
                    iIndx.Add(lstItem[j].iX);                               // 入った荷物のNo保持
                }
                OneUsr = new ClsInIf();
                OneUsr.lW = lWone;                                          // ここまで入った荷物の総重量
