class Program
{
    public static int[][] memo;
    public static int[] wn;
    public static int[] vn;

    static int dfs(int n, int w)
    {
        if (n < 0 || w < 0)
            return 0;

        if (memo[n][w] != 0)
            return memo[n][w];

        if (w < wn[n])
            return memo[n][w] = dfs(n-1, w);

        return memo[n][w] = Math.Max(dfs(n-1, w), dfs(n-1, w-wn[n])+vn[n]);
    }

    static void Main(string[] args)
    {
        int[] input = Console.ReadLine().Split(' ').Select(e => int.Parse(e)).ToArray();
