        {
            input = Console.ReadLine().Split(' ').Select(e => int.Parse(e)).ToArray();
            wn[i] = input[0];
            vn[i] = input[1];
        }

        memo = new int[n][];
        for (int i = 0; i < n; i++)
            memo[i] = new int[w+1];


        Console.WriteLine(dfs(n-1, w));
    }
}

