            var v = structs[i].v;
            for (int j = dp.Length - w - 1; j >= 0; j--)
                UpdateMax(ref dp[j + w], dp[j] + v);
        }
        return dp.Select((s, i) => new { s, i }).Where(t => w0 * (t.i / 400) + t.i % 400 <= W).Max(t => t.s);
    }
