    public static long[] vn;

    static long dfs(long n, long w)
    {
        if (n < 0 || w < 0)
            return 0;

        if (memo[n][w] != 0)
            return memo[n][w];

        if (w < wn[n])
            return memo[n][w] = dfs(n-1, w);

        return memo[n][w] = Math.Max(dfs(n-1, w), dfs(n-1, w-wn[n])+vn[n]);
    }

