                        dp[i, j] = Math.Max(dp[i - 1, j], dp[i, j]);

                        var nW = j + pList[i].w;
                        if (nW <= W)
                        {
                            dp[i, nW] = dp[i - 1, nW] == -1 ?
                                Math.Max(dp[i - 1, j] + pList[i].v, dp[i, nW]) :
                                Math.Max(dp[i - 1, nW], dp[i - 1, j] + pList[i].v);
                        }
                    }

                    for (int j = 0; j < W + 1; j++)
                    {
                        //Console.Write(Convert.ToInt32(dp[i, j]) + " ");
                        maxCount = Math.Max(maxCount, dp[i, j]);
                    }

                    Console.WriteLine(maxCount);
                }
            }
        }

        private class Product
        {
            internal int w;
            internal int v;
        }
    }
