    class Program
    {
        static void Main()
        {
            var read = Console.ReadLine();
            string[] split = read.Split(' ');
            int N = Int32.Parse(split[0]);
            int W = Int32.Parse(split[1]);

            int[] w = new int[N];
            int[] v = new int[N];

            for (int c = 0; c < N; ++c)
            {

                read = Console.ReadLine();
                split = read.Split(' ');
                w[c] = Int32.Parse(split[0]);
                v[c] = Int32.Parse(split[1]);
            }


            Console.Write(knapsack(N, W, w, v));
            ;

        }

        static int knapsack(int N, int W_limit, int[] w, int[] v)
        {
            int[][] knapsack_inside = new int[N+1][];
            for (int c = 0; c < N+1; c++)
            {
                knapsack_inside[c] = new int[W_limit+1];
            }


            for (int i = 1; i < N+1; i++)
            {
                for (int wei = 1; wei < W_limit+1; wei++)
                {
                    if (wei - w[i - 1] >= 0)
                    {
                        knapsack_inside[i][wei] = Math.Max(knapsack_inside[i - 1][wei - w[i - 1]] + v[i - 1], knapsack_inside[i - 1][wei]);
                    }
                    else knapsack_inside[i][wei] = knapsack_inside[i - 1][wei];
                }


            }


            return knapsack_inside[N][W_limit];

        }


    }
}

