public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Alice" : "Brown"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var W = cr.Int;
        var structs = cr.Repeat(N).Select(cr => new Struct { w = cr.Int, v = cr.Int });
        var w0 = structs[0].w;
        var dp = NewArray(N + 1, 4 * N, long.MinValue);
        dp[0][0] = 0;
        for (int i = 0; i < structs.Length; i++)
        {
            var w = structs[i].w - w0;
            var v = structs[i].v;
            for (int j = dp.Length - 1; j > 0; j--)
                for (int k = w; k < dp[j].Length; k++)
                    UpdateMax(ref dp[j][k], dp[j - 1][k - w] + v);
        }

        long max = 0;
        for (int i = 1; i < dp.Length; i++)
            for (int j = 0; j < dp[i].Length; j++)
                if (i * w0 + j <= W)
                    UpdateMax(ref max, dp[i][j]);
        return max;
    }
