        {
            lis[i].Sort();
            int c = lis[i].Count;
            sumv[i] = new long[c + 1];
            for (int j = 0; j < c; j++)
                sumv[i][j + 1] = sumv[i][j] + lis[i][c - j - 1];
        }
        long ans = 0;
        for (int i = 0; i <= lis[0].Count; i++)
        {
            for (int j = 0; j <= lis[1].Count; j++)
            {
                for (int k = 0; k <= lis[2].Count; k++)
                {
                    for (int l = 0; l <= lis[3].Count && i * mi + j * (mi + 1) + k * (mi + 2) + l * (mi + 3) <= w; l++)
                    {
                        ans = Math.Max(ans, sumv[0][i] + sumv[1][j] + sumv[2][k] + sumv[3][l]);
