        var p = new bool[n + 1];
        for (int i = 2; i <= n; i++) p[i] = true;
        for (int i = 2; i * i <= n; i++) if (p[i]) for (int j = i * i; j <= n; j += i) p[j] = false;
        return p;
    }
    public static List<int> getprimes(int n) {
        var prs = new List<int>();
        var p = sieve(n);
        for (int i = 2; i <= n; i++) if (p[i]) prs.Add(i);
        return prs;
    }
    public static long[][] E(int n) {
        var ret = new long[n][];
        for (int i = 0; i < n; i++) { ret[i] = new long[n]; ret[i][i] = 1; }
        return ret;
    }
    public static double[][] dE(int n) {
        var ret = new double[n][];
        for (int i = 0; i < n; i++) { ret[i] = new double[n]; ret[i][i] = 1; }
        return ret;
    }
    public static long[][] pow(long[][] A, long n) {
        if (n == 0) return E(A.Length);
        var t = pow(A, n / 2);
        if ((n & 1) == 0) return mul(t, t);
        return mul(mul(t, t), A);
    }
    public static double[][] pow(double[][] A, long n) {
        if (n == 0) return dE(A.Length);
        var t = pow(A, n / 2);
        if ((n & 1) == 0) return mul(t, t);
        return mul(mul(t, t), A);
    }
    public static double dot(double[] x, double[] y) {
        int n = x.Length;
        double ret = 0;
        for (int i = 0; i < n; i++) ret += x[i] * y[i];
        return ret;
    }
    public static double _dot(double[] x, double[] y) {
        int n = x.Length;
        double ret = 0, r = 0;
        for (int i = 0; i < n; i++) {
            double s = ret + (x[i] * y[i] + r);
            r = (x[i] * y[i] + r) - (s - ret);
            ret = s;
        }
        return ret;
    }
    public static long dot(long[] x, long[] y) {
        int n = x.Length;
        long ret = 0;
        for (int i = 0; i < n; i++) ret = (ret + x[i] * y[i]) % Mod;
        return ret;
    }
    public static T[][] trans<T>(T[][] A) {
        int n = A[0].Length, m = A.Length;
        var ret = new T[n][];
        for (int i = 0; i < n; i++) { ret[i] = new T[m]; for (int j = 0; j < m; j++) ret[i][j] = A[j][i]; }
        return ret;
    }
    public static double[] mul(double[][] A, double[] x) {
        int n = A.Length;
        var ret = new double[n];
        for (int i = 0; i < n; i++) ret[i] = dot(x, A[i]);
        return ret;
    }
    public static long[] mul(long[][] A, long[] x) {
        int n = A.Length;
        var ret = new long[n];
        for (int i = 0; i < n; i++) ret[i] = dot(x, A[i]);
        return ret;
    }
    public static long[][] mul(long[][] A, long[][] B) {
        int n = A.Length;
        var Bt = trans(B);
        var ret = new long[n][];
        for (int i = 0; i < n; i++) ret[i] = mul(Bt, A[i]);
        return ret;
    }
    public static double[][] mul(double[][] A, double[][] B) {
        int n = A.Length;
        var Bt = trans(B);
        var ret = new double[n][];
        for (int i = 0; i < n; i++) ret[i] = mul(Bt, A[i]);
        return ret;
    }
    public static long[] add(long[] x, long[] y) {
        int n = x.Length;
        var ret = new long[n];
        for (int i = 0; i < n; i++) ret[i] = (x[i] + y[i]) % Mod;
        return ret;
    }
    public static long[][] add(long[][] A, long[][] B) {
        int n = A.Length;
        var ret = new long[n][];
        for (int i = 0; i < n; i++) ret[i] = add(A[i], B[i]);
        return ret;
    }
    public static long pow(long a, long b) {
        if (a >= Mod) return pow(a % Mod, b);
        if (a == 0) return 0;
        if (b == 0) return 1;
        var t = pow(a, b / 2);
        if ((b & 1) == 0) return t * t % Mod;
        return t * t % Mod * a % Mod;
    }
    public static long inv(long a) => pow(a, Mod - 2);
    public static long gcd(long a, long b) {
        while (b > 0) { var t = a % b; a = b; b = t; } return a;
    }
    // a x + b y = gcd(a, b)
    public static long extgcd(long a, long b, out long x, out long y) {
        long g = a; x = 1; y = 0;
        if (b > 0) { g = extgcd(b, a % b, out y, out x); y -= a / b * x; }
        return g;
    }
    public static long lcm(long a, long b) => a / gcd(a, b) * b;

    static long[] facts;
    public static long[] setfacts(int n) {
        facts = new long[n + 1];
        facts[0] = 1;
        for (int i = 0; i < n; i++) facts[i + 1] = facts[i] * (i + 1) % Mod;
        return facts;
    }
    public static long comb(int n, int r) {
        if (n < 0 || r < 0 || r > n) return 0;
        if (n - r < r) r = n - r;
        if (r == 0) return 1;
        if (r == 1) return n;
        if (facts != null && facts.Length > n) return facts[n] * inv(facts[r]) % Mod * inv(facts[n - r]) % Mod;
        int[] numer = new int[r], denom = new int[r];
        for (int k = 0; k < r; k++) { numer[k] = n - r + k + 1; denom[k] = k + 1; }
        for (int p = 2; p <= r; p++) {
            int piv = denom[p - 1];
            if (piv > 1) {
                int ofst = (n - r) % p;
                for (int k = p - 1; k < r; k += p) { numer[k - ofst] /= piv; denom[k] /= piv; }
            }
        }
        long ret = 1;
        for (int k = 0; k < r; k++) if (numer[k] > 1) ret = ret * numer[k] % Mod;
        return ret;
    }
    public static long[][] getcombs(int n) {
        var ret = new long[n + 1][];
        for (int i = 0; i <= n; i++) {
            ret[i] = new long[i + 1];
            ret[i][0] = ret[i][i] = 1;
            for (int j = 1; j < i; j++) ret[i][j] = (ret[i - 1][j - 1] + ret[i - 1][j]) % Mod;
        }
        return ret;
    }
    // nC0, nC2, ..., nCn
    public static long[] getcomb(int n) {
        var ret = new long[n + 1];
        ret[0] = 1;
        for (int i = 0; i < n; i++) ret[i + 1] = ret[i] * (n - i) % Mod * inv(i + 1) % Mod;
        return ret;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace AtCoder
{
	class Program
	{
		static void Main(string[] args)
		{
			var firstLine = Console.ReadLine().Split(' ').Select(value => long.Parse(value)).ToList();
			var n = firstLine[0];
			var w = firstLine[1];

			var baggages = new List<List<long>>();

			for(var i = 0; i < n; i++)
			{
				baggages.Add(Console.ReadLine().Split(' ').Select(value => long.Parse(value)).ToList());
			}

			var minWeight = baggages.Min(list => list[0]);
			baggages.ForEach(list => list[0] -= minWeight - 1);

			var dpValue = new long[n + 1, n * 4 + 1];
			var dpNumber = new long[n + 1, n * 4 + 1];
			var dpWeight = new long[n + 1, n * 4 + 1];

			for(var i = 1; i <= n; i++)
			{
				for(var j = 1; j <= n * 4; j++)
				{
					if(j >= baggages[i - 1][0] && w >= (minWeight - 1) * (dpNumber[i - 1, j - baggages[i - 1][0]] + 1) + dpWeight[i - 1, j - baggages[i - 1][0]] + baggages[i - 1][0])
					{
						if(dpValue[i - 1, j - baggages[i - 1][0]] + baggages[i - 1][1] > dpValue[i - 1, j])
						{
							dpValue[i, j] = dpValue[i - 1, j - baggages[i - 1][0]] + baggages[i - 1][1];
							dpNumber[i, j] = dpNumber[i - 1, j - baggages[i - 1][0]] + 1;
							dpWeight[i, j] = dpWeight[i - 1, j - baggages[i - 1][0]] + baggages[i - 1][0];
						}
						else
						{
							dpValue[i, j] = dpValue[i - 1, j];
							dpNumber[i, j] = dpNumber[i - 1, j];
							dpWeight[i, j] = dpWeight[i - 1, j];
						}
					}
					else
					{
						dpValue[i, j] = dpValue[i - 1, j];
						dpNumber[i, j] = dpNumber[i - 1, j];
						dpWeight[i, j] = dpWeight[i - 1, j];
					}
				}
			}

			long maxValue = 0;

			for(var i = 0; i < n * 4 + 1; i++)
			{
				maxValue = Math.Max(maxValue, dpValue[n, i]);
			}
			Console.WriteLine(maxValue);
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
public class Simple {
    public static void Main() {
        new Simple().Solve();
    }

    void Solve(){
        List<long>[] li = new List<long>[4];
        for (int i = 0; i < 4; ++i)
            li[i] = new List<long>();
        //input
        var NW = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
        var ini= Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
        var w1 = ini[0];
        li[0].Add(ini[1]);
        for (int i = 1; i < NW[0];++i){
            var inp = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
            li[inp[0] - w1].Add(inp[1]);
        }

        //sort
        foreach (var v in li)
            v.Sort((x, y) => x.CompareTo(y));
        //cal
        long ans = 0;
        for (int i = 0; i <= li[0].Count() && i * w1 <= NW[1]; ++i) {
            for (int j = 0; j <= li[1].Count(); ++j) {
                if ((i * w1 + j * (w1 + 1)) > NW[1]) break;
                for (int k = 0; k <= li[2].Count(); ++k) {
                    if ((i * w1 + j * (w1 + 1) + k * (w1 + 2)) > NW[1]) break;
                    for (int l = 0; l <= li[3].Count(); ++l) {
                        if ((i * w1 + j * (w1 + 1) + k * (w1 + 2) + l * (w1 + 3)) > NW[1]) break;
                        var sum = li[0].Take(i).Sum() + li[1].Take(j).Sum() +
                                           li[2].Take(k).Sum() + li[3].Take(l).Sum();
                        ans = Math.Max(ans, sum);
                    }
                }
            }
        }
        //res
        Console.WriteLine(ans);
    }
}

