                    v = 0
                });
                for (int i = 0; i < N; i++)
                {
                    var product = Console.ReadLine().Split(' ');
                    pList.Add(new Product()
                    {
                        w = Convert.ToInt32(product[0]),
                        v = Convert.ToInt32(product[1])
                    });
                }

                var dp = new int[N + 1, W + 1];
                for (int i = 0; i < N + 1; i++)
                {
                    for (int j = 0; j < W + 1; j++)
                    {
                        dp[i, j] = -1;
                    }
                }
                /////////////////////////////////////////////////////////////

                for (int i = 0; i <= N; i++)
                {
                    for (int j = 0; j <= W; j++)
                    {
                        if (i == 0 && j == 0)
                        {
                            dp[i, j] = 0;
                            break;
