            List<item>[] items = new List<item>[4];
            for (int i = 0; i < 4; ++i)
            {
                items[i] = new List<item>();
            }
            io.ReadSplit();
            item item0 = new item();
            item0.w = io.Int();
            item0.v = io.Int();
            items[0].Add(item0);
            int min_w = item0.w;
            for (int i = 1; i < N; ++i)
            {
                io.ReadSplit();
                item itemX = new item();
                itemX.w = io.Int();
                itemX.v = io.Int();
                items[itemX.w - min_w].Add(itemX);
            }

            for (int i = 0; i < 4; ++i)
            {
                items[i] = items[i].OrderByDescending(item => item.v).ToList();
            }
            int total_w = 0;
            int total_v = 0;
            io.WriteLine(Calc(N, W, items, total_w, total_v, 0, 0).ToString());
        }

        private static int Calc(int N, int W, List<item>[] items, int total_w, int total_v, int w, int i)
        {
            if (w > 3)
            {
                return total_v;
            }
            if (i >= items[w].Count)
            {
                return Math.Max(total_v, Calc(N, W, items, total_w, total_v, w + 1, 0));
            }
            if (total_w + items[w][i].w <= W)
            {
                int rv = Math.Max(total_v, Calc(N, W, items, total_w + items[w][i].w, total_v + items[w][i].v, w, i + 1));
                return Math.Max(rv, Calc(N, W, items, total_w, total_v, w + 1, 0));
            }
            else
            {
                return total_v;
            }
        }
