        static void Solve()
        {
            (long N, long W) = Slice2<long>();
            var cdt = Enumerable.Repeat(0, 4).Select(_ => new List<long>()).ToArray();

            var WV0 = Slice2<long>();
            cdt[0].Add(WV0.b);
            for (var i = 1; i < N; ++i)
            {
                (long w, long v) = Slice2<long>();
                cdt[w - WV0.a].Add(v);
            }
            for (var i = 0; i < 4; ++i)
            {
                cdt[i].Sort();
                cdt[i].Reverse();
                cdt[i].Insert(0, 0);
            }
            var ans = 0L;
            for (var c1 = 0; c1 < cdt[0].Count; ++c1)
                for (var c2 = 0; c2 < cdt[1].Count; ++c2)
                    for (var c3 = 0; c3 < cdt[2].Count; ++c3)
                        for (var c4 = 0; c4 < cdt[3].Count; ++c4)
                        { 
                            var b = WV0.a;
                            var w = b * c1 + (b + 1) * c2 + (b + 2) * c3 + (b + 3) * c4;
                            if (w <= W)
                            {
                                ans = Max(ans,
                                    cdt[0].Take(c1 + 1).Sum() +
                                    cdt[1].Take(c2 + 1).Sum() +
                                    cdt[2].Take(c3 + 1).Sum() +
                                    cdt[3].Take(c4 + 1).Sum());
                            }
                        }
            WriteLine(ans);
        }

