namespace ABC060D
{
    class Program
    {
        // Will be RE or MLE
        static void Main(string[] args)
        {
            string[] bufs = Console.ReadLine().Split(' ');
            int N = Int32.Parse(bufs[0]);
            int W = Int32.Parse(bufs[1]);

            int[] v = new int[N];
            int[] w = new int[N];

            int[,] table = new int[N, W + 1];

            for (int i = 0; i < N; i++)
            {
                bufs = Console.ReadLine().Split(' ');
                w[i] = Int32.Parse(bufs[0]);
                v[i] = Int32.Parse(bufs[1]);

                for (int j = 0; j <= W; j++)
                {
                    table[i, j] = 0;
                }
            }

            table[0, w[0]] = v[0];

            int lim = w[0] + 3;
            for (int i = 1; i < N; i++)
            {
                if (w[i] <= W)
                {
                    table[i, w[i]] = Math.Max(v[i], table[i - 1, w[i]]);
                }

                for (int j = Math.Min(lim, W); j >= w[0]; j--)
                {
                    if(table[i - 1, j] > 0)
                    {
                        table[i, j] = table[i - 1, j];

                        if (j + w[i] <= W)
                        {
                            table[i, j + w[i]] = Math.Max(table[i, j] + v[i], table[i - 1, j + w[i]]);
                        }
                    }
                }

                lim += w[0] + 3;
            }


            int res = 0;
            for (int i = 0; i < N; i++)
            {
                for (int j = w[0]; j <= W; j++)
                {
                    if (res < table[i, j]) res = table[i, j];
                }
            }

            Console.WriteLine(res);
        }
    }
}

