class Program{
	static void Main(){
		int[] s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		int a=0,b=0,ans=0;
		int[,,] dp=new int[s[0]+1,s[0]+1,s[0]*4+1];
		for(int i=1;i<=s[0];i++){
			int[] q=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
			if(i==1){a=q[0]-1;}
			q[0]-=a;
			b+=q[0];
			for(int j=1;j<=i;j++){
				for(int k=1;k<=b;k++){
					if(k>=q[0]&&j*a+k<=s[1]){dp[i,j,k]=Math.Max(dp[i-1,j-1,k-q[0]]+q[1],Math.Max(dp[i-1,j,k],dp[i,j-1,k]));}
					else{dp[i,j,k]=Math.Max(dp[i-1,j,k],dp[i,j-1,k]);}
				}
			}
		}
