    class Program
    {

        static void Main(string[] args)
        {
            var NW = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            var N = NW[0];
            var W = NW[1];
            var wei = new List<long>[4];
            var val = new List<long>[4];

            for (int i = 0; i < 4; i++)
            {
                wei[i] = new List<long>();
                val[i] = new List<long>();
            }
            //最初の情報を格納
            var WV1 = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            var wei1 = WV1[0];
            wei[0].Add(WV1[0]);
            val[0].Add(WV1[1]);
            for (int i = 1; i < N; i++)
            {
                var WV = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
                var weight = WV[0];
                var value  = WV[1];
                wei[weight - wei1].Add(weight);
                val[weight - wei1].Add(value);
            }

            for (int i = 0; i < 4; i++)
            {
                val[i] = val[i].OrderByDescending(x => x).ToList();
            }

            var sum = 0L;
            for (int i = 0; i <= N && i <= val[0].Count; i++)
            {
                var Cumval1 = 0L;
                for (int p = 0; p < i; p++)
                {
                    Cumval1 += val[0][p];
                }
                for (int j = 0; j <= N-i && j <= val[1].Count; j++)
                {
                    var Cumval2 = Cumval1;
                    for (int p = 0; p < j; p++)
                    {
                        Cumval2 += val[1][p];
                    }
                    for (int k = 0; k <= N - i-j && k <= val[2].Count; k++)
                    {
                        var Cumval3 = Cumval2;
                        for (int p = 0; p < k; p++)
                        {
                            Cumval3 += val[2][p];
                        }
                        for (int l = 0; l <= N - i - j -k && l <= val[3].Count; l++)
                        {
                            var Cumval4 = Cumval3;
                            for (int p = 0; p < l; p++)
                            {
                                Cumval4 += val[3][p];
                            }
                            var souju = (i + j + k + l) * wei1 + i * 0 + j * 1 + k * 2 + l * 3;
                            if (souju <= W)
                            {
                                sum = Max(sum, Cumval4);
                            }
                        }
                    }
                }
            }
            Console.WriteLine(sum);
        }
    }
}

