public class Hello
{
    public static void Main()
    {
        var d = new Dictionary<int, List<int>>();
        string[] line = Console.ReadLine().Trim().Split(' ');
        var n = int.Parse(line[0]);
        var W = int.Parse(line[1]);
        var minw = 1000000001;
        for (int i = 0; i < n; i++)
        {
            line = Console.ReadLine().Trim().Split(' ');
            var w = int.Parse(line[0]);
            minw = Math.Min(minw, w);
            var v = int.Parse(line[1]);
            if (d.ContainsKey(w)) d[w].Add(v);
            else
            {
                d[w] = new List<int>();
                d[w].Add(v);
            }
        }
        var amax = new int[4];
        amax[0] = d[minw].Count();
        for (int i = 1; i <= 3; i++)
            if (d.ContainsKey(minw + i)) amax[i] = d[minw + i].Count();
        foreach (var x in d) d[x.Key].Sort();
        var t = 0L; var ret = 0L;
        for (long i = 0; i <= amax[0]; i++)
            for (long j = 0; j <= amax[1]; j++)
                for (long k = 0; k <= amax[2]; k++)
                    for (long L = 0; L <= amax[3]; L++)
                    {
                        if (i * minw + j * (minw+1) + k *(minw + 2) + L * (minw + 3) <= W)
                            t = getW(d, i, minw) + getW(d, j, minw + 1) + getW(d, k, minw + 2) + getW(d, L, minw + 3);
                        ret = Math.Max(t, ret);
                    }
        Console.WriteLine(ret);
    }
    public static long getW(Dictionary<int, List<int>> d, long a, int k)
    {
        if (a == 0) return 0;
        var ret = 0L;
        var dL = d[k].Count();
        for (int i = 0; i < a; i++)
            ret += d[k][dL - 1 - i];
        return ret;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static int N, W;
    static int[] w;
    static int[] v;

    public static void Main(string[] args)
    {
        N = Input.NextInt();
        W = Input.NextInt();
        w = new int[N];
        v = new int[N];
        foreach (var i in Enumerable.Range(0, N))
        {
            var wv = Input.LineInt();
            w[i] = wv[0];
            v[i] = wv[1];
        }

        dp = new Dictionary<NumberAndWeight, int>(); 
        Console.WriteLine(F(new NumberAndWeight(N, W)));
    }

    class NumberAndWeight
    {
        public NumberAndWeight(int n, int w)
        {
            Number = n;
            Weight = w;
        }

        public int Number;
        public int Weight;

        // override object.Equals
        public override bool Equals(object obj)
        {
            if (obj == null || GetType() != obj.GetType())
            {
                return false;
            }

            var o = (NumberAndWeight)obj;
            return this.Number == o.Number && this.Weight == o.Weight;
        }

        public override int GetHashCode()
        {
            return Number << 8 + Weight;
        }
    }

    static Dictionary<NumberAndWeight, int> dp;

    static int F(NumberAndWeight nw)
    {
        if (dp.ContainsKey(nw))
            return dp[nw];

        int newValue;
        if (nw.Number == 0)
        {
            newValue = 0;
        }
        else
        {
            newValue = F(new NumberAndWeight(nw.Number - 1, nw.Weight));
            var newWeight = nw.Weight - w[nw.Number - 1];
            if (newWeight >= 0)
            {
                var b = F(new NumberAndWeight(nw.Number - 1, newWeight)) + v[nw.Number - 1];
                newValue = Math.Max(b, newValue);
            }
        }
        return dp[nw] = newValue;
    }
}

