            Use = (Use != -1) ? Use : Arr.Length; if (Use == 0) yield break; var s = new Stack<List<int>>();
            Arr.Length.REPR(i => s.Push(new List<int>() { Arr[i] }));
            while (s.Count > 0) {
                var cur = s.Pop();
                if (cur.Count == Use)
                    yield return cur.ToArray();
                else
                    Arr.Length.REPR(i => s.Push(new List<int>(cur) { Arr[i] }));
            }
