            4.REP(i => pair[i] = new List<long>());
            var w1 = io.Long;
            pair[0].Add(io.Long);
            FOR(1, N, i => pair[io.Long - w1].Add(io.Long));
            4.REP(i => pair[i] = pair[i].OrderByDescending(v => v).ToList());

            long ans = 0;

            for (int i = 0; i <= pair[0].Count() && i * w1 <= W; i++) {
                for (int j = 0; j <= pair[1].Count(); j++) {
                    if ((i * w1 + j * (w1 + 1)) > W) break;
                    for (int k = 0; k <= pair[2].Count(); k++) {
                        if ((i * w1 + j * (w1 + 1) + k * (w1 + 2)) > W) break;
                        for (int l = 0; l <= pair[3].Count(); l++) {
                            if ((i * w1 + j * (w1 + 1) + k * (w1 + 2) + l * (w1 + 3)) > W) break;
                            var sum = pair[0].Take(i).Sum() + pair[1].Take(j).Sum() +
                                           pair[2].Take(k).Sum() + pair[3].Take(l).Sum();
                            ans = Math.Max(ans, sum);
                        }
                    }
                }
            }

