namespace D
{
    public class Program
    {
        static void Main(string[] args)
        {
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            Solve();
            Console.Out.Flush();
        }

        public static void Solve()
        {
            var NW = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
            var (N, W) = (NW[0], NW[1]);
            var w = new int[N];
            var v = new int[N];
            for (var i = 0; i < N; i++)
            {
                var wv = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
                w[i] = wv[0];
                v[i] = wv[1];
            }

            var dp = (new long[2][]).Select(x => x = new long[W + 1]).ToArray();
            var t = 1;
            for (var i = 0; i < N; i++)
            {
                t ^= 1;
                for (var j = 0; j <= W; j++)
                {
                    if (j < w[i])
                    {
                        dp[t ^ 1][j] = dp[t][j];
                    }
                    else
                    {
                        dp[t ^ 1][j] = Math.Max(dp[t][j], dp[t][Math.Max(0, j - w[i])] + v[i]);
                    }
                }
            }
            var answer = dp[t ^ 1][W];
            Console.WriteLine(answer);
        }
    }
}

