namespace AtCoder
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var NW = Sarray();
            var N = NW[0];
            var W = NW[1];
            var wi = new long[N];
            var vi = new long[N];
            for (var i = 0; i < N; ++i)
            {
                var wv = Sarray();
                wi[i] = wv[0];
                vi[i] = wv[1];
            }
            var GETA = wi[0] - 1;
            for (var i = 0; i < N; ++i)
                wi[i] -= GETA;
            var lst = 4 * N;
            var dp = new long[N + 1, N + 1, lst + 1];
            for (var i = 1; i <= N; ++i)
            {
                for (var n = 1; n <= N; ++n)
                {
                    for (var j = 0; j <= lst; ++j)
                    {
                        if (wi[i - 1] <= j)
                        {
                            var t = dp[i - 1, n - 1, j - wi[i - 1]];
                            if (n == 1 || t != 0)
                                dp[i, n, j] = t + vi[i - 1];
                        }
                        dp[i, n, j] = Max(dp[i, n, j], dp[i - 1, n, j]);
                    }
                }
            }
            var ans = 0L;
            for (var n = 1; n <= N; ++n)
            {
                var ho = GETA * n;
                for (var j = 0; j <= lst; ++j)
                {
                    if (ho + j <= W)
                        ans = Max(ans, dp[N, n, j]);
                }
            }
            WriteLine(ans);
        }
    }
}

