            int[] w = new int[n];
            int[] v = new int[n];
            for (int i = 0; i < n; i++)
            {
                string[] a = Console.ReadLine().Split();
                w[i] = int.Parse(a[0]);
                v[i] = int.Parse(a[1]);
            }
            for (int i = n - 1; i >= 0; i--)
            {
                for (int j = 0; j <= W; j++)
                {
                    if (j < w[i])
                    {
                        dp[i, j] = dp[i + 1, j];
                    }
                    else
                    {
                        dp[i, j] = Math.Max(dp[i + 1, j], dp[i + 1, j - w[i]] + v[i]);
                    }
                }
            }
            Console.WriteLine(dp[0, W]);
        }
    }
}

