    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Alice" : "Brown"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var W = cr.Int;
        var structs = cr.Repeat(N).Select(cr => new Struct { w = cr.Int, v = cr.Int });
        var w0 = structs[0].w;
        var dp = NewArray(101 * 4, int.MinValue);
        dp[0] = 0;
        for (int i = 0; i < structs.Length; i++)
        {
            var w = structs[i].w - w0 + 100;
            var v = structs[i].v;
            for (int j = dp.Length - w - 1; j >= 0; j--)
                UpdateMax(ref dp[j + w], dp[j] + v);
        }
        return dp.Select((s, i) => new { s, i }).Where(t => w0 * (t.i / 100) + t.i % 100 <= W).Max(t => t.s);
    }
