using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace D
{
    public class Program
    {
        static void Main(string[] args)
        {
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            Solve();
            Console.Out.Flush();
        }

        public static void Solve()
        {
            var NW = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
            var (N, W) = (NW[0], NW[1]);
            var w = new int[N];
            var v = new int[N];
            for (var i = 0; i < N; i++)
            {
                var wv = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
                w[i] = wv[0];
                v[i] = wv[1];
            }

            var maxV = v.Max();
            var Infinity = (long)1e18;
            var dp = (new long[N + 1][]).Select(x => x = Enumerable.Repeat(Infinity, N * maxV + 1).ToArray()).ToArray();
            dp[0][0] = 0;
            for (var i = 0; i < N; i++)
            {
                for (var j = 0; j <= N * maxV; j++)
                {
                    if (j < v[i])
                    {
                        dp[i + 1][j] = dp[i][j];
                    }
                    else
                    {
                        dp[i + 1][j] = Math.Min(dp[i][j], dp[i][j - v[i]] + w[i]);
                    }
                }
            }
            var answer = 0L;
            for (var i = 0; i <= N * maxV; i++)
            {
                if (dp[N][i] <= W) answer = i;
            }

            Console.WriteLine(answer);
        }
    }
}

