            val[0].Add(input[1]);
            for (int i = 1; i < N; i++)
            {
                input = ReadArrayInt();
                val[input[0] - wS].Add(input[1]);
            }
            for (int i = 0; i < 4; i++) val[i] = val[i].OrderByDescending(x => x).ToList();
            var ans = 0L;
            for (int i = 0; i <= val[0].Count; i++)
            {               
                long iSum = i != 0 ? val[0].Take(i).Sum() : 0;                
                for (int j = 0; j <= val[1].Count; j++)
                {
                    long jSum = j != 0 ? val[1].Take(j).Sum() : 0;
                    for (int k = 0; k <= val[2].Count; k++)
                    {
                        long kSum = k != 0 ? val[2].Take(k).Sum() : 0;
                        for (int l = 0; l <= val[3].Count; l++)
                        {
                            var rem = W - wS * i - (wS + 1) * j - (wS + 2) * k - (wS + 3) * l;
                            if (rem < 0) continue;
                            long lSum = l != 0 ? val[3].Take(l).Sum() : 0;
                            var sum = iSum + jSum + kSum + lSum;
                            if (sum > ans) ans = sum;
                        }
                    }
                }
            }

            Console.WriteLine(ans);
            Console.ReadLine();
        }

        static string Read() { return Console.ReadLine(); }
        static int ReadInt() { return int.Parse(Read()); }
        static long ReadLong() { return long.Parse(Read()); }
