function sort(xs, n, _, i, j, t) {
    for (i = 0; i < n; ++i) {
        for (j = 1; j < n; ++j) {
            if (xs[j] < xs[j+1]) {
                t=xs[j]; xs[j]=xs[j+1]; xs[j+1] = t;
            }
        }
    }
}

function accumulate(xs, n, ac, _, i) {
    ac[0] = 0;
    ac[1] = xs[1];
    for (i=2; i<=n; ++i) {
        ac[i] = ac[i-1] + xs[i];
    }
}

