function recursive(num,weight){
    if(dp[num][weight] >= 0){
        return dp[num][weight];
    }

    var result = 0;

    if (num === maxnum){
        result = 0;
    } else if (weight < weights[num]){
        result = recursive(num+1,weight);
    } else {
        result = Math.max(recursive(num + 1, weight), recursive(num + 1, weight - weights[num]) + values[num]);
    }

    return dp[num][weight] = result;
}

    var ans = recursive(0,limitweight,maxnum,weights,values);

