		if i == 0 {
			fmt.Scan(&firstWeight, &(items[i].v))
			firstWeight = firstWeight - 1
			items[i].w = 1
			continue
		}
		fmt.Scan(&(items[i].w), &(items[i].v))
		items[i].w = items[i].w - firstWeight
	}

	weightSumMax := 3 * n

	// dp[i][j]はi番目までのitemを最適にpickした際、各weightにおけるvalueの最大値
	dp := make([][]ValueWeight, n)
	for i := 0; i < n; i++ {
		dp[i] = make([]ValueWeight, weightSumMax+1)
		for j := 0; j <= weightSumMax; j++ {
			dp[i][j].valueSum = -1
		}
	}

	dp[0][0] = ValueWeight{0, 0}
	dp[0][1] = ValueWeight{items[0].v, 1}
	//fmt.Println(dp[0])
	for i := 1; i < n; i++ {
		for j := 0; j <= weightSumMax; j++ {
			if j-items[i].w < 0 {
				dp[i][j].valueSum = dp[i-1][j].valueSum
				dp[i][j].itemCount = dp[i-1][j].itemCount
				continue
			}

			v1 := dp[i-1][j].valueSum
			i1 := dp[i-1][j].itemCount
			v2 := dp[i-1][j-items[i].w].valueSum
			i2 := dp[i-1][j-items[i].w].itemCount

			if v1 == -1 && v2 == -1 {
				dp[i][j].valueSum = v1
				dp[i][j].itemCount = i1
			} else if v1 == -1 {
				v2 = v2 + items[i].v
				dp[i][j].valueSum = v2
				dp[i][j].itemCount = i2 + 1
			} else if v2 == -1 {
				dp[i][j].valueSum = v1
				dp[i][j].itemCount = i1
			} else {
				v2 = v2 + items[i].v
				if v1 > v2 {
					dp[i][j].valueSum = v1
					dp[i][j].itemCount = i1
				} else {
					dp[i][j].valueSum = v2
					dp[i][j].itemCount = i2 + 1
				}
			}
		}

		//fmt.Println(dp[i])
	}

	max := 0
	for j := weightSumMax; j >= 0; j-- {
		item := dp[n-1][j]
		value := item.valueSum
		weight := j + (firstWeight)*item.itemCount

		//fmt.Printf("%v: value=%v weight=%v\n", j, value, weight)
		if value == -1 || weight > w {
			continue
		}
		if value > max {
			max = value
		}
	}
	fmt.Println(max)
}

