func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	n, w := sc.nextInt(), sc.nextInt()
	W := make([]int, n)
	V := make([]int, n)
	for i := 0; i < n; i++ {
		W[i] = sc.nextInt()
		V[i] = sc.nextInt()
	}
	base := W[0]
	var nums [4][]int
	for i := 0; i < n; i++ {
		idx := W[i] - base
		nums[idx] = append(nums[idx], V[i])
	}
	for i := 0; i < 4; i++ {
		sort.Sort(sort.Reverse(sort.IntSlice(nums[i])))
	}
	ans := 0
	for i := 0; i <= len(nums[0]); i++ {
		for j := 0; j <= len(nums[1]); j++ {
			for k := 0; k <= len(nums[2]); k++ {
				for l := 0; l <= len(nums[3]); l++ {
					if base*(i+j+k+l)+j*1+k*2+l*3 > w {
						continue
					}
					total := 0
					for _, num := range nums[0][:i] {
						total += num
					}
					for _, num := range nums[1][:j] {
						total += num
					}
					for _, num := range nums[2][:k] {
						total += num
					}
					for _, num := range nums[3][:l] {
						total += num
					}
					ans = max(ans, total)
				}
			}
		}
	}

	fmt.Fprintln(wtr, ans)
}

