func main() {
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, initialBufSize), maxBufSize)
	defer wt.Flush()

	N, W := nextInt(), nextInt()
	w, v := make([]int, N), make([]int, N)

	// dp[i][j][k]: i番目まで見て，j個のモノを使って重さk以下を満たすときの価値の最大値
	dp := make([][][500]int, N+1)
	for i := range dp {
		dp[i] = make([][500]int, N+1)
	}

	var w1 int
	for i := 1; i <= N; i++ {
		w[i-1], v[i-1] = nextInt(), nextInt()
