			w1 = w[0]
		}
		// 0 <= w[i-1] <= 3
		w[i-1] -= w1
		for j := 1; j <= N; j++ {
			for k := 0; k <= 3*(N-1); k++ {
				if k >= w[i-1] {
					dp[i][j][k] = max(dp[i-1][j][k], dp[i-1][j-1][k-w[i-1]]+v[i-1])
				} else {
					dp[i][j][k] = dp[i-1][j][k]
				}
			}
		}
	}

	ans := 0
	for j := 1; j <= N; j++ {
		if j*w1 <= W && W <= w1+(j-1)*(w1+3) {
			ans = max(ans, dp[N][j][W-j*w1])
		}
	}

	puts(ans)
}

