sub add {
    my($old, $w, $v, $wmax, $new) = @_;
    my $current_maxv = -1;
    my @add;
 mainloop:
    for (;;) {
        if ($#{$old} < 0) {
            ($#add  < 0) and last mainloop;
            goto putaddp;
        }
        push(@add, [$old->[0]->[0]+$w, $old->[0]->[1]+$v]);
        if ($old->[0]->[0] < $add[0]->[0]) {
            goto putoldp;
        } elsif ($old->[0]->[0] > $add[0]->[0]) {
            goto putaddp;
        } elsif ($old->[0]->[1] > $add[0]->[1]) {
            shift(@add);
            goto putoldp;
        } else {
            shift(@{$old});
            goto putaddp;
        }
    putoldp:
        if ($current_maxv < $old->[0]->[1]) {
            $current_maxv = $old->[0]->[1];
            push(@{$new}, shift(@{$old}));
        } else {
            shift(@{$old});
        }
        next mainloop;
    putaddp:
        ($wmax < $add[0]->[0])  and last mainloop;
        if ($current_maxv < $add[0]->[1]) {
            $current_maxv =  $add[0]->[1];
            push(@{$new}, shift(@add));
        } else {
            shift(@add);
        }
        next mainloop;
    }
    $current_maxv;
}

