def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, W, WV):
    items = defaultdict(list)
    for w, v in WV:
        items[w].append(v)

    for w in items:
        items[w].sort(reverse=True)

    for i in range(3-len(items)):
        items[-i] = []
    ws = list(items.keys())

    @lru_cache(maxsize=None)
    def f(rw, i, j, k):
        if rw <= 0:
            return 0
        ret = 0
        if i < len(items[ws[0]]):
            ret = max(ret, f(rw - ws[0], i+1, j, k) + items[ws[0]][i])
        if j < len(items[ws[1]]):
            ret = max(ret, f(rw - ws[1], i, j+1, k) + items[ws[1]][j])
        if k < len(items[ws[2]]):
            ret = max(ret, f(rw - ws[2], i, j, k+1) + items[ws[2]][k])

        return ret

