import sys

def max_value(items, space):
    if len(items) == 1:
        if space >= items[0][0]:
            return items[0][1]
        else:
            return 0

    selected = 0
    not_selected = 0
    if space >= items[0][0]:
        selected = items[0][1] + max_value(items[1:], space - items[0][0])
        not_selected = max_value(items[1:], space)

    return max(selected, not_selected)

def main(argv):
    line = sys.stdin.readline()
    while line:
        n, w = map(lambda x: int(x), line.split(" ", 2))

        items = []
        for i in range(n):
            weight, value = map(lambda x: int(x), raw_input().split(" ", 2))
            items.append((weight, value))

        items = sorted(items, key=lambda x: x[0])
        print(max_value(items, w))

        line = sys.stdin.readline()

if __name__ == "__main__":
    main(sys.argv)

