    for i in range(M):
        if i*w[0] > W:
            break
        if len(V[0]) <= i:
            break
        for j in range(M-i):
            if i*w[0] + j*(w[0]+1) > W:
                break
            if len(V[1]) <= j:
                break
            for k in range(M-i-j):
                if i*w[0] + j*(w[0]+1) + k*(w[0]+2) > W:
                    break
                if len(V[2]) <= k:
                    break
                for l in range(M-i-j-k):
                    if i*w[0] + j*(w[0]+1) + k*(w[0]+2) + l*(w[0]+3) > W:
                        break
                    if len(V[3]) <= l:
                        break
                    tot = V[0][i]+V[1][j]+V[2][k]+V[3][l]
                    m = max(m, tot)
    print(m)
    return


