    dp = [[-1] * (max_w + 1)  for _ in range(N + 1)]
    dp[0][0] = 0
    for i in range(N):
        for j in range(N, -1, -1):
            for k in range(max_w, -1, -1):
                if dp[j][k] >= 0:
                    dp[j + 1][k + w[i] - base] = max(dp[j + 1][k + w[i] - base], dp[j][k] + v[i])
    ret = 0
    for j in range(N + 1):
        for k in range(max_w + 1):
            if base * j + k <= W:
                ret = max(ret, dp[j][k])
