import sys

def max_value(items, space):
    if len(items) == 1:
        if space >= items[0][0]:
            return items[0][1]
        else:
            return 0

    selected = 0
    if space >= items[0][0]:
        selected = items[0][1] + max_value(items[1:], space - items[0][0])
    not_selected = max_value(items[1:], space)

    return max(selected, not_selected)

def main(argv):
    line = sys.stdin.readline()
    while line:
        n, w = map(lambda x: int(x), line.split(" ", 2))

