def search_with_memo(i, rest):
    if memo[i][rest] != None:
        return memo[i][rest]

    if i == N:
        return 0
    elif rest < items[i].w:
        through = search_with_memo(i + 1, rest)
        memo[i+1][rest] = through
        return through
    else:
        selected = search_with_memo(i+1, rest - items[i].w) + items[i].v
        memo[i+1][rest - items[i].w] = selected
        through = search_with_memo(i+1, rest)
        memo[i+1][rest] = through
        return max(selected, through)


def all_search(i, rest):
    if i == N:
        return 0
    elif rest < items[i].w:
        return all_search(i+1, rest)
    else:
        selected = all_search(i+1, rest - items[i].w) + items[i].v
        through = all_search(i+1, rest)
        return max(selected, through)


