def solveDP(N, W, value, weight):
    dp = np.zeros((N+1, W+1))

    for i in range(N):
        for w in range(W+1):
            if w >= weight[i]:
                dp[i + 1, w] = max(dp[i, w - weight[i]] + value[i], dp[i, w])
            else:
                dp[i + 1, w] = dp[i, w]

    return dp[N , W ]

