def KnapsackDP(N,WMax,WVList):
    DP = [[0]*(WMax+1) for T in range(N+1)]

    for I in range(0,N):
        for K in range(0,WMax+1):
            if K<WVList[I][0]:
                DP[I+1][K] = DP[I][K]
            else:
                if DP[I][K]>DP[I][K-WVList[I][0]]+WVList[I][1]:
                    DP[I+1][K] = DP[I][K]
                else:
                    DP[I+1][K] = DP[I][K-WVList[I][0]]+WVList[I][1]
    return DP[N][WMax]

