# i番目以降の品物から重さの和がj以下なるように選んだときの、
# 取りうる価値の総和の最大値を返す関数
@lru_cache(maxsize=1000)
def rec(i, j):
    if i == N:
        return 0
    # 残りの容量が足りず品物iを入れられないので、入れないパターンだけ処理
    # i + 1以降の品物のみを使ったときの最大値をそのままこの場合の最大値にする
    elif j < ws[i]:
        return rec(i+1, j)
    # 品物iを入れるか入れないか選べるので、両方試して価値の和が大きい方を選ぶ
    else:
        return max(rec(i+1, j), rec(i+1, j-ws[i])+vs[i])

