def simple_knapsack(N: int, W: int, items: list) -> int:
    # dp[n][w] は n~N 番目の品物を利用して重さが w 以下となるときの
    # 最大価値
    dp = [[0] * (W+1) for _ in range(N+1)]

    for i, (iw, iv) in enumerate(items):
        for w in range(W+1):
            if w < iw:
                dp[N-i-1][w] = dp[N-i][w]
            else:
                dp[N-i-1][w] = max(dp[N-i][w], dp[N-i][w-iw]+iv)
    return dp[0][W]


