fn solve() {
    let (n, wl) = get!(usize, usize);
    let wv = get!(usize, usize; n);

    let sumw = wv.iter().map(|&(w,_v)| w).sum::<usize>();
    let sumv = wv.iter().map(|&(_w,v)| v).sum::<usize>();
    if wl >= sumw {
        println!("{}", sumv);
        return;
    }
    if wl < wv[0].0 {
        println!("0");
        return;
    }
    let mut dp = vec![vec![0; wl+1]; n+1];

    for i in 0..n {
        for w in wv[0].0..(wl+1) {
            dp[i+1][w] = if w >= wv[i].0 {
                max!(dp[i][w-wv[i].0]+wv[i].1, dp[i][w])
            } else {
                dp[i][w]
            };
        }
    }
    println!("{}", dp[n].iter().max().unwrap());
}

