#[allow(dead_code)]
fn calc(data: Vec<Vec<u64>>, w: usize) -> i64 {
    let mut memo: Vec<Vec<i64>> = vec![vec![-1; data.len()]; w + 1];

    let n = data.len() - 1;

    for i in 0..n + 1 {
        memo[0][i] = 0;
    }

    for i in 0..w + 1 {
        memo[i][n] = if i as u64 >= data[n][0] {
            data[n][1] as i64
        } else {
            0
        };
    }

    fn dp(data: &Vec<Vec<u64>>, memo: &mut Vec<Vec<i64>>, n: usize, w: usize) -> i64 {
        if memo[w][n] != -1 {
            return memo[w][n];
        }

        let off = dp(data, memo, n + 1, w);

        let res = if (w as u64) < data[n][0] {
            off
        } else {
            std::cmp::max(dp(data, memo, n + 1, w - data[n][0] as usize) + data[n][1] as i64,
                          off)
        };

        memo[w][n] = res;
        res
    }

    dp(&data, &mut memo, 0, w)
}

