    let mut V = vec![vec![0;0]; 4];
    let mut w0 = 0;
    for i in 0..N{
        let (w,v) = WV[i];
        if i==0{
            V[0].push(v);
            w0 = w;
        }else{
            V[(w-w0) as usize].push(v);
        }
    }
