    let mut S = vec![vec![0;1]; 4];
    for i in 0..4{
        let mut tmp = 0;
        for v in V[i].iter(){
            tmp += *v;
            S[i].push(tmp);
        }
    }
    // 全探索
    let mut ans = 0;
    for i0 in 0..S[0].len(){
        for i1 in 0..S[1].len(){
            for i2 in 0..S[2].len(){
                for i3 in 0..S[3].len(){
                    if w0*i0 as u64 +(w0+1)*i1 as u64 +(w0+2)*i2 as u64 +(w0+3)*i3 as u64 <= W{
                        ans = max(ans, S[0][i0]+S[1][i1]+S[2][i2]+S[3][i3]);
                    }
                }
            }
        }
    }
    println!("{}",ans);
}

