    }

    let mut bagage_0 = Vec::new();
    let mut bagage_1 = Vec::new();
    let mut bagage_2 = Vec::new();
    let mut bagage_3 = Vec::new();

    let base_weight = bagage[0].0;

    for &(w, v) in &bagage {
        if w == base_weight {
           bagage_0.push((w, v));
        } else if w == base_weight + 1 {
           bagage_1.push((w, v));
        } else if w == base_weight + 2 {
            bagage_2.push((w, v));
        } else {
            bagage_3.push((w, v));
        }
    }

    bagage_0.sort_by(|a, b| b.1.cmp(&a.1));
    bagage_1.sort_by(|a, b| b.1.cmp(&a.1));
    bagage_2.sort_by(|a, b| b.1.cmp(&a.1));
    bagage_3.sort_by(|a, b| b.1.cmp(&a.1));

    bagage_0.insert(0, (0, 0));
    bagage_1.insert(0, (0, 0));
    bagage_2.insert(0, (0, 0));
