    for &(w_0, v_0) in &bagage_0 {
        for &(w_1, v_1) in &bagage_1 {
            for &(w_2, v_2) in &bagage_2 {
                for &(w_3, v_3) in &bagage_3 {
                    if weight + w_0 + w_1 + w_2 + w_3 <= W {
                       weight += w_0 + w_1 + w_2 + w_3;
                       ans += v_0 + v_1 + v_2 + v_3;
                    }
                }
            }
        }
    }

    println!("{}", ans);
