use nyan::*;

fn main() {
    let stdin = std::io::stdin();
    let mut sc = Scanner::new(stdin.lock());

    let n: usize = sc.read();
    let w: u64 = sc.read();
    let p: Vec<_> = (0..n)
        .map(|_| {
            let w: u64 = sc.read();
            let v: u64 = sc.read();
            (w, v)
        })
        .collect();

    // dp[i][j] = j までの物で w を超えないよう i 個揃えたときの価値の最大
    let mut dp = vec![vec![(0, 0); n + 1]; n + 1];
    for i in 1..n + 1 {
        for j in i..n + 1 {
            dp[i][j] = (i - 1..j)
                .map(|x| {
                    let (ww, vv) = dp[i - 1][x];
                    let (wj, vj) = p[j - 1];
                    (ww + wj, vv + vj)
                })
                .chain(std::iter::once(dp[i][j - 1]))
                .filter(|v| v.0 <= w)
                .max_by_key(|v| v.1)
                .unwrap();
        }

        if dp[i][n].1 == 0 {
            break;
        }
    }

    // for i in 0..n + 1 {
    //     println!("{:?}", dp[i]);
    // }

    println!("{}", (0..n + 1).map(|i| dp[i][n].1).max().unwrap());
}

