use std::collections::{BinaryHeap, HashMap, HashSet, VecDeque};

fn main() {
    input! {
        n: usize,
        w: usize,
        wv: [(usize, usize); n],
    }
    let mut wmap = vec![vec![]; 4];
    let w1 = wv[0].0;

    for i in 0..wv.len() {
        let wvi = wv[i];
        let d = wvi.0 - w1;
        wmap[d].push(wvi.1);
    }

    for i in 0..wmap.len() {
        wmap[i].sort();
        wmap[i].reverse();
    }

    for i in 0..wmap.len() {
        let mut tmp = 0;
        for j in 0..wmap[i].len() {
            tmp += wmap[i][j];
            wmap[i][j] = tmp;
        }
    }
    let mut ans = 0;

    for a in 0..=n {
        for b in 0..=n - a {
            for c in 0..=n - b - a {
                for d in 0..=n - a - b - c {
                    if a > wmap[0].len()
                        || b > wmap[1].len()
                        || c > wmap[2].len()
                        || d > wmap[3].len()
                    {
                        continue;
                    }
                    // println!("a:{}, b:{}, c:{}, d:{}", a, b, c, d);
                    if a * w1 + b * (w1 + 1) + c * (w1 + 2) + d * (w1 + 3) > w {
                        continue;
                    }
                    let abcd = vec![a, b, c, d];
                    let mut s = 0;
                    for i in 0..4 {
                        if abcd[i] != 0 {
                            s += wmap[i][abcd[i] - 1];
                        }
                    }
                    ans = max(ans, s);
                }
            }
        }
    }

    // println!("wmap:{:?}", wmap);
    println!("{}", ans);
}

