fn dfs(m: usize, weight: i64, value: i64, n: usize, ww: i64, wv: &Vec<(i64, i64)>) -> i64 {
    if m == n {
        if weight <= ww {
            value
        } else {
            0
        }
    } else {
        let mut ans = 0;
        ans = std::cmp::max(ans, dfs(m + 1, weight, value, n, ww, wv));
        let &(w, v) = &wv[m];
        ans = std::cmp::max(ans, dfs(m + 1, weight + w, value + v, n, ww, wv));
        ans
    }
}

