fn main(){
    let line = read_as_vec::<usize>();
    let (n, capacity) = (line[0], line[1]);
    let mut objects: Vec<Vec<u64>> = vec![vec![];4];

    let line = read_as_vec::<usize>();
    let (w, v) = (line[0], line[1] as u64);

    let mut bias = w;
    objects[0].push(v);

    for i in 1..n{
        let line = read_as_vec::<usize>();
        let (w, v) = (line[0], line[1] as u64);

        objects[w-bias].push(v);
    }

    for i in 0..4{
        objects[i].sort();
        objects[i].reverse();
    }

    let mut acc_obj: Vec<Vec<u64>> = vec![vec![];4];

    for i in 0..4{
        acc_obj[i] = vec![0;objects[i].len()+1];
    }

    for i in 0..4{
        let mut acc = 0;
        for j in 0..objects[i].len(){
            acc += objects[i][j];
            acc_obj[i][j+1] = acc;
        }
    }

    //println!("{:?}", acc_obj);
    let mut ans = 0;
    for n0 in 0..acc_obj[0].len(){
        if n0 * bias > capacity{
            continue;
        }
        for n1 in 0..acc_obj[1].len(){
            if n0* bias + n1 * (bias+1)> capacity{
                continue;
            }
            for n2 in 0..acc_obj[2].len(){
                if n0* bias + n1 * (bias+1) + n2*(bias+2) > capacity{
                    continue;
                }

                let n3 = (capacity - n0* bias - n1 * (bias+1) - n2*(bias+2))/(bias+3);
                //println!("{}, {}, {}, {}", n0, n1, n2, n3);
                if n3 >= acc_obj[3].len(){
                    ans = cmp::max(ans, acc_obj[0][n0] + acc_obj[1][n1] + acc_obj[2][n2]);
                }else{
                    ans = cmp::max(ans, acc_obj[0][n0] + acc_obj[1][n1] + acc_obj[2][n2] + acc_obj[3][n3]);
                }
            }
        }
    }

    println!("{}", ans);
}

