fn vec_range_sum(v: &Vec<usize>, n: usize) -> usize {
    let to;
    let mut sum = 0;
    if n > v.len() {
        to = v.len();
    } else {
        to = n
    }
    for i in 0..to {
        sum += v[i];
    }
    sum
}

fn main() {
    let (n, w): (usize, usize);
    input!(n, w);
    let mut ans = 0;
    let mut vc = vec![Vec::new(); 4];
    let mut offset = 0;
    for _ in 0..n {
        let (w, v): (usize, usize);
        input!(w, v);
        if offset == 0 {
            offset = w;
        }
        vc[w - offset].push(v);
    }

    for z in &mut vc {
        z.sort();
        z.reverse();
    }

    for i in 0..w + 1 {
        if i * offset > w {
            break;
        }
        for j in 0..w + 1 {
            if i * offset + j * (offset + 1) > w {
                break;
            }
            for k in 0..w + 1 {
                if i * offset + j * (offset + 1) + k * (offset + 2) > w {
                    break;
                }
                for l in 0..w + 1 {
                    if i * offset + j * (offset + 1) + k * (offset + 2) + l * (offset + 3) > w {
                        break;
                    }
                    let mut ans_buf = 0;
                    ans_buf += vec_range_sum(&vc[0], i);
                    ans_buf += vec_range_sum(&vc[1], j);
                    ans_buf += vec_range_sum(&vc[2], k);
                    ans_buf += vec_range_sum(&vc[3], l);
                    ans = cmp::max(ans_buf, ans);
                }
            }
        }
    }
    p(ans);
}

