                    if w_0 + w_1 + w_2 + w_3 <= W {
                       ans = max(ans, v_0+v_1+v_2+v_3);
                    }
                }
            }
        }
    }

    println!("{}", ans);
}

fn sum_by_index(v: &Vec<(usize, usize)>, start: usize, end: usize) -> (usize, usize) {
    let mut res = (0, 0);
    for i in start..end {
        res = (res.0 + v[i].0, res.1 + v[i].1);
    }

    res
}

