fn main() {
    let (n, w) = scan!(usize, i64);
    let vs = scan!(i64, i64; n);
    let weight = vs[0].0 - 1;
    let mut dp: Vec<Vec<(i64, i64)>> = (0..n + 1).map(|_| vec![(0, 0); n * 3 + 1]).collect();

    dp[0][0] = (0, 0);
    for (i, &v) in vs.iter().enumerate() {
        for j in 0..dp[i].len() {
            let k = j as i64 - (v.0 - weight);
            dp[i + 1][j] = if k >= 0 {
                if dp[i][j].1 * weight + j as i64 <= w {
                    cmp::max(
                        dp[i][j],
                        (dp[i][k as usize].0 + v.1, dp[i][k as usize].1 + 1),
                    )
                } else {
                    dp[i][j]
                }
            } else {
                dp[i][j]
            }
        }
    }

    if let Some(v) = dp[n]
        .iter()
        .enumerate()
        .filter(|&(i, &(_, m))| (i as i64 + m * weight) <= w)
        .map(|(_, &(v, _))| v)
        .max()
    {
        println!("{}", v)
    } else {
        println!("0")
    }
}

