fn solve() {
    let (n, wl) = get!(usize, usize);
    let mut wv = get!(usize, usize; n);

    let st = wv[0].0;
    wv.sort_by(|&(w1,v1), &(w2,v2)| v2.cmp(&v1));

    let sumw = wv.iter().map(|&(w,_v)| w).sum::<usize>();
    let sumv = wv.iter().map(|&(_w,v)| v).sum::<usize>();
    if wl >= sumw {
        println!("{}", sumv);
        return;
    }
    for i in 0..n {
        wv[i].0 -= st;
    }

    let mut mx = 0;
    for i in 0..(n+1) {
        if (st+3)*i <= wl {
            mx = max!(mx, wv.iter().take(i).map(|&(w,v)| v).sum());
            continue;
        }
        if st*i > wl {
            continue;
        }
        let wlt = wl-st*i;

        let mut dp =  vec![vec![vec![0; wlt+1]; i+1]; n+1];
        for j in 0..n {
            for k in 0..i {
                for w in 0..(wlt+1) {
                    dp[j+1][k+1][w] = if w >= wv[j].0 && i > 0 {
                        max!(dp[j][k][w-wv[j].0]+wv[j].1, dp[j][k+1][w])
                    } else {
                        dp[j][k+1][w]
                    };
                }
            }
        }
        mx = max!(mx, *dp[n].iter().map(|e| e.iter().max().unwrap()).max().unwrap());
    }

    println!("{}", mx);
}

