	let mut v: Vec<Vec<usize>> = vec![vec![]; 4];

	for i in 0..n {
		w.push(wv[i][0]);
	}
	w.sort();
	w.dedup();

	for i in 0..n {
		for j in 0..w.len() {
			if wv[i][0] == w[j] {
				v[j].push(wv[i][1]);
			}
		}
	}
	for i in 0..4 {
		v[i].sort_by_key(|&x| std::cmp::Reverse(x));
	}

	let mut sv: [usize; 4] = [0; 4];
	let mut mval = 0;
	for i in 0..=n {
		if i > v[0].len() {
			break;
		}
		if i > 0 {
			sv[0] += v[0][i-1];
		}
		for j in 0..=n-i {
			if j > v[1].len() {
				break;
			}
			if j > 0 {
				sv[1] += v[1][j-1];
			}
			for k in 0..=n-i-j {
				if k > v[2].len() {
					break;
				}
				if k > 0 {
					sv[2] += v[2][k-1];
				}
				for m in 0..=n-i-j-k {
					if m > v[3].len() {
						break;
					}
					if m > 0 {
						sv[3] += v[3][m-1];
					}
					let mut sw = 0;
					match w.len() {
						1 => {sw = w[0]*i;},
						2 => {sw = w[0]*i + w[1]*j;},
						3 => {sw = w[0]*i + w[1]*j + w[2]*k;},
						4 => {sw = w[0]*i + w[1]*j + w[2]*k + w[3]*m;},
						_ => {},
					}
					if sw > wmax {
						continue;
					}
					mval = std::cmp::max(mval, sv[0] + sv[1] + sv[2] + sv[3]);
				}
				sv[3] = 0;
			}
