use std::cmp::max;

fn solve(wv: &Vec<Vec<u32>>, w: u32, sumw: u32, sumv: u32, i: usize, l: usize) -> u32 {
    if sumw > w {
        return 0;
    }
    if i >= l {
        return sumv;
    }

    max(
        solve(wv, w, sumw, sumv, i + 1, l),
        solve(wv, w, sumw + wv[i][0], sumv + wv[i][1], i + 1, l),
    )
}

